INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27144, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "经济负担", "is_correct": true, "explanation": "指家庭承受的金钱压力，与“对农村家庭是”搭配，符合句意。"}, {"text": "教育机会", "is_correct": false, "explanation": "语义：学费高是负担，不会是教育机会，句意相反。"}, {"text": "经济优势", "is_correct": false, "explanation": "语义：学费很高不会给家庭带来经济优势，句意相反。"}, {"text": "生财之道", "is_correct": false, "explanation": "语域：“生财之道”是书面成语，与口语句“学费这么高”不协调；且学费高不是致富的途径。"}], "explanations": {"经济负担": "指家庭承受的金钱压力，与“对农村家庭是”搭配，符合句意。", "教育机会": "语义：学费高是负担，不会是教育机会，句意相反。", "经济优势": "语义：学费很高不会给家庭带来经济优势，句意相反。", "生财之道": "语域：“生财之道”是书面成语，与口语句“学费这么高”不协调；且学费高不是致富的途径。"}, "sentence_index": 6, "correct_answer": "经济负担"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们一直为他承担着一条经济负担。", "explanation": "这里应该用〈种〉。“条”用于细长的东西，不能修饰抽象的经济负担。"}, {"text": "这次意外让家里多了一张经济负担。", "explanation": "这里应该用〈种〉。“张”用于纸、桌子等平面的东西，不能用于经济负担。"}, {"text": "孩子的教育费用是我家的一只经济负担。", "explanation": "这里应该用〈种〉。“只”用于动物等，不用于抽象名词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39bff450-c9af-46a3-9425-4644eeb5ede1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27144, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这笔医药费对我们家来说是很大的经济负担们。", "corrected_sentence": "这笔医药费对我们家来说是很大的经济负担。", "error_description": "错误：“经济负担”后加了“们”；“们”只用于指人的名词，不能用在“经济负担”后。正确：去掉“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39bff450-c9af-46a3-9425-4644eeb5ede1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27144, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学费这么高，对我们家来说确实是一把沉重的经济负担。", "corrected_sentence": "学费这么高，对我们家来说确实是一种沉重的经济负担。", "error_description": "“经济负担”的量词应为“种”；“把”用于有柄的器具，不能修饰这个抽象名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39bff450-c9af-46a3-9425-4644eeb5ede1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
