INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27148, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "保护区是一个地方，动物和植物在里面很安全，不会受到伤害。", "primary_collocate": null, "pronunciation": "bǎo hù qū", "ipa": "paʊ˨˩ xu˥˩ tɕʰy˥", "syllable_count": 3, "sentences": [{"text": "保护区里的动物很安全。", "target_word": "保护区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们周末去保护区看熊猫。", "target_word": "保护区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在保护区里，人不能打猎。", "target_word": "保护区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个保护区很大，有很多树。", "target_word": "保护区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鸟在保护区里安静地生活。", "target_word": "保护区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师带学生参观了一个保护区。", "target_word": "保护区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "保护区的工人每天给动物检查身体。", "target_word": "保护区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们建了保护区，让植物慢慢长大。", "target_word": "保护区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在保护区门口看到一只鹿。", "target_word": "保护区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个保护区不让汽车进去。", "target_word": "保护区", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "自然保护区", "label": "复合"}], "register": "中性", "sense_fingerprint": "动植物能安全生活的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b4ede4-b5c5-47ad-9967-6cec6e48f26b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27148, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保护区", "is_correct": true, "explanation": "正确。“保护区里的动物很安全”说的是动植物能安全生活的地方，与句意相符。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房不是动物安全生活的地方，与“动物很安全”的前提相悖。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行里不住动物，“动物很安全”的前提不成立，句意不通。"}, {"text": "停车场", "is_correct": false, "explanation": "搭配：停车场是停放车辆的地方，与“动物生活安全”的语境不搭配。"}], "explanations": {"保护区": "正确。“保护区里的动物很安全”说的是动植物能安全生活的地方，与句意相符。", "厨房": "语义：厨房不是动物安全生活的地方，与“动物很安全”的前提相悖。", "银行": "语义：银行里不住动物，“动物很安全”的前提不成立，句意不通。", "停车场": "搭配：停车场是停放车辆的地方，与“动物生活安全”的语境不搭配。"}, "sentence_index": 0, "correct_answer": "保护区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只保护区很大，树很多。", "explanation": "量词错误：〈只〉用于动物，保护区是地方，应用〈个〉或〈片〉。"}, {"text": "这家保护区里有很多好吃的菜。", "explanation": "这里应该用〈餐厅〉。保护区是动植物生活的地方，不提供饭菜。"}, {"text": "我把作业放进了保护区里。", "explanation": "这里应该用〈书包〉或〈柜子〉。保护区是动植物生活的地方，不是存放物品的场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48db653b-5390-420d-858d-9c25a581ed1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27148, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保护区", "is_correct": true, "explanation": "正确。“保护区的工人”指在保护区工作的人，负责照顾其中的动物，与句意相符。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆的工人不负责给动物检查身体，与句中“动物”的主体不符。"}, {"text": "餐厅", "is_correct": false, "explanation": "搭配：“检查身体”的对象是动物，餐厅的工作内容与之不搭配。"}, {"text": "超市", "is_correct": false, "explanation": "语义：超市的工人不会给动物检查身体，句意不通。"}], "explanations": {"保护区": "正确。“保护区的工人”指在保护区工作的人，负责照顾其中的动物，与句意相符。", "图书馆": "语义：图书馆的工人不负责给动物检查身体，与句中“动物”的主体不符。", "餐厅": "搭配：“检查身体”的对象是动物，餐厅的工作内容与之不搭配。", "超市": "语义：超市的工人不会给动物检查身体，句意不通。"}, "sentence_index": 6, "correct_answer": "保护区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "保护区里关着很多犯人。", "explanation": "这里应该用〈监狱〉。保护区是为保护动植物划定的区域，不关押犯人。"}, {"text": "我们走进了这把保护区。", "explanation": "量词错误：〈把〉用于有柄的器具，保护区是地方，应用〈个〉或〈片〉。"}, {"text": "他是我们班最聪明的保护区。", "explanation": "这里应该用〈学霸〉。保护区是地方名词，不能用来指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48db653b-5390-420d-858d-9c25a581ed1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27148, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在山里看到了一把保护区。", "corrected_sentence": "我们在山里看到了一个保护区。", "error_description": "量词错误：“把”用于有柄的器具，保护区是地方，应改为“个”，说“一个保护区”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48db653b-5390-420d-858d-9c25a581ed1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27148, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条小路通向那只保护区。", "corrected_sentence": "这条小路通向那个保护区。", "error_description": "量词错误：“只”用于动物，保护区是地方，应改为“个”，说“那个保护区”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48db653b-5390-420d-858d-9c25a581ed1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
