INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27150, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "本来就这样，不是从别处来的。", "primary_collocate": null, "pronunciation": "yuán shēng", "ipa": "ɥɛn˧˥ ʂɤŋ˥˥", "syllable_count": 2, "sentences": [{"text": "这种竹子是中国原生的。", "target_word": "原生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的原生鱼和外来鱼不一样。", "target_word": "原生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原生的花草不需要太多水。", "target_word": "原生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要保护原生的小树林。", "target_word": "原生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种鸟是原生的，不是从外地引进的。", "target_word": "原生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的原生草很高。", "target_word": "原生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个岛上的动物都是原生的，没有一只是从外地来的。", "target_word": "原生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，这棵树是原生的吗？", "target_word": "原生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外来的草多了，原生的草就少了。", "target_word": "原生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢在原生的森林里走路。", "target_word": "原生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "原生植物", "label": "复合"}, {"form": "原生态", "label": "复合"}], "register": "书面", "sense_fingerprint": "本来如此、非外来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c117361b-798a-4a43-83e2-632764919ae4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27150, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原生", "is_correct": true, "explanation": "正确：句子说竹子在中国本来就有、不是从外地来的，“中国原生的”正合语境。"}, {"text": "陌生", "is_correct": false, "explanation": "语义：陌生指不熟悉，与竹子“原本产于中国”的来源描述不符。"}, {"text": "新鲜", "is_correct": false, "explanation": "搭配：新鲜用来形容食物或空气，不能用来说明竹子的产地。"}, {"text": "雪白", "is_correct": false, "explanation": "语义：雪白描述颜色，与“是中国……的”所说的来源无关，句子意思不通。"}], "explanations": {"原生": "正确：句子说竹子在中国本来就有、不是从外地来的，“中国原生的”正合语境。", "陌生": "语义：陌生指不熟悉，与竹子“原本产于中国”的来源描述不符。", "新鲜": "搭配：新鲜用来形容食物或空气，不能用来说明竹子的产地。", "雪白": "语义：雪白描述颜色，与“是中国……的”所说的来源无关，句子意思不通。"}, "sentence_index": 0, "correct_answer": "原生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块草地是原生的，是工人用塑料做成的。", "explanation": "这里应该用〈人造〉。“原生”指本来就这样、不是人为造出来的，用塑料做成的草地应说“人造”。"}, {"text": "这种植物是原生的，是十年前从国外引进的。", "explanation": "这里应该用〈外来〉。“原生”指本来就这样、不是从别处来的，从国外引进的植物应说“外来”。"}, {"text": "这个品种是科学家原生培育出来的。", "explanation": "这里应该用〈人工〉。这个品种是科学家人为培育的，“原生”指本来就这样、不是人为造出来的，两者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '754b4d02-52a0-4a9b-a662-6693fb895906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27150, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原生", "is_correct": true, "explanation": "正确：句子说岛上动物都没有从外地来，“都是原生的”正合语境。"}, {"text": "外来", "is_correct": false, "explanation": "语义：后半句说“没有一只是从外地来的”，填“外来”则“都是外来的”与之矛盾。"}, {"text": "荒凉", "is_correct": false, "explanation": "语义：荒凉指环境冷清，不能用来形容动物的归属，句子意思不通。"}, {"text": "幼稚", "is_correct": false, "explanation": "搭配：幼稚多用来形容人的想法或行为，不能用来修饰动物。"}], "explanations": {"原生": "正确：句子说岛上动物都没有从外地来，“都是原生的”正合语境。", "外来": "语义：后半句说“没有一只是从外地来的”，填“外来”则“都是外来的”与之矛盾。", "荒凉": "语义：荒凉指环境冷清，不能用来形容动物的归属，句子意思不通。", "幼稚": "搭配：幼稚多用来形容人的想法或行为，不能用来修饰动物。"}, "sentence_index": 6, "correct_answer": "原生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座桥是原生建的。", "explanation": "这里应该用〈新建〉。桥是人建造的，“原生”指非人工的本来状态，不能用于建造。"}, {"text": "这盏灯是原生的，是他自己焊接出来的。", "explanation": "这里应该用〈自制〉。“原生”指本来就这样、不是后来做出来的，自己焊的灯应说“自制”。"}, {"text": "这辆车是原生的，是他刚花钱改造的。", "explanation": "这里应该用〈改装〉。车是他花钱改造过的，“原生”指本来就这样、没人动过，两者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '754b4d02-52a0-4a9b-a662-6693fb895906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27150, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种花是被中国原生的。", "corrected_sentence": "这种花是中国原生的。", "error_description": "错误形式：“是被中国原生的”；正确形式：“是中国原生的”。“原生”是描述本来状态的词，不能用“被”构成被动式，应去掉“被”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '754b4d02-52a0-4a9b-a662-6693fb895906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27150, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家附近有一片原生了的小树林。", "corrected_sentence": "我家附近有一片原生的小树林。", "error_description": "错误在“原生”后多加了“了”。“原生”作修饰语时不能带“了”，应改为“我家附近有一片原生的小树林”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '754b4d02-52a0-4a9b-a662-6693fb895906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
