INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27152, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "把几个数加起来，再除以它们的个数，得到的结果。", "primary_collocate": null, "pronunciation": "píng jūn", "ipa": "pʰiŋ˧˥ tɕyn˥", "syllable_count": 2, "sentences": [{"text": "三、五、七的平均是五。", "target_word": "平均", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这四个数的平均是多少？", "target_word": "平均", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师算出了我们分数的平均。", "target_word": "平均", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "求平均要先把数字加起来。", "target_word": "平均", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几天温度的平均是二十度。", "target_word": "平均", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他三次数学考试的平均是九十分。", "target_word": "平均", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你来算一下这五个数的平均吧。", "target_word": "平均", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "八和十二的平均是十。", "target_word": "平均", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把这些数加起来再除，就得到了平均。", "target_word": "平均", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这组数的平均是六，不是七。", "target_word": "平均", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "平均数", "label": "复合词"}, {"form": "平均值", "label": "复合词"}, {"form": "平均分", "label": "复合词"}], "register": "通用", "sense_fingerprint": "几个数相加再除以个数所得的结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c117361b-798a-4a43-83e2-632764919ae4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27152, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "平均", "is_correct": true, "explanation": "平均指这三个数相加后除以个数所得的结果，与“是五”相符。"}, {"text": "和", "is_correct": false, "explanation": "语义：“和”指相加的总数，三、五、七的和是十五，不是五。"}, {"text": "最大值", "is_correct": false, "explanation": "语义：三、五、七的最大值是七，不是五。"}, {"text": "平方", "is_correct": false, "explanation": "搭配：“平方”只作用于单个数，不能对三、五、七整体使用。"}], "explanations": {"平均": "平均指这三个数相加后除以个数所得的结果，与“是五”相符。", "和": "语义：“和”指相加的总数，三、五、七的和是十五，不是五。", "最大值": "语义：三、五、七的最大值是七，不是五。", "平方": "搭配：“平方”只作用于单个数，不能对三、五、七整体使用。"}, "sentence_index": 0, "correct_answer": "平均"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他算出了一块平均。", "explanation": "这里应该用〈个〉。量词“块”用于块状的东西，不能用于“平均”这样抽象的结果。"}, {"text": "这次比赛的平均是他。", "explanation": "“平均”指算出的数值结果，不能指人，这里说的是人，应该说“第一名”。"}, {"text": "这本书的平均很好看。", "explanation": "这里应该用〈封面〉。“平均”是算出来的数值结果，不能说“好看”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '754b4d02-52a0-4a9b-a662-6693fb895906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27152, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "平均", "is_correct": true, "explanation": "平均是对这五个数算出来的结果，与“算一下”相符。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”不是可以计算的数值，句意不通。"}, {"text": "字母", "is_correct": false, "explanation": "语义：“字母”不能用“算”来求得，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“算”后面不能接“颜色”这类不可计算的名词。"}], "explanations": {"平均": "平均是对这五个数算出来的结果，与“算一下”相符。", "名字": "语义：“名字”不是可以计算的数值，句意不通。", "字母": "语义：“字母”不能用“算”来求得，句意不通。", "颜色": "搭配：“算”后面不能接“颜色”这类不可计算的名词。"}, "sentence_index": 6, "correct_answer": "平均"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块石头的平均很重。", "explanation": "这里应该用〈分量〉。平均要对一组数求得，单独一块石头的数值不能说“平均”。"}, {"text": "他的平均是十二岁，比我大。", "explanation": "这里应该用〈年龄〉。平均要对一组数求得，单独一个人的数值不能说“平均”。"}, {"text": "这杯水的平均很甜。", "explanation": "这里应该用〈味道〉。“平均”是一组数算出的结果，不能用来说味道甜不甜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '754b4d02-52a0-4a9b-a662-6693fb895906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27152, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这三个数的平均了是六。", "corrected_sentence": "这三个数的平均是六。", "error_description": "错误形式：“平均了”；正确形式：“平均”。“平均”作名词表示计算结果时不能带动态助词“了”，应删去“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '754b4d02-52a0-4a9b-a662-6693fb895906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27152, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这五个数的平均了十。", "corrected_sentence": "这五个数的平均是十。", "error_description": "错误字：“了”应为“是”。“平均”作主语，后接判断动词“是”，不能用动态助词“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '754b4d02-52a0-4a9b-a662-6693fb895906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
