INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27154, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "所有都死光了，再也没有了。", "primary_collocate": null, "pronunciation": "miè jué", "ipa": "mjɛ˥˩ tɕɥɛ˧˥", "syllable_count": 2, "sentences": [{"text": "这个岛上的鸟全都灭绝了。", "target_word": "灭绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林着火后，那里的蛇灭绝了。", "target_word": "灭绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上说，这种鱼两百年前就灭绝了。", "target_word": "灭绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多动物因为天气变冷而灭绝。", "target_word": "灭绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家担心这种花会灭绝。", "target_word": "灭绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种动物早就灭绝了，我们只能在博物馆里看到它。", "target_word": "灭绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球上有过很多灭绝的动物。", "target_word": "灭绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想知道渡渡鸟为什么灭绝。", "target_word": "灭绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种青蛙快要灭绝了，大家要小心。", "target_word": "灭绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要保护小动物，不让它们灭绝。", "target_word": "灭绝", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "灭绝了", "label": "体标"}, {"form": "灭绝过", "label": "体标"}], "register": "书面", "sense_fingerprint": "全部死光再也没有", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c117361b-798a-4a43-83e2-632764919ae4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27154, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "灭绝", "is_correct": true, "explanation": "正确：句子说这个岛上的鸟全部死光了，“灭绝了”正符合“全都”的语境。"}, {"text": "上学", "is_correct": false, "explanation": "语义：鸟不会上学，“全都上学了”与岛上的情况完全不符。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：鸟不会毕业，“全都毕业了”说的事情与鸟类无关。"}, {"text": "考试", "is_correct": false, "explanation": "配价：考试需要能参加考试的人，鸟不能作为“考试”的主体，句子说不通。"}], "explanations": {"灭绝": "正确：句子说这个岛上的鸟全部死光了，“灭绝了”正符合“全都”的语境。", "上学": "语义：鸟不会上学，“全都上学了”与岛上的情况完全不符。", "毕业": "语义：鸟不会毕业，“全都毕业了”说的事情与鸟类无关。", "考试": "配价：考试需要能参加考试的人，鸟不能作为“考试”的主体，句子说不通。"}, "sentence_index": 0, "correct_answer": "灭绝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨停后，天上的云全都灭绝了。", "explanation": "这里应该用〈消散〉。云气散开应说“消散”，“灭绝”指生物全部死光，不能用于云。"}, {"text": "他生病了，在家灭绝了一个星期。", "explanation": "这里应该用〈休息〉。在家养病一段时间应说“休息”，“灭绝”指全部死光，不能用于一个人的休养。"}, {"text": "战争时兄弟俩灭绝了，几十年后才重逢。", "explanation": "这里应该用〈失散〉。兄弟在战乱中分开应说“失散”，“灭绝”指全部死光、再也没有了，不能用于人暂时分开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '754b4d02-52a0-4a9b-a662-6693fb895906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27154, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "灭绝", "is_correct": true, "explanation": "正确：这里说的是地球上过去的动物，“灭绝的动物”指已经不存在的种类。"}, {"text": "现存", "is_correct": false, "explanation": "语义：现存指当下仍然存在，与“地球上有过”所指的过去时间相矛盾。"}, {"text": "当代", "is_correct": false, "explanation": "语义：当代指现在这个时代，与“有过”所表示的过去相冲突。"}, {"text": "现有", "is_correct": false, "explanation": "搭配：“有过”表示过去，“现有”表示当下，二者不能在同一句中搭配。"}], "explanations": {"灭绝": "正确：这里说的是地球上过去的动物，“灭绝的动物”指已经不存在的种类。", "现存": "语义：现存指当下仍然存在，与“地球上有过”所指的过去时间相矛盾。", "当代": "语义：当代指现在这个时代，与“有过”所表示的过去相冲突。", "现有": "搭配：“有过”表示过去，“现有”表示当下，二者不能在同一句中搭配。"}, "sentence_index": 6, "correct_answer": "灭绝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小偷见到警察，马上灭绝了。", "explanation": "这里应该用〈逃跑〉。小偷逃走应说“逃跑”，“灭绝”指种类全部死光，不能用于人的逃走。"}, {"text": "太阳落山后，天边的晚霞慢慢灭绝了。", "explanation": "这里应该用〈消失〉。晚霞慢慢散去应说“消失”，“灭绝”只指生物全部死光，不能用于景象。"}, {"text": "夏天到了，温度不停地灭绝。", "explanation": "这里应该用〈升高〉。温度上升应说“升高”，“灭绝”不能用于温度这类数值。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '754b4d02-52a0-4a9b-a662-6693fb895906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27154, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那种蛇已经很灭绝了。", "corrected_sentence": "那种蛇已经灭绝了。", "error_description": "错误在“灭绝”前多加了程度副词“很”。“灭绝”是动词，不能受“很”修饰，应改为“那种蛇已经灭绝了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '754b4d02-52a0-4a9b-a662-6693fb895906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27154, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种鸟灭绝着。", "corrected_sentence": "这种鸟灭绝了。", "error_description": "错误形式：“灭绝着”；正确形式：“灭绝了”。“灭绝”表示一下子完成的结果，不能带表示持续的“着”，应改为“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '754b4d02-52a0-4a9b-a662-6693fb895906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
