INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27156, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48db653b-5390-420d-858d-9c25a581ed1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27156, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "毒性是指某种东西能让人或动物生病或死去的能力，比如老鼠药有毒性。", "primary_collocate": null, "pronunciation": "dú xìng", "ipa": "tu˧˥ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "老鼠药有毒性，孩子不能碰。", "target_word": "毒性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种草有毒性，牛不吃它。", "target_word": "毒性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "毒性越大，越危险。", "target_word": "毒性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种蘑菇的毒性很强。", "target_word": "毒性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说这瓶水有毒性，不能喝。", "target_word": "毒性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蛇的毒性可以让人生病。", "target_word": "毒性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种花的毒性不大，但是别吃。", "target_word": "毒性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生检测了这种药的毒性，结果显示很低。", "target_word": "毒性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种虫子没有毒性，别害怕。", "target_word": "毒性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗吃了有毒性的东西，生病了。", "target_word": "毒性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "毒性反应", "label": "复合"}, {"form": "毒性物质", "label": "复合"}], "register": "中性", "sense_fingerprint": "东西能让人或动物生病或死去的能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b4ede4-b5c5-47ad-9967-6cec6e48f26b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27156, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "毒性", "is_correct": true, "explanation": "正确。“老鼠药有毒性”指它能伤害人或动物，与“孩子不能碰”相符。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格与“孩子不能碰”所强调的危险无关，句意不通。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”只用于生物，不用于老鼠药这类物品。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重与危险性无关，句中强调的是老鼠药的危害。"}], "explanations": {"毒性": "正确。“老鼠药有毒性”指它能伤害人或动物，与“孩子不能碰”相符。", "价格": "语义：价格与“孩子不能碰”所强调的危险无关，句意不通。", "年龄": "搭配：“年龄”只用于生物，不用于老鼠药这类物品。", "体重": "语义：体重与危险性无关，句中强调的是老鼠药的危害。"}, "sentence_index": 0, "correct_answer": "毒性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子误喝了毒性，被送进了医院。", "explanation": "这里应该用〈毒药〉。毒性是性质，不能被喝下，说“喝了毒药”。"}, {"text": "这块毒性很大，别碰它。", "explanation": "量词错误：〈块〉用于块状物，毒性是抽象性质，不能用量词“块”计量。"}, {"text": "他的毒性很大，总是欺负同学。", "explanation": "语义：毒性指物质对生物的损害性质，不用来形容人的性格，形容人应说“恶毒”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48db653b-5390-420d-858d-9c25a581ed1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27156, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "毒性", "is_correct": true, "explanation": "正确。“这种花的毒性不大，但是别吃”指花对人的损害性质，句中转折与“别吃”相符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：颜色一般说“深”或“浅”，不说“颜色不大”。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：名字不用“大小”来形容，“名字不大”说不通。"}, {"text": "长相", "is_correct": false, "explanation": "语义：长相与“别吃”的提醒无关，句中转折说的是危险性。"}], "explanations": {"毒性": "正确。“这种花的毒性不大，但是别吃”指花对人的损害性质，句中转折与“别吃”相符。", "颜色": "搭配：颜色一般说“深”或“浅”，不说“颜色不大”。", "名字": "搭配：名字不用“大小”来形容，“名字不大”说不通。", "长相": "语义：长相与“别吃”的提醒无关，句中转折说的是危险性。"}, "sentence_index": 6, "correct_answer": "毒性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他染上了毒性，戒不掉了。", "explanation": "这里应该用〈毒瘾〉。毒性是物质的损害性质，不能被染上，应说“染上毒瘾”。"}, {"text": "这粒毒性很低，可以放心吃。", "explanation": "量词错误：〈粒〉用于颗粒，毒性是抽象性质，不能用量词“粒”计量。"}, {"text": "工厂排出的毒性污染了河水。", "explanation": "这里应该用〈毒物〉。毒性是性质，不能被排放，排放的是毒物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48db653b-5390-420d-858d-9c25a581ed1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27156, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种草有一棵毒性，牛最好别吃。", "corrected_sentence": "这种草有一定的毒性，牛最好别吃。", "error_description": "量词错误：“棵”用于植物，“毒性”是抽象名词，不能用“棵”计量，应说“一定的毒性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48db653b-5390-420d-858d-9c25a581ed1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27156, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生说这种花有一片毒性。", "corrected_sentence": "医生说这种花有一定的毒性。", "error_description": "量词错误：“片”用于面状的东西，“毒性”是抽象名词，不能用“片”计量，应说“一定的毒性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48db653b-5390-420d-858d-9c25a581ed1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
