INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27166, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "大家一起做不同的事情，一起完成一个任务。", "primary_collocate": null, "pronunciation": "fēn gōng xié zuò", "ipa": "fən˥˥ kʊŋ˥˥ ɕjɛ˧˥ tswɔ˥˩", "syllable_count": 4, "sentences": [{"text": "我们三个人分工协作做饭。", "target_word": "分工协作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家分工协作，很快打扫完了教室。", "target_word": "分工协作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分工协作就是一起做不同的事。", "target_word": "分工协作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家那天，全家人分工协作。", "target_word": "分工协作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小组里每个人都要分工协作。", "target_word": "分工协作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们分工协作准备了一场晚会。", "target_word": "分工协作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分工协作可以让工作更简单。", "target_word": "分工协作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们分工协作，我买菜，他做饭。", "target_word": "分工协作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们分工协作，一起完成了一幅画。", "target_word": "分工协作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛时，队员们分工协作得很好。", "target_word": "分工协作", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分工合作", "label": "近义复合"}, {"form": "分工", "label": "缩略形式"}], "register": "通用", "sense_fingerprint": "大家各做不同的事，一起完成任务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b4ede4-b5c5-47ad-9967-6cec6e48f26b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27166, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分工协作", "is_correct": true, "explanation": "正确：“分工协作”说明三人如何做饭，是互相配合的方式，与句意相合。"}, {"text": "独自", "is_correct": false, "explanation": "语义：“独自”指一个人做，与“我们三个人”矛盾。"}, {"text": "单独", "is_correct": false, "explanation": "语义：“单独”指一个人单干，与三个人一起做饭不符。"}, {"text": "逐一", "is_correct": false, "explanation": "搭配：“逐一”强调依次进行，与“做饭”的合作义搭配不当。"}], "explanations": {"分工协作": "正确：“分工协作”说明三人如何做饭，是互相配合的方式，与句意相合。", "独自": "语义：“独自”指一个人做，与“我们三个人”矛盾。", "单独": "语义：“单独”指一个人单干，与三个人一起做饭不符。", "逐一": "搭配：“逐一”强调依次进行，与“做饭”的合作义搭配不当。"}, "sentence_index": 0, "correct_answer": "分工协作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一个人分工协作，搬完了所有的箱子。", "explanation": "这里应该用〈独自〉。分工协作需要多人各负其责，一个人搬箱子不能用它。"}, {"text": "比赛时，两队分工协作，想尽办法压倒对方。", "explanation": "这里应该用〈竞争〉。分工协作是为同一目标互相配合，与“压倒对方”的对立关系不符。"}, {"text": "这道数学题很难，我分工协作想了很久。", "explanation": "这里应该用〈独自〉。分工协作需要多人各自承担任务，一个人动脑筋不能用它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48db653b-5390-420d-858d-9c25a581ed1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27166, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分工协作", "is_correct": true, "explanation": "正确：分工协作能分担任务，与“让工作更简单”的句意相合。"}, {"text": "懒惰", "is_correct": false, "explanation": "语义：懒惰只会拖慢工作，不能让工作更简单。"}, {"text": "拖延", "is_correct": false, "explanation": "语义：拖延会让工作变得更难，与“更简单”相反。"}, {"text": "疲劳", "is_correct": false, "explanation": "搭配：“疲劳”不作“让工作更简单”的主语，搭配不当。"}], "explanations": {"分工协作": "正确：分工协作能分担任务，与“让工作更简单”的句意相合。", "懒惰": "语义：懒惰只会拖慢工作，不能让工作更简单。", "拖延": "语义：拖延会让工作变得更难，与“更简单”相反。", "疲劳": "搭配：“疲劳”不作“让工作更简单”的主语，搭配不当。"}, "sentence_index": 6, "correct_answer": "分工协作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "姐弟俩吃饭时分工协作，吵个不停。", "explanation": "这里应该用〈吵架〉。分工协作是互相配合，与“吵个不停”的意思相反。"}, {"text": "全家人在饭桌上分工协作吃饭。", "explanation": "这里应该用〈一起〉。吃饭不需要分配不同的任务，不能用分工协作来形容。"}, {"text": "她在屋里分工协作画画。", "explanation": "这里应该用〈独自〉。分工协作需要多人各负其责，她一个人画画不能用它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48db653b-5390-420d-858d-9c25a581ed1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27166, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们分工协作很得顺利。", "corrected_sentence": "我们分工协作得很顺利。", "error_description": "补语用法错误：“分工协作”后用“得”引出补语，应说“分工协作得很顺利”，不说“很得顺利”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48db653b-5390-420d-858d-9c25a581ed1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27166, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姐妹俩分工协作了一幅画。", "corrected_sentence": "姐妹俩分工协作完成了一幅画。", "error_description": "词语缺失：“分工协作”不能直接带宾语，中间应加“完成”，应说“分工协作完成了一幅画”，不说“分工协作了一幅画”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48db653b-5390-420d-858d-9c25a581ed1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
