INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27168, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "一种跟着音乐跳的舞，身体会左右摇动。", "primary_collocate": null, "pronunciation": "yáo bǎi wǔ", "ipa": "jɑʊ˧˥ paɪ˨˩ u˨˩", "syllable_count": 3, "sentences": [{"text": "孩子们跟着音乐跳起了摇摆舞。", "target_word": "摇摆舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我会跳一点摇摆舞。", "target_word": "摇摆舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的摇摆舞跳得很有意思。", "target_word": "摇摆舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐在教我跳摇摆舞。", "target_word": "摇摆舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跳摇摆舞时，身体要左右摇动。", "target_word": "摇摆舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚会上，大家都想看他跳摇摆舞。", "target_word": "摇摆舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐一响，她就跳起摇摆舞来。", "target_word": "摇摆舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌很适合跳摇摆舞。", "target_word": "摇摆舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们在家跳了摇摆舞。", "target_word": "摇摆舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和朋友一起练习摇摆舞。", "target_word": "摇摆舞", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一段摇摆舞", "label": "量词搭配"}], "register": "通用", "sense_fingerprint": "跟着音乐身体左右摇动的舞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b4ede4-b5c5-47ad-9967-6cec6e48f26b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27168, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "摇摆舞", "is_correct": true, "explanation": "正确：孩子们跟着音乐跳的正是这种身体左右摇动的舞。"}, {"text": "算术", "is_correct": false, "explanation": "搭配：“跳起了”后不能接“算术”，两者搭配不当。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：“跳起了”不能与“电脑”搭配，语义上说不通。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海不是舞蹈，不能被“跳”，与句意不符。"}], "explanations": {"摇摆舞": "正确：孩子们跟着音乐跳的正是这种身体左右摇动的舞。", "算术": "搭配：“跳起了”后不能接“算术”，两者搭配不当。", "电脑": "搭配：“跳起了”不能与“电脑”搭配，语义上说不通。", "大海": "语义：大海不是舞蹈，不能被“跳”，与句意不符。"}, "sentence_index": 0, "correct_answer": "摇摆舞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "姐姐在教我跳一只摇摆舞。", "explanation": "量词错误：这里应该用〈一段〉或〈一支〉。〈只〉用于动物或成对的东西，不用于舞蹈。"}, {"text": "摇摆舞者要保持身体挺直，不能左右摇动。", "explanation": "这里应该用〈芭蕾〉。芭蕾要求身体挺直、不左右摇动，而摇摆舞的特点正是身体左右摇动，两者不能互换。"}, {"text": "姐姐在教我跳一朵摇摆舞。", "explanation": "量词错误：这里应该用〈一段〉或〈一支〉。〈朵〉用于花、云等，不用于舞蹈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48db653b-5390-420d-858d-9c25a581ed1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27168, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "摇摆舞", "is_correct": true, "explanation": "正确：“跳起……来”后接舞蹈名称，与句意相合。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“跳起”不能接“作业”，搭配不当。"}, {"text": "算术", "is_correct": false, "explanation": "搭配：“算术”不能被“跳起”，与句中的舞动场景不搭。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不能被“跳”，与“音乐一响”的舞动场景不符。"}], "explanations": {"摇摆舞": "正确：“跳起……来”后接舞蹈名称，与句意相合。", "作业": "搭配：“跳起”不能接“作业”，搭配不当。", "算术": "搭配：“算术”不能被“跳起”，与句中的舞动场景不搭。", "河流": "语义：河流不能被“跳”，与“音乐一响”的舞动场景不符。"}, "sentence_index": 6, "correct_answer": "摇摆舞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我和朋友每天早上在公园里打拳，练的是摇摆舞。", "explanation": "这里应该用〈武术〉。“打拳”是武术，与“练的是摇摆舞”互相矛盾。"}, {"text": "我和朋友一起练习一双摇摆舞。", "explanation": "量词错误：这里应该用〈一段〉或〈一支〉。〈双〉用于成对的东西，不用于舞蹈。"}, {"text": "我和朋友一起练习一把摇摆舞。", "explanation": "量词错误：这里应该用〈一段〉或〈一支〉。〈把〉用于有把手的东西，不用于舞蹈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48db653b-5390-420d-858d-9c25a581ed1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27168, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末我们一起学一只摇摆舞。", "corrected_sentence": "周末我们一起学一段摇摆舞。", "error_description": "量词错误：“只”用于动物，不用于舞蹈。舞蹈用“段”或“支”，应说“学一段摇摆舞”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48db653b-5390-420d-858d-9c25a581ed1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27168, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她突然跳了起摇摆舞。", "corrected_sentence": "她突然跳起了摇摆舞。", "error_description": "补语位置错误：“跳起”的“起”应紧跟动词，应说“跳起了摇摆舞”，不说“跳了起”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48db653b-5390-420d-858d-9c25a581ed1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
