INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27170, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "心里突然想出的好主意。", "primary_collocate": null, "pronunciation": "líng gǎn", "ipa": "liŋ˧˥ kan˨˩˦", "syllable_count": 2, "sentences": [{"text": "我今天写不出来，没有灵感。", "target_word": "灵感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他洗澡的时候忽然有了灵感。", "target_word": "灵感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到那朵花，她有了画画的灵感。", "target_word": "灵感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的灵感常常来得很突然。", "target_word": "灵感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个广告的灵感来自一个小故事。", "target_word": "灵感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天散步，是为了找灵感。", "target_word": "灵感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐给了她很多写作的灵感。", "target_word": "灵感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作曲家半夜醒来，记下了新的灵感。", "target_word": "灵感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灵感一来，他就马上拿起笔。", "target_word": "灵感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这个灵感真不错，可以写成一首歌。", "target_word": "灵感", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "创作灵感", "label": "复合"}], "register": "中性", "sense_fingerprint": "心里突然想到的好主意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f0f8b3d-3b38-41b9-91fd-9b8b797a5035') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27170, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鱼", "is_correct": false, "explanation": "语义：“鱼”与写作无关，“写不出来，没有鱼”不通。"}, {"text": "房子", "is_correct": false, "explanation": "语义：“房子”不是写作的材料或条件，句子意思不成立。"}, {"text": "灵感", "is_correct": true, "explanation": "正确：“没有灵感”指没有创作时突然冒出的好主意，是写不出来的原因。"}, {"text": "窗帘", "is_correct": false, "explanation": "搭配：“窗帘”与写作的能力或条件没有搭配关系，不能作为写不出来的原因。"}], "explanations": {"鱼": "语义：“鱼”与写作无关，“写不出来，没有鱼”不通。", "房子": "语义：“房子”不是写作的材料或条件，句子意思不成立。", "灵感": "正确：“没有灵感”指没有创作时突然冒出的好主意，是写不出来的原因。", "窗帘": "搭配：“窗帘”与写作的能力或条件没有搭配关系，不能作为写不出来的原因。"}, "sentence_index": 0, "correct_answer": "灵感"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今天向老板申请了一个灵感。", "explanation": "这里应该用〈假期〉。“申请”用于假期、资金等，“灵感”是突然想出的好主意，不能申请。"}, {"text": "这座古城的灵感很古老。", "explanation": "这里应该用〈灵魂〉。“古老”形容事物的年代，“灵感”是突然产生的想法，不能这样形容。"}, {"text": "这个房间让我的灵感很温暖。", "explanation": "这里应该用〈感觉〉。“很温暖”是身体或心理的感受，“灵感”不能被感受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54c86b3-c290-4d8b-95c6-0bc26c161b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27170, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”与写作无关，“音乐给了她很多写作的冰箱”不成立。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：“汽车”不是音乐能给予的写作启发，句子意思不通。"}, {"text": "灵感", "is_correct": true, "explanation": "正确：“写作的灵感”指写作时突然产生的想法，“音乐给了她很多”符合语境。"}, {"text": "灰尘", "is_correct": false, "explanation": "搭配：“灰尘”与“写作”“给予”都不构成常见搭配，句子中的给予关系不成立。"}], "explanations": {"冰箱": "语义：“冰箱”与写作无关，“音乐给了她很多写作的冰箱”不成立。", "汽车": "语义：“汽车”不是音乐能给予的写作启发，句子意思不通。", "灵感": "正确：“写作的灵感”指写作时突然产生的想法，“音乐给了她很多”符合语境。", "灰尘": "搭配：“灰尘”与“写作”“给予”都不构成常见搭配，句子中的给予关系不成立。"}, "sentence_index": 6, "correct_answer": "灵感"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "听到消息后，他的灵感很激动。", "explanation": "这里应该用〈心情〉。“激动”形容人的情绪，“灵感”指突然想出的好主意，不能说“激动”。"}, {"text": "这个人的灵感很健康。", "explanation": "这里应该用〈身体〉。“健康”形容身体或生活状况，“灵感”是突然想出的好主意，不能用“健康”来形容。"}, {"text": "她的灵感很倔强。", "explanation": "这里应该用〈脾气〉。“倔强”形容人的性格，“灵感”不具备性格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54c86b3-c290-4d8b-95c6-0bc26c161b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27170, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他想了很久，突然有了一把灵感。", "corrected_sentence": "他想了很久，突然有了一个灵感。", "error_description": "量词：灵感用“个”计量，“把”不能用于灵感，应写作“一个灵感”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54c86b3-c290-4d8b-95c6-0bc26c161b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27170, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他今天很灵感，写了三首歌。", "corrected_sentence": "他今天很有灵感，写了三首歌。", "error_description": "词性：“灵感”是名词，不能直接受“很”修饰作谓语，应说“很有灵感”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54c86b3-c290-4d8b-95c6-0bc26c161b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27172, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "松散", "is_correct": true, "explanation": "正确：「松散」与「紧密」是反义词，指挨得不近或联系不紧，符合这一义项。"}, {"text": "明亮", "is_correct": false, "explanation": "无反义关系：「明亮」形容光线充足，与「紧密」不构成反义。"}, {"text": "柔软", "is_correct": false, "explanation": "无反义关系：「柔软」形容质地，不与「紧密」相对。"}, {"text": "缓慢", "is_correct": false, "explanation": "无反义关系：「缓慢」形容速度，不是「紧密」的反义词。"}], "correct_answer": "松散", "explanations": {"松散": "正确：「松散」与「紧密」是反义词，指挨得不近或联系不紧，符合这一义项。", "明亮": "无反义关系：「明亮」形容光线充足，与「紧密」不构成反义。", "柔软": "无反义关系：「柔软」形容质地，不与「紧密」相对。", "缓慢": "无反义关系：「缓慢」形容速度，不是「紧密」的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54c86b3-c290-4d8b-95c6-0bc26c161b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27172, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "松散", "is_correct": true, "explanation": "正确：「松散」与「紧密」是反义词，指挨得不近或联系不紧，符合这一义项。"}, {"text": "安静", "is_correct": false, "explanation": "无反义关系：「安静」是与「吵闹」相对的，不是「紧密」的反义词。"}, {"text": "平坦", "is_correct": false, "explanation": "无反义关系：「平坦」形容表面，不与「紧密」相对。"}, {"text": "迅速", "is_correct": false, "explanation": "无反义关系：「迅速」形容速度，不是「紧密」的反义词。"}], "correct_answer": "松散", "explanations": {"松散": "正确：「松散」与「紧密」是反义词，指挨得不近或联系不紧，符合这一义项。", "安静": "无反义关系：「安静」是与「吵闹」相对的，不是「紧密」的反义词。", "平坦": "无反义关系：「平坦」形容表面，不与「紧密」相对。", "迅速": "无反义关系：「迅速」形容速度，不是「紧密」的反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54c86b3-c290-4d8b-95c6-0bc26c161b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27172, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "两个东西挨得很近，或者关系很好。", "primary_collocate": null, "pronunciation": "jǐn mì", "ipa": "tɕin˨˩ mi˥˩", "syllable_count": 2, "sentences": [{"text": "这些房子紧密地排在一起。", "target_word": "紧密", "complexity_tier": "T3", "furigana": "jǐnmì", "sentence_source": "generated"}, {"text": "我和他的关系很紧密。", "target_word": "紧密", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "书架上的书紧密地排列着。", "target_word": "紧密", "complexity_tier": "T3", "furigana": "jǐnmì", "sentence_source": "generated"}, {"text": "我和同学的感情越来越紧密。", "target_word": "紧密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两块木板拼接得很紧密，没有缝隙。", "target_word": "紧密", "complexity_tier": "T3", "furigana": "jǐnmì", "sentence_source": "generated"}, {"text": "路两边的树木紧密相连，像一道绿墙。", "target_word": "紧密", "complexity_tier": "T3", "furigana": "jǐnmì", "sentence_source": "generated"}, {"text": "这两家人的联系十分紧密，经常一起吃饭。", "target_word": "紧密", "complexity_tier": "T3", "furigana": "jǐnmì", "sentence_source": "generated"}, {"text": "这块布的针脚十分紧密。", "target_word": "紧密", "complexity_tier": "T3", "furigana": "jǐnmì", "sentence_source": "generated"}, {"text": "小鸟紧密地挤在一起取暖。", "target_word": "紧密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友之间要保持紧密的联系。", "target_word": "紧密", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "紧密地", "label": "状语形式"}, {"form": "緊密", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东西挨得近、关系亲近", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f0f8b3d-3b38-41b9-91fd-9b8b797a5035') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27172, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "紧密", "is_correct": true, "explanation": "正确：「紧密地排在一起」描述房子挨得近，符合句意。"}, {"text": "愉快", "is_correct": false, "explanation": "语义：房子是无生命的物体，不能「愉快地」排列。"}, {"text": "生气", "is_correct": false, "explanation": "语义：「生气」是人的情绪，房子不会生气。"}, {"text": "有力", "is_correct": false, "explanation": "搭配：「有力」修饰论证、行动，不修饰排列的方式。"}], "explanations": {"紧密": "正确：「紧密地排在一起」描述房子挨得近，符合句意。", "愉快": "语义：房子是无生命的物体，不能「愉快地」排列。", "生气": "语义：「生气」是人的情绪，房子不会生气。", "有力": "搭配：「有力」修饰论证、行动，不修饰排列的方式。"}, "sentence_index": 0, "correct_answer": "紧密"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "考试前，我的心里很紧密，一直睡不着。", "explanation": "这里应该用〈紧张〉。紧密说事物之间的距离或联系，不用来形容心理状态。"}, {"text": "现在的情况很紧密，我们得马上出发。", "explanation": "这里应该用〈紧急〉。紧密说事物之间的联系，形容情况危急要用紧急。"}, {"text": "这个地方的水很紧密，大家都很着急。", "explanation": "这里应该用〈紧缺〉。紧密说联系，水源不足要说紧缺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54c86b3-c290-4d8b-95c6-0bc26c161b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27172, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "紧密", "is_correct": true, "explanation": "正确：「联系十分紧密」与后句「经常一起吃饭」相合，符合句意。"}, {"text": "陌生", "is_correct": false, "explanation": "语义：「陌生」说明不熟悉，与后句「经常一起吃饭」矛盾。"}, {"text": "干净", "is_correct": false, "explanation": "搭配：「干净」多修饰环境、衣物，不修饰人家之间的联系。"}, {"text": "光滑", "is_correct": false, "explanation": "搭配：「光滑」修饰物体表面，不说人家之间的联系。"}], "explanations": {"紧密": "正确：「联系十分紧密」与后句「经常一起吃饭」相合，符合句意。", "陌生": "语义：「陌生」说明不熟悉，与后句「经常一起吃饭」矛盾。", "干净": "搭配：「干净」多修饰环境、衣物，不修饰人家之间的联系。", "光滑": "搭配：「光滑」修饰物体表面，不说人家之间的联系。"}, "sentence_index": 6, "correct_answer": "紧密"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座城市的交通很紧密，上班的人很多。", "explanation": "这里应该用〈拥挤〉。紧密说事物之间的距离或联系，人多、车多要说拥挤。"}, {"text": "他听到消息后，脸色很紧密，一句话也不说。", "explanation": "这里应该用〈紧绷〉。紧密说事物之间的距离或联系，不用来形容脸色的僵硬。"}, {"text": "妈妈的脾气很紧密，从不发火。", "explanation": "这里应该用〈温和〉。紧密形容距离近或关系好，不用来形容脾气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54c86b3-c290-4d8b-95c6-0bc26c161b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27172, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两根木头连得很紧密地。", "corrected_sentence": "两根木头连得很紧密。", "error_description": "错误：句末加“地”，写成“连得很紧密地”。正确应为“连得很紧密”；形容词作补语或谓语时句末不加“地”，“紧密地”只用作状语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54c86b3-c290-4d8b-95c6-0bc26c161b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27172, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几根竹子捆很紧密。", "corrected_sentence": "这几根竹子捆得很紧密。", "error_description": "错误：「捆很紧密」；正确：「捆得很紧密」。形容词作补语时，动词和补语之间要用「得」连接。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54c86b3-c290-4d8b-95c6-0bc26c161b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
