INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27174, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "最后说到最根本的地方。", "primary_collocate": null, "pronunciation": "guī gēn jié dǐ", "ipa": "kweɪ˥ kən˥ tɕjɛ˧˥ ti˨˩˦", "syllable_count": 4, "sentences": [{"text": "归根结底，我们还是要靠自己。", "target_word": "归根结底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛输了，归根结底是准备不够。", "target_word": "归根结底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "归根结底，钱不是最重要的。", "target_word": "归根结底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们吵架，归根结底是互相不了解。", "target_word": "归根结底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说了这么多，归根结底就是一句话：要努力。", "target_word": "归根结底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "归根结底，学习是自己的事。", "target_word": "归根结底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我生病了，归根结底是穿得太少。", "target_word": "归根结底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "归根结底，做人要诚实。", "target_word": "归根结底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司不赚钱，归根结底是东西太贵。", "target_word": "归根结底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "归根结底，快乐来自一颗平静的心。", "target_word": "归根结底", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "归根到底", "label": "变体"}], "register": "书面", "sense_fingerprint": "说到最后最根本的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f0f8b3d-3b38-41b9-91fd-9b8b797a5035') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27174, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然，与后面的原则性论断“我们还是要靠自己”不相符。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上，句子是在说根本的道理，不是立即的动作。"}, {"text": "归根结底", "is_correct": true, "explanation": "正确：“归根结底”引出最终的根本道理，与“我们还是要靠自己”相符。"}, {"text": "已经", "is_correct": false, "explanation": "体貌：“已经”表示动作已经完成，与这里的根本道理不相符。"}], "explanations": {"忽然": "语义：“忽然”表示突然，与后面的原则性论断“我们还是要靠自己”不相符。", "立刻": "语义：“立刻”表示马上，句子是在说根本的道理，不是立即的动作。", "归根结底": "正确：“归根结底”引出最终的根本道理，与“我们还是要靠自己”相符。", "已经": "体貌：“已经”表示动作已经完成，与这里的根本道理不相符。"}, "sentence_index": 0, "correct_answer": "归根结底"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个箱子归根结底有五公斤重。", "explanation": "这里应该用〈大约〉。“归根结底”表示归结到根本，不用于估计数量。"}, {"text": "归根结底！我找到钥匙了！", "explanation": "这里应该用〈终于〉。“归根结底”表示归结到根本，不用于表示终于达成时的感叹。"}, {"text": "归根结底，请大家坐好。", "explanation": "这里应该用〈现在〉。“归根结底”表示归结到根本，不用于提示当下的时间或指令。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54c86b3-c290-4d8b-95c6-0bc26c161b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27174, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偶然", "is_correct": false, "explanation": "语义：“偶然”表示碰巧，与“生病是因为穿得太少”的因果归纳不相符。"}, {"text": "猛然", "is_correct": false, "explanation": "搭配：“猛然”多用于突然的动作或发现，不与这种因果归纳搭配。"}, {"text": "当场", "is_correct": false, "explanation": "语义：“当场”指在现场，与句子所说的原因无关，句子不通。"}, {"text": "归根结底", "is_correct": true, "explanation": "正确：“归根结底”引出生病的根本原因，与“穿得太少”的语境相符。"}], "explanations": {"偶然": "语义：“偶然”表示碰巧，与“生病是因为穿得太少”的因果归纳不相符。", "猛然": "搭配：“猛然”多用于突然的动作或发现，不与这种因果归纳搭配。", "当场": "语义：“当场”指在现场，与句子所说的原因无关，句子不通。", "归根结底": "正确：“归根结底”引出生病的根本原因，与“穿得太少”的语境相符。"}, "sentence_index": 6, "correct_answer": "归根结底"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我归根结底喝两杯咖啡。", "explanation": "这里应该用〈通常〉。“归根结底”表示归结到根本，不用于表示动作的频率。"}, {"text": "我们先吃饭，归根结底再去看电影。", "explanation": "这里应该用〈然后〉。“归根结底”表示归结到根本，不表示动作的先后顺序。"}, {"text": "这朵花归根结底很红。", "explanation": "这里应该用〈非常〉。“归根结底”表示归结到根本，不表示程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54c86b3-c290-4d8b-95c6-0bc26c161b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27174, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的失败，归根结底他自己的错误。", "corrected_sentence": "他的失败，归根结底是他自己的错误。", "error_description": "错误：“归根结底”后漏掉判断词“是”，写成“归根结底他自己的错误”。正确应为“归根结底是他自己的错误”，“归根结底”引出的判断句需要“是”连接。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54c86b3-c290-4d8b-95c6-0bc26c161b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27174, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次考试没过，归根结底，归根结底是他没复习。", "corrected_sentence": "这次考试没过，归根结底是他没复习。", "error_description": "错误：“归根结底”重复出现了两次。只需在句中出现一次，正确应为“归根结底是他没复习”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54c86b3-c290-4d8b-95c6-0bc26c161b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
