INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27176, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "容易因为一点小事就生气或者难过。", "primary_collocate": null, "pronunciation": "mǐn gǎn", "ipa": "min˨˩˦ kan˨˩˦", "syllable_count": 2, "sentences": [{"text": "她是个很敏感的人。", "target_word": "敏感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对别人的话特别敏感。", "target_word": "敏感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子比较敏感，你别说得太重。", "target_word": "敏感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一说到考试，他就变得很敏感。", "target_word": "敏感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她太敏感了，一句玩笑也会哭。", "target_word": "敏感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别这么敏感，我只是随便说说。", "target_word": "敏感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的朋友很敏感，容易不开心。", "target_word": "敏感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对自己的身高很敏感。", "target_word": "敏感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "青春期的孩子往往很敏感。", "target_word": "敏感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为太敏感，她常常想很多。", "target_word": "敏感", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "敏感度", "label": "复合"}, {"form": "敏感性", "label": "复合"}], "register": "中性", "sense_fingerprint": "心思细，容易因小事情绪波动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d952261-361f-4475-b6c1-65e9db11d94e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27176, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "湿润", "is_correct": false, "explanation": "搭配：“湿润”多形容空气、土地或皮肤的水分，不能用来形容一个人的性格。"}, {"text": "敏感", "is_correct": true, "explanation": "“敏感”指容易因为小事而情绪受影响，与“很敏感的人”相符。"}, {"text": "嘹亮", "is_correct": false, "explanation": "语义：“嘹亮”形容声音清脆响亮，不能用来描写一个人的性格，句子读来不通。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：“潮湿”形容环境或物品，不能用于形容一个人。"}], "explanations": {"湿润": "搭配：“湿润”多形容空气、土地或皮肤的水分，不能用来形容一个人的性格。", "敏感": "“敏感”指容易因为小事而情绪受影响，与“很敏感的人”相符。", "嘹亮": "语义：“嘹亮”形容声音清脆响亮，不能用来描写一个人的性格，句子读来不通。", "潮湿": "搭配：“潮湿”形容环境或物品，不能用于形容一个人。"}, "sentence_index": 0, "correct_answer": "敏感"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件外套很敏感，穿起来很舒服。", "explanation": "这里应该用〈柔软〉。柔软形容织物的质地；“敏感”不用来形容衣物。"}, {"text": "这名运动员的动作很敏感，转身比别人快得多。", "explanation": "这里应该用〈敏捷〉。敏捷形容动作快而灵活；“敏感”不用来形容动作的快慢。"}, {"text": "他的思路很敏感，总能想出新办法。", "explanation": "这里应该用〈灵活〉。灵活形容思路、方法善于变通；“敏感”不用于形容思路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e43ab20-e93c-472d-8971-52aaf3267d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27176, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冰凉", "is_correct": false, "explanation": "搭配：“冰凉”形容温度或触感，不能用来描写朋友的性格。"}, {"text": "豁达", "is_correct": false, "explanation": "语义：“豁达”指心胸开阔、不计较，与后半句“容易不开心”相矛盾。"}, {"text": "干燥", "is_correct": false, "explanation": "搭配：“干燥”形容空气、皮肤或物体，不能用来说一个人很干燥。"}, {"text": "敏感", "is_correct": true, "explanation": "“敏感”指容易受小事影响，与“容易不开心”前后一致。"}], "explanations": {"冰凉": "搭配：“冰凉”形容温度或触感，不能用来描写朋友的性格。", "豁达": "语义：“豁达”指心胸开阔、不计较，与后半句“容易不开心”相矛盾。", "干燥": "搭配：“干燥”形容空气、皮肤或物体，不能用来说一个人很干燥。", "敏感": "“敏感”指容易受小事影响，与“容易不开心”前后一致。"}, "sentence_index": 6, "correct_answer": "敏感"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的目光很敏感，一眼就能看穿别人的心思。", "explanation": "这里应该用〈锐利〉。锐利形容目光、言辞尖锐有力；“敏感”不用来形容目光。"}, {"text": "她的文笔很敏感，描写得很有层次。", "explanation": "这里应该用〈细腻〉。细腻形容文笔、描写精细；“敏感”不用于形容文笔。"}, {"text": "他射击的准头很敏感，每一枪都中靶心。", "explanation": "这里应该用〈精准〉。精准形容动作或判断非常准确；“敏感”不用来形容准头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e43ab20-e93c-472d-8971-52aaf3267d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27176, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她别人的一个眼神就很敏感，常为此难过。", "corrected_sentence": "她对别人的一个眼神就很敏感，常为此难过。", "error_description": "错误：“敏感”所针对的对象要用介词“对”引出，应说“对别人的一个眼神就很敏感”，漏掉“对”就不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e43ab20-e93c-472d-8971-52aaf3267d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27176, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她对别人的话很敏感度，一点小事就会难过。", "corrected_sentence": "她对别人的话很敏感，一点小事就会难过。", "error_description": "错误：“敏感度”是名词，不能跟在“很”后面；形容词要说“很敏感”，应去掉“度”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e43ab20-e93c-472d-8971-52aaf3267d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
