INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27178, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "房屋、桥梁等建筑物中撑住重量的柱子。", "primary_collocate": null, "pronunciation": "zhī zhù", "ipa": "ʈʂɨ˥ ʈʂu˥˩", "syllable_count": 2, "sentences": [{"text": "这座桥有四根粗大的支柱。", "target_word": "支柱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子的支柱断了，屋顶掉了下来。", "target_word": "支柱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在检查大厅里的支柱，看有没有裂缝。", "target_word": "支柱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风一吹，帐篷的支柱就弯了。", "target_word": "支柱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用一根木头做帐篷的支柱。", "target_word": "支柱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请扶住这根支柱，不要让它倒下。", "target_word": "支柱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老房子的支柱是木头做的，已经很旧了。", "target_word": "支柱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地下室里有几根水泥支柱，撑着上面的楼。", "target_word": "支柱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把新的支柱放在桥下面。", "target_word": "支柱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震时，房子的支柱倒了，楼也塌了。", "target_word": "支柱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "根", "label": "量词"}, {"form": "精神支柱", "label": "复合"}, {"form": "支柱产业", "label": "复合"}], "register": "中性", "sense_fingerprint": "实物义：房屋、桥梁、帐篷等建筑物上撑住重量的柱子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2f8d72d-01b8-470d-9c8d-ddfe701976a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27178, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "支柱", "is_correct": true, "explanation": "正确答案：支柱（zhī zhù），指房屋、桥梁等建筑中撑住重量的柱子。"}, {"text": "止住", "is_correct": false, "explanation": "止（zhǐ，第三声）与支（zhī，第一声）声调不同，「止住」意思是停下来、制止。"}, {"text": "植株", "is_correct": false, "explanation": "植株（zhí zhū）与支柱两个音节声调都不同：zhí 为第二声，zhū 为第一声，意思是植物的整个株体。"}, {"text": "蜘蛛", "is_correct": false, "explanation": "蜘蛛（zhī zhū）与支柱只有第二个音节声调不同：zhū 为第一声，zhù 为第四声，意思是一种八条腿的小动物。"}], "explanations": {"支柱": "正确答案：支柱（zhī zhù），指房屋、桥梁等建筑中撑住重量的柱子。", "止住": "止（zhǐ，第三声）与支（zhī，第一声）声调不同，「止住」意思是停下来、制止。", "植株": "植株（zhí zhū）与支柱两个音节声调都不同：zhí 为第二声，zhū 为第一声，意思是植物的整个株体。", "蜘蛛": "蜘蛛（zhī zhū）与支柱只有第二个音节声调不同：zhū 为第一声，zhù 为第四声，意思是一种八条腿的小动物。"}, "sentence_index": null, "correct_answer": "支柱"}, "level_3": {"options": [{"text": "支柱", "is_correct": true, "explanation": "正确答案：「这座桥有四根粗大的支柱」指桥下撑住桥身的柱子，与「四根粗大的」搭配。"}, {"text": "花瓣", "is_correct": false, "explanation": "搭配：「粗大」不形容花瓣，花瓣也不用「根」来计量，与「四根粗大的」不搭。"}, {"text": "树枝", "is_correct": false, "explanation": "语义：桥上不会长出树枝，句中说的是桥的构件，树枝与桥的结构不相关。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：「钥匙」用「把」计量，不说「粗大的钥匙」，与「四根」也不搭配。"}], "explanations": {"支柱": "正确答案：「这座桥有四根粗大的支柱」指桥下撑住桥身的柱子，与「四根粗大的」搭配。", "花瓣": "搭配：「粗大」不形容花瓣，花瓣也不用「根」来计量，与「四根粗大的」不搭。", "树枝": "语义：桥上不会长出树枝，句中说的是桥的构件，树枝与桥的结构不相关。", "钥匙": "搭配：「钥匙」用「把」计量，不说「粗大的钥匙」，与「四根」也不搭配。"}, "sentence_index": 0, "correct_answer": "支柱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人把这块布当支柱，挂在屋顶下撑住房梁。", "explanation": "这里应该用〈木头〉。布撑不住重物，把布当作支柱是误用；支柱应是坚硬的木头或金属。"}, {"text": "这张桌子的支柱很平，上面可以放书。", "explanation": "这里应该用〈桌面〉。支柱是竖着撑住东西的，不是平的台面，不能说支柱很平。"}, {"text": "这块玻璃是窗户的支柱，阳光才能照进来。", "explanation": "这里应该用〈窗框〉。玻璃透光却承不了重，支柱要承重，撑住窗户的是窗框。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94806ba5-fdd3-4ab9-a20c-1bf54e573444') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27178, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "支柱", "is_correct": true, "explanation": "正确答案：支柱（zhī zhù），指房屋、桥梁等建筑中撑住重量的柱子。"}, {"text": "蜘蛛", "is_correct": false, "explanation": "蜘蛛（zhī zhū）与支柱只有第二个音节不同：zhū 为第一声，zhù 为第四声，意思是蜘蛛。"}, {"text": "资助", "is_correct": false, "explanation": "zī 与 zhī 声母不同（z 与 zh），声调相同，意思是资助、援助。"}, {"text": "制住", "is_correct": false, "explanation": "zhì（第四声）与 zhī（第一声）声调不同，意思是控制住、压制住。"}, {"text": "吃住", "is_correct": false, "explanation": "chī 与 zhī 声母不同（ch 与 zh），声调相同，意思是吃和住。"}], "explanations": {"支柱": "正确答案：支柱（zhī zhù），指房屋、桥梁等建筑中撑住重量的柱子。", "蜘蛛": "蜘蛛（zhī zhū）与支柱只有第二个音节不同：zhū 为第一声，zhù 为第四声，意思是蜘蛛。", "资助": "zī 与 zhī 声母不同（z 与 zh），声调相同，意思是资助、援助。", "制住": "zhì（第四声）与 zhī（第一声）声调不同，意思是控制住、压制住。", "吃住": "chī 与 zhī 声母不同（ch 与 zh），声调相同，意思是吃和住。"}, "sentence_index": null, "correct_answer": "支柱"}, "level_3": {"options": [{"text": "支柱", "is_correct": true, "explanation": "正确答案：「老房子的支柱是木头做的」指老房子里承重的木柱，与「木头做的」相合。"}, {"text": "发动机", "is_correct": false, "explanation": "语义：房子里没有发动机，句中说的是房屋的承重结构，「发动机」与此无关。"}, {"text": "玻璃", "is_correct": false, "explanation": "搭配：「是木头做的」不能用来说玻璃，玻璃一般不是木头做的。"}, {"text": "围巾", "is_correct": false, "explanation": "语义：围巾是穿戴的物品，不属于老房子的结构，句中说的是承重的柱子。"}], "explanations": {"支柱": "正确答案：「老房子的支柱是木头做的」指老房子里承重的木柱，与「木头做的」相合。", "发动机": "语义：房子里没有发动机，句中说的是房屋的承重结构，「发动机」与此无关。", "玻璃": "搭配：「是木头做的」不能用来说玻璃，玻璃一般不是木头做的。", "围巾": "语义：围巾是穿戴的物品，不属于老房子的结构，句中说的是承重的柱子。"}, "sentence_index": 6, "correct_answer": "支柱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这股烟是房子的支柱，能撑住屋顶。", "explanation": "这里应该用〈木头〉。烟没有承重能力，不能当支柱。"}, {"text": "这条河是桥的支柱，把桥撑在水上。", "explanation": "这里应该用〈桥墩〉。河流不能撑住桥身，支撑桥梁的是桥墩。"}, {"text": "这片云是房子的支柱，能挡住风雨。", "explanation": "这里应该用〈屋顶〉。云不能承重，支柱要撑住屋顶这类结构。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94806ba5-fdd3-4ab9-a20c-1bf54e573444') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27178, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座桥下有三只支柱。", "corrected_sentence": "这座桥下有三根支柱。", "error_description": "量词错误：支柱应该用量词「根」计量，说「三根支柱」。「只」多用于动物和成对的东西，不能用于支柱。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94806ba5-fdd3-4ab9-a20c-1bf54e573444') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27178, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把那块旧支柱换掉了。", "corrected_sentence": "工人把那根旧支柱换掉了。", "error_description": "量词错误：支柱应该用量词「根」计量，说「那根旧支柱」。「块」用于块状的东西，不能用于支柱。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94806ba5-fdd3-4ab9-a20c-1bf54e573444') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27180, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94806ba5-fdd3-4ab9-a20c-1bf54e573444') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
