INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27180, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "肉眼看不见的。", "primary_collocate": null, "pronunciation": "yǐn xíng", "ipa": "in˨˩ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这种墨水写的字是隐形的，要用光才看得见。", "target_word": "隐形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事里的魔法师有一件隐形的衣服。", "target_word": "隐形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子说他有一个隐形的朋友，我们都看不见他。", "target_word": "隐形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玻璃擦得太干净，好像是隐形的。", "target_word": "隐形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的小精灵一挥手，就变成隐形的了，大家都看不见她。", "target_word": "隐形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他穿上隐形的斗篷，别人就看不见他了。", "target_word": "隐形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黑猫在夜里几乎是隐形的，我们很难看见它。", "target_word": "隐形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上有一道隐形的门，只有他知道在哪里。", "target_word": "隐形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张纸上有隐形的字，我什么也看不见。", "target_word": "隐形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说他想变得隐形，这样就没人能看见他。", "target_word": "隐形", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "隱形", "label": "繁体"}, {"form": "隐形人", "label": "复合"}, {"form": "隐形眼镜", "label": "复合"}], "register": "中性", "sense_fingerprint": "字面上眼睛看不见的，如隐形的墨水、隐形的斗篷", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2f8d72d-01b8-470d-9c8d-ddfe701976a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27180, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "清晰", "is_correct": false, "explanation": "语义：“清晰”指看得很分明，与“要用光才看得见”矛盾。"}, {"text": "鲜艳", "is_correct": false, "explanation": "体貌：“鲜艳”描写颜色明亮，与字迹要用光才看见的情况相反。"}, {"text": "隐形", "is_correct": true, "explanation": "隐形：指眼睛看不见，与“要用光才看得见”相合。"}, {"text": "醒目", "is_correct": false, "explanation": "语义：“醒目”指引人注意，与字迹难以看见矛盾。"}], "explanations": {"清晰": "语义：“清晰”指看得很分明，与“要用光才看得见”矛盾。", "鲜艳": "体貌：“鲜艳”描写颜色明亮，与字迹要用光才看见的情况相反。", "隐形": "隐形：指眼睛看不见，与“要用光才看得见”相合。", "醒目": "语义：“醒目”指引人注意，与字迹难以看见矛盾。"}, "sentence_index": 0, "correct_answer": "隐形"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这盏灯的光很隐形，房间里一下子亮堂了。", "explanation": "这里应该用〈明亮〉。隐形 指看不见，与“房间一下子亮堂了”矛盾；灯光充足要用“明亮”。"}, {"text": "这辆车的颜色很隐形，远处一眼就能认出来。", "explanation": "这里应该用〈鲜艳〉。隐形 指看不见，与“远处一眼就能认出来”矛盾；颜色鲜亮要用“鲜艳”。"}, {"text": "这块布料的花纹很隐形，穿在身上特别显眼。", "explanation": "这里应该用〈鲜明〉。隐形 指看不见，与“特别显眼”矛盾；花纹对比强烈要用“鲜明”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94806ba5-fdd3-4ab9-a20c-1bf54e573444') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27180, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "显眼", "is_correct": false, "explanation": "语义：“显眼”指容易被看见，与“我们很难看见它”矛盾。"}, {"text": "隐形", "is_correct": true, "explanation": "隐形：指眼睛看不见，与“几乎……很难看见”相合。"}, {"text": "闪亮", "is_correct": false, "explanation": "语义：“闪亮”指光线明亮，与夜里几乎看不见的情境矛盾。"}, {"text": "庞大", "is_correct": false, "explanation": "语义：“庞大”指体积很大、容易看见，与“很难看见它”相矛盾。"}], "explanations": {"显眼": "语义：“显眼”指容易被看见，与“我们很难看见它”矛盾。", "隐形": "隐形：指眼睛看不见，与“几乎……很难看见”相合。", "闪亮": "语义：“闪亮”指光线明亮，与夜里几乎看不见的情境矛盾。", "庞大": "语义：“庞大”指体积很大、容易看见，与“很难看见它”相矛盾。"}, "sentence_index": 6, "correct_answer": "隐形"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这栋高楼很隐形，站在几公里外就能望见。", "explanation": "这里应该用〈高耸〉。隐形 指看不见，与“几公里外就能望见”矛盾；建筑高大要用“高耸”。"}, {"text": "黑板上的字很隐形，全班都能看见。", "explanation": "这里应该用〈清晰〉。隐形 指看不见，与“全班都能看见”矛盾；字迹清楚要说“清晰”。"}, {"text": "那个红色标志很隐形，远处也能看到。", "explanation": "这里应该用〈醒目〉。隐形 指看不见，与“远处也能看到”矛盾；引人注意要用“醒目”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94806ba5-fdd3-4ab9-a20c-1bf54e573444') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27180, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件斗篷是隐形地，谁也看不见他。", "corrected_sentence": "这件斗篷是隐形的，谁也看不见他。", "error_description": "“隐形”作谓语（“是”之后）要用“的”，不能用“地”。应说“是隐形的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94806ba5-fdd3-4ab9-a20c-1bf54e573444') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27180, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "墙上有一道隐形地门，外人根本找不到。", "corrected_sentence": "墙上有一道隐形的门，外人根本找不到。", "error_description": "定语错误：“隐形”修饰名词“门”时用“的”，不能用“地”。应说“隐形的门”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94806ba5-fdd3-4ab9-a20c-1bf54e573444') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
