INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27182, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "表示‘是不是’的意思。", "primary_collocate": null, "pronunciation": "yǔ fǒu", "ipa": "y˨˩ fou˨˩", "syllable_count": 2, "sentences": [{"text": "参加与否，请在明天前告诉老师。", "target_word": "与否", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨与否，我们明天都出发。", "target_word": "与否", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你喜欢与否，我都要说实话。", "target_word": "与否", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "合格与否，要看考试成绩。", "target_word": "与否", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个办法有用与否，试试就知道。", "target_word": "与否", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃早饭与否，对身体影响很大。", "target_word": "与否", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "答应与否，是你自己的事。", "target_word": "与否", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "方便与否，请你先说一声。", "target_word": "与否", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "成绩好与否，爸爸都支持我。", "target_word": "与否", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有钱与否，做人都要诚实。", "target_word": "与否", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "與否", "label": "繁体"}], "register": "书面", "sense_fingerprint": "跟在词语后，表示是不是", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f0f8b3d-3b38-41b9-91fd-9b8b797a5035') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27182, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "与否", "is_correct": true, "explanation": "正确：“参加与否”表示“是否参加”，与后面的“请在明天前告诉老师”呼应。"}, {"text": "反对", "is_correct": false, "explanation": "语义：“参加”与“反对”意思相反，“参加反对”说不通。"}, {"text": "拒绝", "is_correct": false, "explanation": "配价：“拒绝”要带动作宾语，应说“拒绝参加”，这里语序不对。"}, {"text": "离开", "is_correct": false, "explanation": "搭配：“参加离开”不成词组，“离开”不能与“参加”组成这样的结构。"}], "explanations": {"与否": "正确：“参加与否”表示“是否参加”，与后面的“请在明天前告诉老师”呼应。", "反对": "语义：“参加”与“反对”意思相反，“参加反对”说不通。", "拒绝": "配价：“拒绝”要带动作宾语，应说“拒绝参加”，这里语序不对。", "离开": "搭配：“参加离开”不成词组，“离开”不能与“参加”组成这样的结构。"}, "sentence_index": 0, "correct_answer": "与否"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一定合格与否，你不用担心。", "explanation": "语义：“与否”表示结果未定、两种情况都有可能，说话人若已确定，就不能用它。这里应直接说“他一定合格”。"}, {"text": "他上次考试已经合格与否，大家都知道了。", "explanation": "语义：“与否”用于尚未确定的情况，“已经”说明结果已经确定，不能用“与否”。"}, {"text": "他必须获胜与否，我们都支持他。", "explanation": "语义：“与否”表示结果还未确定，“必须获胜”表示一定要赢，两者意思相反。这里应直接说“他必须获胜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54c86b3-c290-4d8b-95c6-0bc26c161b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27182, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "与否", "is_correct": true, "explanation": "正确：“答应与否”表示“是否答应”，与后面“是你自己的事”呼应。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“答应讨厌”意思矛盾，“答应”表示同意，与“讨厌”的态度不相容。"}, {"text": "哭", "is_correct": false, "explanation": "搭配：“答应”后不能直接接“哭”作为决定的内容，这里搭配不通。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“答应摔”意思不通，“摔”与“答应”表示的意思没有关系。"}], "explanations": {"与否": "正确：“答应与否”表示“是否答应”，与后面“是你自己的事”呼应。", "讨厌": "语义：“答应讨厌”意思矛盾，“答应”表示同意，与“讨厌”的态度不相容。", "哭": "搭配：“答应”后不能直接接“哭”作为决定的内容，这里搭配不通。", "摔": "语义：“答应摔”意思不通，“摔”与“答应”表示的意思没有关系。"}, "sentence_index": 6, "correct_answer": "与否"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我已经吃过饭与否，你不用再问了。", "explanation": "语义：“与否”表示结果未定，“已经吃过饭”说明已经确定，两者矛盾，应直接说“我已经吃过饭了”。"}, {"text": "他一定能通过与否，我们都替他高兴。", "explanation": "语义：“一定能通过”表示有把握，与“与否”表示的未定之义矛盾，应直接说“他一定能通过”。"}, {"text": "妈妈肯定同意与否，我们都要去。", "explanation": "语义：“肯定同意”已有确定答案，不能再用“与否”，应直接说“妈妈肯定同意”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54c86b3-c290-4d8b-95c6-0bc26c161b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27182, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天的比赛参加与否了，请尽快回复。", "corrected_sentence": "明天的比赛参加与否，请尽快回复。", "error_description": "“参加与否”后面不能加“了”，应写作“明天的比赛参加与否，请尽快回复”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54c86b3-c290-4d8b-95c6-0bc26c161b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27182, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批产品很合格与否，要经过检验。", "corrected_sentence": "这批产品合格与否，要经过检验。", "error_description": "搭配：“与否”前的状态词不能受“很”修饰，应说“合格与否”，不能说“很合格与否”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54c86b3-c290-4d8b-95c6-0bc26c161b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
