INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27186, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指示器是告诉我们某样东西状态的工具。", "primary_collocate": null, "pronunciation": "zhǐ shì qì", "ipa": "ʈʂɨ˨˩ ʂɨ˥˩ tɕʰi˥˩", "syllable_count": 3, "sentences": [{"text": "温度指示器显示今天很热。", "target_word": "指示器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个指示器能告诉我们水够不够。", "target_word": "指示器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车上的指示器亮了，要加油了。", "target_word": "指示器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸给车买了一个新指示器。", "target_word": "指示器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "门口的指示器是绿色的，表示里面没人。", "target_word": "指示器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用指示器看电池还有多少电。", "target_word": "指示器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "指示器坏了，机器就不好用了。", "target_word": "指示器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天看着指示器，检查机器。", "target_word": "指示器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种指示器很便宜，也很好用。", "target_word": "指示器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "湿度指示器变成了红色。", "target_word": "指示器", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "告诉人东西状态的工具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f0f8b3d-3b38-41b9-91fd-9b8b797a5035') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27186, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "指示器", "is_correct": true, "explanation": "正确：“温度指示器”指显示温度的装置，与“显示今天很热”搭配通顺。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：“花瓶”不能显示温度，“温度花瓶显示今天很热”意思不通。"}, {"text": "农民", "is_correct": false, "explanation": "语义：“农民”是人，不能显示温度，这里说不通。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“温度”通常修饰仪器或天气，不能修饰“书包”。"}], "explanations": {"指示器": "正确：“温度指示器”指显示温度的装置，与“显示今天很热”搭配通顺。", "花瓶": "语义：“花瓶”不能显示温度，“温度花瓶显示今天很热”意思不通。", "农民": "语义：“农民”是人，不能显示温度，这里说不通。", "书包": "搭配：“温度”通常修饰仪器或天气，不能修饰“书包”。"}, "sentence_index": 0, "correct_answer": "指示器"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工程师用指示器剪了一块布。", "explanation": "这里应该用〈剪刀〉。指示器是显示状态的工具，不能用来剪东西。"}, {"text": "妈妈戴上指示器，出门去买菜了。", "explanation": "这里应该用〈帽子〉。指示器是显示状态的装置，不能戴在头上。"}, {"text": "他每天给指示器浇水。", "explanation": "语义：指示器是工具，不是植物，不能浇水，这里应换成〈花〉之类的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54c86b3-c290-4d8b-95c6-0bc26c161b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27186, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "指示器", "is_correct": true, "explanation": "正确：“指示器坏了”说明装置出故障，与后面“机器不好用”呼应。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空坏了”意思不通，天空不会因为故障而“坏”。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情坏了”指情绪不好，与“机器不好用”的因果关系不通。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“作业”不能说“坏了”，这里搭配不通。"}], "explanations": {"指示器": "正确：“指示器坏了”说明装置出故障，与后面“机器不好用”呼应。", "天空": "语义：“天空坏了”意思不通，天空不会因为故障而“坏”。", "心情": "语义：“心情坏了”指情绪不好，与“机器不好用”的因果关系不通。", "作业": "搭配：“作业”不能说“坏了”，这里搭配不通。"}, "sentence_index": 6, "correct_answer": "指示器"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "门口的指示器跑过来迎接我。", "explanation": "这里应该用〈保安〉。指示器是显示状态的装置，不会跑来迎接人。"}, {"text": "这个指示器很甜，我们都爱吃。", "explanation": "语义：指示器是显示状态的工具，不是食物，不能吃，这里应换成〈饼干〉这类食物。"}, {"text": "他用指示器烧开了一锅水。", "explanation": "语义：指示器只用来显示状态，不能加热，这里应换成〈电热水壶〉这类能加热的器具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54c86b3-c290-4d8b-95c6-0bc26c161b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27186, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "检查完以后，指示器们慢慢亮起来了。", "corrected_sentence": "检查完以后，指示器慢慢亮起来了。", "error_description": "错误：“们”只用于指人或有生命的事物，“指示器”是器物，不能加“们”，应去掉“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54c86b3-c290-4d8b-95c6-0bc26c161b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27186, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人每天看着指示器着，检查机器运转。", "corrected_sentence": "工人每天看着指示器，检查机器运转。", "error_description": "“着”附在动词后表示动作持续，不能附在名词“指示器”后，应写作“看着指示器”，删去多余的“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54c86b3-c290-4d8b-95c6-0bc26c161b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
