INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27188, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27188, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "做工作的人。", "primary_collocate": null, "pronunciation": "gōng zuò zhě", "ipa": "kʊŋ˥ tswɔ˥˩ ʈʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "他是一个认真的工作者。", "target_word": "工作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的工作者都很友好。", "target_word": "工作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个工作者都应该得到尊重。", "target_word": "工作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是公司里最努力的工作者。", "target_word": "工作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些工作者每天很早就来上班。", "target_word": "工作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的工作者会不断学习。", "target_word": "工作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一名年轻的工作者。", "target_word": "工作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作者需要休息，也需要运动。", "target_word": "工作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是一位很有经验的工作者。", "target_word": "工作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该感谢辛苦的工作者。", "target_word": "工作者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "科技工作者", "label": "复合词"}, {"form": "医务工作者", "label": "复合词"}], "register": "中性", "sense_fingerprint": "工作者：做工作的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884d9f3f-532e-4ab3-9ab1-95e22aa6b1de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27188, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工作者", "is_correct": true, "explanation": "工作者指做工作的人，可以用“认真”修饰。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有意志，不能“认真”。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不是能够认真的人。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“他是……”要求指人，“作业”是物，不能作为人的身份，句意不通。"}], "explanations": {"工作者": "工作者指做工作的人，可以用“认真”修饰。", "石头": "语义：石头没有意志，不能“认真”。", "冰箱": "语义：冰箱是家用电器，不是能够认真的人。", "作业": "语义：“他是……”要求指人，“作业”是物，不能作为人的身份，句意不通。"}, "sentence_index": 0, "correct_answer": "工作者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们厂新来了一辆工作者。", "explanation": "这里应该用〈名〉或〈位〉。辆用于车辆，不用于人，工作者指人。"}, {"text": "工作者师傅教我们怎么操作机器。", "explanation": "这里应该用〈工人〉。工作者泛指做工作的人，不能与“师傅”这类称呼搭配。"}, {"text": "这台机器是厂里最好的工作者。", "explanation": "这里不应指物。工作者指做工作的人，机器这里应说“设备”或“工具”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27188, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工作者", "is_correct": true, "explanation": "工作者指做工作的人，可以用“年轻”修饰。"}, {"text": "老人", "is_correct": false, "explanation": "语义：“年轻”与“老人”矛盾，句子不成立。"}, {"text": "婴儿", "is_correct": false, "explanation": "搭配：“年轻”不用于形容婴儿。"}, {"text": "古人", "is_correct": false, "explanation": "语义：“古人”早已故去，与“年轻”矛盾，句子说的是在世的工作者。"}], "explanations": {"工作者": "工作者指做工作的人，可以用“年轻”修饰。", "老人": "语义：“年轻”与“老人”矛盾，句子不成立。", "婴儿": "搭配：“年轻”不用于形容婴儿。", "古人": "语义：“古人”早已故去，与“年轻”矛盾，句子说的是在世的工作者。"}, "sentence_index": 6, "correct_answer": "工作者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只小猫是我们家的工作者。", "explanation": "这里应该用〈宠物〉。工作者指做工作的人，小猫是动物，不能算工作者。"}, {"text": "这份工作者很辛苦，但很有意思。", "explanation": "这里应该用〈职业〉。职业指一个人长期从事的工作类别，应说“这份职业很辛苦”；工作者指做工作的人，不能用来指这份职业。"}, {"text": "这支笔是我最好的工作者。", "explanation": "这里不应指物。工作者指做工作的人，笔不能算工作者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27188, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一只认真的工作者。", "corrected_sentence": "他是一位认真的工作者。", "error_description": "量词错误：“只”用于动物等，指人应说“一位”或“一名”，应改为“他是一位认真的工作者。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27188, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是一位年轻的工作者们。", "corrected_sentence": "他是一位年轻的工作者。", "error_description": "错误：“们”表示复数，不能与“一位”同时使用。正确：“一位年轻的工作者”，去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
