INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27190, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "帮别人做事情。", "primary_collocate": null, "pronunciation": "xié zhù", "ipa": "ɕi̯ɛ˧˥ ʈʂu˥˩", "syllable_count": 2, "sentences": [{"text": "他协助朋友处理了搬家的事务。", "target_word": "协助", "complexity_tier": "T3", "furigana": "tā xiézhù péngyou chǔ lǐ le bānjiā de shìwù", "sentence_source": "generated"}, {"text": "学生们协助交警维持路口的秩序。", "target_word": "协助", "complexity_tier": "T3", "furigana": "xuéshengmen xiézhù jiāojǐng wéichí lùkǒu de zhìxù", "sentence_source": "generated"}, {"text": "她协助妈妈准备了一桌好菜。", "target_word": "协助", "complexity_tier": "T3", "furigana": "tā xiézhù māma zhǔnbèi le yì zhuō hǎo cài", "sentence_source": "generated"}, {"text": "志愿者协助医院照顾病人。", "target_word": "协助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "如果你需要，我可以协助你办手续。", "target_word": "协助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥协助爸爸完成了这项维修工作。", "target_word": "协助", "complexity_tier": "T3", "furigana": "gēge xiézhù bàba wánchéng le zhè xiàng wéixiū gōngzuò", "sentence_source": "generated"}, {"text": "邻居协助我寻找走失的小狗。", "target_word": "协助", "complexity_tier": "T3", "furigana": "línjū xiézhù wǒ xúnzhǎo zǒushī de xiǎo gǒu", "sentence_source": "generated"}, {"text": "请你协助我整理一下这批文件。", "target_word": "协助", "complexity_tier": "T3", "furigana": "qǐng nǐ xiézhù wǒ zhěnglǐ yíxià zhè pī wénjiàn", "sentence_source": "generated"}, {"text": "他每天协助老师发作业。", "target_word": "协助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们协助大家打扫了公园。", "target_word": "协助", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "协助了", "label": "体标（完成）"}, {"form": "协助过", "label": "体标（经历）"}], "register": "书面", "sense_fingerprint": "协助：帮别人做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884d9f3f-532e-4ab3-9ab1-95e22aa6b1de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27190, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "协助", "is_correct": true, "explanation": "协助（xié zhù）：帮别人做事情。"}, {"text": "截住", "is_correct": false, "explanation": "jié 与 xié 声母不同（j 与 x），“截住”意思是拦住。"}, {"text": "邪术", "is_correct": false, "explanation": "shù 与 zhù 声母不同（sh 与 zh），“邪术”意思是邪门的法术。"}, {"text": "鞋子", "is_correct": false, "explanation": "鞋子（xié zi）：穿在脚上的东西。第二字 zi 与 zhù 的声母与声调都不同（z 与 zh）。"}], "explanations": {"协助": "协助（xié zhù）：帮别人做事情。", "截住": "jié 与 xié 声母不同（j 与 x），“截住”意思是拦住。", "邪术": "shù 与 zhù 声母不同（sh 与 zh），“邪术”意思是邪门的法术。", "鞋子": "鞋子（xié zi）：穿在脚上的东西。第二字 zi 与 zhù 的声母与声调都不同（z 与 zh）。"}, "sentence_index": null, "correct_answer": "协助"}, "level_3": {"options": [{"text": "协助", "is_correct": true, "explanation": "协助：帮朋友处理搬家的事务，正合语境。"}, {"text": "原谅", "is_correct": false, "explanation": "配价：“原谅”的宾语是人或过错，不能带“处理搬家的事务”。"}, {"text": "阻止", "is_correct": false, "explanation": "语义：“阻止”是妨碍，与“帮朋友处理事务”的语境相反。"}, {"text": "参观", "is_correct": false, "explanation": "配价：“参观”的宾语应是场所或展品，不能带“处理搬家的事务”这样的动作。"}], "explanations": {"协助": "协助：帮朋友处理搬家的事务，正合语境。", "原谅": "配价：“原谅”的宾语是人或过错，不能带“处理搬家的事务”。", "阻止": "语义：“阻止”是妨碍，与“帮朋友处理事务”的语境相反。", "参观": "配价：“参观”的宾语应是场所或展品，不能带“处理搬家的事务”这样的动作。"}, "sentence_index": 0, "correct_answer": "协助"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "士兵协助祖国的尊严。", "explanation": "这里应该用〈捍卫〉。协助指帮别人办事，不用于守护尊严这类抽象对象。"}, {"text": "奶奶细心协助我的感冒。", "explanation": "这里应该用〈照顾〉。协助指帮别人做具体的事，感冒是病，不能被协助，应说照顾。"}, {"text": "老板始终协助我的想法。", "explanation": "这里应该用〈支持〉。协助指帮别人做事，不用于对想法表示赞同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27190, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "协助", "is_correct": true, "explanation": "协助：邻居帮我找小狗，正合语境。"}, {"text": "煮", "is_correct": false, "explanation": "配价：“煮”的宾语是食物，不能带“我寻找走失的小狗”这样的动作短语。"}, {"text": "缝", "is_correct": false, "explanation": "配价：“缝”的宾语是布料或衣物，不能带动作短语，句意说不通。"}, {"text": "擦", "is_correct": false, "explanation": "配价：“擦”的宾语是有形的表面或物品，不能带“我寻找走失的小狗”这样的动作短语。"}], "explanations": {"协助": "协助：邻居帮我找小狗，正合语境。", "煮": "配价：“煮”的宾语是食物，不能带“我寻找走失的小狗”这样的动作短语。", "缝": "配价：“缝”的宾语是布料或衣物，不能带动作短语，句意说不通。", "擦": "配价：“擦”的宾语是有形的表面或物品，不能带“我寻找走失的小狗”这样的动作短语。"}, "sentence_index": 6, "correct_answer": "协助"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们协助远道而来的朋友喝了一杯茶。", "explanation": "这里应该用〈招待〉。协助是帮别人做事，请客喝茶应说招待，不能说协助。"}, {"text": "他协助了伤心妹妹的心情。", "explanation": "这里应该用〈安慰〉。协助指帮别人完成具体工作，不用于安抚情绪。"}, {"text": "老板协助员工的身体健康。", "explanation": "这里应该用〈关心〉。协助的对象是工作或事务，身体健康不能被协助。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27190, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他曾协助了过老师批改试卷。", "corrected_sentence": "他曾协助过老师批改试卷。", "error_description": "错误：“协助”后同时出现了“了”和“过”。正确：“协助过”，只用“过”表示曾经有过这种经历。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27190, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她常常协助的我整理文件。", "corrected_sentence": "她常常协助我整理文件。", "error_description": "错误：“协助”与“我”之间多加了“的”，“协助的我”不成立。正确：“协助我整理文件”，“我”直接作“协助”的宾语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27192, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27192, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27192, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "方法论就是教人怎么做事情的方法和道理。", "primary_collocate": null, "pronunciation": "fāng fǎ lùn", "ipa": "faŋ˥ fa˨˩˦ lwən˥˩", "syllable_count": 3, "sentences": [{"text": "我们要认真学习这套方法论，才能把事情做好。", "target_word": "方法论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "方法论教我们怎么做事情。", "target_word": "方法论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学方法论，可以让我们做事更有办法。", "target_word": "方法论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的方法论很简单，就是多练习。", "target_word": "方法论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，这是一种好的方法论。", "target_word": "方法论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做研究时，我们需要清楚的方法论。", "target_word": "方法论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个人解决问题的方法论都不一样。", "target_word": "方法论", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爸爸的方法论是：先想，再做。", "target_word": "方法论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听了这个故事，我懂了一种方法论。", "target_word": "方法论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们先学方法论，再做练习。", "target_word": "方法论", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种方法论", "label": "量词"}, {"form": "方法論", "label": "繁体"}], "register": "书面", "sense_fingerprint": "教人怎样做事的方法和道理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884d9f3f-532e-4ab3-9ab1-95e22aa6b1de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27192, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "方法论", "is_correct": true, "explanation": "正确：方法论是教人怎样做事的方法和道理，“学习这套……”正指这类内容。"}, {"text": "哭声", "is_correct": false, "explanation": "语义：“哭声”是哭的声音，不是可以学习的内容，“学习这套哭声”说不通。"}, {"text": "雨伞", "is_correct": false, "explanation": "搭配：“雨伞”是实物，不能被“学习”，句意说不通。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“脚步”是走路的动作，不是可以学习的内容，句意说不通。"}], "explanations": {"方法论": "正确：方法论是教人怎样做事的方法和道理，“学习这套……”正指这类内容。", "哭声": "语义：“哭声”是哭的声音，不是可以学习的内容，“学习这套哭声”说不通。", "雨伞": "搭配：“雨伞”是实物，不能被“学习”，句意说不通。", "脚步": "搭配：“脚步”是走路的动作，不是可以学习的内容，句意说不通。"}, "sentence_index": 0, "correct_answer": "方法论"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个方法论跑到了火车站。", "explanation": "这里应该用〈人〉作主语。方法论是抽象的道理，不会自己移动，不能跑到火车站。"}, {"text": "他的方法论打破了杯子。", "explanation": "这里应该用〈锤子〉作主语。锤子能打破东西；方法论是抽象的道理，不能去打破杯子。"}, {"text": "这次比赛，他的方法论拿了冠军。", "explanation": "这里应该用〈选手〉。拿冠军的是人或队伍；方法论是抽象的道理，不能参加比赛或获奖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27192, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "方法论", "is_correct": true, "explanation": "正确：方法论是做事的方法和道理，“每个人解决问题的方法论都不一样”说得通。"}, {"text": "哭声", "is_correct": false, "explanation": "搭配：“解决问题的哭声”说不通，哭声不是解决问题的方式。"}, {"text": "电线", "is_correct": false, "explanation": "语义：“电线”是导电的物体，不能说“解决问题的电线”，句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是自然状况，不是解决问题的方式，句意不通。"}], "explanations": {"方法论": "正确：方法论是做事的方法和道理，“每个人解决问题的方法论都不一样”说得通。", "哭声": "搭配：“解决问题的哭声”说不通，哭声不是解决问题的方式。", "电线": "语义：“电线”是导电的物体，不能说“解决问题的电线”，句意不通。", "天气": "语义：“天气”是自然状况，不是解决问题的方式，句意不通。"}, "sentence_index": 6, "correct_answer": "方法论"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们先给方法论称重，再做练习。", "explanation": "这里应该用〈面粉〉。面粉有重量，可以称；方法论是抽象的道理，没有重量，不能称。"}, {"text": "我们先给方法论浇水，再做练习。", "explanation": "这里应该用〈花〉。花需要浇水；方法论是抽象的道理，不能浇水。"}, {"text": "我们先把方法论放进冰箱，再做练习。", "explanation": "这里应该用〈牛奶〉。牛奶是实物，可以放进冰箱；方法论是抽象的道理，不能放进冰箱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27192, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老师讲了一只很实用的方法论。", "corrected_sentence": "这位老师讲了一套很实用的方法论。", "error_description": "错误：量词“只”用错，“只”用于动物等。方法论是一整套道理，应用“套”。正确：这位老师讲了一套很实用的方法论。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27192, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把这套方法论学完过。", "corrected_sentence": "我们把这套方法论学完了。", "error_description": "体标错误：结果补语“学完”表示动作已完成，应用完成体“了”，不能用经历体“过”。正确：我们把这套方法论学完了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
