INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27202, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27202, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "假设就是心里想一个可能不是真的事情，就像玩游戏时先想好规则。", "primary_collocate": null, "pronunciation": "jiǎ shè", "ipa": "tɕja˨˩˦ ʂɤ˥˩", "syllable_count": 2, "sentences": [{"text": "我们先假设明天不下雨。", "target_word": "假设", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "假设你有一百块钱，你想买什么？", "target_word": "假设", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说：“假设这个数字是五。”", "target_word": "假设", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们先假设大家都会遵守规则。", "target_word": "假设", "complexity_tier": "T3", "furigana": "jiǎ shè", "sentence_source": "generated"}, {"text": "假设他不来，我们就自己开始吧。", "target_word": "假设", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她常常假设自己是一个小老师。", "target_word": "假设", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们假设地上是大海，不能踩到。", "target_word": "假设", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们不能随便假设别人在说谎。", "target_word": "假设", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "假设你是我，你会怎么做？", "target_word": "假设", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他先假设了一种情况，再慢慢想办法。", "target_word": "假设", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "假设了", "label": "完成体"}, {"form": "假设过", "label": "经历体"}, {"form": "假設", "label": "繁体"}], "register": "中性", "sense_fingerprint": "心里先想一种可能不真实的情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884d9f3f-532e-4ab3-9ab1-95e22aa6b1de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27202, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "假设", "is_correct": true, "explanation": "正确：假设是先认定明天不下雨为前提，与“先”字的句意相合。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”指清理场所，“明天不下雨”不是可以打扫的对象，句子说不通。"}, {"text": "感到", "is_correct": false, "explanation": "配价：“感到”后接情绪或感受，不接整件事情，不能说“感到明天不下雨”。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：“购买”后接商品，“明天不下雨”不能被购买。"}], "explanations": {"假设": "正确：假设是先认定明天不下雨为前提，与“先”字的句意相合。", "打扫": "语义：“打扫”指清理场所，“明天不下雨”不是可以打扫的对象，句子说不通。", "感到": "配价：“感到”后接情绪或感受，不接整件事情，不能说“感到明天不下雨”。", "购买": "搭配：“购买”后接商品，“明天不下雨”不能被购买。"}, "sentence_index": 0, "correct_answer": "假设"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈假设了一锅米饭。", "explanation": "这里应该用〈煮〉。煮是做饭的动作；假设是心里先想一种可能的情况，不能做出米饭。"}, {"text": "学校假设了一座新的食堂。", "explanation": "这里应该用〈建造〉。假设是心里认定某情况可能为真，不能用来建造食堂。"}, {"text": "他假设了一辆新车。", "explanation": "这里应该用〈购买〉。购买是付钱得到东西；假设是心里认定某情况可能为真，不能用来得到实物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27202, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "假设", "is_correct": true, "explanation": "正确：假设在这里表示孩子们把地上暂时当作大海，与句意相合。"}, {"text": "擦洗", "is_correct": false, "explanation": "语义：“擦洗”是清洁地面的动作，“地上是大海”不是可以擦洗的东西，句意说不通。"}, {"text": "修建", "is_correct": false, "explanation": "搭配：“修建”后接房屋、道路等建筑，不接“地上是大海”这样的判断。"}, {"text": "使用", "is_correct": false, "explanation": "配价：“使用”后接工具或物品，不接一个判断，句子说不通。"}], "explanations": {"假设": "正确：假设在这里表示孩子们把地上暂时当作大海，与句意相合。", "擦洗": "语义：“擦洗”是清洁地面的动作，“地上是大海”不是可以擦洗的东西，句意说不通。", "修建": "搭配：“修建”后接房屋、道路等建筑，不接“地上是大海”这样的判断。", "使用": "配价：“使用”后接工具或物品，不接一个判断，句子说不通。"}, "sentence_index": 6, "correct_answer": "假设"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上假设牙齿。", "explanation": "这里应该用〈刷〉。刷牙是清洁动作；假设是心里先想一种可能的情况，不能用于牙齿。"}, {"text": "工人假设了一条新的铁路。", "explanation": "这里应该用〈修建〉。修建是建造道路等设施；假设是心里认定某情况可能为真，不能用来建造铁路。"}, {"text": "法院假设了一份判决书。", "explanation": "这里应该用〈作出〉。假设是心里认定某情况可能为真，不能用来制作判决书；判决书需要依据证据作出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27202, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们先假设他明天会的来。", "corrected_sentence": "我们先假设他明天会来。", "error_description": "错误：“会”是助动词，其后不能加“的”，“会的来”不成立。正确：删去“的”，写成“他明天会来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27202, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们先假设着地上是大海。", "corrected_sentence": "孩子们先假设地上是大海。", "error_description": "错误：“假设”后接一个完整的情况（地上是大海）作宾语时，不能加持续体“着”。正确：删去“着”，说“孩子们先假设地上是大海”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
