INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27204, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "对人亲近，愿意和对方一起玩。", "primary_collocate": null, "pronunciation": "yǒu hǎo", "ipa": "joʊ˨˩ xɑʊ˨˩", "syllable_count": 2, "sentences": [{"text": "这只小狗对陌生人也很友好。", "target_word": "友好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家的猫很友好，喜欢和孩子玩。", "target_word": "友好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的小朋友对大家都很友好。", "target_word": "友好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只大狗看起来很友好。", "target_word": "友好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小男孩友好地和我一起玩球。", "target_word": "友好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居家的孩子很友好，常来找我玩。", "target_word": "友好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海豚是一种很友好的动物。", "target_word": "友好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只小马对孩子特别友好。", "target_word": "友好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的狗不凶，对小朋友很友好。", "target_word": "友好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很友好，一见面就拉着我去玩。", "target_word": "友好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "友好地", "label": "状语形式"}, {"form": "不友好", "label": "否定形式"}], "register": "通用", "sense_fingerprint": "孩子或小动物对人亲近、愿意一起玩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b4ede4-b5c5-47ad-9967-6cec6e48f26b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27204, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "友好", "is_correct": true, "explanation": "“友好”指小狗对人亲近，句中“对陌生人也”正与之相合。"}, {"text": "高", "is_correct": false, "explanation": "搭配：“很高”不能用来形容小狗对人的态度。"}, {"text": "新鲜", "is_correct": false, "explanation": "语义：“新鲜”形容食物等，不能形容小狗对人的态度。"}, {"text": "轻盈", "is_correct": false, "explanation": "语义：“轻盈”形容动作或身体轻巧，与对人的态度无关。"}], "explanations": {"友好": "“友好”指小狗对人亲近，句中“对陌生人也”正与之相合。", "高": "搭配：“很高”不能用来形容小狗对人的态度。", "新鲜": "语义：“新鲜”形容食物等，不能形容小狗对人的态度。", "轻盈": "语义：“轻盈”形容动作或身体轻巧，与对人的态度无关。"}, "sentence_index": 0, "correct_answer": "友好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只狗很友好，一口咬伤了路人。", "explanation": "这里应该用〈凶〉。“友好”指对人亲近、愿意一起玩，与“一口咬伤了路人”互相矛盾。"}, {"text": "这只猫很友好，一靠近就哈气。", "explanation": "这里应该用〈警惕〉。“友好”指对人亲近，与一靠近就哈气的戒备态度互相矛盾。"}, {"text": "这位老板很友好，从来不跟员工说话。", "explanation": "这里应该用〈高傲〉。“友好”指对人亲近、愿意相处，与从来不理员工的态度互相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48db653b-5390-420d-858d-9c25a581ed1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27204, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "友好", "is_correct": true, "explanation": "“友好”形容海豚对人亲近，符合句意。"}, {"text": "锋利", "is_correct": false, "explanation": "搭配：“锋利”形容刀刃等，不能用来形容动物的性情。"}, {"text": "干燥", "is_correct": false, "explanation": "语义：“干燥”指缺少水分，与动物的性情无关。"}, {"text": "坚硬", "is_correct": false, "explanation": "语义：“坚硬”指质地硬，与海豚的性情不符。"}], "explanations": {"友好": "“友好”形容海豚对人亲近，符合句意。", "锋利": "搭配：“锋利”形容刀刃等，不能用来形容动物的性情。", "干燥": "语义：“干燥”指缺少水分，与动物的性情无关。", "坚硬": "语义：“坚硬”指质地硬，与海豚的性情不符。"}, "sentence_index": 6, "correct_answer": "友好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很友好，经常推搡身边的孩子。", "explanation": "这里应该用〈粗暴〉。“友好”指对人亲近、愿意相处，与推搡孩子的态度互相矛盾。"}, {"text": "那个孩子很友好，谁也不理。", "explanation": "这里应该用〈冷漠〉。“友好”指对人亲近、愿意一起玩，与谁也不理的态度互相矛盾。"}, {"text": "两个孩子天天争抢玩具，互相很友好。", "explanation": "这里应该用〈不和〉。“友好”指对人亲近、愿意一起玩，与天天争抢玩具的状况互相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48db653b-5390-420d-858d-9c25a581ed1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27204, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只猫对生人从来没友好。", "corrected_sentence": "这只猫对生人从来不友好。", "error_description": "否定词用错：形容词“友好”的否定用“不”，应说“从来不友好”，不能说“从来没友好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48db653b-5390-420d-858d-9c25a581ed1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27204, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两个孩子友好的分享了玩具。", "corrected_sentence": "两个孩子友好地分享了玩具。", "error_description": "状语标记用错：修饰动词“分享”要用“地”，“友好的”是定语形式，应说“友好地分享”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48db653b-5390-420d-858d-9c25a581ed1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27206, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "远离", "is_correct": true, "explanation": "正确。“远离”与“趋近”构成反义，指距离越来越远。"}, {"text": "烘焙", "is_correct": false, "explanation": "无关：“烘焙”指用火烤制食品，与距离变化无关。"}, {"text": "缝补", "is_correct": false, "explanation": "无关：“缝补”指用针线修补衣物，与空间变化无反义关系。"}, {"text": "擦拭", "is_correct": false, "explanation": "无关：“擦拭”指用布等除去表面的污物，与“趋近”无反义关系。"}], "correct_answer": "远离", "explanations": {"远离": "正确。“远离”与“趋近”构成反义，指距离越来越远。", "烘焙": "无关：“烘焙”指用火烤制食品，与距离变化无关。", "缝补": "无关：“缝补”指用针线修补衣物，与空间变化无反义关系。", "擦拭": "无关：“擦拭”指用布等除去表面的污物，与“趋近”无反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb3844a-d98c-4257-86ea-b1110a3aa7df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27206, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "远离", "is_correct": true, "explanation": "正确。“远离”与“趋近”构成反义，指距离越来越远。"}, {"text": "装饰", "is_correct": false, "explanation": "无关：“装饰”指使事物美观，与距离变化无反义关系。"}, {"text": "翻译", "is_correct": false, "explanation": "无关：“翻译”指转换语言文字，与“趋近”无反义关系。"}, {"text": "运输", "is_correct": false, "explanation": "无关：“运输”指把物品从一处送到另一处，不构成与“趋近”的反义。"}], "correct_answer": "远离", "explanations": {"远离": "正确。“远离”与“趋近”构成反义，指距离越来越远。", "装饰": "无关：“装饰”指使事物美观，与距离变化无反义关系。", "翻译": "无关：“翻译”指转换语言文字，与“趋近”无反义关系。", "运输": "无关：“运输”指把物品从一处送到另一处，不构成与“趋近”的反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb3844a-d98c-4257-86ea-b1110a3aa7df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27206, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "慢慢靠近。", "primary_collocate": null, "pronunciation": "qū jìn", "ipa": "tɕʰy˥ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "小猫趋近盘子，闻了闻里面的鱼。", "target_word": "趋近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他趋近那扇门，听见里面有声音。", "target_word": "趋近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳落山，天色慢慢趋近黑暗。", "target_word": "趋近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们趋近山顶时，风越来越大。", "target_word": "趋近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人一步一步趋近河边。", "target_word": "趋近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一辆车慢慢趋近路口，司机踩了刹车。", "target_word": "趋近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子趋近妈妈，小声说了一句话。", "target_word": "趋近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船慢慢趋近岸边，大家开始收拾东西。", "target_word": "趋近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老鹰慢慢趋近草丛，眼睛盯着地面。", "target_word": "趋近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他慢慢趋近讲台，声音有点发抖。", "target_word": "趋近", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "趋近了", "label": "体标"}, {"form": "趋近过", "label": "体标"}], "register": "中性", "sense_fingerprint": "一点一点向某处靠近", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350e46f9-b0cc-46b5-afe7-c34cc96c73df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27206, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "趋近", "is_correct": true, "explanation": "正确。“小猫趋近盘子”指小猫慢慢靠近盘子，与后句的悠闲动作相合。"}, {"text": "熄灭", "is_correct": false, "explanation": "语义：“熄灭”用于火或灯，不能与“盘子”搭配，句子不通。"}, {"text": "逃离", "is_correct": false, "explanation": "语义：“逃离”指躲开某处，与后句“闻了闻里面的鱼”相矛盾。"}, {"text": "驶向", "is_correct": false, "explanation": "搭配：“驶”多用于车船，不说小猫“驶向”盘子。"}], "explanations": {"趋近": "正确。“小猫趋近盘子”指小猫慢慢靠近盘子，与后句的悠闲动作相合。", "熄灭": "语义：“熄灭”用于火或灯，不能与“盘子”搭配，句子不通。", "逃离": "语义：“逃离”指躲开某处，与后句“闻了闻里面的鱼”相矛盾。", "驶向": "搭配：“驶”多用于车船，不说小猫“驶向”盘子。"}, "sentence_index": 0, "correct_answer": "趋近"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座小屋趋近山顶，所以视野很好。", "explanation": "这里表示位置相近，应该用〈临近〉。趋近强调朝目标移动靠拢的过程，不用来说静止的位置关系。"}, {"text": "一阵风吹过，我们突然趋近了山顶。", "explanation": "这里表示“一下子靠近、瞬间到达”的意思。趋近强调慢慢靠拢的过程，不能用于瞬间完成的变化。"}, {"text": "两人的感情趋近了，常常一起去公园散步。", "explanation": "这里表示感情上的亲密，应该用〈亲近〉。趋近只指朝某个目标慢慢靠拢，不用来说感情的亲密。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb3844a-d98c-4257-86ea-b1110a3aa7df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27206, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "趋近", "is_correct": true, "explanation": "正确。“孩子趋近妈妈”指孩子慢慢走近妈妈，与后句“小声说了一句话”相合。"}, {"text": "撕碎", "is_correct": false, "explanation": "语义：“撕碎”指把物体扯成碎片，不能用于人，句子不通。"}, {"text": "悄悄", "is_correct": false, "explanation": "语法：副词“悄悄”不能作谓语带宾语“妈妈”，句子不通。"}, {"text": "驱赶", "is_correct": false, "explanation": "语义：“驱赶”指把人或动物赶走，与“趋近”的靠近义相反，也与“小声说话”不合。"}], "explanations": {"趋近": "正确。“孩子趋近妈妈”指孩子慢慢走近妈妈，与后句“小声说了一句话”相合。", "撕碎": "语义：“撕碎”指把物体扯成碎片，不能用于人，句子不通。", "悄悄": "语法：副词“悄悄”不能作谓语带宾语“妈妈”，句子不通。", "驱赶": "语义：“驱赶”指把人或动物赶走，与“趋近”的靠近义相反，也与“小声说话”不合。"}, "sentence_index": 6, "correct_answer": "趋近"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的身高趋近一米八，比同学都高。", "explanation": "这里表示数量的约数，应该用〈将近〉。趋近指朝某个目标靠拢，不用来表示数量的约数。"}, {"text": "这孩子趋近他父亲，连说话的样子都一样。", "explanation": "这里表示“相像”的意思。趋近只表示空间或状态上的靠拢，不能用来说人与人相像。"}, {"text": "压力一步步趋近他，他快要喘不过气了。", "explanation": "这里表示步步紧逼的压迫感，应该用〈逼近〉。趋近只指慢慢靠拢，不含压迫的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb3844a-d98c-4257-86ea-b1110a3aa7df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27206, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老牛慢慢趋近了把水边。", "corrected_sentence": "老牛慢慢趋近了水边。", "error_description": "错误：句中多了一个“把”。“趋近”直接带处所宾语“水边”，不需要也不能在动词后加“把”。改为“老牛慢慢趋近了水边”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb3844a-d98c-4257-86ea-b1110a3aa7df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27206, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小船曾经趋近着那片礁石。", "corrected_sentence": "小船曾经趋近过那片礁石。", "error_description": "错误：“着”表示持续的状态，与表示经历的“曾经”不搭配。正确：应用经历体“过”，写作“趋近过那片礁石”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb3844a-d98c-4257-86ea-b1110a3aa7df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
