INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27210, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "悖论是一个说法，听起来很对，但想下去却和自己打架。", "primary_collocate": null, "pronunciation": "bèi lùn", "ipa": "pei˥˩ luən˥˩", "syllable_count": 2, "sentences": [{"text": "这个悖论很难懂。", "target_word": "悖论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说了一个悖论，我想了半天。", "target_word": "悖论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这句话是悖论，听起来对，想下去却不对。", "target_word": "悖论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上写了一个悖论。", "target_word": "悖论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他最爱和朋友聊各种悖论。", "target_word": "悖论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个悖论让全班同学都笑了。", "target_word": "悖论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能说说这个悖论错在哪里吗？", "target_word": "悖论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友拿一个悖论考我，我一时答不上来。", "target_word": "悖论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书里有十个悖论。", "target_word": "悖论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我怎么也想不通这个悖论。", "target_word": "悖论", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "种", "label": "量词"}, {"form": "逻辑悖论", "label": "复合词"}], "register": "书面", "sense_fingerprint": "听起来对、细想却自相矛盾的说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f7f17ff-c32d-47a8-bf1e-867aef9f7341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27210, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "悖论", "is_correct": true, "explanation": "正确：“悖论”是抽象的命题，可以“难懂”，符合句子语境。"}, {"text": "西瓜", "is_correct": false, "explanation": "语义：“西瓜”是水果，不能被“很难懂”形容。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：“窗帘”是家居用品，不能被“很难懂”形容。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”是人的外形数值，不能被“难懂”描述。"}], "explanations": {"悖论": "正确：“悖论”是抽象的命题，可以“难懂”，符合句子语境。", "西瓜": "语义：“西瓜”是水果，不能被“很难懂”形容。", "窗帘": "语义：“窗帘”是家居用品，不能被“很难懂”形容。", "身高": "语义：“身高”是人的外形数值，不能被“难懂”描述。"}, "sentence_index": 0, "correct_answer": "悖论"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师在黑板上挂了一个悖论。", "explanation": "这里应该用〈照片〉。“挂”的对象是照片或画，悖论是抽象的命题，不能挂。"}, {"text": "老师在课上唱了一个悖论。", "explanation": "这里应该用〈歌〉。“唱”的对象是歌，悖论是抽象的命题，不能唱。"}, {"text": "他把那个悖论装进了纸箱。", "explanation": "这里应该用〈包裹〉。“装进纸箱”的对象是实物，悖论是抽象的命题，不能装箱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c165fc5-8ecb-4d31-a2d9-19aa7e835074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27210, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "悖论", "is_correct": true, "explanation": "正确：“悖论”是一种说法，可以判断对错、说出错在哪里，符合语境。"}, {"text": "手套", "is_correct": false, "explanation": "语义：“手套”是穿戴用品，不是可以判断对错的说法，不能“错在哪里”。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：“钢琴”是乐器，不是可以判断对错的内容。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”是数值，“错在哪里”一般用于说法或做法，不搭配。"}], "explanations": {"悖论": "正确：“悖论”是一种说法，可以判断对错、说出错在哪里，符合语境。", "手套": "语义：“手套”是穿戴用品，不是可以判断对错的说法，不能“错在哪里”。", "钢琴": "语义：“钢琴”是乐器，不是可以判断对错的内容。", "体重": "搭配：“体重”是数值，“错在哪里”一般用于说法或做法，不搭配。"}, "sentence_index": 6, "correct_answer": "悖论"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我怎么也吃不完这个悖论。", "explanation": "这里应该用〈苹果〉。“吃”的对象是食物，悖论是抽象的命题，不能吃。"}, {"text": "他把这个悖论种在花园里。", "explanation": "这里应该用〈种子〉。“种”的对象是种子或植物，悖论是命题，不能种。"}, {"text": "他去树下摘了一个悖论。", "explanation": "这里应该用〈苹果〉。“摘”的对象是果实、花等植物，悖论是抽象的命题，不能摘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c165fc5-8ecb-4d31-a2d9-19aa7e835074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27210, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把这只悖论讲了三遍。", "corrected_sentence": "他把这个悖论讲了三遍。", "error_description": "量词错误：“只”用于动物等，“悖论”是抽象的说法，量词应用“个”。应改为：他把这个悖论讲了三遍。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c165fc5-8ecb-4d31-a2d9-19aa7e835074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27210, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想了一整天，还是理不清这份悖论。", "corrected_sentence": "我想了一整天，还是理不清这个悖论。", "error_description": "“份”用于文件、礼物等，“悖论”是抽象的命题，量词应用“个”。应改为：我想了一整天，还是理不清这个悖论。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c165fc5-8ecb-4d31-a2d9-19aa7e835074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27214, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不同", "is_correct": true, "explanation": "“不同”与“相似”相对，指看起来差别大，是反义关系。"}, {"text": "复杂", "is_correct": false, "explanation": "“复杂”形容事物构成繁多，与“相似”没有反义关系。"}, {"text": "狭窄", "is_correct": false, "explanation": "“狭窄”形容空间小，与“相似”无关。"}, {"text": "冰冷", "is_correct": false, "explanation": "“冰冷”形容温度低，与“相似”没有反义关系。"}], "correct_answer": "不同", "explanations": {"不同": "“不同”与“相似”相对，指看起来差别大，是反义关系。", "复杂": "“复杂”形容事物构成繁多，与“相似”没有反义关系。", "狭窄": "“狭窄”形容空间小，与“相似”无关。", "冰冷": "“冰冷”形容温度低，与“相似”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c165fc5-8ecb-4d31-a2d9-19aa7e835074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27214, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不同", "is_correct": true, "explanation": "“不同”与“相似”相对，指看起来差别大，是反义关系。"}, {"text": "温暖", "is_correct": false, "explanation": "“温暖”形容温度或感受，与“相似”没有反义关系。"}, {"text": "辽阔", "is_correct": false, "explanation": "“辽阔”形容面积大，与“相似”无关。"}, {"text": "清脆", "is_correct": false, "explanation": "“清脆”形容声音清亮利落，与“相似”没有反义关系。"}], "correct_answer": "不同", "explanations": {"不同": "“不同”与“相似”相对，指看起来差别大，是反义关系。", "温暖": "“温暖”形容温度或感受，与“相似”没有反义关系。", "辽阔": "“辽阔”形容面积大，与“相似”无关。", "清脆": "“清脆”形容声音清亮利落，与“相似”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c165fc5-8ecb-4d31-a2d9-19aa7e835074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27214, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "两个东西很像，比如两个苹果看起来差不多。", "primary_collocate": null, "pronunciation": "xiāng sì", "ipa": "ɕjɑŋ˥ sɹ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这两个苹果很相似。", "target_word": "相似", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双胞胎长得非常相似。", "target_word": "相似", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两只小狗看起来很相似。", "target_word": "相似", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的包和你的包很相似。", "target_word": "相似", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两件衣服的颜色相似。", "target_word": "相似", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个杯子大小相似，我分不清。", "target_word": "相似", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们两个人的声音很相似。", "target_word": "相似", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两张照片太相似了。", "target_word": "相似", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟的帽子和我的帽子很相似。", "target_word": "相似", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个房间相似，都很小。", "target_word": "相似", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "相似度", "label": "复合词"}, {"form": "相似性", "label": "复合词"}], "register": "中性", "sense_fingerprint": "两个东西看起来很像", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f7f17ff-c32d-47a8-bf1e-867aef9f7341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27214, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相似", "is_correct": true, "explanation": "正确：“相似”形容两个东西看起来很像，符合句子语境。"}, {"text": "寂寞", "is_correct": false, "explanation": "语义：“寂寞”形容人的心情，苹果不能“寂寞”，与句意冲突。"}, {"text": "严肃", "is_correct": false, "explanation": "语义：“严肃”形容人的态度或场合，不能用来形容水果。"}, {"text": "粗壮", "is_correct": false, "explanation": "搭配：“粗壮”多用于树干或身躯，不说苹果很粗壮。"}], "explanations": {"相似": "正确：“相似”形容两个东西看起来很像，符合句子语境。", "寂寞": "语义：“寂寞”形容人的心情，苹果不能“寂寞”，与句意冲突。", "严肃": "语义：“严肃”形容人的态度或场合，不能用来形容水果。", "粗壮": "搭配：“粗壮”多用于树干或身躯，不说苹果很粗壮。"}, "sentence_index": 0, "correct_answer": "相似"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他和我相似十年了，是同班同学。", "explanation": "这里应该用〈相识〉。“相识”指彼此认识，“相似”指看起来很像，说认识多年要用“相识”。"}, {"text": "这两件外套完全相似，连颜色和扣子都一模一样。", "explanation": "这里应该用〈相同〉。“相似”指看起来像但有差别，完全一样要用“相同”。"}, {"text": "多年后我们终于相似了。", "explanation": "这里应该用〈相见〉。“相似”指事物有共同点，不指再次见面；分别多年后见到对方要用“相见”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c165fc5-8ecb-4d31-a2d9-19aa7e835074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27214, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相似", "is_correct": true, "explanation": "正确：“相似”形容两个人的声音接近，符合句意。"}, {"text": "高大", "is_correct": false, "explanation": "语义：“高大”形容体积或身材，不能形容声音。"}, {"text": "宽敞", "is_correct": false, "explanation": "语义：“宽敞”形容空间大，不能形容声音。"}, {"text": "修长", "is_correct": false, "explanation": "体貌：“修长”形容身材或外形，声音不能修长。"}], "explanations": {"相似": "正确：“相似”形容两个人的声音接近，符合句意。", "高大": "语义：“高大”形容体积或身材，不能形容声音。", "宽敞": "语义：“宽敞”形容空间大，不能形容声音。", "修长": "体貌：“修长”形容身材或外形，声音不能修长。"}, "sentence_index": 6, "correct_answer": "相似"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两个室友相似得很好，每天一起吃饭。", "explanation": "这里应该用〈相处〉。“相似”指事物有共同点，不能用来说人与人之间的相处。"}, {"text": "这两个房间相似很远，走过去要五分钟。", "explanation": "这里应该用〈相隔〉。“相似”指事物的共同点，不能表示空间距离。"}, {"text": "他们俩相似地看了看对方，谁也没说话。", "explanation": "这里应该用〈相视〉。“相视”指互相看，“相似”不能表示互看的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c165fc5-8ecb-4d31-a2d9-19aa7e835074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27214, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两件瓷器相似得。", "corrected_sentence": "这两件瓷器相似得很。", "error_description": "“相似”后用“得”引出补语时，补语不能缺少。“得”后面缺少补语“很”。应改为：这两件瓷器相似得很。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c165fc5-8ecb-4d31-a2d9-19aa7e835074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27214, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两条裙子看起来没相似。", "corrected_sentence": "这两条裙子看起来不相似。", "error_description": "“相似”是形容词，否定要用“不”，不用“没”。应改为：这两条裙子看起来不相似。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c165fc5-8ecb-4d31-a2d9-19aa7e835074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
