INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27218, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "有两个轴的东西。", "primary_collocate": null, "pronunciation": "shuāng zhóu", "ipa": "ʂuaŋ˥˥ ʈʂou˧˥", "syllable_count": 2, "sentences": [{"text": "这辆车有双轴。", "target_word": "双轴", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他买了一辆双轴的小车。", "target_word": "双轴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "单轴的太简单，我要双轴的。", "target_word": "双轴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台玩具车是双轴的。", "target_word": "双轴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人在修一辆双轴货车。", "target_word": "双轴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "双轴的机器更稳。", "target_word": "双轴", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这种双轴设计很常见。", "target_word": "双轴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟的小车是双轴的。", "target_word": "双轴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "双轴和单轴有什么不同？", "target_word": "双轴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们厂新买了双轴车床。", "target_word": "双轴", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "双轴：有两个轴的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c08a22b5-1600-4fdc-bce0-99a670ecd18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27218, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "双翼", "is_correct": false, "explanation": "语义：“双翼”指飞机的两层机翼，不是车的部件，这辆车没有。"}, {"text": "双腿", "is_correct": false, "explanation": "搭配：“双腿”用于人和动物，不能说车有双腿。"}, {"text": "双肺", "is_correct": false, "explanation": "语义：“双肺”是人或动物的器官，与车无关。"}, {"text": "双轴", "is_correct": true, "explanation": "双轴：指有两个轴的东西，是车的部件，与句中的“车”相符。"}], "explanations": {"双翼": "语义：“双翼”指飞机的两层机翼，不是车的部件，这辆车没有。", "双腿": "搭配：“双腿”用于人和动物，不能说车有双腿。", "双肺": "语义：“双肺”是人或动物的器官，与车无关。", "双轴": "双轴：指有两个轴的东西，是车的部件，与句中的“车”相符。"}, "sentence_index": 0, "correct_answer": "双轴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条围巾是双轴的，两面颜色不一样。", "explanation": "这里应该用〈双色〉。围巾两面颜色不同说“双色”；“双轴”指有两个轴的东西，不用于围巾。"}, {"text": "这条马路是双轴的，两边都能通车。", "explanation": "这里应该用〈双向〉。马路的两个行驶方向说“双向”；“双轴”指有两个轴的东西，不用于道路。"}, {"text": "这座桥是双轴的，上下都能通车。", "explanation": "这里应该用〈双层〉。桥的上下两层说“双层”，“双轴”指有两个轴的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b78d34-1ff3-4211-b59f-884fce69a9bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27218, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "珍品", "is_correct": false, "explanation": "语义：“珍品”指稀少的宝物，与“很常见”相悖。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”指人的身材高矮，“这种身高设计”不成话。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“体温”是身体的温度，不能说“体温设计”。"}, {"text": "双轴", "is_correct": true, "explanation": "双轴：指有两个轴的部件或东西，与“设计”搭配自然。"}], "explanations": {"珍品": "语义：“珍品”指稀少的宝物，与“很常见”相悖。", "身高": "搭配：“身高”指人的身材高矮，“这种身高设计”不成话。", "体温": "搭配：“体温”是身体的温度，不能说“体温设计”。", "双轴": "双轴：指有两个轴的部件或东西，与“设计”搭配自然。"}, "sentence_index": 6, "correct_answer": "双轴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电视是双轴的，两边都能看。", "explanation": "这里应该用〈双屏〉。电视的两块屏幕说“双屏”；“双轴”指有两个轴的东西，不用于电视。"}, {"text": "这口锅是双轴的，拿起来很方便。", "explanation": "这里应该用〈双耳〉。锅两侧的提手说“双耳”；“双轴”指有两个轴的东西，不用于锅。"}, {"text": "这件衣服是双轴的，穿起来很挺。", "explanation": "这里应该用〈双排扣〉。西装前襟两排纽扣说“双排扣”；“双轴”指有两个轴的东西，不用于衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b78d34-1ff3-4211-b59f-884fce69a9bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27218, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人已经修了好那辆双轴货车。", "corrected_sentence": "工人已经修好了那辆双轴货车。", "error_description": "补语位置错误：“修好”是动补结构，“了”应放在“好”之后，说“修好了”，不能说“修了好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b78d34-1ff3-4211-b59f-884fce69a9bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27218, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "师傅在修一只双轴拖车。", "corrected_sentence": "师傅在修一辆双轴拖车。", "error_description": "量词错误：车辆用“辆”，“一只双轴拖车”应说“一辆双轴拖车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b78d34-1ff3-4211-b59f-884fce69a9bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
