INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27220, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "词语用来讲一个东西有什么特点。", "primary_collocate": null, "pronunciation": "shǔ xìng", "ipa": "ʂu˨˩˦ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "形容词常常用来说明事物的属性。", "target_word": "属性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词表示的是人的属性。", "target_word": "属性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“红”这个词说的是花的属性。", "target_word": "属性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问：“大”说的是什么属性？", "target_word": "属性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请用一个词说说这只猫的属性。", "target_word": "属性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“软”和“硬”都是讲东西的属性。", "target_word": "属性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学过说明属性的词语。", "target_word": "属性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些词都是讲水果属性的。", "target_word": "属性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个句子里，“甜”是苹果的属性。", "target_word": "属性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用三个词写下了这本书的属性。", "target_word": "属性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种属性", "label": "量词"}, {"form": "一个属性", "label": "量词"}, {"form": "屬性", "label": "繁体"}], "register": "书面", "sense_fingerprint": "词语所说明的事物的特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c08a22b5-1600-4fdc-bce0-99a670ecd18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27220, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原因", "is_correct": false, "explanation": "语义：形容词说明的是事物的性质，不说明事情的原因。"}, {"text": "属性", "is_correct": true, "explanation": "属性指词语用来说明的事物特点，形容词就是用来说明这些的。"}, {"text": "门道", "is_correct": false, "explanation": "语域：“门道”是口语，不合书面的说明句。"}, {"text": "来源", "is_correct": false, "explanation": "语义：形容词说明的是性质，不说明事物的来源。"}], "explanations": {"原因": "语义：形容词说明的是事物的性质，不说明事情的原因。", "属性": "属性指词语用来说明的事物特点，形容词就是用来说明这些的。", "门道": "语域：“门道”是口语，不合书面的说明句。", "来源": "语义：形容词说明的是性质，不说明事物的来源。"}, "sentence_index": 0, "correct_answer": "属性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的属性在二楼。", "explanation": "这里应该用〈位置〉。“属性”指词语所说明的特点，房子所在的地方要用位置。"}, {"text": "这首歌的属性很好听。", "explanation": "这里应该用〈名字〉。“属性”指词语所说明的特点，歌名要用名字。"}, {"text": "这次考试的属性在三点。", "explanation": "这里应该用〈时间〉。“属性”指词语所说明的特点，考试的开始时间要用时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b78d34-1ff3-4211-b59f-884fce69a9bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27220, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "数字", "is_correct": false, "explanation": "语义：“数字”指数目，不是事物的特点，与句中“属性”所指不同。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：“黑板”是物体的名称，不是事物的特点，与句意不合。"}, {"text": "河流", "is_correct": false, "explanation": "语义：“河流”是事物本身，不是可以说明的特点，与句意不合。"}, {"text": "属性", "is_correct": true, "explanation": "属性指词语用来说明的事物特点，这句话说的正是这种词语。"}], "explanations": {"数字": "语义：“数字”指数目，不是事物的特点，与句中“属性”所指不同。", "黑板": "语义：“黑板”是物体的名称，不是事物的特点，与句意不合。", "河流": "语义：“河流”是事物本身，不是可以说明的特点，与句意不合。", "属性": "属性指词语用来说明的事物特点，这句话说的正是这种词语。"}, "sentence_index": 6, "correct_answer": "属性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的属性很有名。", "explanation": "这里应该用〈作者〉。“属性”指词语所说明的特点，写书的人要用作者。"}, {"text": "这本书的属性很便宜。", "explanation": "这里应该用〈价格〉。“属性”指词语所说明的特点，书的价钱要用价格。"}, {"text": "这本书的属性在书架上。", "explanation": "这里应该用〈位置〉。“属性”指词语所说明的特点，书放在哪里要用位置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b78d34-1ff3-4211-b59f-884fce69a9bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27220, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两个词各说明了一种属性的。", "corrected_sentence": "这两个词各说明了一种属性。", "error_description": "句末多出“的”，“一种属性”后面不能直接加“的”结束句子。错误形式：属性的；正确形式：属性。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b78d34-1ff3-4211-b59f-884fce69a9bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27220, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些词都是讲动物属性的的。", "corrected_sentence": "这些词都是讲动物属性的。", "error_description": "句末多出一个“的”，“属性的的”重复，句末应只保留一个“的”。错误形式：属性的的；正确形式：属性的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b78d34-1ff3-4211-b59f-884fce69a9bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
