INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27222, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "到某个时间为止。", "primary_collocate": null, "pronunciation": "jié zhì", "ipa": "tɕjɛ˧˥ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "截至本月底，请大家交一下材料。", "target_word": "截至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "截至明天中午，你都可以修改答案。", "target_word": "截至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "截至十二点，门口一共来了八个客人。", "target_word": "截至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "截至开学前，我已经看完了三本书。", "target_word": "截至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "截至上星期，我们班已经学了十课。", "target_word": "截至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "截至今晚，大家的作业都收好了。", "target_word": "截至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "截至六点，商店里的水果都卖完了。", "target_word": "截至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "截至去年冬天，他一直住在北京。", "target_word": "截至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "截至现在，你的成绩是班里第一。", "target_word": "截至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上报名截至周日晚上，过了这个时间就不能报了。", "target_word": "截至", "complexity_tier": "T3", "furigana": "wǎng shàng bào míng jié zhì zhōu rì wǎn shang, guò le zhè ge shí jiān jiù bù néng bào le.", "sentence_source": "generated"}], "morphological_forms": [{"form": "截至目前", "label": "固定搭配"}], "register": "书面语", "sense_fingerprint": "截至|介词|到某个时间为止", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d698ce0-810b-4db1-bf3a-88dde9784e24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27222, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "截至", "is_correct": true, "explanation": "正确：“截至”表示到某个时间为止，与“本月底”搭配，句意完整。"}, {"text": "按照", "is_correct": false, "explanation": "语义：“按照”表示依据或标准，与“本月底”这样的时间不搭配。"}, {"text": "凭", "is_correct": false, "explanation": "语义：“凭”表示依据，与“本月底”这样的时间词不搭配。"}, {"text": "把", "is_correct": false, "explanation": "配价：“把”后面要接受处置的对象，不能接时间词。"}], "explanations": {"截至": "正确：“截至”表示到某个时间为止，与“本月底”搭配，句意完整。", "按照": "语义：“按照”表示依据或标准，与“本月底”这样的时间不搭配。", "凭": "语义：“凭”表示依据，与“本月底”这样的时间词不搭配。", "把": "配价：“把”后面要接受处置的对象，不能接时间词。"}, "sentence_index": 0, "correct_answer": "截至"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "截至两个小时，我一直在写作业。", "explanation": "这里应该用〈持续〉。截至只表示到某个时间点为止，不能表示一段时间。"}, {"text": "截至这件事，我们需要讨论一下。", "explanation": "这里应该用〈关于〉。截至只能接时间点，不能用来引出讨论的话题。"}, {"text": "截至他家，我们走了半个小时。", "explanation": "这里应该用〈到〉。截至只接时间点，不能接地点；表示走到某个地方要说“到他家”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '499b1f08-7089-4fce-8232-e7e87bcbf736') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27222, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "截至", "is_correct": true, "explanation": "正确：“截至”表示到某个时间为止，与“六点”搭配，句意完整。"}, {"text": "对", "is_correct": false, "explanation": "搭配：“对”引出对象，不能接“六点”这样的时间词。"}, {"text": "把", "is_correct": false, "explanation": "配价：“把”后面要接受处置的对象，不能接时间词。"}, {"text": "替", "is_correct": false, "explanation": "语义：“替”表示代替他人，与时间词不搭配。"}], "explanations": {"截至": "正确：“截至”表示到某个时间为止，与“六点”搭配，句意完整。", "对": "搭配：“对”引出对象，不能接“六点”这样的时间词。", "把": "配价：“把”后面要接受处置的对象，不能接时间词。", "替": "语义：“替”表示代替他人，与时间词不搭配。"}, "sentence_index": 6, "correct_answer": "截至"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "截至门口，大家都排好了队。", "explanation": "这里应该用〈在〉。截至只接时间点，表示地点要说“在门口”。"}, {"text": "截至一年，他都在北京工作。", "explanation": "这里应该用〈持续〉。截至只接某个时间点，不能表示一段时间。"}, {"text": "截至天气，大家都换上了短袖。", "explanation": "这里应该用〈因为〉。截至接时间点，不能接原因；“因为天气热”才表示原因。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '499b1f08-7089-4fce-8232-e7e87bcbf736') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27222, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "截至的周五，大家都交完了材料。", "corrected_sentence": "截至周五，大家都交完了材料。", "error_description": "多余成分：“截至”是介词，后面直接接时间词，“周五”前不能加“的”，应说“截至周五，大家都交完了……”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '499b1f08-7089-4fce-8232-e7e87bcbf736') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27222, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "截至了晚上九点，店里还有人在工作。", "corrected_sentence": "截至晚上九点，店里还有人在工作。", "error_description": "时态标记错误：“截至”是介词，后面不能加“了”，应说“截至晚上九点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '499b1f08-7089-4fce-8232-e7e87bcbf736') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
