INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27232, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "加密技术是让秘密信息只能让想告诉的人看懂的方法。", "primary_collocate": null, "pronunciation": "jiā mì jì shù", "ipa": "tɕja˥ mi˥˩ tɕi˥˩ ʂu˥˩", "syllable_count": 4, "sentences": [{"text": "加密技术可以保护你的秘密。", "target_word": "加密技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了加密技术。", "target_word": "加密技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的手机用了加密技术，别人看不到信息。", "target_word": "加密技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了加密技术，朋友的消息更安全。", "target_word": "加密技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想学加密技术，做一个安全的软件。", "target_word": "加密技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "加密技术是让秘密信息变安全的方法。", "target_word": "加密技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上银行都要用加密技术。", "target_word": "加密技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种加密技术很难破解。", "target_word": "加密技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对加密技术很感兴趣。", "target_word": "加密技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校有一门讲加密技术的课。", "target_word": "加密技术", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "让秘密信息只有指定的人才能看懂的方法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350e46f9-b0cc-46b5-afe7-c34cc96c73df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27232, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不能保护秘密，句子不通。"}, {"text": "加密技术", "is_correct": true, "explanation": "正确。“加密技术可以保护你的秘密”，主语是能让信息只被指定的人看懂的方法。"}, {"text": "篮球", "is_correct": false, "explanation": "语义：篮球是运动器材，不能保护秘密。"}, {"text": "午饭", "is_correct": false, "explanation": "搭配：“保护秘密”的主语须是能保护信息的事物，“午饭”不能与“保护秘密”搭配。"}], "explanations": {"冰箱": "语义：冰箱不能保护秘密，句子不通。", "加密技术": "正确。“加密技术可以保护你的秘密”，主语是能让信息只被指定的人看懂的方法。", "篮球": "语义：篮球是运动器材，不能保护秘密。", "午饭": "搭配：“保护秘密”的主语须是能保护信息的事物，“午饭”不能与“保护秘密”搭配。"}, "sentence_index": 0, "correct_answer": "加密技术"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从口袋里掏出加密技术，打开了门。", "explanation": "此处应用〈钥匙〉。从口袋里掏出、用来开门的是“钥匙”；“加密技术”是方法，不能被掏出。"}, {"text": "他忘了银行加密技术，只好去柜台查询。", "explanation": "此处应用〈账号〉。去柜台查询的是自己忘了的银行账号；“加密技术”是银行保护信息的方法，不是个人要记住的东西。"}, {"text": "他出国前忘带加密技术，被拦在了机场。", "explanation": "此处应用〈护照〉。出国前忘带的是“护照”，才会被拦在机场；“加密技术”不是证件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb3844a-d98c-4257-86ea-b1110a3aa7df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27232, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雨伞", "is_correct": false, "explanation": "语义：网上银行不会用雨伞，“网上银行都要用雨伞”句意不通。"}, {"text": "草地", "is_correct": false, "explanation": "语义：草地是地貌，与网上银行的安全措施无关，句子不通。"}, {"text": "加密技术", "is_correct": true, "explanation": "正确。“网上银行都要用加密技术”，加密技术是网上银行必备的安全手段。"}, {"text": "老头", "is_correct": false, "explanation": "语义：“老头”指老年男子，不能作为银行使用的技术，句子不通。"}], "explanations": {"雨伞": "语义：网上银行不会用雨伞，“网上银行都要用雨伞”句意不通。", "草地": "语义：草地是地貌，与网上银行的安全措施无关，句子不通。", "加密技术": "正确。“网上银行都要用加密技术”，加密技术是网上银行必备的安全手段。", "老头": "语义：“老头”指老年男子，不能作为银行使用的技术，句子不通。"}, "sentence_index": 6, "correct_answer": "加密技术"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我忘了邮箱的加密技术，只能找客服重置。", "explanation": "此处应用〈密码〉。能找客服重置的是邮箱“密码”；“加密技术”是保护信息的方法，不能被重置。"}, {"text": "我的手机中了加密技术，只好送去修理。", "explanation": "此处应用〈病毒〉。手机可以“中病毒”，“加密技术”不能被手机“中”。"}, {"text": "门上的加密技术坏了，我们进不去。", "explanation": "此处应用〈锁〉。坏的是门上的“锁”，“加密技术”不是实物，不能说门上坏了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb3844a-d98c-4257-86ea-b1110a3aa7df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27232, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司用了一条加密技术。", "corrected_sentence": "这家公司用了一项加密技术。", "error_description": "量词错误：“加密技术”应用“项”，“条”用于细长的东西，不能修饰“加密技术”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb3844a-d98c-4257-86ea-b1110a3aa7df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27232, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把加密技术非常难以破解。", "corrected_sentence": "这种加密技术非常难以破解。", "error_description": "量词错误：“把”用于有柄的器具，不能修饰“加密技术”。应改为“这种加密技术”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb3844a-d98c-4257-86ea-b1110a3aa7df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
