INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27234, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "一个东西能用在很多种电脑或手机上，不用重新做。", "primary_collocate": null, "pronunciation": "kuà píng tái", "ipa": "kʰua˥˩ pʰiŋ˧˥ tʰaɪ˧˥", "syllable_count": 3, "sentences": [{"text": "这个软件跨平台，手机电脑都能用。", "target_word": "跨平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做了一个跨平台的小程序。", "target_word": "跨平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跨平台的软件不用重新做。", "target_word": "跨平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢跨平台的游戏，因为朋友用什么设备都行。", "target_word": "跨平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个视频软件跨平台，电脑手机都能看。", "target_word": "跨平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，跨平台软件可以省很多时间。", "target_word": "跨平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个笔记本软件跨平台，换了手机也不用重装。", "target_word": "跨平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司需要一个跨平台的应用。", "target_word": "跨平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种跨平台的游戏，苹果和安卓都能玩。", "target_word": "跨平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的新软件不跨平台，所以我用不了。", "target_word": "跨平台", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一个东西能在多种电脑或手机上使用，不必重做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350e46f9-b0cc-46b5-afe7-c34cc96c73df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27234, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "跨平台", "is_correct": true, "explanation": "正确。“这个软件跨平台”指软件能在多种设备上使用，与“手机电脑都能用”相合。"}, {"text": "专属", "is_correct": false, "explanation": "语义：“专属”指只归某一对象使用，与“手机电脑都能用”相矛盾。"}, {"text": "单一", "is_correct": false, "explanation": "语义：“单一”指只有一种，与“手机电脑都能用”相矛盾。"}, {"text": "双向", "is_correct": false, "explanation": "搭配：“双向”多用于通信、交流或流动，不用来说软件的运行范围。"}], "explanations": {"跨平台": "正确。“这个软件跨平台”指软件能在多种设备上使用，与“手机电脑都能用”相合。", "专属": "语义：“专属”指只归某一对象使用，与“手机电脑都能用”相矛盾。", "单一": "语义：“单一”指只有一种，与“手机电脑都能用”相矛盾。", "双向": "搭配：“双向”多用于通信、交流或流动，不用来说软件的运行范围。"}, "sentence_index": 0, "correct_answer": "跨平台"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这项规定跨平台，迟到一分钟都不行。", "explanation": "此处应用〈严格〉。“跨平台”只用于软件或硬件的运行范围，不用来说规定的严格程度。"}, {"text": "这张桌子跨平台，四条腿都很稳。", "explanation": "此处应用〈稳固〉。“跨平台”只用于软件或硬件的运行范围，不用来形容桌子。"}, {"text": "这场比赛很跨平台，从早上一直打到晚上。", "explanation": "这里应该用〈漫长〉。跨平台只用于软件或硬件的运行范围，不用来说时间的长短。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb3844a-d98c-4257-86ea-b1110a3aa7df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27234, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跨平台", "is_correct": true, "explanation": "正确。“这个笔记本软件跨平台”指软件可在不同设备间通用，与“换了手机也不用重装”相合。"}, {"text": "单机", "is_correct": false, "explanation": "语义：“单机”指只能在一台设备上运行，与“换了手机也不用重装”相矛盾。"}, {"text": "本地", "is_correct": false, "explanation": "语义：“本地”指只在本机使用，与“换了手机也不用重装”相矛盾。"}, {"text": "固定", "is_correct": false, "explanation": "搭配：“固定”多修饰位置、价格，不用来说软件的运行范围。"}], "explanations": {"跨平台": "正确。“这个笔记本软件跨平台”指软件可在不同设备间通用，与“换了手机也不用重装”相合。", "单机": "语义：“单机”指只能在一台设备上运行，与“换了手机也不用重装”相矛盾。", "本地": "语义：“本地”指只在本机使用，与“换了手机也不用重装”相矛盾。", "固定": "搭配：“固定”多修饰位置、价格，不用来说软件的运行范围。"}, "sentence_index": 6, "correct_answer": "跨平台"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位老师跨平台，课堂上总爱讲笑话。", "explanation": "此处应用〈幽默〉。“跨平台”只用于软件或硬件的运行范围，不用来形容人的性格。"}, {"text": "这个插座跨平台，颜色是亮红色的。", "explanation": "此处应用〈鲜艳〉。“跨平台”只用于软件或硬件的运行范围，不用来说颜色。"}, {"text": "这把椅子跨平台，坐上去很舒服。", "explanation": "这里表示“舒适”的意思，应该用〈舒适〉。跨平台只指软件或硬件的运行范围，不能用来形容椅子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb3844a-d98c-4257-86ea-b1110a3aa7df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27234, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个跨平台地阅读器，平板和电脑都能看书。", "corrected_sentence": "这个跨平台的阅读器，平板和电脑都能看书。", "error_description": "错误：“跨平台”修饰名词“阅读器”时要用“的”，不能用“地”。应改为“这个跨平台的阅读器”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb3844a-d98c-4257-86ea-b1110a3aa7df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27234, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个打卡应用跨平台的。", "corrected_sentence": "这个打卡应用是跨平台的。", "error_description": "错误：作谓语的“跨平台的”前漏掉了“是”。正确：应写作“是跨平台的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb3844a-d98c-4257-86ea-b1110a3aa7df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
