INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27240, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用眼睛一直看着。", "primary_collocate": null, "pronunciation": "níng shì", "ipa": "niŋ˧˥ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他一动不动地凝视着天空。", "target_word": "凝视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "母亲凝视着熟睡的孩子，舍不得离开。", "target_word": "凝视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在海边凝视着落日，直到天黑。", "target_word": "凝视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他凝视了她很久，什么也没说。", "target_word": "凝视", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "猫凝视着桌上的小鱼。", "target_word": "凝视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她站在门口，凝视着他的背影。", "target_word": "凝视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们凝视着舞台，一眼也不眨。", "target_word": "凝视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他凝视星空，心里很平静。", "target_word": "凝视", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人凝视着河水，半天没动。", "target_word": "凝视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他凝视着手里的车票，想了很久。", "target_word": "凝视", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "凝视着", "label": "体标"}, {"form": "凝视了", "label": "体标"}, {"form": "凝视过", "label": "体标"}, {"form": "凝視", "label": "繁体"}], "register": "书面", "sense_fingerprint": "用眼睛一直看着", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c928e1f6-5741-4790-be78-40c893415c14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27240, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "凝视", "is_correct": true, "explanation": "正确答案。níng shì，意思是用眼睛一直看着。"}, {"text": "明示", "is_correct": false, "explanation": "míng（第二声）与 níng 声母不同（m 与 n），意思是清楚地表示。"}, {"text": "凝实", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是紧密结实。"}, {"text": "凝思", "is_correct": false, "explanation": "sī（第一声）与 shì（第四声）声母与声调都不同，意思是集中精力地思考。"}], "explanations": {"凝视": "正确答案。níng shì，意思是用眼睛一直看着。", "明示": "míng（第二声）与 níng 声母不同（m 与 n），意思是清楚地表示。", "凝实": "shí（第二声）与 shì（第四声）声调不同，意思是紧密结实。", "凝思": "sī（第一声）与 shì（第四声）声母与声调都不同，意思是集中精力地思考。"}, "sentence_index": null, "correct_answer": "凝视"}, "level_3": {"options": [{"text": "凝视", "is_correct": true, "explanation": "正确：“一动不动”说明目光持续停留，与“凝视”的含义相符。"}, {"text": "张望", "is_correct": false, "explanation": "语义：“张望”指东看西看、视线移动，与“一动不动”矛盾。"}, {"text": "扫视", "is_correct": false, "explanation": "语义：“扫视”是快速从一边看到另一边，与“一动不动”矛盾。"}, {"text": "抚摸", "is_correct": false, "explanation": "语义：「抚摸」需要用手触碰，不能用于天空，与「一动不动地看」无关，句子不通。"}], "explanations": {"凝视": "正确：“一动不动”说明目光持续停留，与“凝视”的含义相符。", "张望": "语义：“张望”指东看西看、视线移动，与“一动不动”矛盾。", "扫视": "语义：“扫视”是快速从一边看到另一边，与“一动不动”矛盾。", "抚摸": "语义：「抚摸」需要用手触碰，不能用于天空，与「一动不动地看」无关，句子不通。"}, "sentence_index": 0, "correct_answer": "凝视"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他凝视着远处传来的钟声，慢慢走了过去。", "explanation": "这里用法不对。“凝视”指用眼睛一直看，钟声要用耳朵听，应说“听”。"}, {"text": "他凝视着这碗汤的味道，迟迟不肯动筷子。", "explanation": "这里用法不对。“凝视”是用眼睛一直看，味道要用舌头尝，不能说“凝视”味道。"}, {"text": "这本书很厚，他凝视了一个星期就读完了。", "explanation": "这里表示认真阅读，但“凝视”只表示用眼睛一直看，不表示读书的过程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b5865-410b-4790-8dfa-e2b7af39d8ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27240, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "凝视", "is_correct": true, "explanation": "正确答案。níng shì，意思是用眼睛一直看着。"}, {"text": "名士", "is_correct": false, "explanation": "míng（第二声）与 níng 声母不同（m 与 n），意思是有名望的文人。"}, {"text": "领事", "is_correct": false, "explanation": "lǐng（第三声）与 níng 声母与声调都不同，意思是外交官。"}, {"text": "凝实", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是紧密结实。"}], "explanations": {"凝视": "正确答案。níng shì，意思是用眼睛一直看着。", "名士": "míng（第二声）与 níng 声母不同（m 与 n），意思是有名望的文人。", "领事": "lǐng（第三声）与 níng 声母与声调都不同，意思是外交官。", "凝实": "shí（第二声）与 shì（第四声）声调不同，意思是紧密结实。"}, "sentence_index": null, "correct_answer": "凝视"}, "level_3": {"options": [{"text": "凝视", "is_correct": true, "explanation": "正确：“一眼也不眨”说明目光持续停在舞台上，与“凝视”相符。"}, {"text": "窥视", "is_correct": false, "explanation": "语义：“窥视”含有偷偷看的意思，与公开的舞台表演不符。"}, {"text": "聆听", "is_correct": false, "explanation": "语义：「聆听」用耳朵，与「一眼也不眨」所描述的目光持续停留相矛盾。"}, {"text": "瞄准", "is_correct": false, "explanation": "语义：“瞄准”指把目标对准，并不是一直看着舞台的意思。"}], "explanations": {"凝视": "正确：“一眼也不眨”说明目光持续停在舞台上，与“凝视”相符。", "窥视": "语义：“窥视”含有偷偷看的意思，与公开的舞台表演不符。", "聆听": "语义：「聆听」用耳朵，与「一眼也不眨」所描述的目光持续停留相矛盾。", "瞄准": "语义：“瞄准”指把目标对准，并不是一直看着舞台的意思。"}, "sentence_index": 6, "correct_answer": "凝视"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他凝视着厨房里飘出的香味，心里很高兴。", "explanation": "这里用法不对。“凝视”是用眼睛看，香味要用鼻子闻，不能说“凝视”香味。"}, {"text": "这碗汤放凉以后，慢慢凝视了。", "explanation": "这里是液体变稠、变硬的意思，而“凝视”只指用眼睛一直看。"}, {"text": "他凝视着这块丝绸的柔软，心里很满意。", "explanation": "这里用法不对。“凝视”是用眼睛一直看，柔软要靠手摸才能感觉到，不能说“凝视”柔软。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b5865-410b-4790-8dfa-e2b7af39d8ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27240, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她站在窗前，凝视着远处的山着。", "corrected_sentence": "她站在窗前，凝视着远处的山。", "error_description": "句末多加了“着”：“凝视”后已有体标“着”，句末不能再加“着”。正确形式是“凝视着远处的山”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b5865-410b-4790-8dfa-e2b7af39d8ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27240, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他坐在窗边，凝视了着下雨的街道。", "corrected_sentence": "他坐在窗边，凝视着下雨的街道。", "error_description": "错误形式“凝视了着下雨的街道”，正确形式“凝视着下雨的街道”。“了”和“着”不能同时用在同一个动词上。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b5865-410b-4790-8dfa-e2b7af39d8ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
