INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27242, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "可以相信和依靠。", "primary_collocate": null, "pronunciation": "kě xìn lài", "ipa": "kʰɤ˨˩ ɕin˥˩ lai˥˩", "syllable_count": 3, "sentences": [{"text": "这条消息来自可信赖的渠道。", "target_word": "可信赖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网上的信息不一定都可信赖。", "target_word": "可信赖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个牌子的手机很可信赖。", "target_word": "可信赖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他做事马马虎虎，不太可信赖。", "target_word": "可信赖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买药要去可信赖的药店。", "target_word": "可信赖", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们要找一个可信赖的数据来源。", "target_word": "可信赖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经过多年的检验，这种方法已经很可信赖了。", "target_word": "可信赖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻报道应该真实，也应该可信赖。", "target_word": "可信赖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台机器用了十年，依然可信赖。", "target_word": "可信赖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专家给出的建议更可信赖。", "target_word": "可信赖", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不可信赖", "label": "否定"}, {"form": "更可信赖", "label": "程度"}, {"form": "可信賴", "label": "繁体"}], "register": "书面", "sense_fingerprint": "可以相信和依靠", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c928e1f6-5741-4790-be78-40c893415c14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27242, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可信赖", "is_correct": true, "explanation": "正确：“来自可信赖的渠道”表示消息来源值得依靠，与句意相符。"}, {"text": "冷清", "is_correct": false, "explanation": "搭配：“冷清”形容场所没有人气，不用来修饰“渠道”。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容人或物的体形，不用来修饰“渠道”。"}, {"text": "苦涩", "is_correct": false, "explanation": "语义：“苦涩”描写味道，与消息的来源无关。"}], "explanations": {"可信赖": "正确：“来自可信赖的渠道”表示消息来源值得依靠，与句意相符。", "冷清": "搭配：“冷清”形容场所没有人气，不用来修饰“渠道”。", "高大": "搭配：“高大”形容人或物的体形，不用来修饰“渠道”。", "苦涩": "语义：“苦涩”描写味道，与消息的来源无关。"}, "sentence_index": 0, "correct_answer": "可信赖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的心情很可信赖，什么都不想做。", "explanation": "这里应该用〈低落〉。“可信赖”指可以依靠的人或事物，不能用来形容心情，心情不好要说“低落”。"}, {"text": "他跑得很可信赖，每次都第一个到。", "explanation": "这里应该用〈快〉。“可信赖”指值得依靠，不能用来形容速度，跑得快要说“快”。"}, {"text": "这套房子的位置很可信赖，离市中心很远。", "explanation": "这里应该用〈偏远〉。“可信赖”指值得依靠，不能用来形容位置，位置偏僻要说“偏远”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b5865-410b-4790-8dfa-e2b7af39d8ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27242, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可信赖", "is_correct": true, "explanation": "正确：“经过多年的检验”说明方法值得信赖，与“可信赖”相符。"}, {"text": "草率", "is_correct": false, "explanation": "语义：“草率”指做事不认真，与“经过多年的检验”矛盾。"}, {"text": "幼稚", "is_correct": false, "explanation": "语义：“幼稚”指不成熟，与“经过多年的检验”得出的稳定结论不符。"}, {"text": "粗糙", "is_correct": false, "explanation": "语义：「粗糙」指做得不精细，与「经过多年的检验」得出的可靠结论相矛盾。"}], "explanations": {"可信赖": "正确：“经过多年的检验”说明方法值得信赖，与“可信赖”相符。", "草率": "语义：“草率”指做事不认真，与“经过多年的检验”矛盾。", "幼稚": "语义：“幼稚”指不成熟，与“经过多年的检验”得出的稳定结论不符。", "粗糙": "语义：「粗糙」指做得不精细，与「经过多年的检验」得出的可靠结论相矛盾。"}, "sentence_index": 6, "correct_answer": "可信赖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次旅行的价钱很可信赖，便宜得让人惊讶。", "explanation": "这里应该用〈便宜〉。“可信赖”指值得依靠，不能用来评价价钱，价格低要说“便宜”。"}, {"text": "这把椅子很可信赖，坐上去软软的。", "explanation": "这里应该用〈舒服〉。“可信赖”指值得相信和依靠，不能用来形容坐着的感觉，坐着软要说“舒服”。"}, {"text": "这首歌的旋律很可信赖，天天都在听。", "explanation": "这里用法不对。“可信赖”不用来形容旋律，形容旋律应说“好听”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b5865-410b-4790-8dfa-e2b7af39d8ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27242, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家药店的药很可信赖地。", "corrected_sentence": "这家药店的药很可信赖。", "error_description": "错误形式“很可信赖地”，正确形式“很可信赖”。作谓语的形容词后面不加“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b5865-410b-4790-8dfa-e2b7af39d8ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27242, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一个可信赖人。", "corrected_sentence": "这是一个可信赖的人。", "error_description": "错误形式“一个可信赖人”，正确形式“一个可信赖的人”。“可信赖”是三个字的形容词，修饰名词时中间要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b5865-410b-4790-8dfa-e2b7af39d8ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
