INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27244, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "心理健康是心里感觉舒服和快乐。", "primary_collocate": null, "pronunciation": "xīn lǐ jiàn kāng", "ipa": "ɕin˥ li˨˩˦ tɕjɛn˥˩ kʰaŋ˥", "syllable_count": 4, "sentences": [{"text": "心理健康的人，每天都很快乐。", "target_word": "心理健康", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说，心理健康比有钱更重要。", "target_word": "心理健康", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做喜欢的事，对心理健康很好。", "target_word": "心理健康", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家人的爱让孩子心理健康地长大。", "target_word": "心理健康", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要多笑，这对心理健康有好处。", "target_word": "心理健康", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "心理健康的老人，每天都笑着过日子。", "target_word": "心理健康", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听音乐能让人心情好，对心理健康有帮助。", "target_word": "心理健康", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每天笑一笑，能让我的心理健康一直保持下去。", "target_word": "心理健康", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "心理健康的孩子爱笑，也爱交朋友。", "target_word": "心理健康", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末去公园走走，对心理健康有好处。", "target_word": "心理健康", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "心理健康教育", "label": "复合"}, {"form": "心理健康课", "label": "复合"}], "register": "中性", "sense_fingerprint": "心里感觉舒服、快乐的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90eedc6c-01dd-4f05-9096-cfdfdc3231d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27244, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "心理健康", "is_correct": true, "explanation": "正确：“心理健康”指心里舒服快乐的状态，与“每天都很快乐”一致。"}, {"text": "心理问题", "is_correct": false, "explanation": "语义：“心理问题”与“每天都很快乐”相矛盾，有心理问题的人不会每天都快乐。"}, {"text": "饥饿", "is_correct": false, "explanation": "语义：“饥饿的人”与“每天都很快乐”不相符，饥饿通常让人难受。"}, {"text": "疾病", "is_correct": false, "explanation": "语义：“疾病的人”与“每天都很快乐”相矛盾，生病一般不会让人每天快乐。"}], "explanations": {"心理健康": "正确：“心理健康”指心里舒服快乐的状态，与“每天都很快乐”一致。", "心理问题": "语义：“心理问题”与“每天都很快乐”相矛盾，有心理问题的人不会每天都快乐。", "饥饿": "语义：“饥饿的人”与“每天都很快乐”不相符，饥饿通常让人难受。", "疾病": "语义：“疾病的人”与“每天都很快乐”相矛盾，生病一般不会让人每天快乐。"}, "sentence_index": 0, "correct_answer": "心理健康"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他心理健康饱满地去上班。", "explanation": "这里应该用〈精神〉。“饱满”形容精神、状态，心理健康指心里舒服快乐的感受，不能说“饱满”。"}, {"text": "他最近心理健康低落，不想说话。", "explanation": "这里应该用〈心情〉。“低落”形容一时的情绪，心理健康指长期舒服快乐的状态，不能说“心理健康低落”。"}, {"text": "他心理健康充沛，能熬夜工作。", "explanation": "这里应该用〈精力〉。“充沛”形容体力、精力，心理健康指舒服快乐的感受，不能说“充沛”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45fd609-c469-4c52-9ccd-364c2aa20591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27244, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心理健康", "is_correct": true, "explanation": "正确：“心理健康”对心情好、快乐有帮助，符合句意。"}, {"text": "螺丝", "is_correct": false, "explanation": "语义：“螺丝”与听音乐、心情好无关，“对螺丝有帮助”句意不通。"}, {"text": "筷子", "is_correct": false, "explanation": "语义：“筷子”与听音乐能让人心情好的句意不相干。"}, {"text": "词典", "is_correct": false, "explanation": "搭配：“对……有帮助”的对象应是人或与人的状态相关的事物，“词典”不能与“心情好”并列。"}], "explanations": {"心理健康": "正确：“心理健康”对心情好、快乐有帮助，符合句意。", "螺丝": "语义：“螺丝”与听音乐、心情好无关，“对螺丝有帮助”句意不通。", "筷子": "语义：“筷子”与听音乐能让人心情好的句意不相干。", "词典": "搭配：“对……有帮助”的对象应是人或与人的状态相关的事物，“词典”不能与“心情好”并列。"}, "sentence_index": 6, "correct_answer": "心理健康"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他跑了五公里，心理健康消耗很大。", "explanation": "这里应该用〈体力〉。“消耗”多用于体力、能量，心理健康是状态，不能说被消耗。"}, {"text": "这个孩子心理健康很大，能背动大书包。", "explanation": "这里应该用〈力气〉。“很大”形容力量，心理健康不能用来说明能背动重物。"}, {"text": "孩子玩得心理健康。", "explanation": "这里应该用〈快乐〉。“玩得……”后接表示心情或状态的形容词，心理健康不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45fd609-c469-4c52-9ccd-364c2aa20591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27244, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈常常陪伴，孩子心理健康得成长。", "corrected_sentence": "妈妈常常陪伴，孩子心理健康地成长。", "error_description": "错误：“地”写成了“得”。“心理健康”作状语修饰“成长”，要用“地”；“得”用于动词或形容词后的补语。正确形式为“心理健康地成长”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45fd609-c469-4c52-9ccd-364c2aa20591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27244, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "常听歌，心理健康有好处。", "corrected_sentence": "常听歌，对心理健康有好处。", "error_description": "错误：漏掉了介词“对”。“对心理健康有好处”引出受益对象，少了“对”，句子不成立。正确形式为“对心理健康有好处”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45fd609-c469-4c52-9ccd-364c2aa20591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27246, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "明示", "is_correct": true, "explanation": "反义：“明示”指明白地表示，与“暗示”的含蓄方式相对。"}, {"text": "拒绝", "is_correct": false, "explanation": "无关：“拒绝”与“暗示”在任何义项上都不构成反义或近义关系。"}, {"text": "解释", "is_correct": false, "explanation": "无关：“解释”是讲清道理，与“暗示”没有反义关系。"}, {"text": "选择", "is_correct": false, "explanation": "无关：“选择”是挑拣，与“暗示”没有反义关系。"}], "correct_answer": "明示", "explanations": {"明示": "反义：“明示”指明白地表示，与“暗示”的含蓄方式相对。", "拒绝": "无关：“拒绝”与“暗示”在任何义项上都不构成反义或近义关系。", "解释": "无关：“解释”是讲清道理，与“暗示”没有反义关系。", "选择": "无关：“选择”是挑拣，与“暗示”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '162139ae-0c32-4afa-8b85-9269af9a2c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27246, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "明示", "is_correct": true, "explanation": "反义：“明示”指明白地表示，与“暗示”的含蓄方式相对。"}, {"text": "承认", "is_correct": false, "explanation": "无关：“承认”是认可某个事实，与“暗示”没有反义关系。"}, {"text": "等待", "is_correct": false, "explanation": "无关：“等待”是等候，与“暗示”没有反义关系。"}, {"text": "询问", "is_correct": false, "explanation": "无关：“询问”是提出问题求答，与“暗示”没有反义关系。"}], "correct_answer": "明示", "explanations": {"明示": "反义：“明示”指明白地表示，与“暗示”的含蓄方式相对。", "承认": "无关：“承认”是认可某个事实，与“暗示”没有反义关系。", "等待": "无关：“等待”是等候，与“暗示”没有反义关系。", "询问": "无关：“询问”是提出问题求答，与“暗示”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '162139ae-0c32-4afa-8b85-9269af9a2c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27246, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让人猜到什么意思。", "primary_collocate": null, "pronunciation": "àn shì zhe", "ipa": "an˥˩ ʂɨ˥˩ ʈʂɤ", "syllable_count": 3, "sentences": [{"text": "满天的乌云暗示着马上要下雨。", "target_word": "暗示着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这封信的口气暗示着他很生气。", "target_word": "暗示着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上的两杯茶暗示着刚才有客人来过。", "target_word": "暗示着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她红红的眼睛暗示着昨晚哭过。", "target_word": "暗示着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路边的落叶暗示着秋天已经到了。", "target_word": "暗示着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他突然安静下来，暗示着有些话不方便说。", "target_word": "暗示着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口的鞋暗示着家里有人。", "target_word": "暗示着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生的表情暗示着情况不太好。", "target_word": "暗示着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格一直下降，暗示着市场不景气。", "target_word": "暗示着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电话暗示着事情可能有了新变化。", "target_word": "暗示着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "暗示", "label": "原形"}, {"form": "暗示了", "label": "体标（了）"}, {"form": "暗示过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "某种迹象或情况让人猜到背后的意思", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42af6dd8-76df-4128-9f4d-41a929127788') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27246, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "赞美着", "is_correct": false, "explanation": "语义：乌云不能“赞美”一场即将到来的雨，句意不通。"}, {"text": "暗示着", "is_correct": true, "explanation": "正确：“暗示着”表示乌云让人猜到马上要下雨，与句意吻合。"}, {"text": "嘱咐着", "is_correct": false, "explanation": "配价：“嘱咐”需要说话人和听话人，乌云无法嘱咐。"}, {"text": "提高着", "is_correct": false, "explanation": "搭配：“提高”说的是水平或程度，不能用来搭配“马上要下雨”。"}], "explanations": {"赞美着": "语义：乌云不能“赞美”一场即将到来的雨，句意不通。", "暗示着": "正确：“暗示着”表示乌云让人猜到马上要下雨，与句意吻合。", "嘱咐着": "配价：“嘱咐”需要说话人和听话人，乌云无法嘱咐。", "提高着": "搭配：“提高”说的是水平或程度，不能用来搭配“马上要下雨”。"}, "sentence_index": 0, "correct_answer": "暗示着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他当着大家的面大声地暗示着自己要辞职。", "explanation": "这里应该用〈宣布〉。“当着大家的面大声地”说出来是明说，“暗示”是不明说，二者矛盾。"}, {"text": "她一五一十地暗示着不想再去。", "explanation": "这里应该用〈直言〉。“一五一十”要求把话原样说出，“暗示”是不明说，二者矛盾。"}, {"text": "化验单白纸黑字地暗示着他有病。", "explanation": "这里应该用〈写明〉。“白纸黑字”指结果写得清清楚楚，“暗示”是间接透露，二者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '162139ae-0c32-4afa-8b85-9269af9a2c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27246, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拆散着", "is_correct": false, "explanation": "语义：“拆散”指分开，门口的鞋不能拆散家里的人，句意不通。"}, {"text": "暗示着", "is_correct": true, "explanation": "正确：“暗示着”表示门口的鞋让人猜到家里有人，与句意吻合。"}, {"text": "回忆着", "is_correct": false, "explanation": "配价：“回忆”的主语须是有记忆的人，“门口的鞋”不能回忆。"}, {"text": "批准着", "is_correct": false, "explanation": "搭配：“批准”的对象是申请或计划，不能批准“家里有人”这一事实。"}], "explanations": {"拆散着": "语义：“拆散”指分开，门口的鞋不能拆散家里的人，句意不通。", "暗示着": "正确：“暗示着”表示门口的鞋让人猜到家里有人，与句意吻合。", "回忆着": "配价：“回忆”的主语须是有记忆的人，“门口的鞋”不能回忆。", "批准着": "搭配：“批准”的对象是申请或计划，不能批准“家里有人”这一事实。"}, "sentence_index": 6, "correct_answer": "暗示着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大使馆正式暗示着我们可以入境。", "explanation": "这里应该用〈通知〉。“正式”的通知要明确说出，“暗示”是间接透露，二者矛盾。"}, {"text": "老师详细暗示着题目的解法。", "explanation": "这里应该用〈解释〉。“详细”指讲得清楚透彻，“暗示”只是让人猜，二者矛盾。"}, {"text": "班长直截了当地暗示着大家安静。", "explanation": "这里应该用〈要求〉。“直截了当”指把话挑明，“暗示”是不把话说明白，二者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '162139ae-0c32-4afa-8b85-9269af9a2c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27246, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窗户上全是水珠，暗示着了外面下过雨。", "corrected_sentence": "窗户上全是水珠，暗示着外面下过雨。", "error_description": "体标错误：“暗示着了”叠加了“着”和“了”。表示迹象显示的状态时只用“着”，这里应改为“暗示着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '162139ae-0c32-4afa-8b85-9269af9a2c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27246, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "电话响了三次，暗示着的有急事。", "corrected_sentence": "电话响了三次，暗示着有急事。", "error_description": "助词错误：“着”与“有急事”之间多了“的”，使“有急事”成为修饰语却没有中心语。应为“暗示着有急事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '162139ae-0c32-4afa-8b85-9269af9a2c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
