INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27248, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做事情最主要、最核心的部分。", "primary_collocate": null, "pronunciation": "zhǔ tǐ", "ipa": "ʈʂu˨˩˦ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "这次活动的主体是比赛。", "target_word": "主体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划的主体是培训新人。", "target_word": "主体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场会议的主体是讨论明年的计划。", "target_word": "主体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项工作的主体是写报告，其他都是小事。", "target_word": "主体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行的主体是看风景，不是买东西。", "target_word": "主体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这门课的主体是练习口语。", "target_word": "主体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次培训的主体是实际操作。", "target_word": "主体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个项目的主体由小王负责。", "target_word": "主体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次演出的主体是三个舞蹈节目。", "target_word": "主体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们这次活动的主体是帮助老人。", "target_word": "主体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "主体性", "label": "复合词"}, {"form": "主體", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一件事或一项活动中最核心的内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90eedc6c-01dd-4f05-9096-cfdfdc3231d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27248, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主体", "is_correct": true, "explanation": "“主体”指活动中最核心的内容，“比赛”是核心，符合语境。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”用于人或动物，不能说活动的体重。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：活动没有颜色，“颜色”不能指活动的内容。"}, {"text": "价钱", "is_correct": false, "explanation": "语义：“价钱”指费用，比赛不是活动的价钱。"}], "explanations": {"主体": "“主体”指活动中最核心的内容，“比赛”是核心，符合语境。", "体重": "搭配：“体重”用于人或动物，不能说活动的体重。", "颜色": "语义：活动没有颜色，“颜色”不能指活动的内容。", "价钱": "语义：“价钱”指费用，比赛不是活动的价钱。"}, "sentence_index": 0, "correct_answer": "主体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次座谈会的主体是王老师。", "explanation": "这里应该用〈主席〉。“主体”指活动中最核心的内容，不指担任职务的人，主持会议的人要说“主席”。"}, {"text": "他的主体很健康，经常运动。", "explanation": "这里应该用〈身体〉。“主体”指做事情最核心的部分，不指人的身体，形容身体健康要用“身体”。"}, {"text": "这本书的主体是红色的，很漂亮。", "explanation": "这里应该用〈封面〉。“主体”指一件事最核心的内容，不指书外面看得见的部分，说书的外皮颜色要用“封面”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45fd609-c469-4c52-9ccd-364c2aa20591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27248, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主体", "is_correct": true, "explanation": "“主体”指培训中最核心的内容，与“实际操作”相符，符合语境。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”用于人，不能说培训的年龄。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气与培训的内容无关，不能指“实际操作”这类内容。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：培训没有脾气，“脾气”不能指培训的内容。"}], "explanations": {"主体": "“主体”指培训中最核心的内容，与“实际操作”相符，符合语境。", "年龄": "搭配：“年龄”用于人，不能说培训的年龄。", "天气": "语义：天气与培训的内容无关，不能指“实际操作”这类内容。", "脾气": "语义：培训没有脾气，“脾气”不能指培训的内容。"}, "sentence_index": 6, "correct_answer": "主体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间屋子的主体是他。", "explanation": "这里应该用〈主人〉。“主体”指事物中主要的部分，不指所有者，说屋子的所有人要用“主人”。"}, {"text": "这部剧的主体是小李。", "explanation": "这里应该用〈主角〉。“主体”指事物的主要部分，指戏剧中的主要人物要说“主角”。"}, {"text": "这档节目的主体是老王。", "explanation": "这里应该用〈主持人〉。“主体”不指担任节目主持的人，节目的主持人要说“主持人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45fd609-c469-4c52-9ccd-364c2aa20591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27248, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场演讲的一把主体是介绍新产品。", "corrected_sentence": "这场演讲的主体是介绍新产品。", "error_description": "量词错误。“主体”是抽象名词，不能用“把”（用于有柄的器具）计量。正确说法是“这场演讲的主体是介绍新产品”，“主体”前不加量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45fd609-c469-4c52-9ccd-364c2aa20591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27248, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次展览的主体老照片。", "corrected_sentence": "这次展览的主体是老照片。", "error_description": "错误：漏掉了系词“是”。“主体”作主语后，谓语需要“是”，应写作“这次展览的主体是老照片”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45fd609-c469-4c52-9ccd-364c2aa20591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27250, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "禁止", "is_correct": true, "explanation": "正确。“禁止”与“允许”是反义词，“博物馆允许拍照”的反面是“博物馆禁止拍照”。"}, {"text": "购买", "is_correct": false, "explanation": "与“允许”没有反义关系，只是同为动词的干扰项。"}, {"text": "思考", "is_correct": false, "explanation": "与“允许”没有反义关系，只是同为动词的干扰项。"}, {"text": "搬运", "is_correct": false, "explanation": "与“允许”没有反义关系，只是同为动词的干扰项。"}], "correct_answer": "禁止", "explanations": {"禁止": "正确。“禁止”与“允许”是反义词，“博物馆允许拍照”的反面是“博物馆禁止拍照”。", "购买": "与“允许”没有反义关系，只是同为动词的干扰项。", "思考": "与“允许”没有反义关系，只是同为动词的干扰项。", "搬运": "与“允许”没有反义关系，只是同为动词的干扰项。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45fd609-c469-4c52-9ccd-364c2aa20591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27250, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "禁止", "is_correct": true, "explanation": "正确。“禁止”与“允许”是反义词，“这个公园允许骑自行车”的反面是“这个公园禁止骑自行车”。"}, {"text": "追赶", "is_correct": false, "explanation": "与“允许”没有反义关系，只是同为动词的干扰项。"}, {"text": "修补", "is_correct": false, "explanation": "与“允许”没有反义关系，只是同为动词的干扰项。"}, {"text": "洗涤", "is_correct": false, "explanation": "与“允许”没有反义关系，只是同为动词的干扰项。"}], "correct_answer": "禁止", "explanations": {"禁止": "正确。“禁止”与“允许”是反义词，“这个公园允许骑自行车”的反面是“这个公园禁止骑自行车”。", "追赶": "与“允许”没有反义关系，只是同为动词的干扰项。", "修补": "与“允许”没有反义关系，只是同为动词的干扰项。", "洗涤": "与“允许”没有反义关系，只是同为动词的干扰项。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45fd609-c469-4c52-9ccd-364c2aa20591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27250, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "有人说可以，你就能做。", "primary_collocate": null, "pronunciation": "yǔn xǔ", "ipa": "yn˨˩˦ ɕy˨˩˦", "syllable_count": 2, "sentences": [{"text": "这里不允许抽烟。", "target_word": "允许", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆里不允许大声说话。", "target_word": "允许", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试时不允许看手机。", "target_word": "允许", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆允许拍照，但不能用闪光灯。", "target_word": "允许", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家酒店允许带宠物入住。", "target_word": "允许", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁里不允许吃东西。", "target_word": "允许", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律不允许人们随便砍树。", "target_word": "允许", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车时不允许打电话。", "target_word": "允许", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游泳池不允许十岁以下的孩子进入。", "target_word": "允许", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公园允许骑自行车。", "target_word": "允许", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "允许了", "label": "体标（了）"}, {"form": "允许过", "label": "体标（过）"}, {"form": "不允许", "label": "否定形式"}, {"form": "允許", "label": "繁体"}], "register": "中性", "sense_fingerprint": "规定或规则上可以做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90eedc6c-01dd-4f05-9096-cfdfdc3231d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27250, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "允许", "is_correct": true, "explanation": "正确。“这里不允许抽烟”表示规定禁止在此抽烟，符合句意。"}, {"text": "承认", "is_correct": false, "explanation": "语义：“承认”的对象是事实，不能用来表示场所的规定。"}, {"text": "答应", "is_correct": false, "explanation": "配价：“答应”需要有意愿的人作主语，“这里”不能作主语答应什么。"}, {"text": "感激", "is_correct": false, "explanation": "语义：“感激”表示感谢，不能表示规定，句子意思不通。"}], "explanations": {"允许": "正确。“这里不允许抽烟”表示规定禁止在此抽烟，符合句意。", "承认": "语义：“承认”的对象是事实，不能用来表示场所的规定。", "答应": "配价：“答应”需要有意愿的人作主语，“这里”不能作主语答应什么。", "感激": "语义：“感激”表示感谢，不能表示规定，句子意思不通。"}, "sentence_index": 0, "correct_answer": "允许"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家餐厅允许我们的心情好。", "explanation": "这里把〈允许〉误当成“使…处于某种状态”的意思，但它后面只能接可以做的动作，“心情好”是状态。"}, {"text": "这家超市允许我们的钱包。", "explanation": "这里把〈允许〉误当成“让…拥有、带着某物”的意思，但它后面只能接可以做的动作，不能接“钱包”。"}, {"text": "这间教室允许桌子很新。", "explanation": "这里把〈允许〉误当成“使…处于某种状态”的意思，但它后面要接可以做的动作，“桌子很新”是状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45fd609-c469-4c52-9ccd-364c2aa20591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27250, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "允许", "is_correct": true, "explanation": "正确。“法律不允许人们随便砍树”表示法律规定禁止随意砍树，符合句意。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”表示取笑，法律不会因此取笑人们砍树，句子不通。"}, {"text": "同情", "is_correct": false, "explanation": "搭配：“同情”的对象是人的遭遇，不能与“法律”作主语后接“砍树”的行为。"}, {"text": "抱怨", "is_correct": false, "explanation": "语义：“抱怨”表示不满，不能表示法律的规定，句子意思不通。"}], "explanations": {"允许": "正确。“法律不允许人们随便砍树”表示法律规定禁止随意砍树，符合句意。", "嘲笑": "语义：“嘲笑”表示取笑，法律不会因此取笑人们砍树，句子不通。", "同情": "搭配：“同情”的对象是人的遭遇，不能与“法律”作主语后接“砍树”的行为。", "抱怨": "语义：“抱怨”表示不满，不能表示法律的规定，句子意思不通。"}, "sentence_index": 6, "correct_answer": "允许"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个公园允许游客的烦恼。", "explanation": "这里把〈允许〉误当成“容纳、包容某种情绪”的意思，但它后面只能接可以做的动作，“烦恼”不是动作。"}, {"text": "这个公园允许了快乐。", "explanation": "这里把〈允许〉误当成“使某种感受出现”的意思，但它只表示准许某人做某件事，“快乐”不是可以被准许的行为。"}, {"text": "这片树林允许阳光很亮。", "explanation": "这里把〈允许〉误当成“让某种状况出现”的意思，但它后面只能接可以做的动作，“阳光很亮”是状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45fd609-c469-4c52-9ccd-364c2aa20591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27250, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "图书馆里很允许吃东西。", "corrected_sentence": "图书馆里允许吃东西。", "error_description": "错误：多了程度副词“很”。“很”不能修饰动词“允许”，去掉“很”，应写作“图书馆里允许吃东西”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45fd609-c469-4c52-9ccd-364c2aa20591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27250, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这里不允许了停车。", "corrected_sentence": "这里不允许停车。", "error_description": "错误：否定句“不允许”后面不能加“了”，应写作“这里不允许停车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45fd609-c469-4c52-9ccd-364c2aa20591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27252, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "萧条", "is_correct": true, "explanation": "“萧条”与“繁荣”互为反义，指生意冷淡、市面不景气。"}, {"text": "狭小", "is_correct": false, "explanation": "与“繁荣”无反义关系，“狭小”指空间窄小，不表示生意状况。"}, {"text": "迟缓", "is_correct": false, "explanation": "与“繁荣”无反义关系，“迟缓”指速度慢，不表示生意状况。"}, {"text": "粗糙", "is_correct": false, "explanation": "与“繁荣”无反义关系，“粗糙”指质地不光滑，不表示生意状况。"}], "correct_answer": "萧条", "explanations": {"萧条": "“萧条”与“繁荣”互为反义，指生意冷淡、市面不景气。", "狭小": "与“繁荣”无反义关系，“狭小”指空间窄小，不表示生意状况。", "迟缓": "与“繁荣”无反义关系，“迟缓”指速度慢，不表示生意状况。", "粗糙": "与“繁荣”无反义关系，“粗糙”指质地不光滑，不表示生意状况。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45fd609-c469-4c52-9ccd-364c2aa20591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27252, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "萧条", "is_correct": true, "explanation": "“萧条”与“繁荣”互为反义，指生意冷淡、市面不景气。"}, {"text": "寒冷", "is_correct": false, "explanation": "与“繁荣”无反义关系，“寒冷”指温度低，不表示生意状况。"}, {"text": "严肃", "is_correct": false, "explanation": "与“繁荣”无反义关系，“严肃”指态度庄重，不表示生意状况。"}, {"text": "稀薄", "is_correct": false, "explanation": "与“繁荣”无反义关系，“稀薄”指密度小，不表示生意状况。"}], "correct_answer": "萧条", "explanations": {"萧条": "“萧条”与“繁荣”互为反义，指生意冷淡、市面不景气。", "寒冷": "与“繁荣”无反义关系，“寒冷”指温度低，不表示生意状况。", "严肃": "与“繁荣”无反义关系，“严肃”指态度庄重，不表示生意状况。", "稀薄": "与“繁荣”无反义关系，“稀薄”指密度小，不表示生意状况。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45fd609-c469-4c52-9ccd-364c2aa20591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27252, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "生意兴旺，市面热闹。", "primary_collocate": null, "pronunciation": "fán róng", "ipa": "fan˧˥ ʐʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这条街的生意很繁荣。", "target_word": "繁荣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "节日里，市场特别繁荣。", "target_word": "繁荣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座小城以前很繁荣，现在人少了。", "target_word": "繁荣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店的生意越来越繁荣。", "target_word": "繁荣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜市很繁荣，到处都是人。", "target_word": "繁荣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的旅游业非常繁荣。", "target_word": "繁荣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老城区的商店一家挨着一家，十分繁荣。", "target_word": "繁荣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为有了新地铁，这个地方变得繁荣了。", "target_word": "繁荣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的家乡是一个繁荣的小镇。", "target_word": "繁荣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座港口城市一直很繁荣。", "target_word": "繁荣", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "繁荣昌盛", "label": "复合词"}, {"form": "繁榮", "label": "繁体"}], "register": "中性", "sense_fingerprint": "生意兴旺、市面热闹发达", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90eedc6c-01dd-4f05-9096-cfdfdc3231d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27252, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "繁荣", "is_correct": true, "explanation": "“繁荣”形容生意兴旺，与“生意很”搭配，符合语境。"}, {"text": "美丽", "is_correct": false, "explanation": "搭配：“美丽”形容外貌，不能说生意很美丽。"}, {"text": "高大", "is_correct": false, "explanation": "语义：生意不是有形的实体，不能用“高大”形容。"}, {"text": "坚硬", "is_correct": false, "explanation": "搭配：“坚硬”形容物体质地，不能用来形容生意。"}], "explanations": {"繁荣": "“繁荣”形容生意兴旺，与“生意很”搭配，符合语境。", "美丽": "搭配：“美丽”形容外貌，不能说生意很美丽。", "高大": "语义：生意不是有形的实体，不能用“高大”形容。", "坚硬": "搭配：“坚硬”形容物体质地，不能用来形容生意。"}, "sentence_index": 0, "correct_answer": "繁荣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很繁荣，经常捐钱帮助别人。", "explanation": "这里应该用〈富裕〉。“繁荣”形容生意兴旺、市面热闹，不用于形容人有钱，人有钱要用“富裕”。"}, {"text": "这个孩子很繁荣，上课时总是举手。", "explanation": "这里应该用〈活跃〉。“繁荣”形容生意或市面兴旺，形容孩子爱动、爱发言要用“活跃”。"}, {"text": "她的精力很繁荣，每天都去跑步。", "explanation": "这里应该用〈旺盛〉。“繁荣”形容生意或市面兴旺，形容精力充沛要用“旺盛”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45fd609-c469-4c52-9ccd-364c2aa20591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27252, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "繁荣", "is_correct": true, "explanation": "“繁荣”形容商店林立、市面热闹，与前句“一家挨着一家”相符，符合语境。"}, {"text": "透明", "is_correct": false, "explanation": "搭配：“透明”形容物体能透光，不能用来形容街市。"}, {"text": "寂静", "is_correct": false, "explanation": "语义：“一家挨着一家”说明热闹，与“寂静”矛盾。"}, {"text": "清澈", "is_correct": false, "explanation": "搭配：“清澈”形容水或眼神，不能用来形容街市。"}], "explanations": {"繁荣": "“繁荣”形容商店林立、市面热闹，与前句“一家挨着一家”相符，符合语境。", "透明": "搭配：“透明”形容物体能透光，不能用来形容街市。", "寂静": "语义：“一家挨着一家”说明热闹，与“寂静”矛盾。", "清澈": "搭配：“清澈”形容水或眼神，不能用来形容街市。"}, "sentence_index": 6, "correct_answer": "繁荣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的手臂很繁荣，经常举重。", "explanation": "这里应该用〈发达〉。“繁荣”形容生意或市面兴旺，形容人体肌肉、手臂发达要用“发达”。"}, {"text": "这个老板很繁荣，但从不炫耀。", "explanation": "这里应该用〈富有〉。“繁荣”形容生意兴旺、市面热闹，形容人有钱要用“富有”。"}, {"text": "我最近工作很繁荣，每天都加班。", "explanation": "这里应该用〈繁忙〉。“繁荣”形容生意或市面兴旺，形容工作多、忙碌要用“繁忙”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45fd609-c469-4c52-9ccd-364c2aa20591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27252, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "开了新地铁以后，这一带的生意繁荣下来了。", "corrected_sentence": "开了新地铁以后，这一带的生意繁荣起来了。", "error_description": "补语错误。“生意繁荣”由弱到强，要说“繁荣起来”；“繁荣下来”不符合表示变化的用法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45fd609-c469-4c52-9ccd-364c2aa20591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27252, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个城市的夜市一到晚上就很繁荣地。", "corrected_sentence": "这个城市的夜市一到晚上就很繁荣。", "error_description": "错误：句末多出“地”。“地”用在动词前作状语，句末不能只留“很繁荣地”，句子不完整。正确形式为“就很繁荣”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45fd609-c469-4c52-9ccd-364c2aa20591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
