INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27256, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "可以照着做或学习的样子。", "primary_collocate": null, "pronunciation": "fàn běn", "ipa": "fan˥˩ pən˨˩˦", "syllable_count": 2, "sentences": [{"text": "这是一份范本，你照着写就行。", "target_word": "范本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我找不到好范本，不知道怎么写。", "target_word": "范本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师的画是我们学画画的范本。", "target_word": "范本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本字帖是小学生练字的范本。", "target_word": "范本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈做的菜成了我学做饭的范本。", "target_word": "范本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的信写得很规范，可以当范本。", "target_word": "范本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有了范本，学写文章就容易多了。", "target_word": "范本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些作业都不错，我选了一份做范本。", "target_word": "范本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把这张表当作范本，照着填一下。", "target_word": "范本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老教授写的论文成了学生们的范本。", "target_word": "范本", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "範本", "label": "繁体"}], "register": "通用", "sense_fingerprint": "可以照着做、照着学的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f7f17ff-c32d-47a8-bf1e-867aef9f7341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27256, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "范本", "is_correct": true, "explanation": "正确：“范本”指可照着写的样子，与“你照着写就行”相合。"}, {"text": "午餐", "is_correct": false, "explanation": "语义：午餐与“照着写”的语境无关，不能作为写作的参照。"}, {"text": "彩虹", "is_correct": false, "explanation": "搭配：“份”用于文件、纸张等，不能与“彩虹”搭配。"}, {"text": "雨衣", "is_correct": false, "explanation": "语义：雨衣不能作为“照着写”的样子，句意不通。"}], "explanations": {"范本": "正确：“范本”指可照着写的样子，与“你照着写就行”相合。", "午餐": "语义：午餐与“照着写”的语境无关，不能作为写作的参照。", "彩虹": "搭配：“份”用于文件、纸张等，不能与“彩虹”搭配。", "雨衣": "语义：雨衣不能作为“照着写”的样子，句意不通。"}, "sentence_index": 0, "correct_answer": "范本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次实验收集了两百份范本。", "explanation": "语义：这里应该用〈样本〉。实验收集的是样本，“范本”指可照着学的样子。"}, {"text": "我的范本增加了两公斤。", "explanation": "语义：这里应该用〈体重〉。范本指可照着学的样子，不能用来指身体的重量，应说“我的体重增加了两公斤”。"}, {"text": "今天的范本很好，我们去公园散步吧。", "explanation": "语义：这里应该用〈天气〉。范本指可照着学的样子，不能用来说天气，应说“今天的天气很好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c165fc5-8ecb-4d31-a2d9-19aa7e835074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27256, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "范本", "is_correct": true, "explanation": "正确：“范本”指可照着学的样子，作“有了”的宾语，与“学写文章就容易多了”相合。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "语义：鸡蛋与学写文章无关，不能让学写文章变得容易。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞与学写文章的过程无关，句意不通。"}, {"text": "一张火车票", "is_correct": false, "explanation": "语义：火车票与学写文章无关，不能让学写文章变得容易。"}], "explanations": {"范本": "正确：“范本”指可照着学的样子，作“有了”的宾语，与“学写文章就容易多了”相合。", "鸡蛋": "语义：鸡蛋与学写文章无关，不能让学写文章变得容易。", "雨伞": "语义：雨伞与学写文章的过程无关，句意不通。", "一张火车票": "语义：火车票与学写文章无关，不能让学写文章变得容易。"}, "sentence_index": 6, "correct_answer": "范本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这箱苹果的范本是五公斤。", "explanation": "语义：这里应该用〈重量〉。范本指可照着学的样子，不能用来指苹果的重量，应说“这箱苹果的重量是五公斤”。"}, {"text": "工厂的货架上摆满了范本。", "explanation": "语义：这里应该用〈样品〉。货架上摆的是商品样品，“范本”指可照着学的样子。"}, {"text": "这座影院放映了许多范本。", "explanation": "语义：这里应该用〈电影〉。影院放映的是影片，“范本”指可照着学的样子，不能用来放映，应说“这座影院放映了许多电影”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c165fc5-8ecb-4d31-a2d9-19aa7e835074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27256, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈给我找了一把范本，让我照着写。", "corrected_sentence": "妈妈给我找了一份范本，让我照着写。", "error_description": "量词错误：“把”用于有柄的器物，“范本”应该用“份”。正确说法是“一份范本”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c165fc5-8ecb-4d31-a2d9-19aa7e835074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27256, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这篇论文可以作为学生们范本。", "corrected_sentence": "这篇论文可以作为学生们的范本。", "error_description": "缺少“的”：“学生们”与“范本”之间需要“的”。正确说法是“学生们的范本”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c165fc5-8ecb-4d31-a2d9-19aa7e835074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
