INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27260, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4ef227a-ccf3-4885-bd62-7a306efce275') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27260, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "学会了一个以前不会的本领。", "primary_collocate": null, "pronunciation": "xīn jì néng", "ipa": "ɕin˥ tɕi˥˩ nɤŋ˧˥", "syllable_count": 3, "sentences": [{"text": "弟弟学会了一个新技能，会骑车了。", "target_word": "新技能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥今年有了新技能：做饭。", "target_word": "新技能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个新技能我以前不会。", "target_word": "新技能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的新技能是画画。", "target_word": "新技能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学好新技能要多练习。", "target_word": "新技能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想用周末学一个新技能。", "target_word": "新技能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有新技能，所以找到了工作。", "target_word": "新技能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶的新技能是用手机。", "target_word": "新技能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的新技能是什么？", "target_word": "新技能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在夏天学了新技能：游泳。", "target_word": "新技能", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一项新技能", "label": "量词"}, {"form": "一个新技能", "label": "量词"}], "register": "中性", "sense_fingerprint": "以前不会、现在学会的本领", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '228a4112-dbe4-4f55-9364-4edc773aa3f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27260, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "新技能", "is_correct": true, "explanation": "正确：学会一个新技能，与“会骑车了”相合。"}, {"text": "杯子", "is_correct": false, "explanation": "语义：学会的不能是杯子，且与“会骑车了”不符。"}, {"text": "房间", "is_correct": false, "explanation": "语义：房间不是可以学会的本领。"}, {"text": "机器", "is_correct": false, "explanation": "搭配：“学会”的对象是能力，不说“学会一台机器”。"}], "explanations": {"新技能": "正确：学会一个新技能，与“会骑车了”相合。", "杯子": "语义：学会的不能是杯子，且与“会骑车了”不符。", "房间": "语义：房间不是可以学会的本领。", "机器": "搭配：“学会”的对象是能力，不说“学会一台机器”。"}, "sentence_index": 0, "correct_answer": "新技能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她学了一部新技能。", "explanation": "这里应该用〈项〉或〈个〉。〈部〉用于电影、书籍，不用于技能。"}, {"text": "她的新技能是一箱牛奶。", "explanation": "这里应该用〈礼物〉之类的词。“一箱牛奶”是物品，不是学会的本领。"}, {"text": "她的新技能是一幅画。", "explanation": "这里应该用〈作品〉。画出来的成果是作品，技能是人学会的本领，不能说“是一幅画”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4ef227a-ccf3-4885-bd62-7a306efce275') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27260, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "新技能", "is_correct": true, "explanation": "正确：有了新技能，所以找到了工作，前后因果相合。"}, {"text": "行李", "is_correct": false, "explanation": "语义：有行李与找到工作没有因果关系。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：带雨伞与找到工作没有因果关系。"}, {"text": "房子", "is_correct": false, "explanation": "语义：有房子不等于找到了工作，二者没有因果关系。"}], "explanations": {"新技能": "正确：有了新技能，所以找到了工作，前后因果相合。", "行李": "语义：有行李与找到工作没有因果关系。", "雨伞": "语义：带雨伞与找到工作没有因果关系。", "房子": "语义：有房子不等于找到了工作，二者没有因果关系。"}, "sentence_index": 6, "correct_answer": "新技能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们在夏天学了一张新技能：游泳。", "explanation": "这里应该用〈项〉。〈张〉用于纸张、桌面等平面物，不用于技能。"}, {"text": "孩子们在夏天参加了一个新技能：游泳。", "explanation": "这里应该用〈项目〉。“参加”的对象是活动或比赛，技能不能参加。"}, {"text": "孩子们把新技能装进了书包。", "explanation": "这里是把〈技能〉当成了〈东西〉。技能是学会的本领，不能装进书包。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4ef227a-ccf3-4885-bd62-7a306efce275') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27260, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹学会了一只新技能，会游泳了。", "corrected_sentence": "妹妹学会了一项新技能，会游泳了。", "error_description": "“一只新技能”应为“一项新技能”。“只”用于动物等，技能要用“项”或“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4ef227a-ccf3-4885-bd62-7a306efce275') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27260, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爷爷新技能是骑车。", "corrected_sentence": "爷爷的新技能是骑车。", "error_description": "“爷爷新技能”应为“爷爷的新技能”。表示所属的人（爷爷）修饰后面的名词短语时要加“的”，“新”作定语则不需要“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4ef227a-ccf3-4885-bd62-7a306efce275') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27262, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "工作", "is_correct": true, "explanation": "正确。“工作”与“休息”构成反义：工作是做事，休息是停下来不做事。"}, {"text": "散步", "is_correct": false, "explanation": "散步是一种轻松的活动，与“休息”并不构成反义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "游泳是一种运动，并不与“休息”相对，不构成反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行是一种活动，与“休息”没有反义关系，不能作为其反义词。"}], "correct_answer": "工作", "explanations": {"工作": "正确。“工作”与“休息”构成反义：工作是做事，休息是停下来不做事。", "散步": "散步是一种轻松的活动，与“休息”并不构成反义关系。", "游泳": "游泳是一种运动，并不与“休息”相对，不构成反义关系。", "旅行": "旅行是一种活动，与“休息”没有反义关系，不能作为其反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27262, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "工作", "is_correct": true, "explanation": "正确。“工作”与“休息”构成反义：工作是做事，休息是停下来不做事。"}, {"text": "跑步", "is_correct": false, "explanation": "跑步是一种运动，并不与“休息”相对，不构成反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌是一种娱乐活动，与“休息”没有反义关系。"}, {"text": "读书", "is_correct": false, "explanation": "读书是一种学习活动，并不是“休息”的反义词。"}], "correct_answer": "工作", "explanations": {"工作": "正确。“工作”与“休息”构成反义：工作是做事，休息是停下来不做事。", "跑步": "跑步是一种运动，并不与“休息”相对，不构成反义关系。", "唱歌": "唱歌是一种娱乐活动，与“休息”没有反义关系。", "读书": "读书是一种学习活动，并不是“休息”的反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27262, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "累了就停下来，不做事。", "primary_collocate": null, "pronunciation": "xiū xi", "ipa": "ɕjoʊ˥ ɕi", "syllable_count": 2, "sentences": [{"text": "走了很久，我们在树下休息。", "target_word": "休息", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "累了就坐下休息，不用急。", "target_word": "休息", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我很累，想休息一会儿。", "target_word": "休息", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老人走累了，坐在椅子上休息。", "target_word": "休息", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一直在工作，从来不休息。", "target_word": "休息", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爬山爬到一半，大家停下来休息。", "target_word": "休息", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "先休息五分钟，再继续写。", "target_word": "休息", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈做了一天饭，晚上也想休息。", "target_word": "休息", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子玩累了，回房间休息。", "target_word": "休息", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你别吵，爸爸正在休息。", "target_word": "休息", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "休息了", "label": "体标"}, {"form": "休息过", "label": "体标"}, {"form": "休息休息", "label": "重叠"}], "register": "口语", "sense_fingerprint": "累了停下来，不做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '618ae9a4-f14e-4a14-a72f-8b79178904af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27262, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "游泳", "is_correct": false, "explanation": "语义：树下没有水，“在树下游泳”与前文“走了很久”的语境不合。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“在树下考试”不合常理，与句中走路之后的情境不相容。"}, {"text": "买", "is_correct": false, "explanation": "配价：“买”需要带宾语（买什么），“在树下买”缺少宾语，句子不完整。"}, {"text": "休息", "is_correct": true, "explanation": "正确。“在树下休息”指走累后停下来歇一歇，与“走了很久”相合。"}], "explanations": {"游泳": "语义：树下没有水，“在树下游泳”与前文“走了很久”的语境不合。", "考试": "语义：“在树下考试”不合常理，与句中走路之后的情境不相容。", "买": "配价：“买”需要带宾语（买什么），“在树下买”缺少宾语，句子不完整。", "休息": "正确。“在树下休息”指走累后停下来歇一歇，与“走了很久”相合。"}, "sentence_index": 0, "correct_answer": "休息"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆摩托车骑到半路突然休息了，只好推着走。", "explanation": "这里应该用〈熄火〉。休息用于人或动物，指停下来不做事、恢复精力；摩托车发动机停止运转应说熄火。"}, {"text": "这台风扇连续转了一夜，后来休息了。", "explanation": "这里应该用〈停转〉。休息用于人，指累了停下来；风扇停止转动应说停转，风扇不会累。"}, {"text": "这条地铁线路因故休息了。", "explanation": "这里应该用〈停运〉。休息指人停下来不做事，线路因故停止运营应说停运。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27262, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喝", "is_correct": false, "explanation": "配价：“喝”需要带宾语（喝什么），“先喝五分钟”缺少宾语，句子不成立。"}, {"text": "结束", "is_correct": false, "explanation": "搭配：“结束”指完成某件事，不说“结束五分钟”，与“再继续写”的语境也不合。"}, {"text": "休息", "is_correct": true, "explanation": "正确。“先休息五分钟，再继续写”表示暂停一下再接着做，搭配自然。"}, {"text": "生气", "is_correct": false, "explanation": "语义：“生气”是情绪，不是可以安排时间的动作，“先生气五分钟，再继续写”句意不通。"}], "explanations": {"喝": "配价：“喝”需要带宾语（喝什么），“先喝五分钟”缺少宾语，句子不成立。", "结束": "搭配：“结束”指完成某件事，不说“结束五分钟”，与“再继续写”的语境也不合。", "休息": "正确。“先休息五分钟，再继续写”表示暂停一下再接着做，搭配自然。", "生气": "语义：“生气”是情绪，不是可以安排时间的动作，“先生气五分钟，再继续写”句意不通。"}, "sentence_index": 6, "correct_answer": "休息"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子坐了一下午，现在休息了。", "explanation": "这里应该用〈坏了〉。休息用于人或动物，指停下来恢复精力；椅子不会累，不能说休息。"}, {"text": "这根蜡烛点了一夜，现在休息了。", "explanation": "这里应该用〈燃尽〉。休息指人停下活动、恢复精力；蜡烛烧完应说燃尽。"}, {"text": "这张桌子被搬走以后，就休息在墙角。", "explanation": "这里应该用〈放置〉。桌子不能休息，搬走后只能说放在墙角。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27262, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我走累了，休息一个会儿就继续走。", "corrected_sentence": "我走累了，休息一会儿就继续走。", "error_description": "量词错误：“一会儿”是固定说法，中间不能加“个”，应说“休息一会儿”，不能说“休息一个会儿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27262, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在树下休息着一会儿吧。", "corrected_sentence": "我们在树下休息一会儿吧。", "error_description": "体标错误：“休息”后面带时量“一会儿”时不能用“着”，应说“休息一会儿”，不能说“休息着一会儿”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
