INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27264, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "公司让一些人不再工作。", "primary_collocate": null, "pronunciation": "cái yuán", "ipa": "tsʰaɪ˧˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "公司要裁员，我很担心。", "target_word": "裁员", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家店生意不好，开始裁员。", "target_word": "裁员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们公司上个月裁员了，他没有工作了。", "target_word": "裁员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为裁员，公司少了二十个人。", "target_word": "裁员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板为了省钱，决定裁员。", "target_word": "裁员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "裁员以后，大家的压力都变大了。", "target_word": "裁员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司裁员，她失去了工作，心情不好。", "target_word": "裁员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新闻说那家大公司又要裁员了。", "target_word": "裁员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小公司钱不够，也只能裁员。", "target_word": "裁员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司裁员时，老板先和大家开会。", "target_word": "裁员", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "裁员潮", "label": "复合"}, {"form": "裁员计划", "label": "复合"}, {"form": "裁員", "label": "繁体"}], "register": "中性", "sense_fingerprint": "公司让一部分人失去工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3108ec33-339a-4478-bb81-96f499e82975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27264, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "裁员", "is_correct": true, "explanation": "裁员：公司辞退员工，我因此担心。"}, {"text": "加薪", "is_correct": false, "explanation": "语义：加薪是好事，与“我很担心”的语气不合。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌与公司的决定无关，“公司要唱歌”不通。"}, {"text": "修车", "is_correct": false, "explanation": "搭配：“修车”的宾语是车辆，“公司要修车”不会让人担心。"}], "explanations": {"裁员": "裁员：公司辞退员工，我因此担心。", "加薪": "语义：加薪是好事，与“我很担心”的语气不合。", "唱歌": "语义：唱歌与公司的决定无关，“公司要唱歌”不通。", "修车": "搭配：“修车”的宾语是车辆，“公司要修车”不会让人担心。"}, "sentence_index": 0, "correct_answer": "裁员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我因为要照顾父母，决定裁员，搬回老家。", "explanation": "这里应该用〈辞职〉。裁员的主体是公司，个人因家庭原因主动离职要用辞职。"}, {"text": "我叔叔六十岁那年裁员了，现在每天在家养花。", "explanation": "这里应该用〈退休〉。裁员是单位辞退员工，到了年龄离开工作要用退休。"}, {"text": "学校放暑假了，学生们都裁员回家了。", "explanation": "这里应该用〈放假〉。裁员是公司辞退员工，学生假期离校回家要用放假。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd951c2e-fe87-454e-9bcd-b9c931db3176') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27264, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "裁员", "is_correct": true, "explanation": "裁员：公司辞退员工，她因此失去了工作。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步与公司人事变动无关，“公司散步”不通。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：游泳与她失去工作的因果无关，“公司游泳”不通。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“考试”不以公司为主语，“公司考试，她失去了工作”搭配不当。"}], "explanations": {"裁员": "裁员：公司辞退员工，她因此失去了工作。", "散步": "语义：散步与公司人事变动无关，“公司散步”不通。", "游泳": "语义：游泳与她失去工作的因果无关，“公司游泳”不通。", "考试": "搭配：“考试”不以公司为主语，“公司考试，她失去了工作”搭配不当。"}, "sentence_index": 6, "correct_answer": "裁员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家商店今年裁员了一批旧货，都打了折。", "explanation": "这里应该用〈清仓〉。裁员的对象必须是员工，旧货处理要用清仓。"}, {"text": "他因为生病，裁员了一个星期。", "explanation": "这里应该用〈请假〉。裁员是单位辞退员工，个人暂时不上班要用请假。"}, {"text": "工人们今天裁员，在厂门口坐了一整天。", "explanation": "这里应该用〈罢工〉。裁员是公司辞退员工的行为，工人集体停工抗议要用罢工。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd951c2e-fe87-454e-9bcd-b9c931db3176') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27264, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司要裁员员工，大家都很担心。", "corrected_sentence": "公司要裁员，大家都很担心。", "error_description": "宾语重复：“裁员”本身已包含“员”，不能再带“员工”作宾语。错误形式是“裁员员工”，正确形式是“裁员”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd951c2e-fe87-454e-9bcd-b9c931db3176') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27264, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司很裁员，她失去了工作。", "corrected_sentence": "公司经常裁员，她失去了工作。", "error_description": "副词错误：“很”不能直接修饰动词“裁员”，表示频率应改用“经常”。错误形式是“公司很裁员”，正确形式是“公司经常裁员”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd951c2e-fe87-454e-9bcd-b9c931db3176') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
