INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27266, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "能还是不能，问别人一件事行不行。", "primary_collocate": null, "pronunciation": "néng fǒu", "ipa": "nɤŋ˧˥ fou˨˩˦", "syllable_count": 2, "sentences": [{"text": "请问，能否告诉我去车站的路？", "target_word": "能否", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师，能否再讲一遍这个问题？", "target_word": "能否", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能否明天早点来？", "target_word": "能否", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "能否请你把门关上？", "target_word": "能否", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理，能否给我一天时间考虑？", "target_word": "能否", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "能否麻烦你帮我拍张照片？", "target_word": "能否", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想问一下，这里能否停车？", "target_word": "能否", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "能否请您小声一点？", "target_word": "能否", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "您能否把地址写给我？", "target_word": "能否", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下周的会，你能否参加？", "target_word": "能否", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "能不能", "label": "口语形式"}], "register": "书面", "sense_fingerprint": "书面语，礼貌地问对方能不能做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42af6dd8-76df-4128-9f4d-41a929127788') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27266, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "能否", "is_correct": true, "explanation": "正确。“能否”用于礼貌地询问对方能不能帮忙，符合“请问”的语境。"}, {"text": "应该", "is_correct": false, "explanation": "语义：“应该”表示义务，用在请求别人帮忙的句子里，语气变成了要求。"}, {"text": "敢", "is_correct": false, "explanation": "语义：“敢”问的是有没有胆量，向人问路不是胆量问题，不符合礼貌请求的句意。"}, {"text": "得", "is_correct": false, "explanation": "语域：“得”表示必要，对陌生人说“得告诉我”显得命令，不符合礼貌请求的语域。"}], "explanations": {"能否": "正确。“能否”用于礼貌地询问对方能不能帮忙，符合“请问”的语境。", "应该": "语义：“应该”表示义务，用在请求别人帮忙的句子里，语气变成了要求。", "敢": "语义：“敢”问的是有没有胆量，向人问路不是胆量问题，不符合礼貌请求的句意。", "得": "语域：“得”表示必要，对陌生人说“得告诉我”显得命令，不符合礼貌请求的语域。"}, "sentence_index": 0, "correct_answer": "能否"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一定能否帮你把门关上。", "explanation": "“能否”用于询问能不能、行不行，不能与“一定”这类表示确定的词连用；表示确定能帮忙应说〈能够〉，即“我一定能够帮你把门关上”。"}, {"text": "我们已经能否把桌子搬到外面了。", "explanation": "“能否”表示还在询问能不能，与“已经”表示的完成事实矛盾；表示已经能做到应说〈能够〉，即“我们已经能够把桌子搬到外面了”。"}, {"text": "这份工作他肯定能否胜任。", "explanation": "“能否”表示还不确定能不能做到，不能与“肯定”连用；表示确定能胜任应说〈能够胜任〉，即“他肯定能够胜任这份工作”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '162139ae-0c32-4afa-8b85-9269af9a2c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27266, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "能否", "is_correct": true, "explanation": "正确。“能否”用于询问这里能不能停车，符合“我想问一下”的语境。"}, {"text": "喜欢", "is_correct": false, "explanation": "搭配：“喜欢”要求有好恶的主语，“这里”不能“喜欢停车”，句意不通。"}, {"text": "肯", "is_correct": false, "explanation": "搭配：“肯”表示愿意，要求主语是有意愿的人，“这里”不能说“肯停车”。"}, {"text": "愿意", "is_correct": false, "explanation": "搭配：“愿意”要求有意愿的主语，地点不能作主语表示愿意。"}], "explanations": {"能否": "正确。“能否”用于询问这里能不能停车，符合“我想问一下”的语境。", "喜欢": "搭配：“喜欢”要求有好恶的主语，“这里”不能“喜欢停车”，句意不通。", "肯": "搭配：“肯”表示愿意，要求主语是有意愿的人，“这里”不能说“肯停车”。", "愿意": "搭配：“愿意”要求有意愿的主语，地点不能作主语表示愿意。"}, "sentence_index": 6, "correct_answer": "能否"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服能否很漂亮。", "explanation": "“能否”用于询问能不能做某事，后面要接动词，不能接形容词「漂亮」；这里应直接说〈很漂亮〉，即“这件衣服很漂亮”。"}, {"text": "这片地能否种出庄稼，已经收获三次了。", "explanation": "“能否”表示还不确定能不能，与“已经收获三次”的事实矛盾；陈述已经能种出来应说〈能够〉。"}, {"text": "小王已经能否准时到达了。", "explanation": "“能否”表示还不确定能不能做到，与“已经……了”表示的事实矛盾；表示能做到应说〈能够〉，即“小王已经能够准时到达了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '162139ae-0c32-4afa-8b85-9269af9a2c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27266, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "您好，能否能帮我看一下这份表格？", "corrected_sentence": "您好，能否帮我看一下这份表格？", "error_description": "情态重复错误：“能否”后又多加了一个“能”，两个情态成分不能并列。应只保留“能否”，即“您好，能否帮我看一下这份表格？”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '162139ae-0c32-4afa-8b85-9269af9a2c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27266, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师，能否借了我用一下笔？", "corrected_sentence": "老师，能否借我用一下笔？", "error_description": "体标错误：“借”后不能加“了”。这是请求句，动作尚未发生，应为“老师，能否借我用一下笔”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '162139ae-0c32-4afa-8b85-9269af9a2c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27268, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "就业", "is_correct": true, "explanation": "就业：指有工作、进入工作岗位，与“失业”意义相反。"}, {"text": "辞职", "is_correct": false, "explanation": "辞职指主动离开现有工作，与“失业”不是反义关系。"}, {"text": "退休", "is_correct": false, "explanation": "退休指到了规定年龄不再工作，与“失业”不是反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "无关：“散步”是休闲活动，与“失业”不构成反义关系。"}], "correct_answer": "就业", "explanations": {"就业": "就业：指有工作、进入工作岗位，与“失业”意义相反。", "辞职": "辞职指主动离开现有工作，与“失业”不是反义关系。", "退休": "退休指到了规定年龄不再工作，与“失业”不是反义关系。", "散步": "无关：“散步”是休闲活动，与“失业”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a5ded58-6004-4c0b-b250-389fa523ecfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27268, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "就业", "is_correct": true, "explanation": "就业：指有工作、进入工作岗位，与“失业”意义相反。"}, {"text": "休息", "is_correct": false, "explanation": "休息指停下来放松，与“失业”不是反义关系。"}, {"text": "旅游", "is_correct": false, "explanation": "旅游指外出游览，与“失业”不是反义关系。"}, {"text": "结婚", "is_correct": false, "explanation": "结婚指建立婚姻关系，与“失业”不是反义关系。"}], "correct_answer": "就业", "explanations": {"就业": "就业：指有工作、进入工作岗位，与“失业”意义相反。", "休息": "休息指停下来放松，与“失业”不是反义关系。", "旅游": "旅游指外出游览，与“失业”不是反义关系。", "结婚": "结婚指建立婚姻关系，与“失业”不是反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a5ded58-6004-4c0b-b250-389fa523ecfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27268, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "没有工作做。", "primary_collocate": null, "pronunciation": "shī yè", "ipa": "ʂʅ˥ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "他已经失业三个月了，每天都待在家里。", "target_word": "失业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥现在失业，白天在家照顾孩子。", "target_word": "失业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "失业的日子里，他常常去公园走一走。", "target_word": "失业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸失业了，我们要少花一点钱。", "target_word": "失业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她失业很久了，还没找到合适的事做。", "target_word": "失业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你失业的时候，朋友有没有帮你？", "target_word": "失业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他虽然失业，但是每天都按时起床。", "target_word": "失业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说小王最近失业了，我想请他吃饭。", "target_word": "失业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想一直失业，所以天天看招聘信息。", "target_word": "失业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在失业的年轻人比以前多了。", "target_word": "失业", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "失业了", "label": "体标"}, {"form": "失业过", "label": "体标"}], "register": "中性", "sense_fingerprint": "处于没有工作可做的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31610bca-58b2-44ff-ad3a-29a665b138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27268, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "失业", "is_correct": true, "explanation": "正确：失业（shī yè），指处于没有工作可做的状态。"}, {"text": "事业", "is_correct": false, "explanation": "shì（第四声）与 shī（第一声）声调不同，意思是事业。"}, {"text": "视野", "is_correct": false, "explanation": "shì（第四声）与 shī（第一声）声调不同，yě（第三声）与 yè（第四声）声调也不同，意思是视野。"}, {"text": "诗意", "is_correct": false, "explanation": "shī 相同，yì（第四声）与 yè（第四声）韵母不同，意思是诗意。"}], "explanations": {"失业": "正确：失业（shī yè），指处于没有工作可做的状态。", "事业": "shì（第四声）与 shī（第一声）声调不同，意思是事业。", "视野": "shì（第四声）与 shī（第一声）声调不同，yě（第三声）与 yè（第四声）声调也不同，意思是视野。", "诗意": "shī 相同，yì（第四声）与 yè（第四声）韵母不同，意思是诗意。"}, "sentence_index": null, "correct_answer": "失业"}, "level_3": {"options": [{"text": "失业", "is_correct": true, "explanation": "正确：“失业”指没有工作可做，与“已经……三个月了，每天都待在家里”的语境一致。"}, {"text": "出差", "is_correct": false, "explanation": "语义：“出差”指外出办公，与“每天都待在家里”矛盾。"}, {"text": "去世", "is_correct": false, "explanation": "语义：“去世”指人已经死亡，不能每天待在家里，与语境矛盾。"}, {"text": "解决", "is_correct": false, "explanation": "配价：“解决”是及物动词，必须带宾语，“已经解决三个月了”结构不完整。"}], "explanations": {"失业": "正确：“失业”指没有工作可做，与“已经……三个月了，每天都待在家里”的语境一致。", "出差": "语义：“出差”指外出办公，与“每天都待在家里”矛盾。", "去世": "语义：“去世”指人已经死亡，不能每天待在家里，与语境矛盾。", "解决": "配价：“解决”是及物动词，必须带宾语，“已经解决三个月了”结构不完整。"}, "sentence_index": 0, "correct_answer": "失业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我妈妈每天五点失业，回家做饭。", "explanation": "这里应该用〈下班〉。下班指每天工作结束后离开单位；“失业”指没有工作可做，不能用于每天的工作结束。"}, {"text": "他觉得这份工作太累，就把它失业了，在家写小说。", "explanation": "这里应该用〈辞职〉。“失业”是不及物动词，不能带“把”引出的宾语；主动离开工作要说辞职。"}, {"text": "他下个月要请长假去旅行，所以提前失业了。", "explanation": "这里应该用〈请假〉。请假是暂时离开工作、之后还会回去；失业指失去工作，不能用于短期休假。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a5ded58-6004-4c0b-b250-389fa523ecfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27268, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "失业", "is_correct": true, "explanation": "正确：失业（shī yè），指处于没有工作可做的状态。"}, {"text": "实业", "is_correct": false, "explanation": "shí（第二声）与 shī（第一声）声调不同，意思是实业。"}, {"text": "书页", "is_correct": false, "explanation": "shū 与 shī 韵母不同（u 与 i），yè 相同，意思是书页。"}, {"text": "枝叶", "is_correct": false, "explanation": "zhī 与 shī 声母不同（zh 与 sh），yè 相同，意思是枝叶。"}], "explanations": {"失业": "正确：失业（shī yè），指处于没有工作可做的状态。", "实业": "shí（第二声）与 shī（第一声）声调不同，意思是实业。", "书页": "shū 与 shī 韵母不同（u 与 i），yè 相同，意思是书页。", "枝叶": "zhī 与 shī 声母不同（zh 与 sh），yè 相同，意思是枝叶。"}, "sentence_index": null, "correct_answer": "失业"}, "level_3": {"options": [{"text": "失业", "is_correct": true, "explanation": "正确：“失业”指没有工作可做，与“虽然……，但是每天都按时起床”的语境一致。"}, {"text": "殉职", "is_correct": false, "explanation": "语义：“殉职”指因公去世，与“每天都按时起床”矛盾。"}, {"text": "拥有", "is_correct": false, "explanation": "配价：“拥有”是及物动词，必须带宾语，“虽然拥有”结构不完整。"}, {"text": "举行", "is_correct": false, "explanation": "搭配：“举行”搭配的是活动、仪式等，不能用来说“他”这个人。"}], "explanations": {"失业": "正确：“失业”指没有工作可做，与“虽然……，但是每天都按时起床”的语境一致。", "殉职": "语义：“殉职”指因公去世，与“每天都按时起床”矛盾。", "拥有": "配价：“拥有”是及物动词，必须带宾语，“虽然拥有”结构不完整。", "举行": "搭配：“举行”搭配的是活动、仪式等，不能用来说“他”这个人。"}, "sentence_index": 6, "correct_answer": "失业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家网站已经失业了，所以访问的人很少。", "explanation": "这里说的是网站停止运营、无法访问，失业只指人没有工作，不能用来描述网站。"}, {"text": "那间教室上个月失业了，学生都搬去了新楼。", "explanation": "这里说的是教室不再使用、被搬空，失业只指人没有工作，不能用来描述教室。"}, {"text": "那辆旧汽车前年就失业了，一直停在院子里。", "explanation": "这里说的是汽车坏了、不能再开，失业只指人没有工作，不能用来描述汽车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a5ded58-6004-4c0b-b250-389fa523ecfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27268, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妹妹上个月失业了工作，现在在家学做蛋糕。", "corrected_sentence": "我妹妹上个月失业了，现在在家学做蛋糕。", "error_description": "宾语错误：“失业”本身已包含“业（工作）”，是不能带宾语的动词，后面不能再接“工作”，应说“上个月失业了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a5ded58-6004-4c0b-b250-389fa523ecfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27268, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我舅舅去年很失业了，但是很快就找到了新工作。", "corrected_sentence": "我舅舅去年失业了，但是很快就找到了新工作。", "error_description": "程度副词错误：“失业”表示没有工作可做，不能用“很”来修饰，应去掉“很”，写作“去年失业了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a5ded58-6004-4c0b-b250-389fa523ecfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
