INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27272, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "没有很多钱的人。", "primary_collocate": null, "pronunciation": "qióng rén", "ipa": "tɕʰʏŋ˧˥ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "穷人没有很多钱，所以不常去饭店。", "target_word": "穷人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小城里有富人，也有穷人。", "target_word": "穷人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好心的老板常常送米给穷人。", "target_word": "穷人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "穷人的钱不多，每一分都要想好再用。", "target_word": "穷人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她说：“我是穷人，可是我很快乐。”", "target_word": "穷人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书写的是一个穷人的故事。", "target_word": "穷人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "穷人买东西时，先看价钱。", "target_word": "穷人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨天，穷人没有伞，只好在路边等。", "target_word": "穷人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把自己的钱都给了穷人。", "target_word": "穷人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要帮助穷人，不要看不起他们。", "target_word": "穷人", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "窮人", "label": "繁体"}], "register": "中性", "sense_fingerprint": "钱不多的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '618ae9a4-f14e-4a14-a72f-8b79178904af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27272, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "穷人", "is_correct": true, "explanation": "正确。「穷人没有很多钱，所以不常去饭店」描述没有很多钱的人，只有「穷人」能填入空格。"}, {"text": "富人", "is_correct": false, "explanation": "语义：富人一般有很多钱，「富人没有很多钱」与句意矛盾。"}, {"text": "富豪", "is_correct": false, "explanation": "语义：富豪的钱通常很多，「富豪没有很多钱」与后半句的因果不成立。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：小狗不会去饭店，也不用钱，「小狗没有很多钱，所以不常去饭店」句意不通。"}], "explanations": {"穷人": "正确。「穷人没有很多钱，所以不常去饭店」描述没有很多钱的人，只有「穷人」能填入空格。", "富人": "语义：富人一般有很多钱，「富人没有很多钱」与句意矛盾。", "富豪": "语义：富豪的钱通常很多，「富豪没有很多钱」与后半句的因果不成立。", "小狗": "语义：小狗不会去饭店，也不用钱，「小狗没有很多钱，所以不常去饭店」句意不通。"}, "sentence_index": 0, "correct_answer": "穷人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小镇的穷人家家都有好几辆汽车。", "explanation": "「穷人」指没有很多钱的人，「家家都有好几辆汽车」与之矛盾，句子不成立。"}, {"text": "这个穷人国家正在积极寻找外国援助。", "explanation": "「穷人」指人，说国家经济落后应该用「穷国」。"}, {"text": "这所小学的穷人学生都是富二代。", "explanation": "「穷人」指没有很多钱的人，与「富二代」矛盾，句子不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27272, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "穷人", "is_correct": true, "explanation": "正确。「穷人买东西时，先看价钱」描述钱不多的人的消费习惯，只有「穷人」能填入空格。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿不会买东西，「婴儿买东西时先看价钱」句意不通。"}, {"text": "神仙", "is_correct": false, "explanation": "语义：神仙一般不需要买东西，「神仙买东西时先看价钱」句意不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会买东西，「石头买东西时先看价钱」句意不通。"}], "explanations": {"穷人": "正确。「穷人买东西时，先看价钱」描述钱不多的人的消费习惯，只有「穷人」能填入空格。", "婴儿": "语义：婴儿不会买东西，「婴儿买东西时先看价钱」句意不通。", "神仙": "语义：神仙一般不需要买东西，「神仙买东西时先看价钱」句意不通。", "石头": "语义：石头不会买东西，「石头买东西时先看价钱」句意不通。"}, "sentence_index": 6, "correct_answer": "穷人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这项政策能帮助国家摆脱穷人的局面。", "explanation": "「摆脱」的对象应是「贫困」，「穷人」指人，不能用来表示状况。"}, {"text": "这座老城里有一片穷人窟。", "explanation": "「穷人窟」不是固定说法，表示居住区应说「贫民窟」，「穷人」只指人。"}, {"text": "这所学校的穷人生最近增加了很多。", "explanation": "「穷人」不能缩略成「生」，表示家境困难的学生应说「贫困生」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27272, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只穷人很可怜，我想帮助他。", "corrected_sentence": "这个穷人很可怜，我想帮助他。", "error_description": "错误形式「这只穷人」，量词「只」用于动物，不能用于人。正确形式「这个穷人」，指人应该用「个」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27272, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把东西送给了很穷人。", "corrected_sentence": "他把东西送给了很穷的人。", "error_description": "错误形式「很穷人」，「穷」是形容词，直接修饰名词时要加「的」。正确形式「很穷的人」，形容词修饰名词需用「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
