INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27274, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个人有很多钱和东西。", "primary_collocate": null, "pronunciation": "cái fù", "ipa": "tsʰaɪ˧˥ fu˥˩", "syllable_count": 2, "sentences": [{"text": "他很有钱，财富多得数不清。", "target_word": "财富", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "富人的财富常常来自生意。", "target_word": "财富", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从爷爷那里得到一大笔财富。", "target_word": "财富", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把财富留给了三个孩子。", "target_word": "财富", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人的财富比我们想的多。", "target_word": "财富", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻时他没有财富，但是很努力。", "target_word": "财富", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别看他穿得简单，其实财富很多。", "target_word": "财富", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "杂志每年公布最有钱的人和他们的财富。", "target_word": "财富", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想用自己的财富帮助穷人。", "target_word": "财富", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座大房子是他一生的财富。", "target_word": "财富", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一笔财富", "label": "量词"}, {"form": "财富观", "label": "复合"}, {"form": "財富", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一个人拥有的大量钱和东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3108ec33-339a-4478-bb81-96f499e82975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27274, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "财富", "is_correct": true, "explanation": "正确：“财富”指一个人拥有的大量钱和东西，与“很有钱”呼应。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是身体特征，与“很有钱”没有关系，也不能“多得数不清”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不会“多得数不清”，句子语义不通。"}, {"text": "饭量", "is_correct": false, "explanation": "搭配：“多得数不清”不与“饭量”搭配，句意荒谬。"}], "explanations": {"财富": "正确：“财富”指一个人拥有的大量钱和东西，与“很有钱”呼应。", "身高": "体貌：身高是身体特征，与“很有钱”没有关系，也不能“多得数不清”。", "年龄": "语义：年龄不会“多得数不清”，句子语义不通。", "饭量": "搭配：“多得数不清”不与“饭量”搭配，句意荒谬。"}, "sentence_index": 0, "correct_answer": "财富"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他出门时身上带了很多财富。", "explanation": "这里应该用〈钱〉。随身携带的现金要说“钱”，财富指积累的财物总和。"}, {"text": "他这几年财富特别旺，买东西总是很顺利。", "explanation": "这里应该用〈财运〉。财运指一段时间的运气，财富是已拥有财物的总和，不能说“旺”。"}, {"text": "他在科研上取得了很大的财富。", "explanation": "这里应该用〈成就〉。财富指财物，不用于说明科研或事业上的成绩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd951c2e-fe87-454e-9bcd-b9c931db3176') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27274, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "财富", "is_correct": true, "explanation": "正确：“财富”指一个人拥有的大量钱和东西，与“穿得简单”形成对比。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温不是可以“很多”的东西，句意不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材是外形特征，“其实身材很多”不通，也与“穿得简单”无关。"}, {"text": "血型", "is_correct": false, "explanation": "语义：血型只有有限的类别，不能说“很多”，句意不通。"}], "explanations": {"财富": "正确：“财富”指一个人拥有的大量钱和东西，与“穿得简单”形成对比。", "体温": "语义：体温不是可以“很多”的东西，句意不通。", "身材": "体貌：身材是外形特征，“其实身材很多”不通，也与“穿得简单”无关。", "血型": "语义：血型只有有限的类别，不能说“很多”，句意不通。"}, "sentence_index": 6, "correct_answer": "财富"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的财富很好，每件事都记得清清楚楚。", "explanation": "这里应该用〈记性〉。财富指财物和金钱的总和，不用来说明记忆力的好坏。"}, {"text": "他的财富每个月按时发到银行卡上。", "explanation": "这里应该用〈工资〉。财富是积累的财物总和，不是每月定期发放的款项。"}, {"text": "这部电影的财富很高，大家都喜欢。", "explanation": "这里应该用〈价值〉。财富指财物和金钱的总和，不用来评价一部电影的好坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd951c2e-fe87-454e-9bcd-b9c931db3176') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27274, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他留下了一本可观的财富。", "corrected_sentence": "他留下了一笔可观的财富。", "error_description": "错误：量词“本”；正确：量词“笔”。“本”用于书籍等，不能修饰财富。财富的量词是“笔”，错误形式是“一本财富”，正确形式是“一笔财富”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd951c2e-fe87-454e-9bcd-b9c931db3176') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27274, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个人有很财富，却很少帮助别人。", "corrected_sentence": "这个人有很多财富，却很少帮助别人。", "error_description": "错误：“很财富”；正确：“很多财富”。“很”不能直接修饰名词“财富”，表示数量多要用“很多”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd951c2e-fe87-454e-9bcd-b9c931db3176') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27278, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "更少", "is_correct": true, "explanation": "更少：数量比原来或别处少，与“更多”意义相反。"}, {"text": "快", "is_correct": false, "explanation": "快：形容速度，与“更多”没有反义关系。"}, {"text": "好", "is_correct": false, "explanation": "好：形容品质，与“更多”没有反义关系。"}, {"text": "高", "is_correct": false, "explanation": "高：形容高度，与“更多”没有反义关系。"}], "correct_answer": "更少", "explanations": {"更少": "更少：数量比原来或别处少，与“更多”意义相反。", "快": "快：形容速度，与“更多”没有反义关系。", "好": "好：形容品质，与“更多”没有反义关系。", "高": "高：形容高度，与“更多”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a5ded58-6004-4c0b-b250-389fa523ecfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27278, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "更少", "is_correct": true, "explanation": "更少：数量比原来或别处少，与“更多”意义相反。"}, {"text": "远", "is_correct": false, "explanation": "远：形容距离，与“更多”没有反义关系。"}, {"text": "贵", "is_correct": false, "explanation": "贵：形容价格，与“更多”没有反义关系。"}, {"text": "新", "is_correct": false, "explanation": "新：形容时间或状态，与“更多”没有反义关系。"}], "correct_answer": "更少", "explanations": {"更少": "更少：数量比原来或别处少，与“更多”意义相反。", "远": "远：形容距离，与“更多”没有反义关系。", "贵": "贵：形容价格，与“更多”没有反义关系。", "新": "新：形容时间或状态，与“更多”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a5ded58-6004-4c0b-b250-389fa523ecfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27278, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "更多就是比之前还要多。", "primary_collocate": null, "pronunciation": "gèng duō", "ipa": "kɤŋ˥˩ tuɔ˥", "syllable_count": 2, "sentences": [{"text": "这个月的雨比上个月更多。", "target_word": "更多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友来了以后，家里的人更多了。", "target_word": "更多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天买的苹果比昨天更多。", "target_word": "更多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们这次带来了更多的礼物。", "target_word": "更多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学了一年汉语，我认识的字更多了。", "target_word": "更多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气变冷以后，穿厚衣服的人更多了。", "target_word": "更多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你已经吃了很多，还想要更多吗？", "target_word": "更多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年的游客比去年更多。", "target_word": "更多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，明天会有更多的同学来。", "target_word": "更多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的钱已经不少了，可是他还想赚更多。", "target_word": "更多", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "更多的", "label": "定语形式"}], "register": "中性", "sense_fingerprint": "比之前或比较对象还要多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31610bca-58b2-44ff-ad3a-29a665b138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27278, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "更多", "is_correct": true, "explanation": "正确：“更多”表示雨量增多，与“比上个月”的比较一致。"}, {"text": "更远", "is_correct": false, "explanation": "语义：“远”形容距离，雨量不能用距离来比较，与语境不符。"}, {"text": "更甜", "is_correct": false, "explanation": "语义：“甜”形容味道，不能用来说雨。"}, {"text": "更亮", "is_correct": false, "explanation": "搭配：“亮”形容光线，不能用来比较雨量。"}], "explanations": {"更多": "正确：“更多”表示雨量增多，与“比上个月”的比较一致。", "更远": "语义：“远”形容距离，雨量不能用距离来比较，与语境不符。", "更甜": "语义：“甜”形容味道，不能用来说雨。", "更亮": "搭配：“亮”形容光线，不能用来比较雨量。"}, "sentence_index": 0, "correct_answer": "更多"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座山比那座更多。", "explanation": "这里应该用〈更高〉。“更多”说的是数量，山的高低要用“更高”。"}, {"text": "这辆车的速度比那辆更多。", "explanation": "这里应该用〈更快〉。“更多”说的是数量，速度的快慢要用“更快”。"}, {"text": "这个孩子的胆子比去年更多。", "explanation": "这里应该用〈更大〉。“更多”说的是数量，胆子的大小要用“更大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a5ded58-6004-4c0b-b250-389fa523ecfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27278, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "更多", "is_correct": true, "explanation": "正确：“更多”表示数量增加，与“你已经吃了很多，还想要……吗”的语境一致。"}, {"text": "更重", "is_correct": false, "explanation": "语义：“重”指重量，与“还想要”的语境不符。"}, {"text": "更冷", "is_correct": false, "explanation": "语义：“冷”指温度，与“还想要”的语境不符。"}, {"text": "更慢", "is_correct": false, "explanation": "搭配：“慢”形容速度，不能作为“想要”的对象。"}], "explanations": {"更多": "正确：“更多”表示数量增加，与“你已经吃了很多，还想要……吗”的语境一致。", "更重": "语义：“重”指重量，与“还想要”的语境不符。", "更冷": "语义：“冷”指温度，与“还想要”的语境不符。", "更慢": "搭配：“慢”形容速度，不能作为“想要”的对象。"}, "sentence_index": 6, "correct_answer": "更多"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他比我更多地聪明。", "explanation": "这里应该用〈更聪明〉。“更多地”表示数量或次数，不能用来修饰“聪明”这样的性质。"}, {"text": "这个房间的温度比那个更多。", "explanation": "这里应该用〈更高〉。“更多”说的是数量，温度的高低要用“更高”。"}, {"text": "她的年纪比我更多。", "explanation": "这里应该用〈更大〉。“更多”说的是数量，年纪的大小要用“更大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a5ded58-6004-4c0b-b250-389fa523ecfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27278, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家超市的顾客比去年更多着。", "corrected_sentence": "这家超市的顾客比去年更多了。", "error_description": "体貌错误：“更多”表示已经发生的变化，应用体标“了”，写作“更多了”。“着”表示状态的持续，不能用于这种比较变化。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a5ded58-6004-4c0b-b250-389fa523ecfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27278, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "教室里的同学比昨天更多的了。", "corrected_sentence": "教室里的同学比昨天更多了。", "error_description": "助词错误：比较结构应写作“比昨天更多了”，“更多”后不能再接结构助词“的”，应去掉“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a5ded58-6004-4c0b-b250-389fa523ecfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
