INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27280, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "长大了的人，不是小孩子了。", "primary_collocate": null, "pronunciation": "chéng nián rén", "ipa": "ʈʂʰɤŋ˧˥ njɛn˧˥ ʐən˧˥", "syllable_count": 3, "sentences": [{"text": "你已经长大了，是成年人了。", "target_word": "成年人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明不是小孩子，他是成年人。", "target_word": "成年人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "成年人也会有害怕的时候。", "target_word": "成年人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们都想快点儿变成成年人。", "target_word": "成年人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "成年人坐火车要买全票。", "target_word": "成年人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子问我：“成年人为什么总是很忙？”", "target_word": "成年人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏是给成年人玩的，小孩子不能玩。", "target_word": "成年人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的个子很高，像个成年人。", "target_word": "成年人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小时候我想当成年人，现在却想回到小时候。", "target_word": "成年人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "成年人要照顾老人和孩子。", "target_word": "成年人", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "未成年人", "label": "复合"}], "register": "中性", "sense_fingerprint": "长大了、不再是小孩子的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35cea5a1-2658-4833-b0af-5dcd0e705238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27280, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "孩子", "is_correct": false, "explanation": "语义：“孩子”仍是未长大的人，与“你已经长大了”矛盾。"}, {"text": "成年人", "is_correct": true, "explanation": "正确。“你已经长大了”之后，“是成年人了”与句意相符。"}, {"text": "木头", "is_correct": false, "explanation": "搭配：“是…了”后接的应是指人的身份，“木头”不能用来指长大的人。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿与“你已经长大了”矛盾。"}], "explanations": {"孩子": "语义：“孩子”仍是未长大的人，与“你已经长大了”矛盾。", "成年人": "正确。“你已经长大了”之后，“是成年人了”与句意相符。", "木头": "搭配：“是…了”后接的应是指人的身份，“木头”不能用来指长大的人。", "婴儿": "语义：婴儿与“你已经长大了”矛盾。"}, "sentence_index": 0, "correct_answer": "成年人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个两岁的宝宝已经是成年人了。", "explanation": "这里不能用〈成年人〉。它指长大了、不再是小孩子的人，两岁的宝宝应说〈幼儿〉。"}, {"text": "这棵树已经是成年人了。", "explanation": "这里不能用〈成年人〉。它只指人，树不能说是成年人，可以说“这棵树已经长大了”。"}, {"text": "这个小学生已经是成年人了。", "explanation": "这里不能用〈成年人〉。它指长大了、不再是小孩子的人，小学生还是孩子，应指〈儿童〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af4e2e5b-5f6c-4077-96ea-7d4a6731d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27280, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小孩子", "is_correct": false, "explanation": "语义：“给小孩子玩的”与后句“小孩子不能玩”自相矛盾。"}, {"text": "成年人", "is_correct": true, "explanation": "正确。游戏是给成年人玩的，与后句“小孩子不能玩”形成对照，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能玩游戏，与句意不符。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“给…玩的”要接能玩游戏的对象，“桌子”不能与之搭配。"}], "explanations": {"小孩子": "语义：“给小孩子玩的”与后句“小孩子不能玩”自相矛盾。", "成年人": "正确。游戏是给成年人玩的，与后句“小孩子不能玩”形成对照，符合句意。", "石头": "语义：石头不能玩游戏，与句意不符。", "桌子": "搭配：“给…玩的”要接能玩游戏的对象，“桌子”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "成年人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个刚出生的婴儿已经是成年人了。", "explanation": "这里不能用〈成年人〉。它指长大了、不再是小孩子的人，刚出生的婴儿应说〈婴儿〉。"}, {"text": "这座大山已经是成年人了。", "explanation": "这里不能用〈成年人〉。它只指长大了的人，大山不是人，不能说是成年人。"}, {"text": "这台老电脑已经是成年人了。", "explanation": "这里不能用〈成年人〉。它只指长大了的人，电脑不是人，可以说“这台电脑已经很旧了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af4e2e5b-5f6c-4077-96ea-7d4a6731d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27280, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他长得很高，像一只成年人。", "corrected_sentence": "他长得很高，像个成年人。", "error_description": "量词错误：“成年人”指人，应用量词“个”，不能用“只”。正确形式是“像个成年人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af4e2e5b-5f6c-4077-96ea-7d4a6731d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27280, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个游戏是给成年人的玩。", "corrected_sentence": "这个游戏是给成年人玩的。", "error_description": "“的”位置错误：“的”应放在动词“玩”之后，说“给成年人玩的”，不能说“给成年人的玩”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af4e2e5b-5f6c-4077-96ea-7d4a6731d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
