INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27282, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个人做事的地方。", "primary_collocate": null, "pronunciation": "gōng zuò gǎng wèi", "ipa": "kʊŋ˥ tswo˥˩ kɑŋ˨˩˦ weɪ˥˩", "syllable_count": 4, "sentences": [{"text": "他每天早上八点到工作岗位。", "target_word": "工作岗位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生不能随便离开自己的工作岗位。", "target_word": "工作岗位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的工作岗位在二楼，不在一楼。", "target_word": "工作岗位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天，警察还站在工作岗位上。", "target_word": "工作岗位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师们都回到了工作岗位。", "target_word": "工作岗位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在工作岗位上认真地做事。", "target_word": "工作岗位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "休假结束后，大家都回工作岗位了。", "target_word": "工作岗位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的工作岗位离窗户很近。", "target_word": "工作岗位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要在工作岗位上玩手机。", "target_word": "工作岗位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护士整夜守在工作岗位上。", "target_word": "工作岗位", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "人每天做事所在的具体位置，可回到、可离开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31610bca-58b2-44ff-ad3a-29a665b138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27282, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工作岗位", "is_correct": true, "explanation": "这里指他每天到达的工作地点，与“到”搭配，句意完整。"}, {"text": "早餐", "is_correct": false, "explanation": "配价：“到”后接地点，“早餐”不是可以到达的地方，应说“吃早餐”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是人去往的地点，句子要表达的是他每天去的地方。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“到”不与“作业”搭配，作业是要完成的任务，不是可以去往的地方。"}], "explanations": {"工作岗位": "这里指他每天到达的工作地点，与“到”搭配，句意完整。", "早餐": "配价：“到”后接地点，“早餐”不是可以到达的地方，应说“吃早餐”。", "天气": "语义：天气不是人去往的地点，句子要表达的是他每天去的地方。", "作业": "搭配：“到”不与“作业”搭配，作业是要完成的任务，不是可以去往的地方。"}, "sentence_index": 0, "correct_answer": "工作岗位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他中午把工作岗位吃完了。", "explanation": "这里应该用〈饭〉。工作岗位是做事的地方，不能吃。"}, {"text": "他把钥匙放进了工作岗位。", "explanation": "这里应该用〈抽屉〉。工作岗位是人做事的地方，不是可以放东西的容器。"}, {"text": "下雨天，工作岗位也跑去开会了。", "explanation": "此处把“工作岗位”当成了〈人〉来用。地方不会跑去开会，应说“警察也去开会了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a5ded58-6004-4c0b-b250-389fa523ecfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27282, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工作岗位", "is_correct": true, "explanation": "这里指大家休假后返回的做事地点，与“回”搭配，句意通顺。"}, {"text": "梦想", "is_correct": false, "explanation": "搭配：“回”后接具体的处所，“梦想”不能说“回梦想”。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：人不会“回”到冰箱里，句中指大家返回做事的地方。"}, {"text": "理论", "is_correct": false, "explanation": "语义：“理论”不是可以返回的地方，与“休假结束”的语境不符。"}], "explanations": {"工作岗位": "这里指大家休假后返回的做事地点，与“回”搭配，句意通顺。", "梦想": "搭配：“回”后接具体的处所，“梦想”不能说“回梦想”。", "冰箱": "语义：人不会“回”到冰箱里，句中指大家返回做事的地方。", "理论": "语义：“理论”不是可以返回的地方，与“休假结束”的语境不符。"}, "sentence_index": 6, "correct_answer": "工作岗位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个工作岗位昨天被老师批评了一顿。", "explanation": "此处把“工作岗位”当成了〈学生〉来用。地方不会被老师批评，应说“他昨天被老师批评了一顿”。"}, {"text": "他的工作岗位是早上八点到晚上五点。", "explanation": "这里应该用〈工作时间〉。工作岗位指做事的地方，不能用来表示时段，时段要说工作时间。"}, {"text": "这个工作岗位去年在大学里读了四年书。", "explanation": "此处把“工作岗位”当成了〈大学生〉来用。地方不能读书，应说“他去年在大学里读了四年书”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a5ded58-6004-4c0b-b250-389fa523ecfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27282, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张工作岗位离门口很近。", "corrected_sentence": "这个工作岗位离门口很近。", "error_description": "量词错误：“工作岗位”应用量词“个”计量，“张”用于平面物品，不能计量这里的地点。正确说法是“这个工作岗位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a5ded58-6004-4c0b-b250-389fa523ecfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27282, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那辆工作岗位在二楼。", "corrected_sentence": "那个工作岗位在二楼。", "error_description": "量词错误：“辆”用于车辆，不能计量“工作岗位”，应用“个”。正确说法是“那个工作岗位在二楼”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a5ded58-6004-4c0b-b250-389fa523ecfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
