INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27284, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "写代码让电脑做事。", "primary_collocate": null, "pronunciation": "biān chéng", "ipa": "pjɛn˥ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他会编程，能让电脑自己做事。", "target_word": "编程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我弟弟很喜欢编程。", "target_word": "编程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学会编程以后，你可以做自己的游戏。", "target_word": "编程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教孩子们编程，让机器人走路。", "target_word": "编程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天编程到很晚，眼睛都累了。", "target_word": "编程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "编程就是写代码，告诉电脑该做什么。", "target_word": "编程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我在家编程，做了一个小网站。", "target_word": "编程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不但会画画，还会编程。", "target_word": "编程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "编程可以让电脑自己算数。", "target_word": "编程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你会编程吗？我想请你帮我做个软件。", "target_word": "编程", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "编了一天程", "label": "体标"}, {"form": "编程语言", "label": "复合"}, {"form": "編程", "label": "繁体"}], "register": "中性", "sense_fingerprint": "写代码，让电脑按要求做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35cea5a1-2658-4833-b0af-5dcd0e705238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27284, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "做饭", "is_correct": false, "explanation": "语义：“做饭”与后句“能让电脑自己做事”无关，不能解释这种能力。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”与“让电脑自己做事”没有关联，句意不通。"}, {"text": "编程", "is_correct": true, "explanation": "正确。“编程”就是写代码让电脑做事，与后句相承接。"}, {"text": "睡觉", "is_correct": false, "explanation": "搭配：“会睡觉”不是能力表达，与“能让电脑自己做事”不搭配。"}], "explanations": {"做饭": "语义：“做饭”与后句“能让电脑自己做事”无关，不能解释这种能力。", "游泳": "语义：“游泳”与“让电脑自己做事”没有关联，句意不通。", "编程": "正确。“编程”就是写代码让电脑做事，与后句相承接。", "睡觉": "搭配：“会睡觉”不是能力表达，与“能让电脑自己做事”不搭配。"}, "sentence_index": 0, "correct_answer": "编程"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座雕像是他编程的。", "explanation": "这里应该用〈雕刻〉。雕像是刻出来的，“编程”指编写代码，不能用于此。"}, {"text": "她负责编程这份杂志。", "explanation": "这里应该用〈编辑〉。编辑指修改、整理稿件，“编程”指编写计算机代码，不能用于杂志。"}, {"text": "这首曲子是他编程的。", "explanation": "这里应该用〈作曲〉。谱曲不是编写代码。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af4e2e5b-5f6c-4077-96ea-7d4a6731d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27284, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌做不出网站，与“做了一个小网站”不符。"}, {"text": "开车", "is_correct": false, "explanation": "搭配：“在家”里不能开车，与“在家”搭配不当。"}, {"text": "编程", "is_correct": true, "explanation": "正确。在家编程做出小网站，符合句意。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉与“做了一个小网站”相矛盾。"}], "explanations": {"唱歌": "语义：唱歌做不出网站，与“做了一个小网站”不符。", "开车": "搭配：“在家”里不能开车，与“在家”搭配不当。", "编程": "正确。在家编程做出小网站，符合句意。", "睡觉": "语义：睡觉与“做了一个小网站”相矛盾。"}, "sentence_index": 6, "correct_answer": "编程"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书是他编程的。", "explanation": "这里应该用〈写〉。书是写出来的，“编程”指编写电脑代码，不能用于写书。"}, {"text": "这间房子是他编程的。", "explanation": "这里应该用〈建造〉。房子是建造出来的，“编程”不能用于此。"}, {"text": "这篇日记是他编程的。", "explanation": "这里应该用〈写〉。日记是写出来的，“编程”指编写代码，不能用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af4e2e5b-5f6c-4077-96ea-7d4a6731d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27284, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他编程编很快，能让电脑自己做事。", "corrected_sentence": "他编程编得很快，能让电脑自己做事。", "error_description": "补语错误：动词后接表示程度的补语时要用“得”，“编很快”漏掉“得”，应说“编得很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af4e2e5b-5f6c-4077-96ea-7d4a6731d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27284, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我姐姐编程编很好。", "corrected_sentence": "我姐姐编程编得很好。", "error_description": "补语错误：动词后接表示程度的补语时要用“得”，“编很好”漏掉“得”，应说“编得很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af4e2e5b-5f6c-4077-96ea-7d4a6731d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
