INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27288, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "这样的感情，这样的景色。", "primary_collocate": null, "pronunciation": "cǐ qíng cǐ jǐng", "ipa": "tsʰɨ˨˩˦ tɕʰiŋ˧˥ tsʰɨ˨˩˦ tɕiŋ˨˩˦", "syllable_count": 4, "sentences": [{"text": "此情此景，让她想起了去世的奶奶。", "target_word": "此情此景", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看到此情此景，心里特别感动。", "target_word": "此情此景", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在雪地里玩耍，此情此景很温馨。", "target_word": "此情此景", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我和妈妈坐着看月亮，此情此景令我难忘。", "target_word": "此情此景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对此情此景，诗人写下了一首短诗。", "target_word": "此情此景", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们第一次见面就是在这儿，此情此景我还记得。", "target_word": "此情此景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到此情此景，大家都笑了。", "target_word": "此情此景", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "回到老房子，此情此景让爸爸红了眼睛。", "target_word": "此情此景", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "画家把此情此景画在了纸上。", "target_word": "此情此景", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁也没想到，此情此景会出现在我们家。", "target_word": "此情此景", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "这样的感情和这样的景色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f7f17ff-c32d-47a8-bf1e-867aef9f7341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27288, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "此情此景", "is_correct": true, "explanation": "正确：“此情此景”指眼前景象和心中感情，作句首话题，与“让她想起了去世的奶奶”相合。"}, {"text": "电费账单", "is_correct": false, "explanation": "语义：电费账单与怀念去世的奶奶没有关联，无法引起这样的回忆。"}, {"text": "数学作业", "is_correct": false, "explanation": "语义：数学作业不能引起对去世奶奶的回忆，与句意不符。"}, {"text": "一摞旧报纸", "is_correct": false, "explanation": "语义：旧报纸只是普通物品，不构成“景象与感情”，与句意不符。"}], "explanations": {"此情此景": "正确：“此情此景”指眼前景象和心中感情，作句首话题，与“让她想起了去世的奶奶”相合。", "电费账单": "语义：电费账单与怀念去世的奶奶没有关联，无法引起这样的回忆。", "数学作业": "语义：数学作业不能引起对去世奶奶的回忆，与句意不符。", "一摞旧报纸": "语义：旧报纸只是普通物品，不构成“景象与感情”，与句意不符。"}, "sentence_index": 0, "correct_answer": "此情此景"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "听完这段故事，她发出了此情此景。", "explanation": "搭配：这里应该用〈感慨〉。“发出”可以搭配“感慨”，此情此景不能被“发出”。"}, {"text": "他对做饭很有此情此景。", "explanation": "搭配：这里应该用〈感觉〉。“有”后接可以拥有的感受，此情此景是固定说法，不能说“有此情此景”。"}, {"text": "这件衣服的此情此景很便宜。", "explanation": "语义：这里应该用〈价格〉。此情此景指景象和感情，不能用来说衣服的价钱，应说“这件衣服的价格很便宜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c165fc5-8ecb-4d31-a2d9-19aa7e835074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27288, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "此情此景", "is_correct": true, "explanation": "正确：“此情此景”指眼前景象和由此产生的感受，作“看到”的宾语，与“大家都笑了”的语境相合。"}, {"text": "葬礼现场", "is_correct": false, "explanation": "语义：葬礼的悲伤氛围与“大家都笑了”相矛盾。"}, {"text": "一份伤心的遗书", "is_correct": false, "explanation": "语义：看到伤心的遗书不会让大家发笑，与句意相反。"}, {"text": "一份会议纪要", "is_correct": false, "explanation": "语义：会议纪要是公文，不是能让大家发笑的景象，与句意不符。"}], "explanations": {"此情此景": "正确：“此情此景”指眼前景象和由此产生的感受，作“看到”的宾语，与“大家都笑了”的语境相合。", "葬礼现场": "语义：葬礼的悲伤氛围与“大家都笑了”相矛盾。", "一份伤心的遗书": "语义：看到伤心的遗书不会让大家发笑，与句意相反。", "一份会议纪要": "语义：会议纪要是公文，不是能让大家发笑的景象，与句意不符。"}, "sentence_index": 6, "correct_answer": "此情此景"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次聚会上，她的此情此景很欢乐。", "explanation": "搭配：这里应该用〈心境〉。此情此景是固定说法，不能用“她的”修饰，应说“她的心境很欢乐”。"}, {"text": "我的此情此景是三月五号。", "explanation": "语义：这里应该用〈生日〉。此情此景指眼前景象和心中感情，不能表示日期，应说“我的生日是三月五号”。"}, {"text": "这台冰箱的此情此景很大。", "explanation": "语义：这里应该用〈容量〉。此情此景指景象和感情，不能用来形容冰箱的大小，应说“这台冰箱的容量很大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c165fc5-8ecb-4d31-a2d9-19aa7e835074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27288, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他站在岸边，此情此景把他感到很平静。", "corrected_sentence": "他站在岸边，此情此景让他感到很平静。", "error_description": "用词错误：“把”字句不能表示使役，此处应用“让”。“此情此景把他感到很平静”不成立，正确说法是“此情此景让他感到很平静”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c165fc5-8ecb-4d31-a2d9-19aa7e835074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27288, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "此情此景的让爸爸想起了童年的事。", "corrected_sentence": "此情此景让爸爸想起了童年的事。", "error_description": "多余的“的”：“此情此景”后直接接动词“让”，不能加“的”。正确说法是“此情此景让爸爸想起了童年的事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c165fc5-8ecb-4d31-a2d9-19aa7e835074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
