INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27290, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "看数字发现规律。", "primary_collocate": null, "pronunciation": "shù jù fēn xī", "ipa": "ʂu˥˩ tɕy˥˩ fən˥ ɕi˥", "syllable_count": 4, "sentences": [{"text": "数据分析就是看数字，找出里面的规律。", "target_word": "数据分析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎么做数据分析。", "target_word": "数据分析", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做数据分析要仔细看每一个数字。", "target_word": "数据分析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "通过数据分析，我们知道大家喜欢什么。", "target_word": "数据分析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据分析让他发现，周末的客人最多。", "target_word": "数据分析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的工作是数据分析，每天和数字打交道。", "target_word": "数据分析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对数据分析很有兴趣。", "target_word": "数据分析", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "数据分析不难，先学会看表格。", "target_word": "数据分析", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的数据分析能告诉我们为什么卖得好。", "target_word": "数据分析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份数据分析说明，夏天饮料卖得特别好。", "target_word": "数据分析", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "数据分析师", "label": "复合"}, {"form": "數據分析", "label": "繁体"}], "register": "中性", "sense_fingerprint": "看数字，从中发现规律", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35cea5a1-2658-4833-b0af-5dcd0e705238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27290, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "数据分析", "is_correct": true, "explanation": "数据分析：看数字、找规律，与句子的定义相符。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐不是看数字找规律，“音乐就是看数字”与句子意思相反。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是看数字找规律，“天气就是看数字”读起来不通。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语，与句子的书面定义语体不符，且意思不对。"}], "explanations": {"数据分析": "数据分析：看数字、找规律，与句子的定义相符。", "音乐": "语义：音乐不是看数字找规律，“音乐就是看数字”与句子意思相反。", "天气": "语义：天气不是看数字找规律，“天气就是看数字”读起来不通。", "玩意儿": "语域：“玩意儿”是口语，与句子的书面定义语体不符，且意思不对。"}, "sentence_index": 0, "correct_answer": "数据分析"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "拿到数据以后，先用数据分析把错误的数据删掉。", "explanation": "这里应该用〈数据处理〉。删除错误数据属于处理数据，数据分析是找出规律，不能直接删除数据。"}, {"text": "他用数据分析把传感器装在工厂里。", "explanation": "这里应该用〈数据采集〉。把传感器装在工厂里是为了收集数字，数据分析是对已有数字找规律。"}, {"text": "他每天下班前用数据分析把电脑里的文件存到另一块硬盘上。", "explanation": "这里应该用〈数据备份〉。把文件存到另一块硬盘是备份，数据分析是找规律，不能用来存文件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af4e2e5b-5f6c-4077-96ea-7d4a6731d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27290, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "数据分析", "is_correct": true, "explanation": "数据分析：一个可以让人感兴趣的领域，与“我对……很有兴趣”相符。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是一种病症，一般人不会对它有兴趣，句子不合理。"}, {"text": "车祸", "is_correct": false, "explanation": "语义：车祸是不幸的事故，不是人们感兴趣的对象，句子读起来不通。"}, {"text": "垃圾桶", "is_correct": false, "explanation": "语义：垃圾桶是装垃圾的器具，不是人们感兴趣的领域，句子读起来不通。"}], "explanations": {"数据分析": "数据分析：一个可以让人感兴趣的领域，与“我对……很有兴趣”相符。", "感冒": "语义：感冒是一种病症，一般人不会对它有兴趣，句子不合理。", "车祸": "语义：车祸是不幸的事故，不是人们感兴趣的对象，句子读起来不通。", "垃圾桶": "语义：垃圾桶是装垃圾的器具，不是人们感兴趣的领域，句子读起来不通。"}, "sentence_index": 6, "correct_answer": "数据分析"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份数据分析只是把每天卖了多少饮料记下来，没有找出任何规律。", "explanation": "这里应该用〈数据记录〉。只把数字记下来、不找规律是记录，数据分析要从数字中发现规律。"}, {"text": "他用数据分析把客人的电话号码一个一个打进电脑里。", "explanation": "这里应该用〈数据录入〉。把数字输入电脑是录入，数据分析是看数字找规律。"}, {"text": "她用数据分析把表格从电脑发到了手机上。", "explanation": "这里应该用〈数据传输〉。把文件从一处发到另一处是传输，数据分析是看数字找规律。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af4e2e5b-5f6c-4077-96ea-7d4a6731d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27290, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我还没学了数据分析。", "corrected_sentence": "我还没学过数据分析。", "error_description": "体标错误：“没”与“了”不搭配，否定经历要用“没……过”，“没学了”不能说，应为“没学过数据分析”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af4e2e5b-5f6c-4077-96ea-7d4a6731d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27290, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我对数据分析很兴趣。", "corrected_sentence": "我对数据分析很感兴趣。", "error_description": "动词缺失：“兴趣”前要加动词“感”，“很兴趣”不能说，应为“很感兴趣”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af4e2e5b-5f6c-4077-96ea-7d4a6731d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27292, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "缓慢", "is_correct": true, "explanation": "正确。「缓慢」指速度低，与「快速」相对。"}, {"text": "宽敞", "is_correct": false, "explanation": "语义：「宽敞」形容空间大，与速度无关，不是「快速」的反义词。"}, {"text": "清楚", "is_correct": false, "explanation": "语义：「清楚」形容看得或听得分明，与速度无关，不构成反义关系。"}, {"text": "轻松", "is_correct": false, "explanation": "语义：「轻松」形容不费力，与「快速」不构成反义关系。"}], "correct_answer": "缓慢", "explanations": {"缓慢": "正确。「缓慢」指速度低，与「快速」相对。", "宽敞": "语义：「宽敞」形容空间大，与速度无关，不是「快速」的反义词。", "清楚": "语义：「清楚」形容看得或听得分明，与速度无关，不构成反义关系。", "轻松": "语义：「轻松」形容不费力，与「快速」不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5130e15f-d8d7-488d-bde2-1feee74671e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27292, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "缓慢", "is_correct": true, "explanation": "正确。「缓慢」指速度低，与「快速」相对。"}, {"text": "温暖", "is_correct": false, "explanation": "「温暖」形容温度或感觉，与速度无关，不是「快速」的反义词。"}, {"text": "高大", "is_correct": false, "explanation": "「高大」形容身材或事物的体积，与速度无关，不构成反义关系。"}, {"text": "清脆", "is_correct": false, "explanation": "「清脆」形容声音清亮爽朗，与速度无关，不构成反义关系。"}], "correct_answer": "缓慢", "explanations": {"缓慢": "正确。「缓慢」指速度低，与「快速」相对。", "温暖": "「温暖」形容温度或感觉，与速度无关，不是「快速」的反义词。", "高大": "「高大」形容身材或事物的体积，与速度无关，不构成反义关系。", "清脆": "「清脆」形容声音清亮爽朗，与速度无关，不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5130e15f-d8d7-488d-bde2-1feee74671e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27292, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很快，没有慢的。", "primary_collocate": null, "pronunciation": "kuài sù", "ipa": "kʰwaɪ˥˩ su˥˩", "syllable_count": 2, "sentences": [{"text": "他们快速跑进教室，因为已经上课了。", "target_word": "快速", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院的救护车快速开到了现场。", "target_word": "快速", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要快速走过这条小路，天快黑了。", "target_word": "快速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用快速的动作把行李放进了车里。", "target_word": "快速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她快速的步伐让我很难跟上。", "target_word": "快速", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨下得很大，我们快速躲进了旁边的商店。", "target_word": "快速", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他快速翻了翻书，找到了那一页。", "target_word": "快速", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请快速回答，不要想太久。", "target_word": "快速", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "电脑可以快速算出很难的数学题。", "target_word": "快速", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她快速地换好衣服，走出了家门。", "target_word": "快速", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "快速地", "label": "状语形式"}, {"form": "快速的", "label": "定语形式"}, {"form": "快速列车", "label": "复合"}], "register": "中性", "sense_fingerprint": "快速：很快，没有慢的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df62efa0-2dbe-46fc-9d7d-40fafa899bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27292, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "慢", "is_correct": false, "explanation": "语义：「慢」与「因为已经上课了」的赶时间原因相矛盾。"}, {"text": "快速", "is_correct": true, "explanation": "正确。「快速」作状语修饰「跑进」，与赶时间的语境一致。"}, {"text": "大声", "is_correct": false, "explanation": "搭配：「大声」多修饰说、喊等发声动作，不修饰「跑进」。"}, {"text": "吵闹", "is_correct": false, "explanation": "语义：「吵闹」形容环境嘈杂，与为了赶时间进教室的语境不符。"}], "explanations": {"慢": "语义：「慢」与「因为已经上课了」的赶时间原因相矛盾。", "快速": "正确。「快速」作状语修饰「跑进」，与赶时间的语境一致。", "大声": "搭配：「大声」多修饰说、喊等发声动作，不修饰「跑进」。", "吵闹": "语义：「吵闹」形容环境嘈杂，与为了赶时间进教室的语境不符。"}, "sentence_index": 0, "correct_answer": "快速"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月的工资很快速，大家都很高兴。", "explanation": "这里应该用〈高〉。「快速」只表示速度，不能形容工资的多少，应说「工资很高」。"}, {"text": "他的脾气很快速，一着急就发火。", "explanation": "这里应该用〈急〉。「脾气急」指性子急躁，「快速」只说速度，不能用来形容脾气。"}, {"text": "这把剪刀很快速，剪纸特别方便。", "explanation": "这里应该用〈快〉。「快」形容剪刀锋利时指刃口的性能，与速度无关；「快速」只表示速度，不能形容剪刀的锋利。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5130e15f-d8d7-488d-bde2-1feee74671e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27292, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "整齐", "is_correct": false, "explanation": "体貌：「整齐」描述排列的外观，不能用来形容翻书的动作。"}, {"text": "快速", "is_correct": true, "explanation": "正确。「快速」作状语修饰「翻了翻」，说明翻书速度快，与「找到了那一页」呼应。"}, {"text": "笔直", "is_correct": false, "explanation": "搭配：「笔直」多形容线条或站姿，不修饰翻书这类动作。"}, {"text": "冰凉", "is_correct": false, "explanation": "搭配：「冰凉」形容温度，不能修饰翻书的动作。"}], "explanations": {"整齐": "体貌：「整齐」描述排列的外观，不能用来形容翻书的动作。", "快速": "正确。「快速」作状语修饰「翻了翻」，说明翻书速度快，与「找到了那一页」呼应。", "笔直": "搭配：「笔直」多形容线条或站姿，不修饰翻书这类动作。", "冰凉": "搭配：「冰凉」形容温度，不能修饰翻书的动作。"}, "sentence_index": 6, "correct_answer": "快速"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗汤很快速，等一会儿再喝。", "explanation": "这里应该用〈烫〉。「快速」只指速度，不能形容汤的温度。"}, {"text": "这件衣服的价格很快速，大家都很满意。", "explanation": "这里应该用〈便宜〉。「快速」只指速度，不能用来形容价格的高低。"}, {"text": "这块布料很快速，穿着很舒服。", "explanation": "这里应该用〈柔软〉。「快速」只指动作或变化的速度，不能用来形容布料的质地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5130e15f-d8d7-488d-bde2-1feee74671e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27292, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他快速的走出了办公室，去接孩子。", "corrected_sentence": "他快速地走出了办公室，去接孩子。", "error_description": "错误在「快速」与动词之间：作状语修饰动词「走出」时应用「地」，写成「的」是结构助词误用，应说「快速地走出」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5130e15f-d8d7-488d-bde2-1feee74671e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27292, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她快速的收拾好包，走出了家门。", "corrected_sentence": "她快速地收拾好包，走出了家门。", "error_description": "结构助词错误：「快速」作状语修饰动词「收拾」时应用「地」，不能用「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5130e15f-d8d7-488d-bde2-1feee74671e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
