INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27298, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做一件事时，会遇到的不容易的地方。", "primary_collocate": null, "pronunciation": "kùn nan", "ipa": "kʰwən˥˩ nan", "syllable_count": 2, "sentences": [{"text": "学外语最大的困难是发音。", "target_word": "困难", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你觉得做这件事有什么困难？", "target_word": "困难", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "搬运这么大的桌子，困难在于门太窄了。", "target_word": "困难", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "写论文时，他碰到了不少困难。", "target_word": "困难", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开车去山里，路上的困难比我想的多。", "target_word": "困难", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你有什么困难，请先告诉我。", "target_word": "困难", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "刚开始做生意时，最大的困难是没有钱。", "target_word": "困难", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把每个困难都写在本子上，一个一个解决。", "target_word": "困难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种花看起来简单，其实也有很多困难。", "target_word": "困难", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次爬山没有想象中那么多困难。", "target_word": "困难", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "困难户", "label": "复合"}], "register": "中性", "sense_fingerprint": "困难：做事时遇到的不容易之处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df62efa0-2dbe-46fc-9d7d-40fafa899bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27298, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "爱好", "is_correct": false, "explanation": "语义：「爱好」指喜欢做的事，与句中指学习障碍的意思不同，句意不通。"}, {"text": "困难", "is_correct": true, "explanation": "正确。「最大的困难」指学外语时遇到的最难的地方，与「是发音」呼应。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：「颜色」指具体的色彩，不能用在「学外语最大的……」这样的抽象说法里。"}, {"text": "动力", "is_correct": false, "explanation": "语义：「动力」指推动前进的力量，与句中要说的阻碍相反。"}], "explanations": {"爱好": "语义：「爱好」指喜欢做的事，与句中指学习障碍的意思不同，句意不通。", "困难": "正确。「最大的困难」指学外语时遇到的最难的地方，与「是发音」呼应。", "颜色": "搭配：「颜色」指具体的色彩，不能用在「学外语最大的……」这样的抽象说法里。", "动力": "语义：「动力」指推动前进的力量，与句中要说的阻碍相反。"}, "sentence_index": 0, "correct_answer": "困难"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "写论文时，他捡到了不少困难。", "explanation": "这里应该用〈机会〉。「捡到机会」是常见说法；「困难」指遇到的阻碍，不能捡拾。"}, {"text": "这台复印机有困难，总是卡纸。", "explanation": "这里应该用〈故障〉。「困难」指人做事时遇到的阻碍，机器出问题应说「有故障」，不能说机器有困难。"}, {"text": "写论文时，他碰到了一根困难。", "explanation": "这里应该用〈个〉。「根」用于细长的东西，不用于困难。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5130e15f-d8d7-488d-bde2-1feee74671e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27298, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "利润", "is_correct": false, "explanation": "语义：「利润」指赚到的钱，与「没有钱」相矛盾。"}, {"text": "困难", "is_correct": true, "explanation": "正确。「最大的困难」指做生意初期遇到的阻碍，与「是没有钱」呼应。"}, {"text": "朋友", "is_correct": false, "explanation": "搭配：「朋友」指人，不能用来说明「最大的……是没有钱」这种情况。"}, {"text": "收入", "is_correct": false, "explanation": "语义：「收入」指赚得的钱，与「没有钱」相矛盾。"}], "explanations": {"利润": "语义：「利润」指赚到的钱，与「没有钱」相矛盾。", "困难": "正确。「最大的困难」指做生意初期遇到的阻碍，与「是没有钱」呼应。", "朋友": "搭配：「朋友」指人，不能用来说明「最大的……是没有钱」这种情况。", "收入": "语义：「收入」指赚得的钱，与「没有钱」相矛盾。"}, "sentence_index": 6, "correct_answer": "困难"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次爬山他犯了不少困难。", "explanation": "这里应该用〈错误〉。「犯错误」是固定搭配，「犯困难」不通。"}, {"text": "这次爬山我遇到了一只困难。", "explanation": "这里应该用〈个〉。「只」用于动物或成对器官之一，不用于困难。"}, {"text": "这次爬山我吃了很多困难。", "explanation": "这里应该用〈苦头〉。「吃苦头」是固定说法，「吃困难」不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5130e15f-d8d7-488d-bde2-1feee74671e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27298, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他碰到了一颗困难，但很快就解决了。", "corrected_sentence": "他碰到了一个困难，但很快就解决了。", "error_description": "量词错误：「困难」应搭配「个」，「颗」用于颗粒状的小东西，不能用于困难。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5130e15f-d8d7-488d-bde2-1feee74671e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27298, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是他遇到了的最大困难。", "corrected_sentence": "这是他遇到的最大困难。", "error_description": "助词多余：「遇到的最大困难」中的定语不需要「了」，「遇到了的」是不规范的说法，应去掉「了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5130e15f-d8d7-488d-bde2-1feee74671e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27300, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "坏事", "is_correct": true, "explanation": "反义：「坏事」与「好事」相对，指不好的、有害的事情，词典有此反义关系。"}, {"text": "烦恼", "is_correct": false, "explanation": "「烦恼」指心里的忧虑，与「好事」没有反义关系。"}, {"text": "道理", "is_correct": false, "explanation": "「道理」指事物的规律或理由，与「好事」没有反义关系。"}, {"text": "天气", "is_correct": false, "explanation": "「天气」是自然现象，与「好事」不构成反义关系。"}], "correct_answer": "坏事", "explanations": {"坏事": "反义：「坏事」与「好事」相对，指不好的、有害的事情，词典有此反义关系。", "烦恼": "「烦恼」指心里的忧虑，与「好事」没有反义关系。", "道理": "「道理」指事物的规律或理由，与「好事」没有反义关系。", "天气": "「天气」是自然现象，与「好事」不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a1d4253-60c4-4d49-bc24-1372accc4694') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27300, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "坏事", "is_correct": true, "explanation": "反义：「坏事」与「好事」相对，指不好的、有害的事情，词典有此反义关系。"}, {"text": "书本", "is_correct": false, "explanation": "「书本」指书籍，与「好事」没有反义关系。"}, {"text": "房间", "is_correct": false, "explanation": "「房间」指空间，与「好事」没有反义关系。"}, {"text": "花园", "is_correct": false, "explanation": "「花园」指种花草的场所，与「好事」没有反义关系。"}], "correct_answer": "坏事", "explanations": {"坏事": "反义：「坏事」与「好事」相对，指不好的、有害的事情，词典有此反义关系。", "书本": "「书本」指书籍，与「好事」没有反义关系。", "房间": "「房间」指空间，与「好事」没有反义关系。", "花园": "「花园」指种花草的场所，与「好事」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a1d4253-60c4-4d49-bc24-1372accc4694') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27300, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "好事是让人开心的事情。", "primary_collocate": null, "pronunciation": "hǎo shì", "ipa": "xɑʊ̯˨˩˦ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "今天我遇到一件好事，朋友请我吃饭庆祝。", "target_word": "好事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他考上了大学，这是我们家的好事。", "target_word": "好事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶身体好了，这真是一件好事。", "target_word": "好事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有什么好事？看你笑得这么开心。", "target_word": "好事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说你要结婚了，真是好事啊！", "target_word": "好事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天天气好，朋友又来看我，都是好事。", "target_word": "好事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好事一件接一件，大家都替他高兴，他笑得很开心。", "target_word": "好事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们得到了新书，这对他们是好事。", "target_word": "好事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王最近好事不断，工作也找到了。", "target_word": "好事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明得了第一名，大家都说这是好事。", "target_word": "好事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一件好事", "label": "量词"}, {"form": "好事多磨", "label": "复合"}], "register": "中性", "sense_fingerprint": "好事：让人开心的喜事、顺心的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d483ca1-93ac-4b0e-b4cc-1888a4e9895c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27300, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "好事", "is_correct": true, "explanation": "正确：好事，指让人开心的事情。"}, {"text": "好戏", "is_correct": false, "explanation": "声母不同：「好戏」的第二音节是 xì，「好事」是 shì，意思是精彩的演出。"}, {"text": "海事", "is_correct": false, "explanation": "韵母不同：「海事」的第一音节韵母是 ai，「好事」是 ao，意思是海上的事务。"}, {"text": "考试", "is_correct": false, "explanation": "声母不同：「考试」以 k 开头，「好事」以 h 开头，意思是测验。"}, {"text": "好使", "is_correct": false, "explanation": "声调不同：「好使」的第二音节是第三声，「好事」是第四声，意思是好用、管用。"}], "explanations": {"好事": "正确：好事，指让人开心的事情。", "好戏": "声母不同：「好戏」的第二音节是 xì，「好事」是 shì，意思是精彩的演出。", "海事": "韵母不同：「海事」的第一音节韵母是 ai，「好事」是 ao，意思是海上的事务。", "考试": "声母不同：「考试」以 k 开头，「好事」以 h 开头，意思是测验。", "好使": "声调不同：「好使」的第二音节是第三声，「好事」是第四声，意思是好用、管用。"}, "sentence_index": null, "correct_answer": "好事"}, "level_3": {"options": [{"text": "好事", "is_correct": true, "explanation": "正确：「朋友请我吃饭」是高兴的事，只有「好事」与之相合。"}, {"text": "坏事", "is_correct": false, "explanation": "语义：「朋友请我吃饭」是愉快的事，「坏事」与之矛盾。"}, {"text": "祸事", "is_correct": false, "explanation": "语义：「祸事」指灾祸，与「朋友请我吃饭」的喜悦语境矛盾。"}, {"text": "噩耗", "is_correct": false, "explanation": "语域：「噩耗」是书面语，指坏消息，且与「朋友请我吃饭」的轻松语境矛盾。"}], "explanations": {"好事": "正确：「朋友请我吃饭」是高兴的事，只有「好事」与之相合。", "坏事": "语义：「朋友请我吃饭」是愉快的事，「坏事」与之矛盾。", "祸事": "语义：「祸事」指灾祸，与「朋友请我吃饭」的喜悦语境矛盾。", "噩耗": "语域：「噩耗」是书面语，指坏消息，且与「朋友请我吃饭」的轻松语境矛盾。"}, "sentence_index": 0, "correct_answer": "好事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们的研究取得了好事，大家都很高兴。", "explanation": "这里应该用〈成果〉。「取得」后面接研究、工作的结果，要说「取得成果」；「好事」指发生的事情，不能说「取得好事」。"}, {"text": "比赛后，他领到了一件好事。", "explanation": "这里应该用〈奖品〉。领到的是具体的奖品，要说「领到奖品」，「好事」不能用来指奖品。"}, {"text": "他总爱打听邻居的私事，真是个好事的人。", "explanation": "这里的「好事」读 hào，是爱管闲事的意思，指好打听、好过问别人事情的人，与指让人开心的事情不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a1d4253-60c4-4d49-bc24-1372accc4694') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27300, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "好事", "is_correct": true, "explanation": "正确：好事，指让人开心的事情。"}, {"text": "好诗", "is_correct": false, "explanation": "声调不同：「好诗」的第二音节是第一声 shī，「好事」是第四声 shì，意思是好的诗作。"}, {"text": "早市", "is_correct": false, "explanation": "声母不同：「早市」以 z 开头，意思是早上的集市。"}, {"text": "搞事", "is_correct": false, "explanation": "声母不同：「搞事」以 g 开头，意思是找麻烦、闹事。"}, {"text": "好似", "is_correct": false, "explanation": "声母不同：「好似」的第二音节是 sì，「好事」是 shì，意思是好像。"}], "explanations": {"好事": "正确：好事，指让人开心的事情。", "好诗": "声调不同：「好诗」的第二音节是第一声 shī，「好事」是第四声 shì，意思是好的诗作。", "早市": "声母不同：「早市」以 z 开头，意思是早上的集市。", "搞事": "声母不同：「搞事」以 g 开头，意思是找麻烦、闹事。", "好似": "声母不同：「好似」的第二音节是 sì，「好事」是 shì，意思是好像。"}, "sentence_index": null, "correct_answer": "好事"}, "level_3": {"options": [{"text": "好事", "is_correct": true, "explanation": "正确：「一件接一件」后面「他笑得很开心」，只有「好事」与之相合。"}, {"text": "苦事", "is_correct": false, "explanation": "语义：「苦事」指令人难受的事，与「他笑得很开心」矛盾。"}, {"text": "烦心事", "is_correct": false, "explanation": "语义：「烦心事」令人烦恼，与「他笑得很开心」矛盾。"}, {"text": "病痛", "is_correct": false, "explanation": "搭配：「病痛」一般说「一阵」「一种」，不说「一件接一件」，且与「他笑得很开心」矛盾。"}], "explanations": {"好事": "正确：「一件接一件」后面「他笑得很开心」，只有「好事」与之相合。", "苦事": "语义：「苦事」指令人难受的事，与「他笑得很开心」矛盾。", "烦心事": "语义：「烦心事」令人烦恼，与「他笑得很开心」矛盾。", "病痛": "搭配：「病痛」一般说「一阵」「一种」，不说「一件接一件」，且与「他笑得很开心」矛盾。"}, "sentence_index": 6, "correct_answer": "好事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这个月的好事很高，老板很满意。", "explanation": "这里应该用〈收入〉。说钱收入多要用「收入」，「好事」是事情，不能说「好事很高」。"}, {"text": "朋友送了我好事，我很感动。", "explanation": "这里应该用〈礼物〉。「送」后面接具体的东西，要说「送了我礼物」；「好事」指让人开心的事情，不能说「送好事」。"}, {"text": "他这人很好事，总爱打听别人家的私事。", "explanation": "这里的「好事」读 hào，是爱管闲事的意思，指好打听、好过问别人事情，与指让人开心的事情不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a1d4253-60c4-4d49-bc24-1372accc4694') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27300, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个月我家有一只好事，大家都很高兴。", "corrected_sentence": "这个月我家有一件好事，大家都很高兴。", "error_description": "量词错误：「好事」的量词应为「件」，不能用「只」。「只」多用于动物或单个的小东西，不用于事情。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a1d4253-60c4-4d49-bc24-1372accc4694') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27300, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班得了一只好事，老师很高兴。", "corrected_sentence": "我们班得了一件好事，老师很高兴。", "error_description": "量词错误：「好事」的量词应为「件」，不能用「只」。应说「得了一件好事」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a1d4253-60c4-4d49-bc24-1372accc4694') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
