INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27302, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "得到好处。", "primary_collocate": null, "pronunciation": "shòu yì", "ipa": "ʂoʊ⁵¹ i⁵¹", "syllable_count": 2, "sentences": [{"text": "好好学习，你会受益一生。", "target_word": "受益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个人都能从这个计划中受益。", "target_word": "受益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次培训让大家都受益了。", "target_word": "受益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "住在公园旁边的人最受益。", "target_word": "受益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从父母的教育中受益很多。", "target_word": "受益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家一起工作，公司和客人都受益。", "target_word": "受益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新的医保政策让老人受益。", "target_word": "受益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多听别人的意见，你会受益。", "target_word": "受益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书让我受益不少。", "target_word": "受益", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们从这门课中受益。", "target_word": "受益", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "受益人", "label": "复合"}, {"form": "受益者", "label": "复合"}, {"form": "受益了", "label": "体标"}], "register": "中性", "sense_fingerprint": "得到好处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '346c9218-cb43-4e91-8a90-710077c45e12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27302, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "受益", "is_correct": true, "explanation": "受益（shòu yì）：得到好处，与听到的读音一致"}, {"text": "收益", "is_correct": false, "explanation": "shōu（第一声）与 shòu（第四声）声调不同，收益指所得的利润或收入"}, {"text": "手艺", "is_correct": false, "explanation": "shǒu（第三声）与 shòu（第四声）声调不同，手艺指手工技能"}, {"text": "寿衣", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，寿衣指为去世者准备的衣服"}, {"text": "兽医", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，兽医指给动物看病的人"}], "explanations": {"受益": "受益（shòu yì）：得到好处，与听到的读音一致", "收益": "shōu（第一声）与 shòu（第四声）声调不同，收益指所得的利润或收入", "手艺": "shǒu（第三声）与 shòu（第四声）声调不同，手艺指手工技能", "寿衣": "yī（第一声）与 yì（第四声）声调不同，寿衣指为去世者准备的衣服", "兽医": "yī（第一声）与 yì（第四声）声调不同，兽医指给动物看病的人"}, "sentence_index": null, "correct_answer": "受益"}, "level_3": {"options": [{"text": "受益", "is_correct": true, "explanation": "受益：得到好处，符合“好好学习”的积极结果"}, {"text": "受伤", "is_correct": false, "explanation": "语义：“受伤”是坏结果，与“好好学习”的好处相反"}, {"text": "受罪", "is_correct": false, "explanation": "语义：“受罪”指遭受痛苦，与“好好学习”带来的积极结果相反"}, {"text": "吃亏", "is_correct": false, "explanation": "语义：“吃亏”指遭受损失，与“受益一生”的意思相反"}], "explanations": {"受益": "受益：得到好处，符合“好好学习”的积极结果", "受伤": "语义：“受伤”是坏结果，与“好好学习”的好处相反", "受罪": "语义：“受罪”指遭受痛苦，与“好好学习”带来的积极结果相反", "吃亏": "语义：“吃亏”指遭受损失，与“受益一生”的意思相反"}, "sentence_index": 0, "correct_answer": "受益"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在工作中受益了很多经验。", "explanation": "这里应该用〈获得〉。受益是不及物动词，后面不能直接带“经验”作宾语；获得可以带宾语"}, {"text": "他受益了老师的很多建议。", "explanation": "这里应该用〈得到〉。受益是不及物动词，不能直接带“建议”作宾语；应说“从老师的建议中受益”或“得到了很多建议”。"}, {"text": "他因为总是抽烟，肺部受益了很多。", "explanation": "这里应该用〈受损〉。受益表示得到好处，抽烟带来的是伤害，应说“受损”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27302, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "受益", "is_correct": true, "explanation": "受益：得到好处，符合“新的医保政策”的作用"}, {"text": "变丑", "is_correct": false, "explanation": "语义：“变丑”说的是外貌，与政策带来的实际好处不合"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”是坏结果，与医保政策的作用相反"}, {"text": "挨饿", "is_correct": false, "explanation": "语义：“挨饿”指遭受困苦，与政策的积极作用相反"}], "explanations": {"受益": "受益：得到好处，符合“新的医保政策”的作用", "变丑": "语义：“变丑”说的是外貌，与政策带来的实际好处不合", "生病": "语义：“生病”是坏结果，与医保政策的作用相反", "挨饿": "语义：“挨饿”指遭受困苦，与政策的积极作用相反"}, "sentence_index": 6, "correct_answer": "受益"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "早睡受益健康。", "explanation": "这里应该用〈有益于〉。受益是不及物动词，不能直接带“健康”作宾语；“有益于”可以。"}, {"text": "这场比赛让我们队受益惨重。", "explanation": "这里应该用〈损失〉。“惨重”说明是损失，而受益表示得到好处，与句意相反"}, {"text": "周末我们在山上受益了清新的空气。", "explanation": "这里应该用〈享受〉。受益是不及物动词，不能直接带“空气”作宾语；享受可以带宾语"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27302, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我从这次旅行中被受益很多。", "corrected_sentence": "我从这次旅行中受益很多。", "error_description": "错误：加了“被”。“受益”是不及物动词，不能用于被动结构，应说“我从这次旅行中受益很多”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27302, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同学们从这门课被受益了不少。", "corrected_sentence": "同学们从这门课受益了不少。", "error_description": "错误：多加了“被”。“受益”是不及物动词，不能用于被动结构，应删去“被”，说“同学们从这门课受益了不少”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
