INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27304, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "想事情。", "primary_collocate": null, "pronunciation": "sī kǎo", "ipa": "sɹ̩˥ kʰɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "安静的晚上，我喜欢一个人思考。", "target_word": "思考", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这道题很难，我需要思考一下。", "target_word": "思考", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不说话，好像在思考什么。", "target_word": "思考", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "先思考，再回答。", "target_word": "思考", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师让我们安静地思考五分钟。", "target_word": "思考", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她看着窗外，一直在思考。", "target_word": "思考", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不要急，慢慢思考。", "target_word": "思考", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "睡觉前，他常常思考一天的事。", "target_word": "思考", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个问题值得我们认真思考。", "target_word": "思考", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明低着头，认真地思考怎么回答。", "target_word": "思考", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "思考了", "label": "体标"}, {"form": "思考着", "label": "体标"}, {"form": "思考过", "label": "体标"}, {"form": "思考思考", "label": "重叠"}], "register": "中性", "sense_fingerprint": "动脑子想事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df62efa0-2dbe-46fc-9d7d-40fafa899bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27304, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "思考", "is_correct": true, "explanation": "正确：“一个人思考”符合“安静的晚上”的语境，句意通顺。"}, {"text": "大喊", "is_correct": false, "explanation": "语义：“大喊”声音很大，与句中“安静的晚上”的语境矛盾。"}, {"text": "吵架", "is_correct": false, "explanation": "配价：“吵架”需要对象，不能只说“一个人吵架”。"}, {"text": "喧哗", "is_correct": false, "explanation": "语义：“喧哗”指吵闹，与“安静的晚上”正好相反。"}], "explanations": {"思考": "正确：“一个人思考”符合“安静的晚上”的语境，句意通顺。", "大喊": "语义：“大喊”声音很大，与句中“安静的晚上”的语境矛盾。", "吵架": "配价：“吵架”需要对象，不能只说“一个人吵架”。", "喧哗": "语义：“喧哗”指吵闹，与“安静的晚上”正好相反。"}, "sentence_index": 0, "correct_answer": "思考"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我思考吃饭。", "explanation": "这里应该用〈想〉。思考表示动脑子想事情，不能表示想要做某事。"}, {"text": "我思考了一觉。", "explanation": "这里应该用〈睡〉。思考是动脑子想事情，不能表示睡觉这个动作。"}, {"text": "他先思考手，然后回家。", "explanation": "这里应该用〈洗〉。思考是动脑子想事情，不能表示洗手这个动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5130e15f-d8d7-488d-bde2-1feee74671e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27304, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "思考", "is_correct": true, "explanation": "正确：“你不要急，慢慢思考”是常见的劝说语，句意通顺。"}, {"text": "冲刺", "is_correct": false, "explanation": "语义：“冲刺”指快速向前，与句中“慢慢”矛盾。"}, {"text": "抢夺", "is_correct": false, "explanation": "配价：“抢夺”需要受事宾语，句中没有可以承受动作的对象。"}, {"text": "逃跑", "is_correct": false, "explanation": "语义：“逃跑”与“你不要急”的劝说语境不符。"}], "explanations": {"思考": "正确：“你不要急，慢慢思考”是常见的劝说语，句意通顺。", "冲刺": "语义：“冲刺”指快速向前，与句中“慢慢”矛盾。", "抢夺": "配价：“抢夺”需要受事宾语，句中没有可以承受动作的对象。", "逃跑": "语义：“逃跑”与“你不要急”的劝说语境不符。"}, "sentence_index": 6, "correct_answer": "思考"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈去超市思考了一斤苹果。", "explanation": "这里应该用〈买〉。思考是动脑子想事情，不能表示购买东西的动作。"}, {"text": "他每天思考书到深夜。", "explanation": "这里应该用〈看〉。思考不能表示用眼睛阅读。"}, {"text": "他饿了，去思考饭。", "explanation": "这里应该用〈吃〉。思考不能表示吃饭的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5130e15f-d8d7-488d-bde2-1feee74671e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27304, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这道题很难，我得先思考了一下。", "corrected_sentence": "这道题很难，我得先思考一下。", "error_description": "错误形式：“得……思考了一下”。正确形式：“得……思考一下”。“得”表示需要，后面的动词不能带“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5130e15f-d8d7-488d-bde2-1feee74671e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27304, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你要仔细得思考这个问题。", "corrected_sentence": "你要仔细思考这个问题。", "error_description": "错误形式：“仔细得思考”。正确形式：“仔细思考”或“仔细地思考”。“得”是补语标记，不能用在动词前作状语；修饰动词的状语要用“地”，或直接省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5130e15f-d8d7-488d-bde2-1feee74671e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27306, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "笨", "is_correct": true, "explanation": "「笨」指脑子不灵活、学东西慢，与「聪明」意义相反，正确。"}, {"text": "高兴", "is_correct": false, "explanation": "「高兴」形容心情愉快，与「聪明」没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "「安静」形容没有声音或情绪平和，与「聪明」没有反义关系。"}, {"text": "整齐", "is_correct": false, "explanation": "「整齐」形容排列有秩序，与「聪明」没有反义关系。"}], "correct_answer": "笨", "explanations": {"笨": "「笨」指脑子不灵活、学东西慢，与「聪明」意义相反，正确。", "高兴": "「高兴」形容心情愉快，与「聪明」没有反义关系。", "安静": "「安静」形容没有声音或情绪平和，与「聪明」没有反义关系。", "整齐": "「整齐」形容排列有秩序，与「聪明」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27306, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "愚蠢", "is_correct": true, "explanation": "「愚蠢」指头脑不灵活，与「聪明」意义相反，正确。"}, {"text": "勤快", "is_correct": false, "explanation": "「勤快」指肯干、不懒，与「聪明」没有反义关系。"}, {"text": "温柔", "is_correct": false, "explanation": "「温柔」形容性情和气，与「聪明」没有反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "「干净」指没有污物，与「聪明」没有反义关系。"}], "correct_answer": "愚蠢", "explanations": {"愚蠢": "「愚蠢」指头脑不灵活，与「聪明」意义相反，正确。", "勤快": "「勤快」指肯干、不懒，与「聪明」没有反义关系。", "温柔": "「温柔」形容性情和气，与「聪明」没有反义关系。", "干净": "「干净」指没有污物，与「聪明」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27306, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "聪明就是学东西快，懂得多。", "primary_collocate": null, "pronunciation": "cōng míng", "ipa": "tsʰʊŋ˥ min˧˥", "syllable_count": 2, "sentences": [{"text": "这个孩子很聪明，学什么都快。", "target_word": "聪明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是一个聪明的女孩。", "target_word": "聪明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海豚是很聪明的动物。", "target_word": "聪明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学东西很快，真聪明。", "target_word": "聪明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个男孩从小就很聪明，懂的东西特别多。", "target_word": "聪明", "complexity_tier": "T3", "furigana": "zhè ge nán hái cóng xiǎo jiù hěn cōng míng, dǒng de dōng xi tè bié duō.", "sentence_source": "generated"}, {"text": "聪明的人也要认真学习。", "target_word": "聪明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟聪明又努力，成绩很好。", "target_word": "聪明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只乌鸦很聪明，会用石头喝水。", "target_word": "聪明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是最聪明的，但是很努力。", "target_word": "聪明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说我们家的孩子都很聪明。", "target_word": "聪明", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "聪明人", "label": "复合"}, {"form": "聪明才智", "label": "复合"}], "register": "通用", "sense_fingerprint": "人或动物脑子好，学东西快", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17259789-fe49-4308-9f94-df080a361105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27306, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "聪明", "is_correct": true, "explanation": "脑子好、学东西快，正确。"}, {"text": "匆忙", "is_correct": false, "explanation": "míng（第二声）与 máng（第二声）韵母不同（ing / ang），「匆忙」意思是急促，不是「聪明」。"}, {"text": "轰鸣", "is_correct": false, "explanation": "hōng 与 cōng 声母不同（h / c），「轰鸣」意思是巨大的响声，不是「聪明」。"}, {"text": "功名", "is_correct": false, "explanation": "gōng 与 cōng 声母不同（g / c），「功名」意思是功绩和名声，不是「聪明」。"}], "explanations": {"聪明": "脑子好、学东西快，正确。", "匆忙": "míng（第二声）与 máng（第二声）韵母不同（ing / ang），「匆忙」意思是急促，不是「聪明」。", "轰鸣": "hōng 与 cōng 声母不同（h / c），「轰鸣」意思是巨大的响声，不是「聪明」。", "功名": "gōng 与 cōng 声母不同（g / c），「功名」意思是功绩和名声，不是「聪明」。"}, "sentence_index": null, "correct_answer": "聪明"}, "level_3": {"options": [{"text": "聪明", "is_correct": true, "explanation": "「聪明」形容人脑子好、学东西快，与「这个孩子很……，学什么都快」相符，正确。"}, {"text": "便宜", "is_correct": false, "explanation": "搭配：「便宜」形容价格低，不能用来形容孩子。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：「高大」形容身材，与学习快慢无关。"}, {"text": "愚笨", "is_correct": false, "explanation": "语义：「愚笨」与「学什么都快」直接相反。"}], "explanations": {"聪明": "「聪明」形容人脑子好、学东西快，与「这个孩子很……，学什么都快」相符，正确。", "便宜": "搭配：「便宜」形容价格低，不能用来形容孩子。", "高大": "体貌：「高大」形容身材，与学习快慢无关。", "愚笨": "语义：「愚笨」与「学什么都快」直接相反。"}, "sentence_index": 0, "correct_answer": "聪明"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子的耳朵很聪明。", "explanation": "这里应该用〈灵敏〉。「聪明」形容人的头脑好、学得快，耳朵反应快要用「灵敏」。"}, {"text": "这碗粥很聪明，喝起来很暖和。", "explanation": "这里应该用〈好喝〉。「聪明」形容人或动物头脑好、学得快，形容食物应说「好喝」。"}, {"text": "今天的天气很聪明。", "explanation": "这里应该用〈好〉。「聪明」形容头脑好、学得快，天气没有头脑，形容天气应说「好」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27306, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "聪明", "is_correct": true, "explanation": "「聪明」形容人脑子好，与「弟弟……又努力，成绩很好」相符，正确。"}, {"text": "懒散", "is_correct": false, "explanation": "语义：「懒散」与「努力」矛盾。"}, {"text": "愚钝", "is_correct": false, "explanation": "语义：「愚钝」与「成绩很好」矛盾。"}, {"text": "可口", "is_correct": false, "explanation": "搭配：「可口」多用来形容食物，不能用来形容人。"}], "explanations": {"聪明": "「聪明」形容人脑子好，与「弟弟……又努力，成绩很好」相符，正确。", "懒散": "语义：「懒散」与「努力」矛盾。", "愚钝": "语义：「愚钝」与「成绩很好」矛盾。", "可口": "搭配：「可口」多用来形容食物，不能用来形容人。"}, "sentence_index": 6, "correct_answer": "聪明"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他起床起得很聪明。", "explanation": "这里应该用〈早〉。「聪明」形容头脑好、学得快，形容起床的时间要用「早」。"}, {"text": "这块石头很聪明，又硬又重。", "explanation": "这里应该用〈坚硬〉。「聪明」只形容人或动物头脑好、学得快，形容石头应说「坚硬」。"}, {"text": "这次考试的成绩很聪明。", "explanation": "这里应该用〈优秀〉。「聪明」形容人的头脑好、学得快，成绩好要用「优秀」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27306, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹非常聪明地，一学就会。", "corrected_sentence": "妹妹非常聪明，一学就会。", "error_description": "错误形式：「聪明地」；正确形式：「聪明」。「聪明」作谓语时后面不能加结构助词「地」，应说「非常聪明」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27306, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他聪明得解决了问题。", "corrected_sentence": "他聪明地解决了问题。", "error_description": "结构助词错误：修饰动词应用「地」，「得」用于动词或形容词后的补语，应说「聪明地解决」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27310, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "马虎", "is_correct": true, "explanation": "反义：“认真”与“马虎”相对，“认真对待”的反面是做事不认真、不在意。"}, {"text": "研究", "is_correct": false, "explanation": "“研究”指探究事物，与“认真对待”没有反义关系。"}, {"text": "参加", "is_correct": false, "explanation": "“参加”指加入某项活动，与“认真对待”没有反义关系。"}, {"text": "完成", "is_correct": false, "explanation": "“完成”指做完某件事，与“认真对待”没有反义关系。"}], "correct_answer": "马虎", "explanations": {"马虎": "反义：“认真”与“马虎”相对，“认真对待”的反面是做事不认真、不在意。", "研究": "“研究”指探究事物，与“认真对待”没有反义关系。", "参加": "“参加”指加入某项活动，与“认真对待”没有反义关系。", "完成": "“完成”指做完某件事，与“认真对待”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8447778d-b004-49a8-af3a-5f79a288da48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27310, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "马虎", "is_correct": true, "explanation": "反义：“认真”与“马虎”相对，“认真对待”的反面是做事不在意。"}, {"text": "清洗", "is_correct": false, "explanation": "“清洗”指用水去除污垢，与“认真对待”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”指悠闲地走路，与“认真对待”没有反义关系。"}, {"text": "观察", "is_correct": false, "explanation": "“观察”指仔细看，与“认真对待”没有反义关系。"}], "correct_answer": "马虎", "explanations": {"马虎": "反义：“认真”与“马虎”相对，“认真对待”的反面是做事不在意。", "清洗": "“清洗”指用水去除污垢，与“认真对待”没有反义关系。", "散步": "“散步”指悠闲地走路，与“认真对待”没有反义关系。", "观察": "“观察”指仔细看，与“认真对待”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8447778d-b004-49a8-af3a-5f79a288da48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27310, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "要认真地做事情，不马虎。", "primary_collocate": null, "pronunciation": "rèn zhēn duì dài", "ipa": "ɻən˥˩ ʈʂən˥ tweɪ˥˩ taɪ˥˩", "syllable_count": 4, "sentences": [{"text": "做作业时要认真对待，不能马虎。", "target_word": "认真对待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，写字要认真对待。", "target_word": "认真对待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不管事情大小，我们都要认真对待。", "target_word": "认真对待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他做事不马虎，对每件小事都认真对待。", "target_word": "认真对待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要认真对待这次比赛，别太随便。", "target_word": "认真对待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈让我认真对待学习，不要玩手机。", "target_word": "认真对待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我会认真对待你交给我的任务。", "target_word": "认真对待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不认真对待，工作容易出错。", "target_word": "认真对待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们认真对待值日，教室很干净。", "target_word": "认真对待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她对什么事都认真对待，从不马虎。", "target_word": "认真对待", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "认真对待了", "label": "体标"}, {"form": "认真对待过", "label": "体标"}], "register": "中性", "sense_fingerprint": "做事认真、不马虎、不敷衍", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd295e12-7231-4a6a-a8ef-075f24fccda5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27310, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "认真对待", "is_correct": true, "explanation": "“认真对待”表示做事不马虎，与“做作业时要……不能马虎”相符。"}, {"text": "种植", "is_correct": false, "explanation": "搭配：“种植”用于植物，不能用于做作业。"}, {"text": "组装", "is_correct": false, "explanation": "搭配：“组装”用于零件或机器，不能用于做作业。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：作业不能被欣赏，与“不能马虎”的要求冲突。"}], "explanations": {"认真对待": "“认真对待”表示做事不马虎，与“做作业时要……不能马虎”相符。", "种植": "搭配：“种植”用于植物，不能用于做作业。", "组装": "搭配：“组装”用于零件或机器，不能用于做作业。", "欣赏": "语义：作业不能被欣赏，与“不能马虎”的要求冲突。"}, "sentence_index": 0, "correct_answer": "认真对待"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天都认真对待那片云。", "explanation": "这里应该用〈欣赏〉。〈认真对待〉指对事情的态度，不用于“那片云”这类景物，应说“欣赏那片云”。"}, {"text": "奶奶认真对待了一阵风。", "explanation": "这里应该用〈感受〉。〈认真对待〉指对事情的态度，不用于“一阵风”这类自然现象，应说“感受了一阵风”。"}, {"text": "他认真对待了一道闪电。", "explanation": "这里应该用〈躲避〉。〈认真对待〉指对事情的态度，不用于“一道闪电”，应说“躲避了一道闪电”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8447778d-b004-49a8-af3a-5f79a288da48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27310, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "认真对待", "is_correct": true, "explanation": "“认真对待”表示认真处理，“我会……你交给我的任务”符合语境。"}, {"text": "出售", "is_correct": false, "explanation": "语义：“出售”指卖东西，任务不能出售。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”用于场所或展览，不能用于任务。"}, {"text": "饲养", "is_correct": false, "explanation": "搭配：“饲养”用于动物，不能用于任务。"}], "explanations": {"认真对待": "“认真对待”表示认真处理，“我会……你交给我的任务”符合语境。", "出售": "语义：“出售”指卖东西，任务不能出售。", "参观": "搭配：“参观”用于场所或展览，不能用于任务。", "饲养": "搭配：“饲养”用于动物，不能用于任务。"}, "sentence_index": 6, "correct_answer": "认真对待"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她每天都认真对待那片天空。", "explanation": "这里应该用〈仰望〉。〈认真对待〉指对事情的态度，不用于“那片天空”，应说“仰望那片天空”。"}, {"text": "她认真对待了那片海。", "explanation": "这里应该用〈眺望〉。〈认真对待〉不用于“那片海”这类景物，应说“眺望那片海”。"}, {"text": "她认真对待了那阵雷声。", "explanation": "这里应该用〈听见〉。〈认真对待〉不用于“那阵雷声”这类声音，应说“听见那阵雷声”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8447778d-b004-49a8-af3a-5f79a288da48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27310, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从来没有认真对待了作业。", "corrected_sentence": "他从来没有认真对待过作业。", "error_description": "错误：表示经历的“认真对待”后用了“了”。正确：“从来没有”表示经历，应说“认真对待过作业”，用“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8447778d-b004-49a8-af3a-5f79a288da48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27310, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师交给我的任务，我会认真对待着。", "corrected_sentence": "老师交给我的任务，我会认真对待。", "error_description": "错误：“会”表示将来，“认真对待”后不能加持续体“着”。正确：去掉“着”，说“我会认真对待”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8447778d-b004-49a8-af3a-5f79a288da48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
