INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27312, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人就是我们，会说话、会走路、会想事情的动物。", "primary_collocate": null, "pronunciation": "rén", "ipa": "ɻən˧˥", "syllable_count": 1, "sentences": [{"text": "人会说话，也会走路。", "target_word": "人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人是我的老师。", "target_word": "人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋子里有五个人。", "target_word": "人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人不吃饭就没有力气。", "target_word": "人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里的人很多。", "target_word": "人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人和狗都喜欢玩。", "target_word": "人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人每天走路去上班。", "target_word": "人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人会想事情，所以会做很多事。", "target_word": "人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口站着一个人，我不认识他。", "target_word": "人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一个很会想办法的人。", "target_word": "人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个人", "label": "量词"}, {"form": "大人", "label": "复合"}], "register": "口语", "sense_fingerprint": "人：我们这样会说话、走路、思考的个体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47c36c6a-10d1-484f-a144-0a730fa56e1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27312, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "人", "is_correct": true, "explanation": "正确答案：人（rén），指会说话、会走路、会想事情的个体。"}, {"text": "忍", "is_correct": false, "explanation": "rěn（第三声）与 rén（第二声）声调不同，意思是忍耐。"}, {"text": "然", "is_correct": false, "explanation": "rán 与 rén 韵母不同（-an / -en），声调相同，意思是这样、如此。"}, {"text": "仍", "is_correct": false, "explanation": "réng 与 rén 韵母不同（-eng / -en），声调相同，意思是仍然。"}], "explanations": {"人": "正确答案：人（rén），指会说话、会走路、会想事情的个体。", "忍": "rěn（第三声）与 rén（第二声）声调不同，意思是忍耐。", "然": "rán 与 rén 韵母不同（-an / -en），声调相同，意思是这样、如此。", "仍": "réng 与 rén 韵母不同（-eng / -en），声调相同，意思是仍然。"}, "sentence_index": null, "correct_answer": "人"}, "level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头不会说话，也不会走路。"}, {"text": "人", "is_correct": true, "explanation": "人：会说话、会走路的个体，正好填入句中的空格。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：「会说话、会走路」要求能自主行动的主体，房子不能这样说。"}, {"text": "树", "is_correct": false, "explanation": "语义：树不会说话，也不能自己走路。"}], "explanations": {"石头": "语义：石头不会说话，也不会走路。", "人": "人：会说话、会走路的个体，正好填入句中的空格。", "房子": "搭配：「会说话、会走路」要求能自主行动的主体，房子不能这样说。", "树": "语义：树不会说话，也不能自己走路。"}, "sentence_index": 0, "correct_answer": "人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班今天来了一只人。", "explanation": "这里应该用〈个〉或〈位〉。量词「只」用于动物，指人要用「个」或「位」。"}, {"text": "小狗是一种很聪明的人。", "explanation": "这里应该用〈动物〉。「人」指人类，不能用来指小狗，小狗属于动物。"}, {"text": "这张人是我们的好朋友。", "explanation": "这里应该用〈位〉或〈个〉。量词「张」用于平面的东西，不用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '571872f6-9807-451a-bc7d-5a66fa6060b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27312, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "人", "is_correct": true, "explanation": "正确答案：人（rén），指会说话、会走路、会想事情的个体。"}, {"text": "任", "is_correct": false, "explanation": "rèn（第四声）与 rén（第二声）声调不同，意思是担任、任务。"}, {"text": "韧", "is_correct": false, "explanation": "rèn（第四声）与 rén（第二声）声调不同，意思是结实、不易断。"}, {"text": "嫩", "is_correct": false, "explanation": "nèn 与 rén 声母不同（n / r），声调也不同，意思是柔嫩、不老。"}], "explanations": {"人": "正确答案：人（rén），指会说话、会走路、会想事情的个体。", "任": "rèn（第四声）与 rén（第二声）声调不同，意思是担任、任务。", "韧": "rèn（第四声）与 rén（第二声）声调不同，意思是结实、不易断。", "嫩": "nèn 与 rén 声母不同（n / r），声调也不同，意思是柔嫩、不老。"}, "sentence_index": null, "correct_answer": "人"}, "level_3": {"options": [{"text": "车", "is_correct": false, "explanation": "搭配：「走路」只用于人或动物，车应说「开车」，不能说「走路」。"}, {"text": "人", "is_correct": true, "explanation": "人：能走路去上班的个体，正好填入句中的空格。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不能自己走路，也不会去上班。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是物品，不能自己走路去上班。"}], "explanations": {"车": "搭配：「走路」只用于人或动物，车应说「开车」，不能说「走路」。", "人": "人：能走路去上班的个体，正好填入句中的空格。", "椅子": "语义：椅子不能自己走路，也不会去上班。", "书包": "语义：书包是物品，不能自己走路去上班。"}, "sentence_index": 6, "correct_answer": "人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "教室里坐着一颗人。", "explanation": "这里应该用〈个〉。量词「颗」用于小而圆的东西，不用于人。"}, {"text": "这块石头是一个很大的人。", "explanation": "这里应该用〈东西〉。「人」指人类，不能用来指石头这样的无生命物体。"}, {"text": "公司新来了十条人。", "explanation": "这里应该用〈个〉或〈位〉。量词「条」不用于指人，「人」要用「个」或「位」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '571872f6-9807-451a-bc7d-5a66fa6060b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27312, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那位老人是一个很善良人。", "corrected_sentence": "那位老人是一个很善良的人。", "error_description": "错误形式是「很善良人」，正确形式是「很善良的人」。「很善良」修饰名词「人」时中间要加「的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '571872f6-9807-451a-bc7d-5a66fa6060b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27312, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "房间里有一个人们在睡觉。", "corrected_sentence": "房间里有一个人在睡觉。", "error_description": "错误形式是「一个人们」，「人们」是复数形式，不能与数量词「一个」搭配，应改为「一个人」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '571872f6-9807-451a-bc7d-5a66fa6060b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
