INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27314, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "机器人是一种能自己动的机器。", "primary_collocate": null, "pronunciation": "jī qì rén", "ipa": "tɕi˥ tɕʰi˥˩ ɻən˧˥", "syllable_count": 3, "sentences": [{"text": "这个机器人会跳舞。", "target_word": "机器人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂里有很多机器人。", "target_word": "机器人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给机器人起了一个名字。", "target_word": "机器人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器人可以帮我打扫房间。", "target_word": "机器人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的生日礼物是一个小机器人。", "target_word": "机器人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机器人会说中文。", "target_word": "机器人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "儿子正玩着机器人。", "target_word": "机器人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器人不会累，也不会生气。", "target_word": "机器人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一个会唱歌的机器人。", "target_word": "机器人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院里的机器人给病人送药。", "target_word": "机器人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个机器人", "label": "量词"}, {"form": "服务机器人", "label": "复合"}], "register": "中性", "sense_fingerprint": "能自动做事的机器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d952261-361f-4475-b6c1-65e9db11d94e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27314, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头没有生命，不会跳舞，与“会跳舞”相矛盾。"}, {"text": "机器人", "is_correct": true, "explanation": "“机器人”是能自己动的机器，可以“会跳舞”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是静止的家具，不能跳舞。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是静止的家电，不能跳舞，与“会跳舞”相矛盾。"}], "explanations": {"石头": "语义：石头没有生命，不会跳舞，与“会跳舞”相矛盾。", "机器人": "“机器人”是能自己动的机器，可以“会跳舞”。", "桌子": "语义：桌子是静止的家具，不能跳舞。", "冰箱": "语义：冰箱是静止的家电，不能跳舞，与“会跳舞”相矛盾。"}, "sentence_index": 0, "correct_answer": "机器人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "院子里的机器人下了几个蛋。", "explanation": "这里应该用〈母鸡〉。下蛋的是动物，机器人是机器，不会下蛋。"}, {"text": "春天到了，花园里的机器人开花了。", "explanation": "这里应该用〈花草〉。开花的是植物，机器人是机器，不会开花。"}, {"text": "这台机器人要人踩着踏板才能动。", "explanation": "这里应该用〈机器〉。机器人是能自己动的机器，需要人踩踏板才能动的应该说“机器”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e43ab20-e93c-472d-8971-52aaf3267d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27314, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作业", "is_correct": false, "explanation": "搭配：“玩”后面不接“作业”，这里应说“做作业”。"}, {"text": "眼泪", "is_correct": false, "explanation": "语义：眼泪不能被当作玩具去玩，与“玩着”不搭。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不能作“玩”的对象，这个句子读来不通。"}, {"text": "机器人", "is_correct": true, "explanation": "“机器人”是儿子正在玩的玩具，与“玩着”相符。"}], "explanations": {"作业": "搭配：“玩”后面不接“作业”，这里应说“做作业”。", "眼泪": "语义：眼泪不能被当作玩具去玩，与“玩着”不搭。", "天气": "搭配：“天气”不能作“玩”的对象，这个句子读来不通。", "机器人": "“机器人”是儿子正在玩的玩具，与“玩着”相符。"}, "sentence_index": 6, "correct_answer": "机器人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的机器人每天要吃两次饭。", "explanation": "这里应该用〈宠物〉。机器人靠电力或电池工作，不需要吃饭，“吃饭”一般用于宠物等生物。"}, {"text": "这个机器人生病了，在医院打针。", "explanation": "这里应该用〈病人〉。生病打针的是人，机器人坏了要修理，不会生病。"}, {"text": "妈妈在树上摘了几个机器人。", "explanation": "这里应该用〈苹果〉。树上长的是果子，机器人是机器，不长在树上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e43ab20-e93c-472d-8971-52aaf3267d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27314, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姐姐给弟弟买了一只机器人当生日礼物。", "corrected_sentence": "姐姐给弟弟买了一个机器人当生日礼物。", "error_description": "错误：“只”用于动物，机器人的量词应该用“个”，应说“买了一个机器人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e43ab20-e93c-472d-8971-52aaf3267d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27314, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个机器人搬很快，一小时就能搬完一车货。", "corrected_sentence": "这个机器人搬得很快，一小时就能搬完一车货。", "error_description": "错误：动词和补语之间要用结构助词“得”连接，应说“搬得很快”，不能说“搬很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e43ab20-e93c-472d-8971-52aaf3267d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27316, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "去", "is_correct": true, "explanation": "正确。“去”与“来”相反，表示从说话人这里到别处。"}, {"text": "吃", "is_correct": false, "explanation": "与“来”没有反义关系，只是同为动词。"}, {"text": "写", "is_correct": false, "explanation": "与“来”没有反义关系，只是同为动词。"}, {"text": "唱", "is_correct": false, "explanation": "与“来”没有反义关系，只是同为动词。"}], "correct_answer": "去", "explanations": {"去": "正确。“去”与“来”相反，表示从说话人这里到别处。", "吃": "与“来”没有反义关系，只是同为动词。", "写": "与“来”没有反义关系，只是同为动词。", "唱": "与“来”没有反义关系，只是同为动词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
