INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27316, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从别处到说话人这里。", "primary_collocate": null, "pronunciation": "lái", "ipa": "lai˧˥", "syllable_count": 1, "sentences": [{"text": "你什么时候来我家？", "target_word": "来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友明天要来看我。", "target_word": "来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他来了，我们开始吃饭吧。", "target_word": "来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面有人敲门，是谁来了？", "target_word": "来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈从北京来看我了。", "target_word": "来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车来了，快上车。", "target_word": "来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在家等你，你快点来。", "target_word": "来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天没有来学校。", "target_word": "来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "欢迎你来我们的城市玩。", "target_word": "来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人来过这里，桌子上还有茶。", "target_word": "来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "来了", "label": "体标"}, {"form": "来过", "label": "体标"}, {"form": "來", "label": "繁体"}], "register": "中性", "sense_fingerprint": "从别处到说话人这里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40c6bb68-9edb-4a24-ad31-cf0cde640a3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27316, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "来", "is_correct": true, "explanation": "正确。“来”表示从别处到说话人这里。"}, {"text": "蓝", "is_correct": false, "explanation": "lán 与 lái 韵母不同，lán 意思是蓝色。"}, {"text": "赖", "is_correct": false, "explanation": "lài（第四声）与 lái（第二声）声调不同，lài 意思是抵赖。"}, {"text": "白", "is_correct": false, "explanation": "bái 与 lái 声母不同，bái 意思是白色。"}], "explanations": {"来": "正确。“来”表示从别处到说话人这里。", "蓝": "lán 与 lái 韵母不同，lán 意思是蓝色。", "赖": "lài（第四声）与 lái（第二声）声调不同，lài 意思是抵赖。", "白": "bái 与 lái 声母不同，bái 意思是白色。"}, "sentence_index": null, "correct_answer": "来"}, "level_3": {"options": [{"text": "来", "is_correct": true, "explanation": "正确。“什么时候来我家”表示对方从别处到说话人家。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”需要食物作宾语，“我家”不能作“吃”的对象。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的对象是文字，不能说“写我家”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，与“什么时候到我家”的语境无关。"}], "explanations": {"来": "正确。“什么时候来我家”表示对方从别处到说话人家。", "吃": "语义：“吃”需要食物作宾语，“我家”不能作“吃”的对象。", "写": "搭配：“写”的对象是文字，不能说“写我家”。", "唱": "语义：“唱”指发出歌声，与“什么时候到我家”的语境无关。"}, "sentence_index": 0, "correct_answer": "来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我现在在北京，明天我来上海。", "explanation": "这里应该用〈去〉。说话人在北京，「来」以说话人所在处为目标，前往上海要用「去」。"}, {"text": "我在北京，下个月我来老家工作。", "explanation": "这里应该用〈回〉。老家是说话人自己的地方，回去要用「回」。"}, {"text": "我在家，等一下我来超市买菜。", "explanation": "这里应该用〈去〉。说话人在家，到超市是离开说话人所在地，要用「去」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27316, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "来", "is_correct": true, "explanation": "正确。“来”表示从别处到说话人这里。"}, {"text": "篮", "is_correct": false, "explanation": "lán 与 lái 韵母不同，lán 意思是篮子。"}, {"text": "才", "is_correct": false, "explanation": "cái 与 lái 声母不同，cái 意思是才、刚刚。"}, {"text": "排", "is_correct": false, "explanation": "pái 与 lái 声母不同，pái 意思是排列、排队。"}], "explanations": {"来": "正确。“来”表示从别处到说话人这里。", "篮": "lán 与 lái 韵母不同，lán 意思是篮子。", "才": "cái 与 lái 声母不同，cái 意思是才、刚刚。", "排": "pái 与 lái 声母不同，pái 意思是排列、排队。"}, "sentence_index": null, "correct_answer": "来"}, "level_3": {"options": [{"text": "来", "is_correct": true, "explanation": "正确。“你快点来”是请对方从别处赶到说话人这里。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“快点睡”与“我在家等你”的语境冲突。"}, {"text": "笑", "is_correct": false, "explanation": "语义：“快点笑”不表示催促对方赶来的意思。"}, {"text": "哭", "is_correct": false, "explanation": "搭配：“哭”不能表示加快到达某处的动作，与句意不合。"}], "explanations": {"来": "正确。“你快点来”是请对方从别处赶到说话人这里。", "睡": "语义：“快点睡”与“我在家等你”的语境冲突。", "笑": "语义：“快点笑”不表示催促对方赶来的意思。", "哭": "搭配：“哭”不能表示加快到达某处的动作，与句意不合。"}, "sentence_index": 6, "correct_answer": "来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在上海，他明天来北京出差。", "explanation": "这里应该用〈去〉。说话人在上海，他前往北京要用「去」，「来」以说话人所在处为目标。"}, {"text": "我在上海，他上周来北京看长城了。", "explanation": "这里应该用〈去〉。说话人在上海，他前往北京要用「去」，「来」以说话人所在处为目标。"}, {"text": "我在上海，他下午来北京的家了。", "explanation": "这里应该用〈回〉。他要回的是自己在北京的家，说回自己的地方要用「回」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27316, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他以前来了过我们学校。", "corrected_sentence": "他以前来过我们学校。", "error_description": "错误：「来过」已经带有体标「过」，前面不能再加「了」。正确是「来过」，应说「他以前来过我们学校」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27316, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们明天来了你家吃饭。", "corrected_sentence": "我们明天来你家吃饭。", "error_description": "错误：“明天来了你家”；正确：“明天来你家”。“来”后加“了”表示已经发生，与表示将来的“明天”冲突，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
