INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27318, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "说就是用嘴巴讲话告诉别人事情。", "primary_collocate": null, "pronunciation": "shuō", "ipa": "ʂwo˥", "syllable_count": 1, "sentences": [{"text": "小明说他昨天去了动物园。", "target_word": "说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我要告诉你一件事，你听我说。", "target_word": "说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在电话里说，晚上会晚点回家。", "target_word": "说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子小声说：“妈妈，我饿了。”", "target_word": "说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请再说一遍，我没听清楚。", "target_word": "说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说下星期要考试。", "target_word": "说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说着说着就笑了。", "target_word": "说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说得太快，我听不懂。", "target_word": "说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把好消息说给了所有的朋友。", "target_word": "说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都在说今天的新闻。", "target_word": "说", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "说了", "label": "体标"}, {"form": "说过", "label": "体标"}, {"form": "说着", "label": "体标"}, {"form": "说说", "label": "重叠"}], "register": "口语", "sense_fingerprint": "开口讲话，把事情告诉别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6062633-d150-4b42-8c9e-91408b62d40d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27318, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "说", "is_correct": true, "explanation": "正确：“说”读 shuō（第一声），意思是开口讲话。"}, {"text": "桌", "is_correct": false, "explanation": "zhuō 与 shuō 声母不同（zh 与 sh），意思是桌子。"}, {"text": "硕", "is_correct": false, "explanation": "shuò（第四声）与 shuō（第一声）只是声调不同，意思是大。"}, {"text": "戳", "is_correct": false, "explanation": "chuō 与 shuō 声母不同（ch 与 sh），意思是用尖的东西刺。"}], "explanations": {"说": "正确：“说”读 shuō（第一声），意思是开口讲话。", "桌": "zhuō 与 shuō 声母不同（zh 与 sh），意思是桌子。", "硕": "shuò（第四声）与 shuō（第一声）只是声调不同，意思是大。", "戳": "chuō 与 shuō 声母不同（ch 与 sh），意思是用尖的东西刺。"}, "sentence_index": null, "correct_answer": "说"}, "level_3": {"options": [{"text": "跑", "is_correct": false, "explanation": "语义：“跑”表示快速移动，不能引出“他昨天去了动物园”这样的内容。"}, {"text": "说", "is_correct": true, "explanation": "正确：“说”表示开口讲话，与“他昨天去了动物园”相符。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”要求食物作宾语，不能引出一个小句。"}, {"text": "买", "is_correct": false, "explanation": "语义：“买”表示用钱换取物品，无法表达这句话的内容。"}], "explanations": {"跑": "语义：“跑”表示快速移动，不能引出“他昨天去了动物园”这样的内容。", "说": "正确：“说”表示开口讲话，与“他昨天去了动物园”相符。", "吃": "配价：“吃”要求食物作宾语，不能引出一个小句。", "买": "语义：“买”表示用钱换取物品，无法表达这句话的内容。"}, "sentence_index": 0, "correct_answer": "说"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他给我说了一封邮件。", "explanation": "这里应该用〈发〉。“说”是用语言讲，发邮件要用“发”。"}, {"text": "他说了灯，屋里很亮。", "explanation": "这里应该用〈开〉。“说”是用语言讲，开灯要用“开”。"}, {"text": "他在说门，声音很响。", "explanation": "这里应该用〈敲〉。“说”是用语言讲，敲门要用“敲”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d7bb3b7-e085-46e5-b1a5-a7408cc8f010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27318, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "说", "is_correct": true, "explanation": "正确：“说”读 shuō（第一声），意思是开口讲话。"}, {"text": "书", "is_correct": false, "explanation": "shū 与 shuō 韵母不同（少了 o），意思是书。"}, {"text": "捉", "is_correct": false, "explanation": "zhuō 与 shuō 声母不同（zh 与 sh），意思是抓。"}, {"text": "硕", "is_correct": false, "explanation": "shuò（第四声）与 shuō（第一声）只是声调不同，意思是大。"}], "explanations": {"说": "正确：“说”读 shuō（第一声），意思是开口讲话。", "书": "shū 与 shuō 韵母不同（少了 o），意思是书。", "捉": "zhuō 与 shuō 声母不同（zh 与 sh），意思是抓。", "硕": "shuò（第四声）与 shuō（第一声）只是声调不同，意思是大。"}, "sentence_index": null, "correct_answer": "说"}, "level_3": {"options": [{"text": "认识", "is_correct": false, "explanation": "体貌：“认识”是状态动词，不能用“……着……着”表示持续动作。"}, {"text": "说", "is_correct": true, "explanation": "正确：“说着说着”表示边说边做某事，与句意相符。"}, {"text": "拥有", "is_correct": false, "explanation": "体貌：“拥有”是状态动词，不能说“拥有着拥有着”。"}, {"text": "姓", "is_correct": false, "explanation": "配价：“姓”后要接姓氏，“姓着姓着”不能表示这个意思。"}], "explanations": {"认识": "体貌：“认识”是状态动词，不能用“……着……着”表示持续动作。", "说": "正确：“说着说着”表示边说边做某事，与句意相符。", "拥有": "体貌：“拥有”是状态动词，不能说“拥有着拥有着”。", "姓": "配价：“姓”后要接姓氏，“姓着姓着”不能表示这个意思。"}, "sentence_index": 6, "correct_answer": "说"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在说信，看得很仔细。", "explanation": "这里应该用〈读〉。“说”是用语言讲，读信要用“读”。"}, {"text": "她在说舞，动作很优美。", "explanation": "这里应该用〈跳〉。“说”是用语言讲，跳舞要用“跳”。"}, {"text": "他每天说步，身体很好。", "explanation": "这里应该用〈跑〉。“说”是用语言讲，跑步要用“跑”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d7bb3b7-e085-46e5-b1a5-a7408cc8f010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27318, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把这个消息说送了大家。", "corrected_sentence": "她把这个消息说给了大家。", "error_description": "“说”后应接“给”构成“说给”，“送”不能接在“说”后构成“说送”；应为“她把这个消息说给了大家。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d7bb3b7-e085-46e5-b1a5-a7408cc8f010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27318, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你能再说一个遍吗？", "corrected_sentence": "你能再说一遍吗？", "error_description": "“说”的动量词应为“遍”，“一个遍”是错误的组合，应说“说一遍”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d7bb3b7-e085-46e5-b1a5-a7408cc8f010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
