INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27322, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用眼睛看东西。", "primary_collocate": null, "pronunciation": "kàn", "ipa": "kʰan˥˩", "syllable_count": 1, "sentences": [{"text": "我在窗前看着外面的大雨。", "target_word": "看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他抬起头，看天上的月亮。", "target_word": "看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们站在路边，看过往的汽车。", "target_word": "看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你看一下这张照片。", "target_word": "看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她闭上眼睛，什么也不想看。", "target_word": "看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷喜欢坐在门口看来往的人。", "target_word": "看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我戴上眼镜才看清黑板上的字。", "target_word": "看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看了一眼手表，急着往外走。", "target_word": "看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，天上有一只大鸟！", "target_word": "看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫一直看着桌上的鱼。", "target_word": "看", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "看了", "label": "完成体"}, {"form": "看过", "label": "经历体"}, {"form": "看着", "label": "持续体"}, {"form": "看看", "label": "重叠"}], "register": "中性", "sense_fingerprint": "用眼睛看眼前的人或东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c06c8ddc-088c-4454-b9ef-23726f1668db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27322, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "看", "is_correct": true, "explanation": "正确答案：看 kàn，表示用眼睛看东西。"}, {"text": "砍", "is_correct": false, "explanation": "砍 kǎn（第三声）与 kàn（第四声）声调不同，意思是用刀斧砍伐。"}, {"text": "抗", "is_correct": false, "explanation": "抗 kàng 与 kàn 韵母不同（ang 与 an），意思是抵抗。"}, {"text": "刊", "is_correct": false, "explanation": "刊 kān（第一声）与 kàn（第四声）声调不同，意思是刊登、刊物。"}], "explanations": {"看": "正确答案：看 kàn，表示用眼睛看东西。", "砍": "砍 kǎn（第三声）与 kàn（第四声）声调不同，意思是用刀斧砍伐。", "抗": "抗 kàng 与 kàn 韵母不同（ang 与 an），意思是抵抗。", "刊": "刊 kān（第一声）与 kàn（第四声）声调不同，意思是刊登、刊物。"}, "sentence_index": null, "correct_answer": "看"}, "level_3": {"options": [{"text": "看", "is_correct": true, "explanation": "正确：“看”表示用眼睛观看窗外的大雨，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象不能是“大雨”，搭配不当，读起来不通。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指书写，与“在窗前”观察大雨的情境不符。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬”不能与“大雨”搭配，读起来不通。"}], "explanations": {"看": "正确：“看”表示用眼睛观看窗外的大雨，符合句意。", "吃": "搭配：“吃”的对象不能是“大雨”，搭配不当，读起来不通。", "写": "语义：“写”指书写，与“在窗前”观察大雨的情境不符。", "咬": "搭配：“咬”不能与“大雨”搭配，读起来不通。"}, "sentence_index": 0, "correct_answer": "看"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在门外看到了哭声。", "explanation": "这里应该用〈听〉。“看”用眼睛，“哭声”是声音，要用〈听〉。"}, {"text": "妈妈让我看一下汤的味道。", "explanation": "这里应该用〈尝〉。“看”用眼睛，“味道”要用舌头品尝，应说“尝一下汤的味道”。"}, {"text": "我用手看了看桌子的温度。", "explanation": "这里应该用〈感觉〉。“看”用眼睛，“温度”要靠皮肤感受，应说“用手感觉桌子的温度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffe4f77-182f-438f-8c01-903bcfaf66b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27322, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "看", "is_correct": true, "explanation": "正确答案：看 kàn，表示用眼睛看东西。"}, {"text": "坎", "is_correct": false, "explanation": "坎 kǎn（第三声）与 kàn（第四声）声调不同，意思是坑、坎坷。"}, {"text": "叹", "is_correct": false, "explanation": "叹 tàn 与 kàn 声母不同（t 与 k），意思是叹息。"}, {"text": "侃", "is_correct": false, "explanation": "侃 kǎn（第三声）与 kàn（第四声）声调不同，意思是闲谈。"}], "explanations": {"看": "正确答案：看 kàn，表示用眼睛看东西。", "坎": "坎 kǎn（第三声）与 kàn（第四声）声调不同，意思是坑、坎坷。", "叹": "叹 tàn 与 kàn 声母不同（t 与 k），意思是叹息。", "侃": "侃 kǎn（第三声）与 kàn（第四声）声调不同，意思是闲谈。"}, "sentence_index": null, "correct_answer": "看"}, "level_3": {"options": [{"text": "看", "is_correct": true, "explanation": "正确：“看”表示用眼睛看清黑板上的字，符合句意。"}, {"text": "听", "is_correct": false, "explanation": "搭配：“听”用耳朵，不能与“黑板上的字”搭配，读起来不通。"}, {"text": "摸", "is_correct": false, "explanation": "搭配：“摸”指用手触碰，不能用来看清字，读起来不通。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”表示擦拭，与“看清字”的意思不符。"}], "explanations": {"看": "正确：“看”表示用眼睛看清黑板上的字，符合句意。", "听": "搭配：“听”用耳朵，不能与“黑板上的字”搭配，读起来不通。", "摸": "搭配：“摸”指用手触碰，不能用来看清字，读起来不通。", "擦": "语义：“擦”表示擦拭，与“看清字”的意思不符。"}, "sentence_index": 6, "correct_answer": "看"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他看到了鱼的味道。", "explanation": "这里应该用〈闻〉。“看”用于视觉对象，气味要用〈闻〉。"}, {"text": "他用手看了看路面的软硬。", "explanation": "这里应该用〈摸〉。“看”用眼睛，判断软硬要用手接触，应说“用手摸一摸路面的软硬”。"}, {"text": "他看了一口牛奶。", "explanation": "这里应该用〈喝〉。“看”用眼睛，“一口牛奶”要用嘴喝，应说“喝了一口牛奶”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffe4f77-182f-438f-8c01-903bcfaf66b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27322, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他抬起头，了看窗外的月亮。", "corrected_sentence": "他抬起头，看了看窗外的月亮。", "error_description": "错误在于“了”的位置。“了”应放在动词“看”之后，不能放在“看”之前写成“了看”；正确说法是“看了看窗外的月亮”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffe4f77-182f-438f-8c01-903bcfaf66b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27322, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他抬起头，看了一下了远处的山。", "corrected_sentence": "他抬起头，看了一下远处的山。", "error_description": "错误在于多出一个“了”：“看了一下”已用“了”，句中“一下了远处”的第二个“了”应删去，写作“看了一下远处的山”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffe4f77-182f-438f-8c01-903bcfaf66b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
