INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27328, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把坏掉的东西弄好，让它又能用了。", "primary_collocate": null, "pronunciation": "xiū hǎo", "ipa": "ɕi̯ou˥ xau̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "小王把坏了的收音机修好了。", "target_word": "修好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台洗衣机是我自己修好的。", "target_word": "修好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯坏了，爸爸今晚会修好它。", "target_word": "修好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的手表昨天修好了，现在走得很准。", "target_word": "修好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想了很久，终于把电风扇修好了。", "target_word": "修好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能帮我把这个玩具修好吗？", "target_word": "修好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门铃修好以后，客人一按就响了。", "target_word": "修好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他修好了摔坏的相机，又开始拍照了。", "target_word": "修好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱修好了，牛奶不会坏了。", "target_word": "修好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这台机器很快就能修好。", "target_word": "修好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "修好了", "label": "体标"}, {"form": "修好过", "label": "体标"}, {"form": "修不好", "label": "否定可能补语"}, {"form": "修得好", "label": "可能补语"}], "register": "中性", "sense_fingerprint": "把坏了的东西弄好，使它重新能用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a50759fb-3f82-4d2e-b11e-78657eb50899') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27328, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "修好", "is_correct": true, "explanation": "修好与“坏了的收音机”搭配，表示把坏了的东西修理好了，句意通顺。"}, {"text": "唱完", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能和收音机搭配。"}, {"text": "咬碎", "is_correct": false, "explanation": "语义：收音机不能咬碎，句中是要让坏了的东西恢复使用，动作与此相反。"}, {"text": "煮烂", "is_correct": false, "explanation": "搭配：“煮烂”只用于食物，收音机不能煮烂。"}], "explanations": {"修好": "修好与“坏了的收音机”搭配，表示把坏了的东西修理好了，句意通顺。", "唱完": "搭配：“唱”的对象是歌曲，不能和收音机搭配。", "咬碎": "语义：收音机不能咬碎，句中是要让坏了的东西恢复使用，动作与此相反。", "煮烂": "搭配：“煮烂”只用于食物，收音机不能煮烂。"}, "sentence_index": 0, "correct_answer": "修好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把这锅汤修好了，大家快来喝。", "explanation": "这里应该用〈熬好〉。汤是熬出来的，修好只用于修理坏了的东西。"}, {"text": "他把蛋糕修好了，明天请大家吃。", "explanation": "这里应该用〈做好〉。蛋糕是做出来的，修好只用于修理坏了的东西。"}, {"text": "这些饼干已经修好了，放在盒子里。", "explanation": "这里应该用〈烤好〉。饼干是烤出来的，修好只用于修理坏了的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '459c1e00-80a1-48bf-a6a9-1b8f4c6573bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27328, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "修好", "is_correct": true, "explanation": "修好说明门铃已经修理完成，与“客人一按就响了”的语境相符。"}, {"text": "拆掉", "is_correct": false, "explanation": "语义：门铃拆掉以后就不能再响，与“客人一按就响了”相矛盾。"}, {"text": "吹干", "is_correct": false, "explanation": "搭配：“吹干”多用于头发、衣物等，不能用于门铃。"}, {"text": "砸碎", "is_correct": false, "explanation": "语义：门铃砸碎后无法发出声音，与“一按就响了”相冲突。"}], "explanations": {"修好": "修好说明门铃已经修理完成，与“客人一按就响了”的语境相符。", "拆掉": "语义：门铃拆掉以后就不能再响，与“客人一按就响了”相矛盾。", "吹干": "搭配：“吹干”多用于头发、衣物等，不能用于门铃。", "砸碎": "语义：门铃砸碎后无法发出声音，与“一按就响了”相冲突。"}, "sentence_index": 6, "correct_answer": "修好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生很快就把他的病修好了。", "explanation": "这里应该用〈治好〉。病痛要用治好，修好只用于修理器物。"}, {"text": "妈妈把饭修好了，我们快来吃。", "explanation": "这里应该用〈煮好〉。饭是煮出来的，修好不能用于做饭。"}, {"text": "我们把明天的聚会修好了，大家都来参加。", "explanation": "这里应该用〈安排好〉。聚会是安排、筹备出来的，修好只用于修理坏了的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '459c1e00-80a1-48bf-a6a9-1b8f4c6573bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27328, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师终于把这台旧电视了修好了。", "corrected_sentence": "老师终于把这台旧电视修好了。", "error_description": "错误：“了”插在“把”字宾语与动词“修”之间，动词前不能用“了”；应删去，正确为“修好了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '459c1e00-80a1-48bf-a6a9-1b8f4c6573bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27328, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我请师傅把空调了修好了。", "corrected_sentence": "我请师傅把空调修好了。", "error_description": "错误：“了”插在“把”字宾语“空调”与动词“修”之间，动词前不能用“了”；应删去，正确为“修好了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '459c1e00-80a1-48bf-a6a9-1b8f4c6573bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
