INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27334, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示事情发生得早或快。", "primary_collocate": null, "pronunciation": "cái", "ipa": "tsʰaɪ̯˧˥", "syllable_count": 1, "sentences": [{"text": "现在才六点，天就已经亮了。", "target_word": "才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他才三岁，就会自己穿衣服了。", "target_word": "才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我才睡了一会儿，闹钟就响了。", "target_word": "才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道菜才十分钟就做好了。", "target_word": "才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她才看了一遍，就记住了这首诗。", "target_word": "才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "才下午三点，商店里已经没有人了。", "target_word": "才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他才学了两天，就说得很好了。", "target_word": "才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议才开始五分钟，大家就走了一半。", "target_word": "才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他才十岁，就上大学了。", "target_word": "才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子才八点就睡着了。", "target_word": "才", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "才+时间或数量，表示早或快", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c06c8ddc-088c-4454-b9ef-23726f1668db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27334, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "才", "is_correct": true, "explanation": "正确答案：才 cái，表示事情发生得早或快。"}, {"text": "菜", "is_correct": false, "explanation": "菜 cài（第四声）与 cái（第二声）声调不同，意思是菜肴。"}, {"text": "彩", "is_correct": false, "explanation": "彩 cǎi（第三声）与 cái（第二声）声调不同，意思是颜色、彩色。"}, {"text": "猜", "is_correct": false, "explanation": "猜 cāi（第一声）与 cái（第二声）声调不同，意思是猜测。"}, {"text": "来", "is_correct": false, "explanation": "来 lái 与 cái 声母不同（l 与 c），意思是来到。"}], "explanations": {"才": "正确答案：才 cái，表示事情发生得早或快。", "菜": "菜 cài（第四声）与 cái（第二声）声调不同，意思是菜肴。", "彩": "彩 cǎi（第三声）与 cái（第二声）声调不同，意思是颜色、彩色。", "猜": "猜 cāi（第一声）与 cái（第二声）声调不同，意思是猜测。", "来": "来 lái 与 cái 声母不同（l 与 c），意思是来到。"}, "sentence_index": null, "correct_answer": "才"}, "level_3": {"options": [{"text": "才", "is_correct": true, "explanation": "正确：“才”表示时间早，六点就算早，符合句意。"}, {"text": "却", "is_correct": false, "explanation": "语义：“却”表示转折，句中没有前后对立的意思，读起来不通。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示即将发生，与“天就已经亮了”的已发生情况相矛盾。"}, {"text": "忽然", "is_correct": false, "explanation": "搭配：“忽然”表示突然发生，不能修饰“六点”这样的时间点。"}], "explanations": {"才": "正确：“才”表示时间早，六点就算早，符合句意。", "却": "语义：“却”表示转折，句中没有前后对立的意思，读起来不通。", "马上": "语义：“马上”表示即将发生，与“天就已经亮了”的已发生情况相矛盾。", "忽然": "搭配：“忽然”表示突然发生，不能修饰“六点”这样的时间点。"}, "sentence_index": 0, "correct_answer": "才"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜做了一个小时，才端上桌。", "explanation": "这里的“才”表示事情发生得晚（耗时长），与“早或快”的意思相反。"}, {"text": "雨停了以后，我们才出门。", "explanation": "这里的“才”表示等条件满足后事情才发生（偏晚），与“早或快”的意思相反。"}, {"text": "我才不吃这种东西，你别再劝我了。", "explanation": "这里的“才不”是强调否定的语气，表示坚决拒绝，不表示事情发生得早或快。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffe4f77-182f-438f-8c01-903bcfaf66b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27334, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "才", "is_correct": true, "explanation": "正确答案：才 cái，表示事情发生得早或快。"}, {"text": "采", "is_correct": false, "explanation": "采 cǎi（第三声）与 cái（第二声）声调不同，意思是采摘。"}, {"text": "踩", "is_correct": false, "explanation": "踩 cǎi（第三声）与 cái（第二声）声调不同，意思是脚下用力按压。"}, {"text": "柴", "is_correct": false, "explanation": "柴 chái 与 cái 声母不同（ch 与 c），意思是柴火。"}], "explanations": {"才": "正确答案：才 cái，表示事情发生得早或快。", "采": "采 cǎi（第三声）与 cái（第二声）声调不同，意思是采摘。", "踩": "踩 cǎi（第三声）与 cái（第二声）声调不同，意思是脚下用力按压。", "柴": "柴 chái 与 cái 声母不同（ch 与 c），意思是柴火。"}, "sentence_index": null, "correct_answer": "才"}, "level_3": {"options": [{"text": "才", "is_correct": true, "explanation": "正确：“才”表示时间短、进展快，两天就学得好，符合句意。"}, {"text": "正", "is_correct": false, "explanation": "体貌：“正”表示动作正在进行，与“学了两天”的完成体矛盾。"}, {"text": "突然", "is_correct": false, "explanation": "搭配：“突然”表示突发，不能与“学了两天”这样的持续时段搭配。"}, {"text": "立刻", "is_correct": false, "explanation": "搭配：“立刻”表示马上行动，不能与持续两天的“学了两天”搭配。"}], "explanations": {"才": "正确：“才”表示时间短、进展快，两天就学得好，符合句意。", "正": "体貌：“正”表示动作正在进行，与“学了两天”的完成体矛盾。", "突然": "搭配：“突然”表示突发，不能与“学了两天”这样的持续时段搭配。", "立刻": "搭配：“立刻”表示马上行动，不能与持续两天的“学了两天”搭配。"}, "sentence_index": 6, "correct_answer": "才"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我等了三个小时，他才到。", "explanation": "这里的“才”表示事情发生得晚，与“早或快”的意思相反。"}, {"text": "我才不信他的话，你别再说了。", "explanation": "这里的“才不”是强调否定的语气，表示坚决不信，不表示事情发生得早或快。"}, {"text": "他想了很久，才想明白这道题。", "explanation": "这里的“才”表示事情发生得晚（耗时长），与“早或快”的意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffe4f77-182f-438f-8c01-903bcfaf66b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27334, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她练才了一个月，钢琴就弹得很好了。", "corrected_sentence": "她才练了一个月，钢琴就弹得很好了。", "error_description": "错误在于“才”的位置。“才”插在动词“练”和动态助词“了”之间，不通。“才”应放在动词前面，写作“她才练了一个月”，表示时间短、进展快。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffe4f77-182f-438f-8c01-903bcfaf66b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27334, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这碗面才煮五分钟就才好了。", "corrected_sentence": "这碗面才煮五分钟就好了。", "error_description": "错误在于“才”多用了一次。“才煮五分钟”已用“才”表示快，“就好了”用“就”表示快，句末的“才”与“就”叠用，不通。正确说法是“这碗面才煮五分钟就好了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffe4f77-182f-438f-8c01-903bcfaf66b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27336, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "隐瞒", "is_correct": true, "explanation": "隐瞒：有意不让别人知道，与“报告”（把知道的情况告诉别人）相反。"}, {"text": "散步", "is_correct": false, "explanation": "散步与“报告”没有反义关系，是一种日常活动。"}, {"text": "修理", "is_correct": false, "explanation": "修理与“报告”没有反义关系，指使坏的东西恢复正常。"}, {"text": "观察", "is_correct": false, "explanation": "观察与“报告”没有反义关系，指仔细看或研究。"}], "correct_answer": "隐瞒", "explanations": {"隐瞒": "隐瞒：有意不让别人知道，与“报告”（把知道的情况告诉别人）相反。", "散步": "散步与“报告”没有反义关系，是一种日常活动。", "修理": "修理与“报告”没有反义关系，指使坏的东西恢复正常。", "观察": "观察与“报告”没有反义关系，指仔细看或研究。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e9f44bb-1b42-4c1e-8695-cf84254f4d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27336, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "隐瞒", "is_correct": true, "explanation": "隐瞒：有意不让别人知道，与“报告”（把知道的情况告诉别人）相反。"}, {"text": "跳舞", "is_correct": false, "explanation": "跳舞与“报告”没有反义关系，指随音乐做动作。"}, {"text": "睡觉", "is_correct": false, "explanation": "睡觉与“报告”没有反义关系，指休息时闭眼入睡。"}, {"text": "画画", "is_correct": false, "explanation": "画画与“报告”没有反义关系，指用笔或颜料作画。"}], "correct_answer": "隐瞒", "explanations": {"隐瞒": "隐瞒：有意不让别人知道，与“报告”（把知道的情况告诉别人）相反。", "跳舞": "跳舞与“报告”没有反义关系，指随音乐做动作。", "睡觉": "睡觉与“报告”没有反义关系，指休息时闭眼入睡。", "画画": "画画与“报告”没有反义关系，指用笔或颜料作画。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e9f44bb-1b42-4c1e-8695-cf84254f4d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27336, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "告诉别人你知道的事情。", "primary_collocate": null, "pronunciation": "bào gào", "ipa": "paʊ˥˩ kaʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他把昨天的事报告给了老师。", "target_word": "报告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有问题要马上向经理报告。", "target_word": "报告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我已经向警察报告了这件事。", "target_word": "报告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明跑去向妈妈报告好消息。", "target_word": "报告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他发现火情，立刻向消防队报告。", "target_word": "报告", "complexity_tier": "T3", "furigana": "tā fāxiàn huǒqíng, lìkè xiàng xiāofángduì bàogào.", "sentence_source": "generated"}, {"text": "他每天都向老板报告工作进度。", "target_word": "报告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子回家后，把学校的事都报告给爸爸。", "target_word": "报告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人生病，要及时报告老师。", "target_word": "报告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我向他报告过自己的计划。", "target_word": "报告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到有人打架，请马上向老师报告。", "target_word": "报告", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "报告了", "label": "体标"}, {"form": "报告过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把知道的情况告诉别人，多是对老师、领导等说", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8eeb9b7-da00-4ad1-a443-5d1569c7e006') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27336, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "报告", "is_correct": true, "explanation": "正确：“报告”表示把知道的情况告诉老师，与“给了老师”搭配。"}, {"text": "报销", "is_correct": false, "explanation": "搭配：“报销”搭配的是费用、账目，不搭配“事”。"}, {"text": "打包", "is_correct": false, "explanation": "语义：事情不能被打包，打包的对象是物品。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：事情不能被吃掉，句中要表达的是告诉老师。"}], "explanations": {"报告": "正确：“报告”表示把知道的情况告诉老师，与“给了老师”搭配。", "报销": "搭配：“报销”搭配的是费用、账目，不搭配“事”。", "打包": "语义：事情不能被打包，打包的对象是物品。", "吃掉": "语义：事情不能被吃掉，句中要表达的是告诉老师。"}, "sentence_index": 0, "correct_answer": "报告"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每晚给孩子报告一个故事。", "explanation": "这里应该用〈讲述〉。报告用于向上级或有关方面陈述事实、情况；给孩子讲故事要用讲述。"}, {"text": "她偷偷报告我一个秘密。", "explanation": "这里应该用〈告诉〉。报告多指向领导或有关部门陈述情况，对朋友说秘密用告诉。"}, {"text": "学校报告家长一个笑话。", "explanation": "这里应该用〈讲〉。报告用于陈述事实或情况，讲笑话要用讲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e9f44bb-1b42-4c1e-8695-cf84254f4d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27336, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "报告", "is_correct": true, "explanation": "正确：把学校的事告诉爸爸，用“报告”最自然，与“把……给爸爸”搭配。"}, {"text": "缝补", "is_correct": false, "explanation": "语义：“缝补”指用针线修补衣物，学校的事不能被缝补。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”的对象是食物，学校的事不能被烤。"}, {"text": "洗掉", "is_correct": false, "explanation": "语义：“洗掉”指去掉污垢，事情不能被洗掉。"}], "explanations": {"报告": "正确：把学校的事告诉爸爸，用“报告”最自然，与“把……给爸爸”搭配。", "缝补": "语义：“缝补”指用针线修补衣物，学校的事不能被缝补。", "烤": "语义：“烤”的对象是食物，学校的事不能被烤。", "洗掉": "语义：“洗掉”指去掉污垢，事情不能被洗掉。"}, "sentence_index": 6, "correct_answer": "报告"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她向妈妈报告一首歌。", "explanation": "这里应该用〈唱〉。报告用于陈述事实或情况，不能用来指唱歌；唱歌要用唱。"}, {"text": "他向学校报告奖学金。", "explanation": "这里应该用〈申请〉。报告是陈述情况，不是请求批准或资助，要求奖学金应说申请。"}, {"text": "他鼓起勇气向她报告心意。", "explanation": "这里应该用〈告白〉。报告用于把事实告诉上级或有关方面，表白心意不用报告。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e9f44bb-1b42-4c1e-8695-cf84254f4d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27336, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事他已经报告了给校长。", "corrected_sentence": "这件事他已经报告给了校长。", "error_description": "“给”与“了”的位置有误。“报告给了”中，“了”要放在“给”之后，应说“报告给了校长”，不能说“报告了给校长”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e9f44bb-1b42-4c1e-8695-cf84254f4d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27336, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他已经向经理报告了过这件事。", "corrected_sentence": "他已经向经理报告过这件事。", "error_description": "错误：“报告了过”，正确：“报告过”。“了”和“过”不能同时跟在“报告”后面，表示有过这个经历时只用“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e9f44bb-1b42-4c1e-8695-cf84254f4d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
