INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27338, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "用在谁、什么、一点等词之后，或用于让步句中，表示强调（连……也）或让步（再……也）。", "primary_collocate": null, "pronunciation": "yě", "ipa": "jɛ˨˩", "syllable_count": 1, "sentences": [{"text": "这件事谁也不知道。", "target_word": "也", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我什么也不想吃。", "target_word": "也", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一点也不累。", "target_word": "也", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天再冷，我也要去跑步。", "target_word": "也", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "就是下雨，我们也要去。", "target_word": "也", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不说，我也知道。", "target_word": "也", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一次也没来过。", "target_word": "也", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路再远，他也走路去学校。", "target_word": "也", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我一个人也不认识。", "target_word": "也", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书再贵，我也想买。", "target_word": "也", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "也好", "label": "复合"}], "register": "中性", "sense_fingerprint": "也：用在谁、什么、一点等词后或让步句中，加强语气", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f82c8ae-82ab-4595-b449-235c22ee33c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27338, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "也", "is_correct": true, "explanation": "“也”与“谁”连用，加强语气，表示“没有一个人知道”，句子通顺。"}, {"text": "正在", "is_correct": false, "explanation": "语义：“正在”表示动作进行，不能修饰“谁……不知道”这样的全称否定。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”是程度副词，不能放在“谁”之后修饰否定结构。"}, {"text": "太", "is_correct": false, "explanation": "搭配：“太”表示程度过分，“谁太不知道”不成立。"}], "explanations": {"也": "“也”与“谁”连用，加强语气，表示“没有一个人知道”，句子通顺。", "正在": "语义：“正在”表示动作进行，不能修饰“谁……不知道”这样的全称否定。", "非常": "搭配：“非常”是程度副词，不能放在“谁”之后修饰否定结构。", "太": "搭配：“太”表示程度过分，“谁太不知道”不成立。"}, "sentence_index": 0, "correct_answer": "也"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一点也很累。", "explanation": "这里应该用〈非常〉。“一点也”加强否定，后面必须接否定词；肯定句要说“非常累”。"}, {"text": "我什么也想吃。", "explanation": "这里应该用〈都〉。“什么也”一般用于否定句，肯定句要说“什么都想吃”。"}, {"text": "他一个字也认识。", "explanation": "这里应该用〈都〉。“一个字……也”的结构要求后接否定词，肯定句中应用“都”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '509b35c6-840c-42b7-b052-f857cb5ec106') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27338, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "也", "is_correct": true, "explanation": "“也”与“一次”连用，表示“一次都没有”，强调否定，句子通顺。"}, {"text": "很", "is_correct": false, "explanation": "搭配：“很”不能修饰“一次”这样的数量结构。"}, {"text": "最", "is_correct": false, "explanation": "语义：“最”表示程度最高，与“一次也没来过”的否定意思不符。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”表示时间上刚发生，与“来过”的整体经历不相符。"}], "explanations": {"也": "“也”与“一次”连用，表示“一次都没有”，强调否定，句子通顺。", "很": "搭配：“很”不能修饰“一次”这样的数量结构。", "最": "语义：“最”表示程度最高，与“一次也没来过”的否定意思不符。", "刚刚": "语义：“刚刚”表示时间上刚发生，与“来过”的整体经历不相符。"}, "sentence_index": 6, "correct_answer": "也"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "谁也知道这件事。", "explanation": "这里应该用〈都〉。“谁也”多用于否定句，肯定句要说“谁都知道”。"}, {"text": "我一点也喜欢这本书。", "explanation": "这里应该用〈很〉。“一点也”后面必须接否定词，肯定句要说“很喜欢”。"}, {"text": "这件事我什么也知道。", "explanation": "这里应该用〈都〉。“什么也”一般用于否定句，肯定句要说“什么都知道”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '509b35c6-840c-42b7-b052-f857cb5ec106') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27338, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他什么没也说。", "corrected_sentence": "他什么也没说。", "error_description": "错误：“没也说”；正确：“也没说”。“也”要放在否定词“没”之前，表示“连……也”的强调。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '509b35c6-840c-42b7-b052-f857cb5ec106') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27338, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本书再难，我能也看懂。", "corrected_sentence": "这本书再难，我也能看懂。", "error_description": "错误：“能也看懂”；正确：“也能看懂”。“也”应放在助动词“能”之前，不能插在助动词与动词之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '509b35c6-840c-42b7-b052-f857cb5ec106') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
