INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27340, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "表示肯定，意思是“对的”。", "primary_collocate": null, "pronunciation": "shì", "ipa": "ʂʐ̩˥˩", "syllable_count": 1, "sentences": [{"text": "“你叫王明吗？”“是，我叫王明。”", "target_word": "是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他问我：“你是学生吗？”我说：“是，我是学生。”", "target_word": "是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问：“作业写完了吗？”小林答：“是，写完了。”", "target_word": "是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理说：“明天八点开会。”小张说：“是，我记住了。”", "target_word": "是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“你是新来的同学吧？”“是，我今天刚到。”", "target_word": "是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈问：“这是你的手机吗？”我答：“是，是我的。”", "target_word": "是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他点点头说：“是，你说得对。”", "target_word": "是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“这是你的书包吗？”“是，是我的。”", "target_word": "是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说：“请把门关上。”小王答：“是，马上关。”", "target_word": "是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“你也喜欢音乐吧？”“是，我天天听。”", "target_word": "是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "回答时表示肯定、同意，意思是对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6062633-d150-4b42-8c9e-91408b62d40d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27340, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "是", "is_correct": true, "explanation": "是：表示肯定、同意，意思是“对”，即本词条的目标词。"}, {"text": "寺", "is_correct": false, "explanation": "sì 与 shì 声母不同（s / sh），声调相同，意思是“寺庙”。"}, {"text": "失", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，意思是“丢失”。"}, {"text": "施", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，意思是“施行、给予”。"}, {"text": "石", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是“石头”。"}], "explanations": {"是": "是：表示肯定、同意，意思是“对”，即本词条的目标词。", "寺": "sì 与 shì 声母不同（s / sh），声调相同，意思是“寺庙”。", "失": "shī（第一声）与 shì（第四声）声调不同，意思是“丢失”。", "施": "shī（第一声）与 shì（第四声）声调不同，意思是“施行、给予”。", "石": "shí（第二声）与 shì（第四声）声调不同，意思是“石头”。"}, "sentence_index": null, "correct_answer": "是"}, "level_3": {"options": [{"text": "是", "is_correct": true, "explanation": "是：表示肯定，用于回答“你叫王明吗？”，符合语境。"}, {"text": "哇", "is_correct": false, "explanation": "语义：“哇”表示惊叹或哭声，不表示应答，与“我叫王明”的确认语境不合。"}, {"text": "哈", "is_correct": false, "explanation": "语义：“哈”表示笑声或轻笑，不能用来确认自己的名字。"}, {"text": "呸", "is_correct": false, "explanation": "语域：“呸”是表示鄙视的口语叹词，用在这里语气不对，也不表示应答。"}], "explanations": {"是": "是：表示肯定，用于回答“你叫王明吗？”，符合语境。", "哇": "语义：“哇”表示惊叹或哭声，不表示应答，与“我叫王明”的确认语境不合。", "哈": "语义：“哈”表示笑声或轻笑，不能用来确认自己的名字。", "呸": "语域：“呸”是表示鄙视的口语叹词，用在这里语气不对，也不表示应答。"}, "sentence_index": 0, "correct_answer": "是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "“你要茶还是咖啡？”“是，我要茶。”", "explanation": "“是”只用来回答是非问句，不能回答选择问句；这里应直接说“我要茶”。"}, {"text": "“谢谢你的帮助！”“是，不客气。”", "explanation": "对感谢一般直接说“不客气”，不用“是”来回应，用在这里语气不对。"}, {"text": "“谁能帮我搬一下箱子？”“是，我来吧。”", "explanation": "这里应直接说“我来吧”。“是”只用来回答是非问句，不能回答“谁”这类特殊疑问句。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d7bb3b7-e085-46e5-b1a5-a7408cc8f010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27340, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "是", "is_correct": true, "explanation": "是：表示肯定、同意，意思是“对”，即本词条的目标词。"}, {"text": "似", "is_correct": false, "explanation": "sì 与 shì 声母不同（s / sh），声调相同，意思是“像”。"}, {"text": "狮", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，意思是“狮子”。"}, {"text": "十", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是数字“十”。"}, {"text": "史", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）声调不同，意思是“历史”。"}], "explanations": {"是": "是：表示肯定、同意，意思是“对”，即本词条的目标词。", "似": "sì 与 shì 声母不同（s / sh），声调相同，意思是“像”。", "狮": "shī（第一声）与 shì（第四声）声调不同，意思是“狮子”。", "十": "shí（第二声）与 shì（第四声）声调不同，意思是数字“十”。", "史": "shǐ（第三声）与 shì（第四声）声调不同，意思是“历史”。"}, "sentence_index": null, "correct_answer": "是"}, "level_3": {"options": [{"text": "是", "is_correct": true, "explanation": "是：表示肯定，用于回应对方的意见，符合“你说得对”的语境。"}, {"text": "哼", "is_correct": false, "explanation": "语义：“哼”表示不满或轻蔑，与“点点头”的赞同动作相矛盾。"}, {"text": "咦", "is_correct": false, "explanation": "语义：“咦”表示惊讶或疑问，不表示同意。"}, {"text": "嘁", "is_correct": false, "explanation": "语域：“嘁”是轻蔑的口语叹词，与“点点头说”的认真应答语气不符。"}], "explanations": {"是": "是：表示肯定，用于回应对方的意见，符合“你说得对”的语境。", "哼": "语义：“哼”表示不满或轻蔑，与“点点头”的赞同动作相矛盾。", "咦": "语义：“咦”表示惊讶或疑问，不表示同意。", "嘁": "语域：“嘁”是轻蔑的口语叹词，与“点点头说”的认真应答语气不符。"}, "sentence_index": 6, "correct_answer": "是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "“你叫什么名字？”“是，我叫王明。”", "explanation": "“是”只用来回答是非问句，不能回答“什么”这类特殊疑问句，这里应直接说“我叫王明”。"}, {"text": "“你好！”“是，你也好。”", "explanation": "问候时一般回应“你好”，不用“是”来回应，用在这里不合习惯。"}, {"text": "“天气怎么样？”“是，很好。”", "explanation": "这里应该直接说“很好”。“是”表示肯定，不用来回答“怎么样”这类询问状况的问题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d7bb3b7-e085-46e5-b1a5-a7408cc8f010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27340, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "“你是老板吗？”“不是，我是老板。”", "corrected_sentence": "“你是老板吗？”“是，我是老板。”", "error_description": "“不是”表示否定，与后面的“我是老板”矛盾；对肯定问句的肯定回答应说“是”，不说“不是”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d7bb3b7-e085-46e5-b1a5-a7408cc8f010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27340, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "“这本书是你的吗？”“是不是，我天天看。”", "corrected_sentence": "“这本书是你的吗？”“是，我天天看。”", "error_description": "“是不是”是正反问结构，不能用来回答；对是非问句作肯定回答直接说“是”，应说“是，我天天看。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d7bb3b7-e085-46e5-b1a5-a7408cc8f010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27344, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "没有", "is_correct": true, "explanation": "没有：与“有”（拥有）构成反义关系，表示不拥有。"}, {"text": "跑", "is_correct": false, "explanation": "跑：动词，表示奔跑，与“有”（拥有）没有反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "唱：动词，表示歌唱，与“有”（拥有）没有反义关系。"}, {"text": "写", "is_correct": false, "explanation": "写：动词，表示书写，与“有”（拥有）没有反义关系。"}], "correct_answer": "没有", "explanations": {"没有": "没有：与“有”（拥有）构成反义关系，表示不拥有。", "跑": "跑：动词，表示奔跑，与“有”（拥有）没有反义关系。", "唱": "唱：动词，表示歌唱，与“有”（拥有）没有反义关系。", "写": "写：动词，表示书写，与“有”（拥有）没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27344, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "没有", "is_correct": true, "explanation": "没有：与“有”（拥有）构成反义关系，表示不拥有。"}, {"text": "吃", "is_correct": false, "explanation": "吃：动词，表示进食，与“有”（拥有）没有反义关系。"}, {"text": "走", "is_correct": false, "explanation": "走：动词，表示行走，与“有”（拥有）没有反义关系。"}, {"text": "看", "is_correct": false, "explanation": "看：动词，表示观看，与“有”（拥有）没有反义关系。"}], "correct_answer": "没有", "explanations": {"没有": "没有：与“有”（拥有）构成反义关系，表示不拥有。", "吃": "吃：动词，表示进食，与“有”（拥有）没有反义关系。", "走": "走：动词，表示行走，与“有”（拥有）没有反义关系。", "看": "看：动词，表示观看，与“有”（拥有）没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27344, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "表示拥有，比如“我有一本书”。", "primary_collocate": null, "pronunciation": "yǒu", "ipa": "jou̯˨˩˦", "syllable_count": 1, "sentences": [{"text": "我有一本新书，是朋友送的。", "target_word": "有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他有两个哥哥和一个妹妹。", "target_word": "有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家有一只小狗，它叫豆豆。", "target_word": "有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她有一辆车，每天开车上班。", "target_word": "有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师有很多书，家里像书店。", "target_word": "有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟有一个新手机，是生日礼物。", "target_word": "有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们学校有一个大操场。", "target_word": "有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "姐姐有一双白鞋，天天穿。", "target_word": "有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小明性格开朗，他有很多好朋友。", "target_word": "有", "complexity_tier": "T3", "furigana": "xiǎo míng xìng gé kāi lǎng, tā yǒu hěn duō hǎo péng you.", "sentence_source": "generated"}, {"text": "爷爷在北京有一套房子。", "target_word": "有", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "没有", "label": "否定式"}, {"form": "有过", "label": "体标"}], "register": "中性", "sense_fingerprint": "动词，表示拥有某物或某人，如有书、有哥哥", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06ef7b24-878b-4d84-b099-4f00efa873d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27344, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "有", "is_correct": true, "explanation": "有（yǒu）：表示拥有，即本题的正确答案。"}, {"text": "又", "is_correct": false, "explanation": "又（yòu，第四声）与有（yǒu，第三声）声调不同，意思是“再，又一次”。"}, {"text": "右", "is_correct": false, "explanation": "右（yòu，第四声）与有（yǒu，第三声）声调不同，意思是“右边”。"}, {"text": "优", "is_correct": false, "explanation": "优（yōu，第一声）与有（yǒu，第三声）声调不同，意思是“优秀”。"}, {"text": "油", "is_correct": false, "explanation": "油（yóu，第二声）与有（yǒu，第三声）声调不同，意思是“油脂”。"}, {"text": "游", "is_correct": false, "explanation": "游（yóu，第二声）与有（yǒu，第三声）声调不同，意思是“游泳”。"}], "explanations": {"有": "有（yǒu）：表示拥有，即本题的正确答案。", "又": "又（yòu，第四声）与有（yǒu，第三声）声调不同，意思是“再，又一次”。", "右": "右（yòu，第四声）与有（yǒu，第三声）声调不同，意思是“右边”。", "优": "优（yōu，第一声）与有（yǒu，第三声）声调不同，意思是“优秀”。", "油": "油（yóu，第二声）与有（yǒu，第三声）声调不同，意思是“油脂”。", "游": "游（yóu，第二声）与有（yǒu，第三声）声调不同，意思是“游泳”。"}, "sentence_index": null, "correct_answer": "有"}, "level_3": {"options": [{"text": "有", "is_correct": true, "explanation": "有：表示拥有，与“一本新书”搭配，符合“是朋友送的”的语境。"}, {"text": "买", "is_correct": false, "explanation": "语义：“买”表示花钱购入，与“是朋友送的”矛盾。"}, {"text": "借", "is_correct": false, "explanation": "语义：“借”表示暂时使用别人的东西，与“是朋友送的”矛盾。"}, {"text": "购", "is_correct": false, "explanation": "语域：“购”偏书面，用于口语叙述不自然；且“购”指购买，与“是朋友送的”矛盾。"}], "explanations": {"有": "有：表示拥有，与“一本新书”搭配，符合“是朋友送的”的语境。", "买": "语义：“买”表示花钱购入，与“是朋友送的”矛盾。", "借": "语义：“借”表示暂时使用别人的东西，与“是朋友送的”矛盾。", "购": "语域：“购”偏书面，用于口语叙述不自然；且“购”指购买，与“是朋友送的”矛盾。"}, "sentence_index": 0, "correct_answer": "有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "北京有中国的首都。", "explanation": "这里应该用〈是〉。“有”表示领有，不能用来说明首都、身份这类归属关系；应说“北京是中国的首都”。"}, {"text": "我家有北京。", "explanation": "这里应该用〈在〉。“在”表示人或物所处的位置，“有”表示领有，不能说家在某个地方。"}, {"text": "他有在学校门口等你。", "explanation": "这里应该用〈正〉。“有”表示领有，不能表示动作正在进行；应说“他正在学校门口等你”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27344, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "有", "is_correct": true, "explanation": "有（yǒu）：表示拥有，即本题的正确答案。"}, {"text": "幼", "is_correct": false, "explanation": "幼（yòu，第四声）与有（yǒu，第三声）声调不同，意思是“年幼”。"}, {"text": "邮", "is_correct": false, "explanation": "邮（yóu，第二声）与有（yǒu，第三声）声调不同，意思是“邮寄”。"}, {"text": "诱", "is_correct": false, "explanation": "诱（yòu，第四声）与有（yǒu，第三声）声调不同，意思是“引诱”。"}, {"text": "忧", "is_correct": false, "explanation": "忧（yōu，第一声）与有（yǒu，第三声）声调不同，意思是“忧愁”。"}], "explanations": {"有": "有（yǒu）：表示拥有，即本题的正确答案。", "幼": "幼（yòu，第四声）与有（yǒu，第三声）声调不同，意思是“年幼”。", "邮": "邮（yóu，第二声）与有（yǒu，第三声）声调不同，意思是“邮寄”。", "诱": "诱（yòu，第四声）与有（yǒu，第三声）声调不同，意思是“引诱”。", "忧": "忧（yōu，第一声）与有（yǒu，第三声）声调不同，意思是“忧愁”。"}, "sentence_index": null, "correct_answer": "有"}, "level_3": {"options": [{"text": "有", "is_correct": true, "explanation": "有：表示拥有，与“操场”搭配，符合“学校有一个大操场”的陈述。"}, {"text": "是", "is_correct": false, "explanation": "语义：“是”表示判断，“我们学校是一个大操场”语义不通。"}, {"text": "在", "is_correct": false, "explanation": "配价：“在”作动词时需要带处所宾语，“在一个大操场”语义不完整。"}, {"text": "送", "is_correct": false, "explanation": "语义：“送”表示赠予他人，与“我们学校”拥有操场的语境相反。"}], "explanations": {"有": "有：表示拥有，与“操场”搭配，符合“学校有一个大操场”的陈述。", "是": "语义：“是”表示判断，“我们学校是一个大操场”语义不通。", "在": "配价：“在”作动词时需要带处所宾语，“在一个大操场”语义不完整。", "送": "语义：“送”表示赠予他人，与“我们学校”拥有操场的语境相反。"}, "sentence_index": 6, "correct_answer": "有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我有你一本书。", "explanation": "这里应该用〈给〉。“有”表示领有，不能表示把东西交给别人；“给”表示交付。"}, {"text": "他有了三年班长。", "explanation": "这里应该用〈当〉。“当”表示担任职务，“有”不能用来说担任班长的经历。"}, {"text": "这只猫有咪咪。", "explanation": "这里应该用〈叫〉。“叫”用于说明名字，“有”不能用来表示猫的名字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27344, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我很有一台新电脑。", "corrected_sentence": "我有一台新电脑。", "error_description": "错误：“我很有一台新电脑”。正确：“我有一台新电脑”。“很”不能修饰表示领有的“有”，“很有”只用于“很有钱”“很有经验”这类表示具有某种性质的说法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27344, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家有没电脑。", "corrected_sentence": "我家没有电脑。", "error_description": "错误：“我家有没电脑”。正确：“我家没有电脑”。“有”的否定形式是“没有”，“没”要放在“有”前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
