INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27346, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "进入一个网站或系统时，输入名字和密码。", "primary_collocate": null, "pronunciation": "dēng lù", "ipa": "təŋ⁵⁵ lu⁵¹", "syllable_count": 2, "sentences": [{"text": "登录这个网站，要输入名字和密码。", "target_word": "登录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的账号在别的手机上登录过。", "target_word": "登录", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想登录游戏，可是网络不好。", "target_word": "登录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们先登录，再做作业。", "target_word": "登录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "登录时，别告诉别人你的密码。", "target_word": "登录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在图书馆的电脑上登录了自己的账号。", "target_word": "登录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "忘了密码，就不能登录。", "target_word": "登录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明每天回家先登录学习网站。", "target_word": "登录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个应用要用名字登录。", "target_word": "登录", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我登录了三次，都没有成功。", "target_word": "登录", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "登录了", "label": "体标"}, {"form": "登录过", "label": "体标"}, {"form": "登录名", "label": "复合"}, {"form": "登录密码", "label": "复合"}, {"form": "登錄", "label": "繁体"}], "register": "中性", "sense_fingerprint": "进网站或系统时输入名字和密码", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20fa5d8e-2296-45e3-ab90-df9c0be39312') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27346, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "登录", "is_correct": true, "explanation": "正确：“登录”指进入网站时输入名字和密码，句中“登录这个网站，要输入名字和密码”前后一致。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”指慢走锻炼，与输入名字和密码无关，“散步这个网站”说不通。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：“跳舞”是身体动作，不能用于网站，“跳舞这个网站”说不通。"}, {"text": "上色", "is_correct": false, "explanation": "语义：“上色”指给物体涂颜色，给网站上色并需要输入名字和密码，语义荒谬。"}], "explanations": {"登录": "正确：“登录”指进入网站时输入名字和密码，句中“登录这个网站，要输入名字和密码”前后一致。", "散步": "语义：“散步”指慢走锻炼，与输入名字和密码无关，“散步这个网站”说不通。", "跳舞": "语义：“跳舞”是身体动作，不能用于网站，“跳舞这个网站”说不通。", "上色": "语义：“上色”指给物体涂颜色，给网站上色并需要输入名字和密码，语义荒谬。"}, "sentence_index": 0, "correct_answer": "登录"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "登山队终于登录，队员们欢呼起来。", "explanation": "这里应该用〈登顶〉。“登顶”指攀登到山顶，“登录”指输入名字和密码进入网站或系统，不能用于登山队到达山顶。"}, {"text": "他正式登录，成为新国王。", "explanation": "这里应该用〈登基〉。“登基”指皇帝即位，“登录”指输入名字和密码进入网站或系统，不能用于即位为王。"}, {"text": "重阳节，老人们结伴去登录。", "explanation": "这里应该用〈登高〉。“登高”指登上高处，尤指重阳节的习俗，“登录”指输入名字和密码进入网站或系统，不能用于攀登高处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63040f2-b408-47a7-9224-16854b1fd9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27346, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "登录", "is_correct": true, "explanation": "正确：“忘了密码，就不能登录”表示没有密码就无法进入系统，语义通顺。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“忘了密码”与“吃饭”没有逻辑关系，“就不能吃饭”句意荒谬。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”与忘记密码无关，“就不能散步”句意不通。"}, {"text": "驾临", "is_correct": false, "explanation": "语域：“驾临”是敬辞，只用于尊贵的客人到访，用在这种日常语境中语域不合。"}], "explanations": {"登录": "正确：“忘了密码，就不能登录”表示没有密码就无法进入系统，语义通顺。", "吃饭": "语义：“忘了密码”与“吃饭”没有逻辑关系，“就不能吃饭”句意荒谬。", "散步": "语义：“散步”与忘记密码无关，“就不能散步”句意不通。", "驾临": "语域：“驾临”是敬辞，只用于尊贵的客人到访，用在这种日常语境中语域不合。"}, "sentence_index": 6, "correct_answer": "登录"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "台风昨天晚上在南方沿海登录了。", "explanation": "这里应该用〈登陆〉。“登陆”指台风、船只等从海上到达陆地，与“登录”同音但意思不同；“登录”指输入名字和密码进入网站或系统。"}, {"text": "他登录了那个文件。", "explanation": "这里应该用〈打开〉。“登录”指输入名字和密码进入网站或系统，打开文件不能说“登录”。"}, {"text": "这位演员第一次登录，观众热烈鼓掌。", "explanation": "这里应该用〈登场〉。“登场”指演员走上舞台、出现在观众面前，“登录”指输入名字和密码进入网站或系统，不能用于演员出场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63040f2-b408-47a7-9224-16854b1fd9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27346, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我明天登录了学习网站。", "corrected_sentence": "我明天登录学习网站。", "error_description": "“了”用错：“明天”表示将来，动作尚未发生，不能加“了”，应说“我明天登录学习网站”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63040f2-b408-47a7-9224-16854b1fd9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27346, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天都登录了学习网站。", "corrected_sentence": "他每天都登录学习网站。", "error_description": "“了”用错：“每天都”表示经常发生的动作，不能加“了”，应说“他每天都登录学习网站”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63040f2-b408-47a7-9224-16854b1fd9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
