INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27348, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "告诉别人一件事。", "primary_collocate": null, "pronunciation": "fā xiāo xi", "ipa": "fa⁵⁵ ɕiau̯⁵⁵ ɕi", "syllable_count": 3, "sentences": [{"text": "学校发消息说，明天不上课。", "target_word": "发消息", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司已经发消息，下周开会。", "target_word": "发消息", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师发消息告诉大家考试的时间。", "target_word": "发消息", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "关于搬家的事，公司还没发消息。", "target_word": "发消息", "complexity_tier": "T3", "furigana": "guān yú bān jiā de shì, gōng sī hái méi fā xiāo xi。", "sentence_source": "generated"}, {"text": "队长发消息说，比赛改到星期日了。", "target_word": "发消息", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有了结果，请马上发消息给我。", "target_word": "发消息", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气要变冷，村里发消息让大家带衣服。", "target_word": "发消息", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理发消息说，大家可以早点回家。", "target_word": "发消息", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "队长决定先不发消息，等比赛结束再说。", "target_word": "发消息", "complexity_tier": "T3", "furigana": "duì zhǎng jué dìng xiān bù fā xiāo xi, děng bǐ sài jié shù zài shuō。", "sentence_source": "generated"}, {"text": "医院发消息，请病人明天早点来。", "target_word": "发消息", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "发了消息", "label": "体标"}, {"form": "发过消息", "label": "体标"}, {"form": "發消息", "label": "繁体"}], "register": "口语", "sense_fingerprint": "把一件事通知或告诉别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20fa5d8e-2296-45e3-ab90-df9c0be39312') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27348, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发消息", "is_correct": true, "explanation": "正确：“发消息说”表示通过消息告知一件事，与“学校”作主语、“说”搭配自然。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”不能用来传达事情，与“说”的内容相矛盾。"}, {"text": "关机", "is_correct": false, "explanation": "搭配：“关机”指停止设备运行，不能与“说”搭配。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“吃饭”不能表示传达事情，与“说，明天不上课”的内容矛盾。"}], "explanations": {"发消息": "正确：“发消息说”表示通过消息告知一件事，与“学校”作主语、“说”搭配自然。", "唱歌": "语义：“唱歌”不能用来传达事情，与“说”的内容相矛盾。", "关机": "搭配：“关机”指停止设备运行，不能与“说”搭配。", "吃饭": "语义：“吃饭”不能表示传达事情，与“说，明天不上课”的内容矛盾。"}, "sentence_index": 0, "correct_answer": "发消息"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "经理当面发消息说，明天放假。", "explanation": "这里应该用〈口头通知〉。〈发消息〉是借设备传递信息，不能用于当面告知。"}, {"text": "公司发消息一台电脑给我。", "explanation": "这里应该用〈送〉。〈发消息〉传递的是文字信息，不能接实物作宾语。"}, {"text": "这块石头发消息说，要下雨了。", "explanation": "这里应该用〈预示〉。〈发消息〉的主语须是能告诉别人的人或机构，石头表示征兆要用〈预示〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63040f2-b408-47a7-9224-16854b1fd9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27348, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发消息", "is_correct": true, "explanation": "正确：“村里发消息让大家带衣服”，表示村里通知大家，语境相符。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”是自然现象，村里不能通过“下雨”来通知大家。"}, {"text": "见面", "is_correct": false, "explanation": "配价：“见面”要用“跟”引出对象，不能说“村里见面让大家”。"}, {"text": "收割", "is_correct": false, "explanation": "语义：“收割”是农事动作，与“让大家带衣服”的意思无关。"}], "explanations": {"发消息": "正确：“村里发消息让大家带衣服”，表示村里通知大家，语境相符。", "下雨": "语义：“下雨”是自然现象，村里不能通过“下雨”来通知大家。", "见面": "配价：“见面”要用“跟”引出对象，不能说“村里见面让大家”。", "收割": "语义：“收割”是农事动作，与“让大家带衣服”的意思无关。"}, "sentence_index": 6, "correct_answer": "发消息"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师在门口发消息，喊我的名字。", "explanation": "这里应该用〈喊〉。〈喊〉是大声叫人，〈发消息〉指通过设备传递文字，不能用于口头呼叫。"}, {"text": "他发消息给我一杯水。", "explanation": "这里应该用〈递〉。〈发消息〉是把一件事告诉别人，传的是信息，不能把一杯水这样的东西交给别人。"}, {"text": "医院发消息给椅子，请它明天早点来。", "explanation": "这里应该把接收者换成人：〈发消息〉的接收者须能理解信息，椅子不能接收；应改为“医院发消息给病人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63040f2-b408-47a7-9224-16854b1fd9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27348, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校昨天发过消息过，今天停课。", "corrected_sentence": "学校昨天发过消息，今天停课。", "error_description": "错误：“过”重复。“发过消息”中已用“过”表示完成，末尾不能再加“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63040f2-b408-47a7-9224-16854b1fd9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27348, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "班长发消息大家，明天不用来了。", "corrected_sentence": "班长发消息给大家，明天不用来了。", "error_description": "错误：缺少“给”。“发消息”后要用“给”引出接收者，“发消息大家”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63040f2-b408-47a7-9224-16854b1fd9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
