INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27354, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把不对的变成对的。", "primary_collocate": null, "pronunciation": "gǎi", "ipa": "kai˨˩˦", "syllable_count": 1, "sentences": [{"text": "老师正在改同学们的作业。", "target_word": "改", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这句话有错，你改一下。", "target_word": "改", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他写错了字，马上改过来了。", "target_word": "改", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "知道错了就要改。", "target_word": "改", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我的作文有三个错字，我都改了。", "target_word": "改", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做错了没关系，改了就好。", "target_word": "改", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个坏习惯，他一直没改掉。", "target_word": "改", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的发音不对，老师让他改。", "target_word": "改", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把文章里的错别字改了。", "target_word": "改", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有错就改，这样才能进步。", "target_word": "改", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "改了", "label": "体标"}, {"form": "改过", "label": "体标"}, {"form": "改改", "label": "重叠"}, {"form": "改正", "label": "复合"}, {"form": "修改", "label": "复合"}], "register": "中性", "sense_fingerprint": "纠正错误、把错的变成对的（改错、改作业、改掉坏习惯）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20fa5d8e-2296-45e3-ab90-df9c0be39312') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27354, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "改", "is_correct": true, "explanation": "正确：改（gǎi），意思是纠正、把错的变成对的。"}, {"text": "海", "is_correct": false, "explanation": "hǎi（第三声）与 gǎi 声母不同（h 与 g），意思是大海。"}, {"text": "奶", "is_correct": false, "explanation": "nǎi（第三声）与 gǎi 声母不同（n 与 g），意思是牛奶。"}, {"text": "盖", "is_correct": false, "explanation": "gài（第四声）与 gǎi 声调不同，意思是覆盖、盖住。"}, {"text": "凯", "is_correct": false, "explanation": "kǎi（第三声）与 gǎi 声母不同（k 与 g），意思是凯旋、胜利。"}], "explanations": {"改": "正确：改（gǎi），意思是纠正、把错的变成对的。", "海": "hǎi（第三声）与 gǎi 声母不同（h 与 g），意思是大海。", "奶": "nǎi（第三声）与 gǎi 声母不同（n 与 g），意思是牛奶。", "盖": "gài（第四声）与 gǎi 声调不同，意思是覆盖、盖住。", "凯": "kǎi（第三声）与 gǎi 声母不同（k 与 g），意思是凯旋、胜利。"}, "sentence_index": null, "correct_answer": "改"}, "level_3": {"options": [{"text": "改", "is_correct": true, "explanation": "正确：“改同学们的作业”指批改、纠正作业中的错误，符合语境。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，作业不能吃。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”指用脚撞击，作业不能用脚去踢，句意不通。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不与“作业”搭配，不能说“唱作业”。"}], "explanations": {"改": "正确：“改同学们的作业”指批改、纠正作业中的错误，符合语境。", "吃": "语义：“吃”指进食，作业不能吃。", "踢": "语义：“踢”指用脚撞击，作业不能用脚去踢，句意不通。", "唱": "搭配：“唱”不与“作业”搭配，不能说“唱作业”。"}, "sentence_index": 0, "correct_answer": "改"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的个子改高了。", "explanation": "这里应该用〈长〉。个子是自然生长，没有对错，不能用“改”；“改”指把错的改成对的。"}, {"text": "客人来了，他给客人改了一杯茶。", "explanation": "这里应该用〈泡〉。茶是泡的，“改”指把错的变成对的，不能用于泡茶。"}, {"text": "他改掉了旧手机。", "explanation": "这里应该用〈换〉。“改掉”表示改正或去除错误、坏习惯，不能用来表示替换东西；旧手机应说“换掉”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63040f2-b408-47a7-9224-16854b1fd9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27354, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "改", "is_correct": true, "explanation": "正确：改（gǎi），意思是纠正、把错的变成对的。"}, {"text": "买", "is_correct": false, "explanation": "mǎi（第三声）与 gǎi 声母不同（m 与 g），意思是购买。"}, {"text": "搞", "is_correct": false, "explanation": "gǎo（第三声）与 gǎi 韵母不同（o 与 i），意思是做、干。"}, {"text": "该", "is_correct": false, "explanation": "gāi（第一声）与 gǎi 声调不同，意思是应当、该当。"}, {"text": "百", "is_correct": false, "explanation": "bǎi（第三声）与 gǎi 声母不同（b 与 g），意思是一百。"}, {"text": "感", "is_correct": false, "explanation": "gǎn（第三声）与 gǎi 韵母不同（n 与 i），意思是感觉。"}], "explanations": {"改": "正确：改（gǎi），意思是纠正、把错的变成对的。", "买": "mǎi（第三声）与 gǎi 声母不同（m 与 g），意思是购买。", "搞": "gǎo（第三声）与 gǎi 韵母不同（o 与 i），意思是做、干。", "该": "gāi（第一声）与 gǎi 声调不同，意思是应当、该当。", "百": "bǎi（第三声）与 gǎi 声母不同（b 与 g），意思是一百。", "感": "gǎn（第三声）与 gǎi 韵母不同（n 与 i），意思是感觉。"}, "sentence_index": null, "correct_answer": "改"}, "level_3": {"options": [{"text": "改", "is_correct": true, "explanation": "正确：“没改掉”指没有改正掉这个坏习惯，符合语境。"}, {"text": "养", "is_correct": false, "explanation": "搭配：“养”与“成”搭配成“养成习惯”，不说“养掉坏习惯”。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指书写，与“坏习惯”无关，“没写掉坏习惯”说不通。"}, {"text": "玩", "is_correct": false, "explanation": "语义：“玩”指玩耍，“玩掉坏习惯”不成立。"}], "explanations": {"改": "正确：“没改掉”指没有改正掉这个坏习惯，符合语境。", "养": "搭配：“养”与“成”搭配成“养成习惯”，不说“养掉坏习惯”。", "写": "语义：“写”指书写，与“坏习惯”无关，“没写掉坏习惯”说不通。", "玩": "语义：“玩”指玩耍，“玩掉坏习惯”不成立。"}, "sentence_index": 6, "correct_answer": "改"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的血压改低了。", "explanation": "这里应该用〈降低〉。血压升降是数量变化，不是对错的纠正，不能说“改低”。"}, {"text": "他改了一朵花。", "explanation": "这里应该用〈摘〉。摘花是取下花朵的动作，“改”用于把错的变对，不能用于摘花。"}, {"text": "他改了一支烟。", "explanation": "这里应该用〈抽〉。烟是抽的，“改”只用于纠正对错，不能用于抽烟这类动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63040f2-b408-47a7-9224-16854b1fd9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27354, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他下次会把错字改过来了。", "corrected_sentence": "他下次会把错字改过来。", "error_description": "“了”用错：“下次”表示将来，动作尚未发生，“改过来”后不能加“了”，应说“他下次会把错字改过来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63040f2-b408-47a7-9224-16854b1fd9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27354, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我已经把错字好改了。", "corrected_sentence": "我已经把错字改好了。", "error_description": "错误形式：“好改了”；正确形式：“改好了”。结果补语“好”应紧跟在动词“改”之后，不能放在“改”前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63040f2-b408-47a7-9224-16854b1fd9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27356, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "虚伪", "is_correct": true, "explanation": "反义：“虚伪”指表里不一、不真实，与“诚实”（不说谎、为人可靠）相反。"}, {"text": "活泼", "is_correct": false, "explanation": "无反义关系：“活泼”形容性格开朗、爱动，与“诚实”的意思无关。"}, {"text": "大方", "is_correct": false, "explanation": "无反义关系：“大方”形容不拘小节、慷慨，与“诚实”的意思无关。"}, {"text": "勇敢", "is_correct": false, "explanation": "无反义关系：“勇敢”形容胆量大，与“诚实”的意思无关。"}], "correct_answer": "虚伪", "explanations": {"虚伪": "反义：“虚伪”指表里不一、不真实，与“诚实”（不说谎、为人可靠）相反。", "活泼": "无反义关系：“活泼”形容性格开朗、爱动，与“诚实”的意思无关。", "大方": "无反义关系：“大方”形容不拘小节、慷慨，与“诚实”的意思无关。", "勇敢": "无反义关系：“勇敢”形容胆量大，与“诚实”的意思无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63040f2-b408-47a7-9224-16854b1fd9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
