INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27356, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不说谎，做实事。", "primary_collocate": null, "pronunciation": "chéng shí", "ipa": "tʂʰɤŋ˧˥ ʂɻ˧˥", "syllable_count": 2, "sentences": [{"text": "这个孩子很诚实，从来不说谎。", "target_word": "诚实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "诚实的人不会骗人。", "target_word": "诚实", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他为人诚实，做事认真。", "target_word": "诚实", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小明很诚实，打破杯子后马上承认了。", "target_word": "诚实", "complexity_tier": "T3", "furigana": "xiǎo míng hěn chéng shí, dǎ pò bēi zi hòu mǎ shàng chéng rèn le.", "sentence_source": "generated"}, {"text": "妈妈常教我们要诚实。", "target_word": "诚实", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他很诚实，捡到钱包就交给了警察。", "target_word": "诚实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试的时候，诚实比分数更重要。", "target_word": "诚实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位商人诚实可靠，大家都愿意和他做生意。", "target_word": "诚实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有诚实地回答，所以老师有点生气。", "target_word": "诚实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做错了事，诚实地说出来才对。", "target_word": "诚实", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "誠實", "label": "繁体"}], "register": "中性", "sense_fingerprint": "不说谎、不骗人，为人踏实可靠（不说谎、诚实可靠、诚实地说出来）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20fa5d8e-2296-45e3-ab90-df9c0be39312') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27356, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "诚实", "is_correct": true, "explanation": "正确：“很诚实，从来不说谎”指不说谎、为人可靠，符合语境。"}, {"text": "狡猾", "is_correct": false, "explanation": "语义：“狡猾”指耍手段骗人，与“从来不说谎”相悖。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容体形，不用来说人的品性。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”说身材，与人的品性无关，不能和“从来不说谎”搭配。"}], "explanations": {"诚实": "正确：“很诚实，从来不说谎”指不说谎、为人可靠，符合语境。", "狡猾": "语义：“狡猾”指耍手段骗人，与“从来不说谎”相悖。", "高大": "搭配：“高大”形容体形，不用来说人的品性。", "瘦": "体貌：“瘦”说身材，与人的品性无关，不能和“从来不说谎”搭配。"}, "sentence_index": 0, "correct_answer": "诚实"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的天气很诚实。", "explanation": "这里应该用〈晴朗〉。“诚实”只形容人不说谎、做实事，不能形容天气。"}, {"text": "他很诚实，敢一个人去救火。", "explanation": "这里应该用〈勇敢〉。“诚实”指不说谎、做实事，不表示胆量；敢一个人救火要说“勇敢”。"}, {"text": "这块石头很诚实。", "explanation": "这里应该用〈坚硬〉。石头的硬度要说“坚硬”，“诚实”只指人不说谎、做实事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63040f2-b408-47a7-9224-16854b1fd9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27356, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "诚实", "is_correct": true, "explanation": "正确：“考试的时候，诚实比分数更重要”，表示为人可靠比分数重要，符合语境。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”说外貌，与“考试”和“分数”无关，不能说“漂亮比分数更重要”。"}, {"text": "吵闹", "is_correct": false, "explanation": "语义：“吵闹”指声音杂乱，与考试时对为人的要求不搭，说不通。"}, {"text": "懒", "is_correct": false, "explanation": "语义：“懒”指不愿动，说“懒比分数更重要”于理不通。"}], "explanations": {"诚实": "正确：“考试的时候，诚实比分数更重要”，表示为人可靠比分数重要，符合语境。", "漂亮": "体貌：“漂亮”说外貌，与“考试”和“分数”无关，不能说“漂亮比分数更重要”。", "吵闹": "语义：“吵闹”指声音杂乱，与考试时对为人的要求不搭，说不通。", "懒": "语义：“懒”指不愿动，说“懒比分数更重要”于理不通。"}, "sentence_index": 6, "correct_answer": "诚实"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈诚实地笑了。", "explanation": "这里应该用〈开心〉。“诚实”描述说话做事是否真实可靠，不用来形容笑这种表情。"}, {"text": "她学习很诚实，每天都复习。", "explanation": "这里应该用〈勤奋〉。“诚实”指不说谎、做实事，不说明学习用功与否；学习刻苦要用“勤奋”。"}, {"text": "这片云很诚实。", "explanation": "这里应该用〈洁白〉。云的颜色要说“洁白”，“诚实”只用于描述人的品行，不能形容云。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63040f2-b408-47a7-9224-16854b1fd9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27356, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一个很诚实。", "corrected_sentence": "他是一个很诚实的人。", "error_description": "错误：缺少“的人”。“诚实”是形容词，不能直接作“一个”的中心语，应说“一个很诚实的人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63040f2-b408-47a7-9224-16854b1fd9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27356, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她诚实的地承认了错误。", "corrected_sentence": "她诚实地承认了错误。", "error_description": "错误形式：“诚实的地承认”；正确形式：“诚实地承认”。修饰动词的状语要用“地”，“的”用于名词性定语，“诚实的”后不能再接“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63040f2-b408-47a7-9224-16854b1fd9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
