INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27358, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示程度高，比如‘很好’就是非常好。", "primary_collocate": null, "pronunciation": "hěn", "ipa": "xən²¹⁴", "syllable_count": 1, "sentences": [{"text": "今天的天气很好。", "target_word": "很", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间很大，也很亮。", "target_word": "很", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的汉语说得很流利。", "target_word": "很", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆的菜很便宜。", "target_word": "很", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我弟弟跑得很快。", "target_word": "很", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京的冬天很冷。", "target_word": "很", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书很贵。", "target_word": "很", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈做的鱼很好吃。", "target_word": "很", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天很高兴，因为考试通过了。", "target_word": "很", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座山很高，我们爬了三个小时。", "target_word": "很", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "程度副词，用在形容词前表示程度高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47c36c6a-10d1-484f-a144-0a730fa56e1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27358, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "很", "is_correct": true, "explanation": "正确答案：hěn（第三声），意思是“很”。"}, {"text": "恨", "is_correct": false, "explanation": "hěn（第三声）与 hèn（第四声）声调不同，意思是“恨”。"}, {"text": "痕", "is_correct": false, "explanation": "hěn（第三声）与 hén（第二声）声调不同，意思是“痕迹”。"}, {"text": "肯", "is_correct": false, "explanation": "h 与 k 声母不同，声调相同（第三声），意思是“肯”。"}, {"text": "喊", "is_correct": false, "explanation": "hǎn（第三声）与 hěn（第三声）只差一个元音（an 与 en），声调相同，意思是“大声叫”。"}], "explanations": {"很": "正确答案：hěn（第三声），意思是“很”。", "恨": "hěn（第三声）与 hèn（第四声）声调不同，意思是“恨”。", "痕": "hěn（第三声）与 hén（第二声）声调不同，意思是“痕迹”。", "肯": "h 与 k 声母不同，声调相同（第三声），意思是“肯”。", "喊": "hǎn（第三声）与 hěn（第三声）只差一个元音（an 与 en），声调相同，意思是“大声叫”。"}, "sentence_index": null, "correct_answer": "很"}, "level_3": {"options": [{"text": "很", "is_correct": true, "explanation": "“很”修饰形容词“好”，表示程度高，符合句意。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”指过去，与“今天”这一现时的天气冲突。"}, {"text": "一向", "is_correct": false, "explanation": "语义：“一向”指长期如此，与“今天”单日的天气不合。"}, {"text": "正在", "is_correct": false, "explanation": "语法：“正在”表示动作进行，不能直接修饰形容词“好”，“天气正在好”不成立。"}], "explanations": {"很": "“很”修饰形容词“好”，表示程度高，符合句意。", "曾经": "语义：“曾经”指过去，与“今天”这一现时的天气冲突。", "一向": "语义：“一向”指长期如此，与“今天”单日的天气不合。", "正在": "语法：“正在”表示动作进行，不能直接修饰形容词“好”，“天气正在好”不成立。"}, "sentence_index": 0, "correct_answer": "很"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是很唯一的办法，你必须试试。", "explanation": "这里误用了〈很〉。“很”表示程度高，只能修饰有程度差别的词；“唯一”只有一个、没有程度之分，不能用“很”修饰，应去掉“很”。"}, {"text": "他很结婚了，现在有两个孩子。", "explanation": "这里误用了〈很〉。“很”不能修饰“结婚”这类动作性动词，应说“结婚很久了”，把“很”放在“久”前面。"}, {"text": "他们很同时到达了机场。", "explanation": "这里误用了〈很〉。“同时”表示时间一致，没有程度差别，不能用“很”修饰，应去掉“很”，直接说“同时到达”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '571872f6-9807-451a-bc7d-5a66fa6060b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27358, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "很", "is_correct": true, "explanation": "正确答案：hěn（第三声），意思是“很”。"}, {"text": "粉", "is_correct": false, "explanation": "f 与 h 声母不同，声调与韵母相同（fěn 与 hěn），意思是“粉末”。"}, {"text": "本", "is_correct": false, "explanation": "b 与 h 声母不同，声调与韵母相同（běn 与 hěn），意思是“书本”。"}, {"text": "忍", "is_correct": false, "explanation": "r 与 h 声母不同，声调与韵母相同（rěn 与 hěn），意思是“忍受”。"}, {"text": "罕", "is_correct": false, "explanation": "hǎn（第三声）与 hěn（第三声）只差一个元音（an 与 en），声调相同，意思是“稀少”。"}], "explanations": {"很": "正确答案：hěn（第三声），意思是“很”。", "粉": "f 与 h 声母不同，声调与韵母相同（fěn 与 hěn），意思是“粉末”。", "本": "b 与 h 声母不同，声调与韵母相同（běn 与 hěn），意思是“书本”。", "忍": "r 与 h 声母不同，声调与韵母相同（rěn 与 hěn），意思是“忍受”。", "罕": "hǎn（第三声）与 hěn（第三声）只差一个元音（an 与 en），声调相同，意思是“稀少”。"}, "sentence_index": null, "correct_answer": "很"}, "level_3": {"options": [{"text": "很", "is_correct": true, "explanation": "“很”修饰形容词“贵”，表示程度高，符合句意。"}, {"text": "都", "is_correct": false, "explanation": "搭配：“都”表示总括，需要复数对象，单本书不能用“都”。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”多与否定词连用，不能直接修饰肯定的“贵”。"}, {"text": "正在", "is_correct": false, "explanation": "语法：“正在”表示动作进行，不能直接修饰形容词“贵”，“这本书正在贵”不成立。"}], "explanations": {"很": "“很”修饰形容词“贵”，表示程度高，符合句意。", "都": "搭配：“都”表示总括，需要复数对象，单本书不能用“都”。", "从来": "搭配：“从来”多与否定词连用，不能直接修饰肯定的“贵”。", "正在": "语法：“正在”表示动作进行，不能直接修饰形容词“贵”，“这本书正在贵”不成立。"}, "sentence_index": 6, "correct_answer": "很"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次比赛他很第一个跑到终点。", "explanation": "这里误用了〈很〉。“很”表示程度高，不能修饰“第一个”这类表示次序的词，应去掉“很”，直接说“第一个跑到终点”。"}, {"text": "这是很最终的结果，已经无法改变。", "explanation": "这里误用了〈很〉。“最终”表示最后、不再变化，没有程度差别，不能用“很”修饰，应去掉“很”。"}, {"text": "他很永远爱着这个城市。", "explanation": "这里误用了〈很〉。“永远”表示时间上没有终点，不分程度，不能用“很”修饰，应去掉“很”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '571872f6-9807-451a-bc7d-5a66fa6060b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27358, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个城市的物价高很。", "corrected_sentence": "这个城市的物价很高。", "error_description": "应为“很高”：程度副词“很”要放在形容词前面，“高很”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '571872f6-9807-451a-bc7d-5a66fa6060b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27358, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她走得太很慢。", "corrected_sentence": "她走得很慢。", "error_description": "错误在“太”与“很”叠用：两个程度副词不能同时修饰“慢”，去掉“太”即为“她走得很慢。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '571872f6-9807-451a-bc7d-5a66fa6060b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
