INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27360, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "通过学习而掌握某种技能，能够做某事。", "primary_collocate": null, "pronunciation": "huì", "ipa": "xweɪ˥˩", "syllable_count": 1, "sentences": [{"text": "我会说一点汉语。", "target_word": "会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今年五岁，已经会游泳了。", "target_word": "会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你会开车吗？", "target_word": "会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我妈妈会做很好吃的中国菜。", "target_word": "会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子会自己穿衣服。", "target_word": "会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不会用这个新手机。", "target_word": "会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她会弹钢琴，弹得很好。", "target_word": "会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们会不会写这个字？", "target_word": "会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的小狗会握手。", "target_word": "会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷不会上网，但是会打电话。", "target_word": "会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "會", "label": "繁体"}], "register": "中性", "sense_fingerprint": "会：经过学习而掌握某种技能，能够做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f82c8ae-82ab-4595-b449-235c22ee33c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27360, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "会", "is_correct": true, "explanation": "正确：huì（第四声）是“会”，表示经过学习掌握某种技能，能够做某事。"}, {"text": "回", "is_correct": false, "explanation": "huí（第二声）与 huì 声调不同，意思是“回来、回答”。"}, {"text": "毁", "is_correct": false, "explanation": "huǐ（第三声）与 huì 声调不同，意思是“毁坏”。"}, {"text": "挥", "is_correct": false, "explanation": "huī（第一声）与 huì 声调不同，意思是“挥动”。"}, {"text": "灰", "is_correct": false, "explanation": "huī（第一声）与 huì 声调不同，意思是“灰色”。"}, {"text": "徽", "is_correct": false, "explanation": "huī（第一声）与 huì 仅声调不同，意思是徽章。"}], "explanations": {"会": "正确：huì（第四声）是“会”，表示经过学习掌握某种技能，能够做某事。", "回": "huí（第二声）与 huì 声调不同，意思是“回来、回答”。", "毁": "huǐ（第三声）与 huì 声调不同，意思是“毁坏”。", "挥": "huī（第一声）与 huì 声调不同，意思是“挥动”。", "灰": "huī（第一声）与 huì 声调不同，意思是“灰色”。", "徽": "huī（第一声）与 huì 仅声调不同，意思是徽章。"}, "sentence_index": null, "correct_answer": "会"}, "level_3": {"options": [{"text": "会", "is_correct": true, "explanation": "正确：“会”表示学过某种技能、能够做某事，此处指掌握了一点汉语。"}, {"text": "敢", "is_correct": false, "explanation": "语义：“敢”表示有胆量去做有风险的事，说汉语不构成冒险，句意不通。"}, {"text": "须", "is_correct": false, "explanation": "语域：“须”属书面语，与口语化的“我……说一点汉语”不协调。"}, {"text": "可", "is_correct": false, "explanation": "语域：“可”作能愿动词时多见于书面或古语，口语中一般不这样用。"}], "explanations": {"会": "正确：“会”表示学过某种技能、能够做某事，此处指掌握了一点汉语。", "敢": "语义：“敢”表示有胆量去做有风险的事，说汉语不构成冒险，句意不通。", "须": "语域：“须”属书面语，与口语化的“我……说一点汉语”不协调。", "可": "语域：“可”作能愿动词时多见于书面或古语，口语中一般不这样用。"}, "sentence_index": 0, "correct_answer": "会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆车会坐五个人。", "explanation": "这里应该用〈能〉。“会”表示学会的技能，表示容量要用“能”。"}, {"text": "我会用一下你的笔吗？", "explanation": "这里应该用〈可以〉。“会”表示掌握技能，请求许可要用“可以”。"}, {"text": "他一次会吃三碗饭。", "explanation": "这里应该用〈能〉。“会”表示学会的技能，表示能达到某个数量要用“能”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '509b35c6-840c-42b7-b052-f857cb5ec106') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27360, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "会", "is_correct": true, "explanation": "正确：huì（第四声）是“会”，表示经过学习掌握某种技能，能够做某事。"}, {"text": "悔", "is_correct": false, "explanation": "huǐ（第三声）与 huì 声调不同，意思是“后悔”。"}, {"text": "辉", "is_correct": false, "explanation": "huī（第一声）与 huì 声调不同，意思是“光辉”。"}, {"text": "贵", "is_correct": false, "explanation": "guì（第四声）与 huì 声母不同（g 与 h），意思是“价格高”。"}, {"text": "挥", "is_correct": false, "explanation": "huī（第一声）与 huì 仅声调不同，意思是挥动。"}], "explanations": {"会": "正确：huì（第四声）是“会”，表示经过学习掌握某种技能，能够做某事。", "悔": "huǐ（第三声）与 huì 声调不同，意思是“后悔”。", "辉": "huī（第一声）与 huì 声调不同，意思是“光辉”。", "贵": "guì（第四声）与 huì 声母不同（g 与 h），意思是“价格高”。", "挥": "huī（第一声）与 huì 仅声调不同，意思是挥动。"}, "sentence_index": null, "correct_answer": "会"}, "level_3": {"options": [{"text": "会", "is_correct": true, "explanation": "正确：“会”表示学过某种技能，此处指她掌握了弹钢琴的能力。"}, {"text": "应", "is_correct": false, "explanation": "语域：“应”偏书面，与口语化的“弹得很好”叙述不协调。"}, {"text": "必", "is_correct": false, "explanation": "语域：“必”属书面语，与口语化的叙述不协调。"}, {"text": "当", "is_correct": false, "explanation": "搭配：“当”作能愿用法极少见，不能与“弹钢琴”组合，句子不成立。"}], "explanations": {"会": "正确：“会”表示学过某种技能，此处指她掌握了弹钢琴的能力。", "应": "语域：“应”偏书面，与口语化的“弹得很好”叙述不协调。", "必": "语域：“必”属书面语，与口语化的叙述不协调。", "当": "搭配：“当”作能愿用法极少见，不能与“弹钢琴”组合，句子不成立。"}, "sentence_index": 6, "correct_answer": "会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个房间会坐二十个人。", "explanation": "这里应该用〈能〉。“会”表示学会的技能，表示容量要用“能”。"}, {"text": "老师，我会进来吗？", "explanation": "这里应该用〈可以〉。“会”表示掌握技能，请求许可要用“可以”。"}, {"text": "他一分钟会打一百个字。", "explanation": "这里应该用〈能〉。“会”只说明掌握了技能，表示达到某种效率要用“能”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '509b35c6-840c-42b7-b052-f857cb5ec106') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27360, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我会不游泳，但是会骑车。", "corrected_sentence": "我不会游泳，但是会骑车。", "error_description": "错误：否定词“不”应放在“会”之前，写作“不会游泳”；“会不游泳”的语序是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '509b35c6-840c-42b7-b052-f857cb5ec106') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27360, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我弟弟没会开车，只会骑自行车。", "corrected_sentence": "我弟弟不会开车，只会骑自行车。", "error_description": "错误：表示“不具备某种能力”应用“不会”，不能用“没会”，“没”只用于“没有”的情况。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '509b35c6-840c-42b7-b052-f857cb5ec106') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
