INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27364, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "关于你自己的信息，比如名字、年龄。", "primary_collocate": null, "pronunciation": "gè rén xìn xī", "ipa": "kɤ˥˩ ɻən˧˥ ɕin˥˩ ɕi˥", "syllable_count": 4, "sentences": [{"text": "请在表格里写名字、年龄等个人信息。", "target_word": "个人信息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们先介绍自己的个人信息。", "target_word": "个人信息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的个人信息只有好朋友知道。", "target_word": "个人信息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在网上填了名字和年龄等个人信息。", "target_word": "个人信息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "软件想知道我的名字和年龄等个人信息。", "target_word": "个人信息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别把你的名字和年龄这些个人信息告诉陌生人。", "target_word": "个人信息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子上网时，不要说出名字、年龄等个人信息。", "target_word": "个人信息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以看看我的个人信息：名字、年龄和城市。", "target_word": "个人信息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把名字、年龄等个人信息写在卡片上了。", "target_word": "个人信息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院要问病人的名字、年龄等个人信息。", "target_word": "个人信息", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "关于自己的基本信息，如名字、年龄", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d3e40a-5887-46ae-a092-87880ccdc4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27364, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "身材", "is_correct": false, "explanation": "体貌：「身材」是外形特征，不是表格里要求填写的基本信息，与「名字、年龄」不并列。"}, {"text": "口号", "is_correct": false, "explanation": "语义：「口号」是宣传用语，不是需要写在表格里的个人资料。"}, {"text": "个人信息", "is_correct": true, "explanation": "正确。「名字、年龄等个人信息」是表格里常见的填写内容。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：「玩意儿」是口语词，不适合表格这类正式的填写要求。"}], "explanations": {"身材": "体貌：「身材」是外形特征，不是表格里要求填写的基本信息，与「名字、年龄」不并列。", "口号": "语义：「口号」是宣传用语，不是需要写在表格里的个人资料。", "个人信息": "正确。「名字、年龄等个人信息」是表格里常见的填写内容。", "玩意儿": "语域：「玩意儿」是口语词，不适合表格这类正式的填写要求。"}, "sentence_index": 0, "correct_answer": "个人信息"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "面试时，他做了一分钟的个人信息。", "explanation": "这里应该用〈自我介绍〉。个人信息指名字、年龄等基本资料，不指口头介绍自己的过程。"}, {"text": "他在草地上踢了一脚个人信息。", "explanation": "这里应该用〈足球〉。个人信息是关于自己的资料，不能被踢。"}, {"text": "他的个人信息在班里排第一。", "explanation": "这里应该用〈成绩〉。个人信息指名字、年龄等基本资料，不能用来表示名次。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308fac2f-75d3-4b72-bab7-3881ffc7e4ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27364, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "价格", "is_correct": false, "explanation": "语义：「名字、年龄」是个人资料，「价格」不是孩子上网时需要保密的信息。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」不属于需要保密的个人资料，与「名字、年龄」语义不合。"}, {"text": "个人信息", "is_correct": true, "explanation": "正确。「说出个人信息」指孩子不要透露名字、年龄等个人资料。"}, {"text": "八卦", "is_correct": false, "explanation": "语域：「八卦」是口语化的闲话，与叮嘱孩子保护隐私的正式语境不符。"}], "explanations": {"价格": "语义：「名字、年龄」是个人资料，「价格」不是孩子上网时需要保密的信息。", "颜色": "语义：「颜色」不属于需要保密的个人资料，与「名字、年龄」语义不合。", "个人信息": "正确。「说出个人信息」指孩子不要透露名字、年龄等个人资料。", "八卦": "语域：「八卦」是口语化的闲话，与叮嘱孩子保护隐私的正式语境不符。"}, "sentence_index": 6, "correct_answer": "个人信息"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的个人信息跑得很快。", "explanation": "这里应该去掉「个人信息」，改为「他跑得很快」。个人信息是名字、年龄等资料，不能用“跑得快”形容。"}, {"text": "他的个人信息爬上了山顶。", "explanation": "这里应该去掉「个人信息」，改为「他爬上了山顶」。个人信息是资料，不能爬山，爬山的是人。"}, {"text": "他的个人信息一米八。", "explanation": "这里应该用〈身高〉。个人信息指名字、年龄等资料，不指身体的高度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308fac2f-75d3-4b72-bab7-3881ffc7e4ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27364, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把个人信息填了好。", "corrected_sentence": "他把个人信息填好了。", "error_description": "补语错误：结果补语「好」应紧跟动词「填」，写作「填好了」；「填了好」把补语拆开，语序不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308fac2f-75d3-4b72-bab7-3881ffc7e4ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27364, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把个人信息删。", "corrected_sentence": "他把个人信息删了。", "error_description": "把字句错误：「把」字句中动词「删」后须带补语或「了」等成分，写作「他把个人信息删了」；只说「他把个人信息删」不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308fac2f-75d3-4b72-bab7-3881ffc7e4ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
