INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27366, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让别人做事情。", "primary_collocate": null, "pronunciation": "ràng", "ipa": "ɻɑŋ˥˩", "syllable_count": 1, "sentences": [{"text": "老板让我今天写完报告。", "target_word": "让", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈让我去买牛奶。", "target_word": "让", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生让他多休息。", "target_word": "让", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师让我们打开书。", "target_word": "让", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他让朋友帮他拿行李。", "target_word": "让", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "奶奶让我早点回家。", "target_word": "让", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "经理让小王给客户打电话。", "target_word": "让", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "姐姐让我把门关上。", "target_word": "让", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她让儿子洗手再吃饭。", "target_word": "让", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "朋友让我明天一起去爬山。", "target_word": "让", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "让了", "label": "完成体"}, {"form": "不让", "label": "否定形式"}], "register": "中性", "sense_fingerprint": "动词：叫、吩咐别人去做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebfe7736-19f5-4660-8550-caa3fb9fd6f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27366, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "让", "is_correct": true, "explanation": "让：第四声，表示“使别人做某事”。"}, {"text": "浪", "is_correct": false, "explanation": "làng（第四声）与 ràng 声母不同（l 与 r），意思是波浪。"}, {"text": "嚷", "is_correct": false, "explanation": "rǎng（第三声）与 ràng 声调不同，意思是大声喊叫。"}, {"text": "瓤", "is_correct": false, "explanation": "ráng（第二声）与 ràng 只差声调，意思是瓜瓤。"}, {"text": "荡", "is_correct": false, "explanation": "dàng（第四声）与 ràng 声母不同（d 与 r），意思是摇荡。"}], "explanations": {"让": "让：第四声，表示“使别人做某事”。", "浪": "làng（第四声）与 ràng 声母不同（l 与 r），意思是波浪。", "嚷": "rǎng（第三声）与 ràng 声调不同，意思是大声喊叫。", "瓤": "ráng（第二声）与 ràng 只差声调，意思是瓜瓤。", "荡": "dàng（第四声）与 ràng 声母不同（d 与 r），意思是摇荡。"}, "sentence_index": null, "correct_answer": "让"}, "level_3": {"options": [{"text": "让", "is_correct": true, "explanation": "让：使役动词，表示“使别人做某事”，与后面的兼语结构搭配。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能带兼语结构“我今天写完报告”，句子不通。"}, {"text": "送", "is_correct": false, "explanation": "语义：“送”指递交、赠送，不能表示“使人去做事”。"}, {"text": "打", "is_correct": false, "explanation": "搭配：“打”与“写完报告”不搭配，句子不通。"}], "explanations": {"让": "让：使役动词，表示“使别人做某事”，与后面的兼语结构搭配。", "吃": "搭配：“吃”不能带兼语结构“我今天写完报告”，句子不通。", "送": "语义：“送”指递交、赠送，不能表示“使人去做事”。", "打": "搭配：“打”与“写完报告”不搭配，句子不通。"}, "sentence_index": 0, "correct_answer": "让"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的钱包让小偷偷走了。", "explanation": "这里的“让”表示被动，相当于“被”，指钱包被小偷偷走，不是“使别人做事”的意思。"}, {"text": "我把座位让给了老人。", "explanation": "这里的“让”是“把座位给别人”的意思（让座），不是“使别人做事”的意思。"}, {"text": "这件事我们各让一步。", "explanation": "这里的“让”是“退让、妥协”的意思（让步），不是“使别人做事”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02226a68-658a-4356-821b-8a8997342f34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
